local _, ns = ...

-- Progress (p) and hand-in (c) texts for quests whose other texts are in Data_Quests.lua
local extra = {
  [2] = {c="Imponerende, <Name>... Skarpklos klo kan ikke have været let at skaffe! Askedalen-jagten går godt for dig!\n\nSkarpklo havde længe terroriseret daglejerne fra tømmerlejrene langs dens vej, da de forsøgte at komme hertil til Splintertræ-Posten. Der går ingen tid, før ordet spreder sig om, at det var dig, der fældede udyret, og så vil mange opildnende sange om din tapperhed lyde ved lejrbål og savværker over hele Askedalen!", p="Ja, mægtige <Class>, jeg mærkede din ankomst. Jeg går ud fra, at du har flere nyheder at rapportere om din jagt?"},
  [5] = {c="Har du brug for nogle krabbekager? Nå, jeg kunne måske lave nogle til dig..."},
  [6] = {c="Hah - du fangede ham! Du har gjort Elvendal en stor tjeneste og fortjent en pæn dusør!", p="Fandt du Garriks hytte? Er vi endelig fri for den skurk?"},
  [7] = {c="Godt klaret, borger. De kobolder er tyve og kujoner, men i store antal udgør de en trussel for os. Og menneskerne i Stormvind har ikke brug for endnu en trussel.\n\nFor at besejre dem har du min taknemmelighed.", p="Hvordan går jagten, <Name>? Har du fundet og besejret de skadedyr?"},
  [8] = {c="Åh? Et brev? Herligt nyt! Jeg har ventet på bud fra min kære gamle mor i Dødsklokken. Sådan et helgen, hun er. Jeg undrer mig over, hvordan hun har det.\n\nHvad? For glad? Køber du den ikke, hva'?\n\nNå, så forsvind da... det er egentlig ingen sag, hvem brevet er fra. Af sted med dig! Forsvind!\n\nKom tilbage, når du har nogle skilling at bruge... slubrian.\n\nSå må du snart komme tilbage for at hvile dig efter en lang dags eventyr eller en eller anden dum ting.", p="Ja? Ja? Hvad er det?\n\nDe Forladte; de har bestemt store appetitter. Gør dig hjemme... ja, hvil de trætte knogler. Mit navn er Renee, hvis du overhovedet har brug for noget."},
  [9] = {c="God gerning, ven. Du har fortjent din løn brønd. Hvem ved, måske vil Vestfald blomstre igen.", p="Ah, jeg ser, du er tilbage! Jeg håber, du har slidt hårdt med at rydde de marker for Høstvogterne. Har du dræbt de tyve endnu?"},
  [11] = {c="Jeg ser, du har haft travlt! Du har vores tak, <Name>.", p="Hilsen, <Name>. Har du dræbt gnoller...?"},
  [12] = {c="Brønd forvoldt, <Name>. Min spejder overværede dine modige gerninger. Du beviser dig selv ganske brønd indtil videre.", p="Måske gjorde jeg mig ikke klar nok, løftemand. For at bevise din værdi som tjener for Folkemilitsen og for Lyset skal du slå 15 Defias-fælder og 15 Defias-smuglere ihjel og vende tilbage til mig, når gerningen er gjort."},
  [13] = {c="Din værdi for Folkemilitsen er blevet bekræftet af dine modige gerninger indtil nu.", p="Vi har ikke tid til snak, <Name>. Defias-hærgerne nægter Vestfalds folk den fred og det velstand, de fortjener. Sørg for, at mindst 15 Defias-hærgere og 15 Defias-plyndrere er blevet dræbt. Det vil sende et klart budskab om, at korruption ikke er velkommen her."},
  [14] = {c="Da jeg forlod de besmittede lande i Herrelande, vendte jeg tilbage til en dyster tilstand her i mit fædreland. Men der er endnu håb for Vestfald. Som din tapperhed i slaget beviser, er det for mig tydeligt, at du tjener vores sag med ære. Det er med stor stolthed, at jeg optager dig i Folkemilitsen. Måtte Let skinne over dig.", p="<Name>, nu er der ingen tid til tomsnak. Hvis du stadig vil bevise dig over for Folkemilitsen, må du slå de Defias ned, som jeg underrettede dig om tidligere. Vend tilbage til mig, når du har fuldført din pligt."},
  [15] = {c="Jeg bryder mig ikke om at høre om alle de kobolder i vores mine. Intet godt kan komme ud af det her. Her, tag det her som betaling, og når du er klar, så tal med mig igen. Jeg vil gerne have, at du går tilbage til minerne én gang til...", p="Har du været i minerne? Er du klar til at rapportere?"},
  [16] = {c="Tak, <Name>! Og kom tilbage, hvis du vil handle igen.", p="Landbrug er tørstigt arbejde, og jeg leder altid efter forfriskende kildevand.\n\nHvis du har noget, så er jeg villig til at bytte."},
  [18] = {c="Tilbage med nogle bandanaer, ser jeg. Stormvindsk Hær sætter pris på din hjælp.", p="Har du samlet de bandanaer til mig endnu?"},
  [19] = {c="Tharil'hund var en ondskabsfuld, snedig ork. Godt gået--jeg er sikker på, at han ikke gik let af. Her er din belønning, <Name>.", p="Ork-presset fra Sortklippe er stadig anspændt. Men har du i det mindste fjernet Tharil'hund for os?"},
  [20] = {c="Det gør der langt færre orker at bekymre sig om, tak.", p="Har du slagtet orker, <Name>? Hvis ja, så vis mig..."},
  [21] = {c="Endnu engang har du fortjent min respekt og den stormvindske hærs taknemmelighed. Der kan stadig være kobolder i minen, men jeg vil samle andre mod dem. Vi har flere opgaver til dig.", p="Jeg ved, det er et blodigt stykke arbejde, <Name>, men det er vitalt for sikkerheden i Nordshire. Er du klar til at rapportere?"},
  [22] = {c="Disse er bare perfekte, <Name>! Tusind tak. Bonde Saldeen og jeg skal feste i aften. Og her er en lille ting til dig for det hårde arbejde. Du troede vel ikke, at jeg ville lade en <Class> som dig gå sulten, vel?", p="Alt, hvad jeg behøver til min berømte kødpai, er 8 Blodsnuser-lever!"},
  [23] = {c="Ah, Bjørnegus' pote! Din dygtighed er imponerende, <Class>; han tilskrives talrige drab. Halvmånen på hans pote er uden tvivl et tegn på, at han blev trænet af nattealferne, der lusker rundt i Askedalen. Bjørnegus er... var en af de mægtigste bjørne, man kan finde i disse egne. At have overvundet sådan et væsen er et vidnesbyrd om din vilje og beslutsomhed.\n\nDine forfædre ville være stolte!", p="Ah - <Name> - jeg tænkte lige på dig! Hvordan går jagten?"},
  [24] = {c="En sejr for <Name> i Askedalen-jagten! Godt gået - Skyggedrøms hoved er et passende trofæ at gøre krav på for en så imponerende kamp, uden tvivl.\n\nSkyggedrøms vildskab var kendt over hele posten her. Enhver tur mod vest, især til fods på vej ud til Zoram-strandbredden, var fyldt med fare på grund af den tiger. Takket være dig er faren nu aftaget.", p="Hilsner endnu en gang, <Name>! Er du kommet for at vise mig beviset på din jagt?"},
  [25] = {c="Jo, jeg hørte, at nogen flåede søen derude op som en støvdjævel gennem Ødemarken. Ud fra det, jeg har hørt, kunne vi måske etablere et observationsområde derude for at holde øje med vores Alliance-venner. Altså, hvis vi kan holde det hemmeligt...\n\nDet ser ud til, du alligevel endte med at være ret nyttig; transporterne mellem her og Stenklippe burde få det lettere. Tag den her – du har fortjent den.", p="Er du allerede tilbage? Hvordan står det til derude - er alt ryddet op nu, takket være dig?"},
  [26] = {c="Hilsen, unge druide; tiden er kommet, til at du skal kende vores akvatiske skikkelse. Det er en, der lader dig bevæge dig frit og uendeligt gennem vand. Du vil finde dette aspekt et nyttigt redskab og en velsignelse... men det skal fortjenes, før det kan mestres.\n\nDu skal møde to prøver, der skal overvindes. Den første vil teste din evne til at arbejde i vand under tryk. Den anden vil teste din beslutsomhed i at forstå selve skikkelsens aspekter.\n\nStå klar, for prøvens tid er nu over os."},
  [27] = {c="Hilsen, unge druide; tiden er kommet, til at du skal kende vores akvatiske skikkelse. Det er en, der lader dig bevæge dig frit og uendeligt gennem vand. Du vil finde dette aspekt et nyttigt redskab og en velsignelse... men det skal fortjenes, før det kan mestres.\n\nDu skal møde to prøver, der skal overvindes. Den første vil teste din evne til at arbejde i vand under tryk. Den anden vil teste din beslutsomhed i at forstå selve skikkelsens aspekter.\n\nStå klar, for prøvens tid er nu over os."},
  [28] = {c="Nå nu, det ser ud til, at endnu en druide har fuldført Søprøven! Godt klaret, min unge ven - godt klaret.\n\nSom jeg har sagt, hedder jeg Tajarie. Det er min pligt og min ære at tjene som vogter for Månelunden, og især for denne helligdom. Vogter Remulos leder Cenarion-kredsen i bevarelsen af natur og balance, og hans helligdom er en varig hyldest til dette. Ved at bruge pyntetingen her nikker du anerkendende til, hvor vigtigt dette sted er inden for kredsen.", p="For at fuldføre Søprøven skal du bruge Helligdoms-pynten inden for denne helligdoms grænser. Indtil du gør det, forbliver din prøve uafsluttet, og den risikerer at mislykkes."},
  [29] = {c="Nå nu, det ser ud til, at endnu en druide har fuldført Søprøven! Godt klaret, min unge ven - godt klaret.\n\nSom jeg har sagt, hedder jeg Tajarie. Det er min pligt og min ære at tjene som vogter for Månelunden, og især for denne helligdom. Vogter Remulos leder Cenarion-kredsen i bevarelsen af natur og balance, og hans helligdom er en varig hyldest til dette. Ved at bruge pyntetingen her nikker du anerkendende til, hvor vigtigt dette sted er inden for kredsen.", p="For at fuldføre Søprøven skal du bruge Helligdoms-pynten inden for denne helligdoms grænser. Indtil du gør det, forbliver din prøve uafsluttet, og den risikerer at mislykkes."},
  [30] = {c="Du har gennemført Søløve-prøven, <Name> - lykønskninger.\n\nHver opgave i at skaffe vedhænget viser, at både smidighed og udholdenhed er nødvendige for at handle i harmoni med det, du ønsker at gøre under vandet. Ingen af delene kan eksistere uden den anden, og begge kan ikke gøres uden din villighed til at omfavne søløvens skikkelse.\n\nHusk disse lektioner godt, og stol på dem, når du har opnået din vandform.", p="Har du fået formet dit vedhæng, så jeg kan inspicere det, <Name>? Hvis du har brug for hjælp til at finde delene, så prøv at spørge de lokale om information. Ikke alene finder du det, du leder efter, men det giver dig også en grund til at udforske denne vidunderlige og hellige lysning."},
  [31] = {c="Meget imponerende, <Name>. Dine forfædre ville være glade for dine fremskridt! Du er klar til at lære din vandskikkelse, og det er mig en fornøjelse at lære dig den.\n\nSom anerkendelse af din præstation under de to prøver giver jeg dig også denne genstand. Jeg håber, du vil finde den en velkommen tilføjelse til dit udstyr, som naturens beskytter og balancens vogter.", p="Din tilbagevenden til Tordenklippe sker ikke uden fanfare, men jeg får brug for bevis på de lektioner, du har tilegnet dig i Månelunden, før jeg vil lære dig din akvatiske skikkelse.\n\nHar du Søløvens Vedhæng?"},
  [33] = {c="Du har været travl! Jeg kan ikke vente med at koge det ulvekød...\n\nJeg har nogle ting her, du måske har lyst til - vælg frit!", p="Hey <Name>. Jeg bliver sulten... fik du det seje ulvekød?"},
  [34] = {c="Endelig er plagen lagt i graven! Tak, <Name>, du har gjort mig en stor tjeneste. Haven skal stå i fuld blomstring denne sæson!", p="Er Bulkmave stadig i gang, eller fik du endelig renset Søshire for plagen én gang for alle?"},
  [35] = {c="Ja, mudderfisk har slået sig ned i og omkring åerne i østlige Elvendal. Vi ved ikke, hvorfor de er her, men de er aggressive og i det mindste halvt intelligente."},
  [36] = {c="Den Verna Rynkebryn var altid sådan en sød pige. Vi kommer til at savne hende her i Vestfald, men mellem dig og mig er hun en bypige i hjertet, og Stormvind passer hende fint. Men nok sladder! Nu kan vi lave Vestfald-gryde!", p="Jeg kommer til at savne den Verna Rynkebryn så meget. Jeg går ikke ud fra, du tilfældigvis så hende på vej herhen?"},
  [37] = {c="Selvom meget er blevet fjernet fra liget, ligger der i nærheden en medaljon med ordene „Fodsoldat Malakai Sten“ ridset ind i den."},
  [38] = {c="De Damefingre vil tykne denne bouillon fint! Nu tilsætter vi bare det Sej Gribbekød, nogle Mudderfisk-øjne og de dejlige Blodsnuser-snuder. Og så er vi færdige! Som tak for al din hjælp, <Name>, vil jeg have dig til at tage dagens første portion Vestfald-gryde!", p="Kom tilbage med følgende ingredienser:\n\n3 Sej Gribbekød\n3 Blodsnuser-snuder\n3 Mudderfisk-øjne\n3 Damefingre"},
  [39] = {c="Hmm, de her nyheder er bekymrende. Vores forsvar er allerede tyndt udspredt, og at miste Rolv og Malakai til de mudderfisk sætter os i en endnu værre stilling.\n\nHvis tingene ikke bliver bedre, bliver der kæmpet i Guldshire inden ugens udgang!"},
  [40] = {c="Ja, jeg talte med Remi. Jeg respekterer ham som købmand, selvom alle rapporter om Mudderfisk mod øst i bedste fald har været tvivlsomme.\n\nDine bekymringer er noteret, men medmindre jeg modtager en militærrapport om en mudderfisk-trussel, har vi ikke råd til at sende flere tropper mod øst."},
  [45] = {c="Om halsen på liget finder du en metalmedaljon, indgraveret med ordene \"Fodsoldat Rolv Hjortevad.\""},
  [46] = {c="Har du finnerne? Fremragende! Marskal Dughan er bekymret over mudderfisk-situationen i det østlige Elvendal, og jeg vil gerne fortælle ham, at den er ved at komme under kontrol.\n\nDine handlinger har hjulpet med at få det til at ske.", p="Hvordan går jagten, <Name>?"},
  [47] = {c="Tak for støvet, <Name>. Her er dine kontanter, og...her er et mærke fra nogle af mine forretningsforbindelser. Du kan måske finde det nyttigt...nyttigt.", p="Psst! Har du det Guldstøv til mig... til mig?"},
  [52] = {c="Mange tak for hjælpen, <Name>. Noget i skoven må gøre disse dyr så frække.\n\nUanset hvad det er, håber jeg, at det bliver der.", p="Har du dræbt de ulve og bjørne?"},
  [54] = {c="Nå, der står her, at du er blevet tildelt status som Virkende Stedfortræder hos Stormvinds Marskalker. Tillykke.\n\nOg held og lykke - at holde Elvendal sikker er ingen dans på roser... med det meste af hæren optaget af at gøre ved ved-ikke-hvad for ved-ikke-hvilken adelsmand!\n\nDet er svært at holde styr på politikken i disse mørke tider...", p="Har du bud fra McBride? Nordshire er en have sammenlignet med Elwynnskoven, men jeg undrer mig over, hvad Marskal McBride har at rapportere.\n\nHer, lad mig få hans papirer..."},
  [55] = {c="Morbent Ondt er blevet besejret. De mørke ryttere er stadig på fri fod, men en lille del af det, jeg havde håbet inderligt på, er gået i opfyldelse.\n\nDu har gjort det umulige, og dine bedrifter vil for evigt leve i Skumringsskovens legender.\n\nGå, <Name>. Og måske, en dag, vil skæbnen føre dig tilbage til mig...", p="Er Morbent Ondt besejret?!"},
  [56] = {c="Storartet, <Name>. For din tjeneste for Mørkeshires folk skal du belønnes.", p="Jeg ser, at du er tilbage, <Name>. Hvis du vil bevise, at du kan være til nytte for Nattevagten, så vend tilbage til mig, når du har slået 8 Skeletkrigere og 6 Skeletmagiker ihjel."},
  [57] = {c="Folket i Mørkeshire takker dig, <Name>. Du har bevist, at du er en stor allieret for Nattevagten.", p="Kom tilbage til mig, når du har dræbt 15 Skeletdæmoner og 15 Skeletgysere, <Name>."},
  [58] = {c="På vegne af folkene i Mørkeshire og som Leder af Nattevagten takker jeg dig, <Name>, for dit mod og din hengivenhed. Må Lyset skinne på dine veje.", p="Jeg har brug for din hjælp, <Name>. Rejs til kirkegården mod nordvest og rens det østlige mausoleum for 20 Pestspredere.\n\nVend tilbage til mig, når din opgave er udført."},
  [59] = {c="Ah, tak for mærket. Vælg gerne den rustning, du foretrækker.\n\nHeld og lykke, modige <Class>. Og må denne rustning tjene dig godt.", p="Jeg er blevet bestilt af Stormvindsk Hær til at forsyne deres folk med klæde- og læderrustninger.\n\nHvis du har et Stormvindsk Rustningsmærke til mig, så vil jeg være glad for at lave noget til dig."},
  [60] = {c="Så du har travlt med at jage kobolder, hva'? Tak for lysene, <Name>, og her er din belønning...", p="Har du samlet de stearinlys endnu?"},
  [61] = {c="Her er din betaling ... og mens du er her, så kig dig omkring! Jeg er sikker på, at vi har en eliksir eller et andet krimskrams, du ville synes er nyttigt."},
  [62] = {c="Det er dårlige nyheder. Hvad bliver det næste, drager?!? Vi bliver nødt til at øge vores patruljer nær den mine. Tak for din indsats, <Name>. Og hold lige et øjeblik... Jeg har måske en anden opgave til dig.", p="Hvad har du at rapportere, <Name>? Har du været i Fjerndyb-minen?"},
  [63] = {c="Du placerer armbeskytterne oven på kulbækkenen og hælder derefter de resterende dråber af Saltlages eliksir i flammen. Dråberne sprutter, da de rammer flammen, og du begynder at fremsige de simple ord, Isleif lærte dig....", p="Bålskålen reflekterer stadig det omgivende lys fra området, og flammen flytter sig en smule, når du kommer tættere på.\n\nKorruptionen langs bakkerne ser ud til at have holdt sig på afstand, og bortset fra de manglende komponenter ser bålskålen klar ud til ritualet, der skal tilkalde en renset manifestation af vand."},
  [64] = {c="Min vagt! Tusind tak, venlige herre!\n\nVi er blot fattige bønder, og vi har mistet vores jord, men modtag venligst denne belønning som et tegn på vores taknemmelighed.", p="Undlad at tro, du har fået fat i mit ur?"},
  [65] = {c="Så, Tykfrakke har sendt dig? Nå, jeg står i gæld til ham."},
  [66] = {c="Ah, så Frue Eva sendte dig. . . ."},
  [67] = {c="Den gamle fodskrin knirker op. . . ."},
  [68] = {c="Interessant. Så fyren brugte alligevel noget tid i Månebæk. Det er ret mærkeligt, at brevet aldrig blev leveret. Ikke desto mindre vil jeg opdatere registret.", p="Ah, jeg husker dig. Du er den, der spurgte til den Stalvan-fyr. Fandt du nogensinde det, du ledte efter?"},
  [69] = {c="Stalvan? Lyder da bekendt."},
  [70] = {c="Du har godt nok en pokkers nerve til at komme herind med det her.", p="Hvad har du så dér? Lad mig lige kigge på det. . ."},
  [71] = {c="Du har bekræftet mine frygt, <Name>. Mudderfiskene er en trussel, vi ikke kan ignorere.", p="Hej, <Name>. Har du opdaget skæbnerne for Rolf og Malakai?"},
  [72] = {c="Du skubber langsomt lågen af kassen. . . ."},
  [74] = {c="Jeg kan knap nok tyde de bogstaver. Men den skrivestil minder mig om noget, jeg engang så, før mit syn blev så dårligt.", p="Hvad har du dér? Jeg kan ikke se. Mit syn er meget dårligt. Læg det i mine hænder."},
  [75] = {c="Du fandt det!", p="Har du fundet den side, jeg nævnte, <Name>?"},
  [76] = {c="Kobolderne i Jaspisåre-minen, siger du? Forbandelser! Situationen bliver værre for hvert minut!\n\nTak for rapporten, <Name>. Men jeg ville ønske, at nyheden du bragte var god nyhed.", p="Hilsen, <Name>. Hvad har du at rapportere? Har du spejdet Jaspisåre-minen?"},
  [78] = {c="Ved Let! Det kan du bande på, at jeg genkender den håndskrift.", p="Marskal Udmattet sendte dig? Hvorfor sagde du det ikke?\n\nÅh, gode gamle Hærget. Stakkels kar bliver snart fuldstændig blind. Men lad mig se, hvad du har dér."},
  [79] = {c="Åh, du har vist dig at være en ganske formidabel detektiv, <Class>.", p="Det må være godt, <Class>. Lad mig se, hvad du har, og fortæl mig din historie. Men for Lets skyld, vær hurtig. Mørkeshires forsvar er min første prioritet. Jeg har ikke tid til at spilde på blindgyder."},
  [80] = {c="Jo da! Skriften på denne side passer faktisk med registerunderskrifterne.", p="Tilbage igen, <Name>? Hvad har du med denne gang?"},
  [83] = {c="Ah, de her er pæne halstørklæder, om end lidt grove...\n\nVær så god!", p="Jeg løber tør for linned, <Name>. Har du noget til mig?"},
  [84] = {c="Mm, nam! Den tærte er den bedste!\n\nJeg tror, min erindring er ved at vende tilbage til mig...", p="Uh... jeg er sulten! Har du den tærte til mig, <Name>?"},
  [85] = {c="Du mistede hvad? Nå, jeg tog ingen halskæde, for jeg er ingen tyv!\n\nJeg ved måske, hvem der gjorde det, men...<grinner>...jeg er for sulten til at huske det."},
  [86] = {c="Selvom dette vildsvinekød er sejt, så lad det simre længe nok, og så bliver det da en lækker tærte!", p="Jeg synes ikke, det er rigtigt at fodre drengen, der stjal min halskæde i første omgang, men hvis det er det, der skal til for at få det tilbage, der er mit, så være det!\n\nHar du det vildsvinekød?"},
  [87] = {c="Åh, du fandt den! Tak, tak, kære!\n\nHer, tag den her. Den var min mands, og han sagde altid, at den bragte held. Hvis han bare ikke havde glemt den på sin sidste kampagne! *snøft*", p="Hej, <Name>. Har du fundet min halskæde?"},
  [88] = {c="Heldigvis! Den gris var ved at blive så stor, at hun ville have ædt hele vores høst! Tak, <Name>.\n\nNu, passer nogen af disse dig?", p="Har du set hende endnu? Fik du fat i hende?"},
  [89] = {c="Stor gerning, <Name>. Disse forsyninger vil hjælpe brobyggeriet enormt. Vi får denne skønhed støttet op på ingen tid.", p="Denne bro bygger sig ikke selv! Hvor er de jernpigge og jernnitter nu henne?"},
  [90] = {c="Meget flot arbejde, <Name>! Nyd delikatessen kendt som Krydrede Ulve-kebab!", p="Har du fundet 10 Magre Ulvesider endnu? Hvad med urterne fra Lykkelia i Stormvind?"},
  [91] = {c="Hoffet i Søshire anerkender din hengivenhed over for retfærdighed, <Name>. Ved at håndhæve Rigets love har du hjulpet med at opretholde landets retfærdighed.", p="Aflever 10 Skyggeskjul-vedhæng til mig, så skal du blive belønnet."},
  [92] = {c="Godt klaret, <Name>. Og sådan nogle fine eksemplarer! Og her er din lækre delikatesse, kendt som Rødryg-gullasch!", p="Jeg mangler stadig fem stykker Sejt Kondorkød, fem Store Blodsnuser-snuder og fem portioner Sprødt Edderkoppekød."},
  [93] = {c="Ah ja, en flot klump ben har du dér! Lad mig lige få dem krydret med mine hemmelige krydderier (ingen kiggen!) og få dem til at sprætte og knitre på en pande et stykke tid...\n\nOg selvom Skumrings-krabbekager er min specialitet, og jeg ikke giver opskriften ud, så er her opskriften på en ret, der er næsten lige så god.", p="Hilsen, <Name>. Har du fået Klistret Edderkoppeben endnu?"},
  [94] = {c="Du placerer Azoras Glyf på stenen. Den hæfter sig fast ... og du hører Teokritos' legemløse stemme komme derfra:\n\nDu har min taknemmelighed, unge <Name>. Du kan nu tale med mig gennem dette Glyf, og jeg har måske fremtidige opgaver til dig ... efter jeg har gennemrodet min rivals tanker.", p="Denne Løvestatue har stået her i årtier og holder en ensom vagt over det berygtede Ilgalars Tårn.\n\nDer er en fordybning ved statuens fod, hvor en ædelsten eller glyf måske kan sættes..."},
  [95] = {c="Her ligger en vold af jord, hastigt opstablet, som om nogen havde brug for at gemme noget... uden meget tid til at gøre det."},
  [97] = {c="Jeg vidste det! Fint arbejde, <Name>.", p="Ja, <Name>?"},
  [98] = {c="Jeg ved det, <Name>: Stalvan er død. Jeg mærkede en bølge af håb skylle gennem den forurenede skov. Endelig og for altid er Skumringsskoven fri for hans blodtørst. Min glæde dæmpes dog af tanker om dem, der faldt offer for det forfærdelige udyr. Ikke desto mindre er du en modig og snedig <Class>.", p="Ja, <Name>?"},
  [99] = {c="Din vedholdenhed er prisværdig. Med den viden, du hjalp mig med at samle, vil Arugel falde, og hans hensynsløse magi skal ophæves. Skål for dig, <Name>.", p="Har du sikret Brandtræ-lænkerne endnu, <Name>?"},
  [101] = {c="Meget klogt af dig, <Name>. Dette Pinetotem vil hjælpe med at beskytte dig mod det onde, der lurer over hele Azerot og videre. Når du føler dig truet, så hold fast i denne totem og find trøst i dens magiske glorie. Vær modig, retfærdige <Class>. Du får brug for al den tapperhed, du kan samle, for jeg ser meget blodsudgydelse i din fremtid.", p="Bring mig 10 gravgyser-hugtænder, 10 skeletfingre og 5 hætteglas edderkoppegift. For dig vil jeg fortrylle et Pinetotem, som skader dem, der forsøger at udøve vold mod dig."},
  [102] = {c="Godt klaret, <Name>. Med modige eventyrere som dig, der kæmper side om side med Folkemilitsen, kan Vestfald måske vende tilbage til den velstående kornkammer, det engang var. Modtag venligst dette som anerkendelse for din utrættelige indsats.", p="Har du samlet 8 poter fra de forræderiske gnoller endnu?"},
  [103] = {c="Lovet være du, modige <Class>. Klipperne ved Vestfaldkysten skal lyse op takket være dit hårde arbejde. Mange liv vil blive skånet, så længe fakkelen holdes tændt.\n\nJeg døde unødigt på netop denne strand. Min straf i det hinsidige er at sørge for, at ingen andre følger min skæbne.", p="Flammen vil ikke brænde længe uden olie, <Name>."},
  [104] = {c="Så den usle hedning, Dynd-Øje, er død. Velgjort, <Name>. Ved din hånd blev ét liv lagt til hvile, men måske blev mange flere reddet. Det Store Hav, så farligt det er, bliver en lillebitte smule sikrere i nat takket være din heltedåd.", p="Har du lagt øde til den plage, der kendes som Gamle Mørkøje, endnu? Han er set vandre langs kysten af Vestfald.\n\nVend tilbage til mig, når det snavsede udyr er dødt."},
  [106] = {c="Ah! Jeg kan ikke holde ud, at vi er adskilt. Jeg må se hende!!", p="Du har hvad?? Majbelle er lyset i mit kedelige liv. Skynd dig, lad mig se hendes brev!"},
  [107] = {c="Mit hjerte går ud til de to stakkels sjæle, Majbelle og Tommi Jøe. Jeg husker, at jeg engang var ung og forelsket.\n\nDer må da være noget, jeg kan gøre for at hjælpe dem! Lad mig tænke...", p="Du har en seddel fra \"Bedstemor\" Stenmark, hva'? Jeg har ikke set Mildrid i årevis! Jeg spekulerer på, hvad hun har at sige..."},
  [109] = {c="Ah, så min ven sendte dig hertil? Hvor venligt.\n\nNå, Stormvind-monarkiet har opgivet vores sag. Nu er det op til Folkemilitsen at holde landet fri for korruption. Hvis vores sag interesserer dig, kan jeg sætte dine kampfærdigheder i frihedens tjeneste."},
  [111] = {c="Mens vores familier er i fejde, har Tommi Jøe og Majbelle ikke meget fremtid, men... måske kan vi få dem sammen en lille stund.\n\nHm, hvad kan vi gøre...", p="Jeg kan ikke vente med at høre, hvordan mine venner reagerer!\n\nDe vil aldrig forvente det"},
  [112] = {c="Du fik dem. Godt klaret! Vent lige et øjeblik, mens jeg brygger eliksiren...", p="Har du den krystaltang? Jeg er sikker på, at Majbelle er ivrig efter at se sin frier..."},
  [114] = {c="Åh... min! Jeg har dårlig samvittighed over at narre min familie, men mine følelser for Tommi Jøe er for stærke til at ignorere.\n\nTak, <Name>. Jeg drikker denne likør, så snart jeg får sjansen, og sniger mig væk til min elskede.\n\nOg til dig... tag venligst den her.", p="Afleverede du mit brev til Tommi Jøe? Hvad sagde han??"},
  [115] = {c="Tak, <Name>. Jeg sender disse afsted til ødelæggelse med det samme.", p="Hvordan går din konflikt med Skyggekasterne? Fandt du midnatskuglerne?"},
  [116] = {c="Et veludført stykke arbejde, <Name>! Jeg kender godt de veje, du måtte rejse for at skaffe denne fine samling spiritus. Men mine kunder bliver glade igen!\n\nMin kone er en ret dygtig syerske. Accepter venligst denne kappe, hun har syet, som tak for din tjeneste.", p="Jeg vil have dig til at hente en tønde Tordenbryg Lagerøl fra Grimsøl Tordenbryg i Vestfalds bakker, et fad Morlot fra Stormvind, en flaske Månebrændevin fra Mørkeshire og en skindsæk Sød Rom fra Guldshire. Bring dem tilbage til mig, så sørger jeg for, at du bliver belønnet."},
  [117] = {c="Humle og Byg, gær og malt\nSmagsløgene får et virtuelt overfald,\nIngen grund til at klynke, ingen grund til at bede\nFor Tordenbryg Lagerøl kommer ud af tønden med glæde!", p="Skynd dig, min ven, træd til med hast\nSå vores rige lager kan smage\nMere som øl og mindre som suppe,\nHumle skal der til for at brygge brygget."},
  [118] = {c="He, så gamle Værner har altså brug for nogle sko, hva'!?!", p="Hvad er det? Værner har sendt dig, siger du? Nå, giv mig hans seddel. Og TAL HØJERE!"},
  [119] = {c="Tak, det hjælper mig virkelig.\n\nMen hvad er det her? Argus sendte en seddel med kassen... Hvad?? Argus vil have, at JEG skal BETALE ham? Bah!\n\nNå, <Name>, tak for din hjælp.", p="Stor, du er tilbage! Fik du skoene?"},
  [120] = {c="Hvil dig, <Class>.\n\nDommer Salomon er en ædel leder. Hans ord vejer tungt hos mig. Jeg vil søge rådgivning hos Kongen og gøre situationen klar for ham. Forsikr den gode dommer om, at han har støtte fra Stormvindsk Hær. Forstærkninger bliver sendt, så snart ordet er givet fra Hans Majestæt.", p="Hvad har du dér?"},
  [121] = {c="Tak for din tid, <Class>. For din tjeneste for Søshire og Stormvind belønner jeg dig med disse mønter.\n\nNu, hvis du undskylder, finder jeg denne korrespondance noget af en gåde. Noget er galt i vores Rige. Jeg frygter, at dette er begyndelsen på en konflikt, ikke enden.", p="Har General sendt nyheder? Er forstærkninger påvej?"},
  [122] = {c="Tak! Disse vil få mig ud af gælden til Argus...", p="Jeg ved, at den grådige Argus sender nogen for at hente hans skæl, hvis jeg ikke snart giver dem til ham. Har du fundet de skæl endnu?"},
  [124] = {c="Tak for al din hjælp, <Name>.", p="Mine heste virker stadig nervøse, og jeg hører stadig det forbandede ulvens råb om natten. Vær sød, <Name>, gør noget ved de gnoller!"},
  [125] = {c="Fremragende genfinding, <Name>! Jeg troede aldrig, jeg skulle se disse værktøjer igen.", p="Fandt du mine værktøjer?"},
  [126] = {c="Igen, tak for din hjælp. Stormvindsk hær har så travlt med at tage sig af orkerne, at de ikke har tropper nok til at beskytte Rødryg mod lokale trusler som gnoldene.", p="Hyleren er et farligt væsen, <Name>. Hvis du ikke er klar til ham, forstår jeg det."},
  [127] = {c="Fornøjelse at handle med dig, makker!", p="Har du nogle solfisk til mig, hva'?"},
  [128] = {c="Jeg ser, du har kæmpet tappert mod Sortklippe-klanen, <Class>. Din tjeneste for vores by er virkelig stor.", p="Kom tilbage, når du har dræbt 15 Sortklippe-kæmper."},
  [129] = {c="Tak, jeg kunne virkelig trænge til måltidet. At vogte Søshire mod orkerne og gnollerne er hårdt arbejde!", p="Darsy sendte mig en frokost, gjorde hun? Sådan et venligt hjerte hun har. Nå... lad os få den!"},
  [130] = {c="Har du brug for en buket blomster? Du har ikke været i byen ret længe... har du allerede fundet dig en kæreste her?\n\nJeg ved, at jeg ikke burde spørge, men det er dejligt at se, at kærligheden er i luften... især i farlige tider som disse."},
  [131] = {c="Åh, de er dejlige! Jeg kan ikke vente med at putte dem i noget vand!\n\nMen... det her er Martes yndlingsblomster. Parkér sendte dig vel ikke til den jaloux rævinde efter denne buket? Du fortalte hende vel ikke, hvem de var til? Hvis du gjorde, ville det ikke overraske mig, hvis hun forgiftede dem.\n\nÅh, men det er ikke din skyld. Tak, og her er din mad.", p="Hej igen, <Name>. Kunne Parkér lide den frokost, jeg sendte ham?"},
  [132] = {c="Bah! Jeg skulle have ladet den skurk rådne, dengang jeg havde chancen. Men denne information er afgørende. Godt arbejde.", p="God at se dig igen, <Name>. Hvad havde Snedig at sige for sig selv?"},
  [133] = {c="Ah, tak. Disse gør lige præcis det rette trick!", p="Jeg tror, jeg hører en flok Gule skurre rundt bag huset - jeg må hellere få den figur op hurtigt! Fik du de Gule Ribbenspjæld til mig?"},
  [134] = {c="Tak til Nek-...nå, tak til DIG, <Name>! Du har mere end fortjent din belønning.\n\nAha! Glad! Glade nætter forude!!", p="Har du min kasse? Hvis ja, så vær sød... giv den til mig hurtigt!"},
  [135] = {c="Denne sag er måske mere kompleks, end Tykfrakke indser.", p="Hvad har du at gøre med mig? Jeg er en yderst travl mand. . ."},
  [136] = {c="Fodskrinet knirker langsomt op. Sand og vand synes at være dets eneste indhold. Men vent! En lille krabbe ilter ud med et spor til skatten i sine klør!"},
  [138] = {c="God gerning, skattejæger!"},
  [139] = {c="Du er på vej mod jackpotten, skattejæger!"},
  [140] = {c="Hængslerne på den gamle kiste er rustne, men de virker stadig. Du tvinger kisten op og tager byttet.\n\nTillykke!"},
  [141] = {c="Edwin VanKløft. . .Jeg kender navnet godt. At en mand så flittig og talentfuld kan udvikle sig til sådan en skurk, gør mig urolig. Jeg skal bruge yderligere beviser, før jeg tror på det.", p="Kastede Mester Skaw noget lys over tingene?"},
  [142] = {c="Det er bestemt et fast bevis på, at VanKløft har magten. Nu skal vi bare vide, hvor Defias-banden gemmer sig.\n\nVi har haft et lykketræf, mens du var væk. Vi fangede en tyv, der forsøgte at stjæle Saldeans vogn. Han har lovet at føre os til skjulestedet i bytte for sit liv. Jeg vil have dig til at forsvare forræderen, så han kan afsløre skjulestedet. Vend tilbage til mig, når du har afdækket placeringen.", p="<Name>, var du i stand til at samle nogen information? Fandt du budbringeren?"},
  [143] = {c="God Budbringer, du har tjent din herre brønd.", p="Hilsen, <Class>. Hvad har du at gøre hos Folkemilitsen?"},
  [144] = {c="Jeg må sige, at det her slet ikke er godt. Jeg indså ikke, at Tykfrakkes situation var så forskellig fra vores her i Søshire. Hvilken handling er så vigtig, at den kalder Stormvindsk Hær væk fra sit folk? Bah, jeg burde ikke grubler over det højt.\n\nSå, budbringer. Accepter disse mønter som betaling for din tjeneste for Kommunen. Jeg kunne finde på at kalde på dig igen.", p="Skal vi forvente Folkemilitsen snart? Varsler Lord Tykfrakkes nyheder noget godt?"},
  [145] = {c="Tak, fordi du tog den lange rejse hertil. Dette er i sandhed vigtige oplysninger.", p="Du ser ud til at være rejst langt hjemmefra, <Class>. Hvad har du at bestille her i Mørkeshire?"},
  [146] = {c="Ved Let! Stormvindsk Hær trak sig tilbage fra Vestfald. Og Vagten beskytter ikke længere Mørkeshire? Der er forræderi i den grad på færde. Hvordan kan det være sådan?\n\nJeg glemte at belønne din tjeneste, <Class>. Her er nogle mønter. Undskyld mig nu. Der er noget galt i Stormvind, og jeg må komme til bunds i det.", p="Ah, godt at se dig tilbage, budbringer. Skal jeg underrette marskallen om, at Nattevagten er på vej fra Mørkeshire?"},
  [147] = {c="Har du fundet ham? Godt gået, <Name>. Han kommer ikke til at \"opkræve\" fra Elvendal-minerne igen!\n\nOg denne ring, du fandt, er interessant... det er en medlemsring fra det gamle Stenhuggerlaug i Stormvind. Hvorfor skulle en ussel tyv have en håndværkerlaugs-ring, og hvorfor opkræver Defias-tyvene penge fra vores miner?\n\nSvære spørgsmål. Jeg håber, at vi en dag får svar.", p="Har du fundet Samleren? Har du opdaget, hvem han arbejder for?"},
  [148] = {c="Ah, så du har brug for Spøgelseshår-tråd, er det? Jeg er bange for, at jeg ikke har noget på lager, men jeg kan lave noget til dig...hvis du kan skaffe spøgelseshåret."},
  [149] = {c="Hvad er det her? En kam? Den er dejlig! Og den glider gennem mit hår, som om det ikke var den stive, strittende rædsel, det egentlig er.\n\nÅh, hvis bare jeg havde et spejl...", p="<Hulk> Åh, for guds skyld, se ikke på mig! Jeg rev disse øjne ud med mine egne hænder, men jeg kan stadig mærke dit blik!\n\nJeg er grusom! Grusom! Vær sød at se væk!!"},
  [150] = {c="Brønd forvoldt, <Name>. Jeg håber, du ikke havde for meget besvær med de mudderfisk.\n\nDet er mærkeligt at se dem så langt fra havet. Jeg undrer mig over, om de er her, fordi de løber fra noget...", p="Har du de finner? Skynd dig, vi skal have de mudderfisk fordrevet fra søen!"},
  [151] = {c="Tusind tak, <Name>! Stakkels Gamle Blegmule bliver så glad!", p="Gamle Blegmule er ved at give op. Fandt du tilfældigvis nogen havre til hende?"},
  [152] = {c="Godt klaret, <Name>. Du har et stort talent for kamp. Takket være dig er Vestfaldkysten et tryggere sted.", p="Dræb 7 Tidevandsjægere, 7 Krigere, 7 Orakelerne og 7 Kystløbere, så skal jeg sørge for, at du bliver belønnet."},
  [153] = {c="Godt arbejde, <Race>. Tag venligst et af disse emner som betaling for al dit hårde arbejde.", p="Bring mig 15 røde læderbandanaer, så betaler jeg dig godt."},
  [154] = {c="Jeg kan lave en spole Spøgelseshår-tråd af dette og have et par tråde til overs. Her er nogle mønter til de ekstra tråde.", p="Jeg fornemmer, at du har set Blinde Mary. Har du min Kam...?"},
  [155] = {c="Aldeles fortrinligt, <Name>! VanKløft er næsten vores nu, da vi ved, hvor han gemmer sig.", p="Hvad har du at gøre med mig? Jeg er en meget travl mand..."},
  [156] = {c="God, du fik rådne blomster. Og jeg vil fortælle Althea Ebenlås fra Nattevagten, at du dræbte skeletter.\n\nAt holde Mørkeshires folk i sikkerhed er en dyster byrde for Nattevagten, og nyheden om, at andre hjælper med at dæmme op for djævlene i Skumringsskoven, er virkelig velkommen.", p="Hej, <Name>. Har du de rådne blomster til mig endnu?"},
  [157] = {c="Herligt! Det her duer fortræffeligt...\n\nVær så god, gode <Name>, tag dette som betaling for din ærefulde dåd.", p="Jeg skal hænge Spøgelseshår-tråden op ved min dør og mine vinduer for at holde uønskede ånder ude. Fik du den til mig?"},
  [158] = {c="Har du brug for noget zombiesaft? Hmm... det er noget stærkt stads - jeg får ikke ofte forespørgsler om det."},
  [159] = {c="Tusind tak, <Name>. Du varmer en gammel mands hjerte med dit tåbelige-... jeg mener... med din venlighed!\n\nVær så venlig, ven. Tag det her som et Mærke på min taknemmelighed.", p="Jeg har brug for den Zombiesaft til at holde mig varm på disse kolde, mørke nætter. Fik du den til mig?"},
  [160] = {c="<Ello kigger på brevet...>\n\nHvilket sprog er dette? Det ser gammelt ud...jeg kan ikke læse det.", p="Abercrumbie...? Jeg kender ingen ved det navn. Siger du, at du har et brev til mig fra den Abercrumbie-fyr?\n\nNå, lad os så have det..."},
  [161] = {c="Ah, nå, Gl' Hinderweir er klog nok til at være bekymret.", p="Siger du noget, din lille knægt? Kan ikke høre en forbandet skid for den evindelige ringen i mine ører. Men hvad er det, du har dér?"},
  [163] = {c="Nej! Dræb mig ikke, vær venlig! Det er bare mig... Rysterne!! De er overalt... Jeg kan ikke undslippe dem! Uhyrer i Ravnehøj? N-n-n-nej... det kan ikke være. Kun uskadelige Ryster."},
  [164] = {c="Disse forsyninger vil komme til stor nytte. Carevin-familiens bistand er altid velkommen. Her er en lille ting for din besvær.", p="Du ser ud til at være en robust type, <Class>. Er du kommet for at slutte dig til vores kamp?"},
  [165] = {c="Ellen Carevin? Hehe, åh ja... selvfølgelig, Carevin-familien.\n\nNej, der er ikke noget galt, men det er svært for mig at gå ind i byen nu. Vejene er farlige, og jeg bliver heller ikke yngre. Måske kan du gøre en gammel mand en tjeneste?"},
  [166] = {c="<Name>, din tapperhed er bemærkelsesværdig. Folkemilitsen takker dig for din tjeneste for Vestfalds folk. Med VanKløft død markerer dette begyndelsen på enden for Defias-broderskabet. Forhåbentlig vil freden snart igen pryde denne skønne lands sletter.\n\nJeg salutterer dig, Ridder!", p="Hvordan går jagten på Edwin VanKløft?"},
  [167] = {c="Mine mistanker var korrekte. Min stakkels bror.... Nå, tak fordi du bragte en afslutning på dette mysterium, selvom afslutningen var dyster.", p="Fandt du noget tegn på min bror? Er der overhovedet noget håb efter al denne tid?"},
  [168] = {c="Tak for at samle disse op, <Name>. Din indsats vil hjælpe med at bringe fred til de døde i kølvandet på denne tragedie. Jeg sørger for, at familierne bliver underrettet.", p="Kunne du hente nogle af min gamle kollegas Minearbejderforenings-kort?"},
  [169] = {c="Fantastisk arbejde, <Name>! Gath'Ilsnavs førte de brutale udyr i slag og dræbte mange uskyldige mennesker. Retfærdiggørelsen er vores. Dette er første skridt til at generobre fæstningen for kongeriget Stormvind!", p="Hvad har du dér, <Race>?"},
  [170] = {c="Hvis de problemer, vi har haft her, er tegn på, hvad der sker andre steder i vores lande, ved Magnies skæg, så står vi over for nogle problemer! Jeg kan kun håbe, at kongen og Senatet tager skridt til at tage sig af truslen fra troggerne.", p="Seje små kryb, er de ikke?"},
  [173] = {c="Imponerende, <Name>. Det lader til, at du er dygtig nok til at klare dig selv. Måske kunne der findes en mere passende udfordring til en af dine evner.\n\nNysgerrigt nok... Varulvene syntes bare at dukke op ud af den blå luft. Men med alle de andre mærkelige væsener, der har bevæget sig hen over vores grænser, må jeg antage, at det kun er en af mange bekymringer.", p="<Name>, hvordan går jagten?"},
  [174] = {c="Det er perfekt, <Name>. Det første trin er fuldført!", p="Har du fundet en dygtig ingeniør, der kan lave et bronzerør endnu?"},
  [175] = {c="Jo da, jeg ejede engang et kigglas."},
  [176] = {c="Hah! Godt gået! Jeg begyndte at tro, at ingen ville nedlægge det uhyre!\n\nVær så god, <Name>. Og tak - den Gnold gav mig en hovedpine på størrelse med Sortklippe-spiret!", p="Ja, Hugger har været en ægte smerte for mig og mine mænd. Har du noget at rapportere om udyret?"},
  [177] = {c="Helt fremragende! Det her vil fungere perfekt. Mange tak!", p="Jeg viste Tandhjul begyndelsen til vores stjerneudkigs-maskine. Han var imponeret. Fandt du tilfældigvis en reflekterende indretning?"},
  [178] = {c="Du har min taknemmelighed, <Name>. Jeg sendte den besked til Skyggeskjul-vedhængene for flere uger siden og troede, at den var mislykket. Men det ser ud til, at besværgelsen nåede i det mindste nogle af vedhængene, efter en betydelig forsinkelse.\n\nMed tiden håber jeg at lære, hvordan man sender et angreb gennem vedhængene, så de immobiliserer de Skyggeskjul-gnolde, der bærer dem.\n\nMen før det er muligt, er jeg bange for, at der kræves meget mere forskning.", p="Jeg talte til dig gennem en halskæde, siger du? Hmm... giv den til mig, så jeg kan studere den."},
  [179] = {c="Ah! Vidunderligt. Ulvekødet burde gøre det fint. Åh, bare rolig, <Name>, jeg ville ikke glemme min del af handlen. Her, en af disse burde passe dig.", p="Ulve giver dig lidt besvær? Du gør klogt i at undgå hugtænderne, klørne og andre skarpe dele, ja?"},
  [180] = {c="Så den onde Løjtnant Hugtand er død? Godt rids for det ulækre væsen. Du er meget modig, <Class>. Søshire-byen takker dig for din hjælp.", p="Hvilke nyheder bringer du for Hoffet?"},
  [181] = {c="Endelig! Stjerneskuemaskinen er færdig! Tak, <Name>. Nu kan jeg fortsætte min forskning. . .", p="Kunne du overtale Zzarc'Brøl til at låne os sit monokel til vores eksperiment?"},
  [182] = {c="Argh! De Let-sprængte trolde!\n\n<Han tager et par vejrtrækninger og virker til at falde lidt til ro... lidt.>\n\nEn flok af dem kom om natten og stjal min dagbog! Jeg vidste bedre end at stole på den dugenikts lærl...", p="Fra det jeg har lært, stammer disse trolde fra Frostmanke-klanen. Jeg er bange for at jeg ikke ved meget andet om dem der ville være til nogen som helst nytte for dig, <Name>."},
  [183] = {c="Fremragende! Nu kan jeg vende tilbage til mine... afslappede... jagter. Tak, <Name>.", p="Hvordan går jagten?"},
  [184] = {c="Masser af tak, <Name>! Som jeg sagde, er disse egne ikke længere egnede for ærlige folk, men hvis tingene bliver bedre, så lader denne gerning os genvinde vores land.\n\nJeg har ikke meget at tilbyde dig, men værsgo -- tag den her.", p="Har du skødet til min gård?? Det er gode nyheder! Nogle ruffianer stjal det for flere dage siden... Jeg troede, det var væk for godt!\n\nVær sød, lad mig få det. Vi er på vej ud af Vestfald og kommer ikke tilbage foreløbig, men hvis vi gør, så får vi brug for de papirer..."},
  [185] = {c="Godt gået, <Name>. Du er klar til at gå videre.", p="Jeg føler mig ikke tryg ved at træne dig videre, <Name>, før du har bevist, at du er dygtig til at slå de yngste af tigrene først."},
  [186] = {c="Jeg er imponeret, <Class>. Du klarer dig ganske glimrende.", p="Hvis du stræber efter større udfordringer, må du først bevise dig selv med opgaven ved hånden. Vend tilbage til mig, når du har dræbt 10 Kvælerdorn-tigre."},
  [187] = {c="Imponerende. Jeg tror, du næsten er klar.", p="Du skal dræbe 10 ældre Kvælerdorn-tigre, før jeg giver dig den sidste udfordring, der afgør, om du er en sand tigerjagt-herre."},
  [188] = {c="Imponerende, siger jeg! Du er en sand Mestertigerjæger, <Name>!", p="Hvordan går jagten på Syndal?"},
  [189] = {c="Åh, udmærket, udmærket. Det hjælper lidt, for nuværende...\n\n<Han hensygner og brokker sig over fortjenstmarginer og omkostninger...>\n\nHvad? Er du stadig her? Belønning? Åh, rigtigt... selvfølgelig, værsgo, tag den her... den burde være mere end rigelig.", p="Du har haft succes, håber jeg? Overalt, de dér trolde. Skidtede djævle.\n\nÅh ja, det minder mig om noget! Husk at fortælle dine venner det, ja? Vi kunne bruge megen hjælp!"},
  [190] = {c="Væk til en god start, <Name>!", p="En sand pantherjæger ville være ude på markerne og forsøge at liste sig frem til sit bytte. Vis lidt engagement over for dit mål, <Class>, og kom så ud igen."},
  [191] = {c="Perfekt udført, <Name>!", p="Gå og dræb 10 pantere! Vis os hvad du har!"},
  [192] = {c="Du har klaret dig godt, <Name>!", p="Hvad laver du her, <Name>! Du burde kravle rundt i krattet og prøve at dræbe 10 Skyggekæbe-pantere. Jeg troede, du så dig selv som en stor jæger af storvildt?"},
  [193] = {c="Så den store Bhag'tvera er død! Skål for dig, <Name>. Du er i sandhed en mægtig <Class>!", p="Bhag'tvera kan vise sig at være et undvigende udyr. Hvordan skrider jagten frem?"},
  [194] = {c="Godt gået, gamle ven!", p="Jeg har aldrig mødt en jæger, der fik nogen drab ved at stå rundt om lejrbålet. Havde du planer om at dræbe de Kvælerdorn-raptorer, eller håbede du, at de ville dø af alderdom?"},
  [195] = {c="Sådan får man et trofæ eller to op over den gamle pejs! Flot drab, <Name>!", p="En sand jæger retter sit fokus mod sit bytte. Du, min ven, virker mere optaget af at sladre rundt om lejrbålet. Gå nu derud og dræb 10 Piskehalerne, før jeg selv går hen og renser hele den forbandede jungle for dem på ét jagt."},
  [196] = {c="Ho ho!! Vi har os selv en ægte rovfugle-dræber! Flot gjort, gamle ven!", p="Bah! Hvad står du og lalleramser for, <Name>! En sand storvildtjæger giver aldrig op, når byttet er i sigtekornet. Vildnis-forfølgerne kommer ikke løbende op til dette lejrbål og kaster sig selv i ilden. Din tossede tølper."},
  [197] = {c="Mester <Name>, rovfugledræberen!\n\nHar en fin ring over sig, hva'?", p="Hvordan går jagten på Tetis? Sporede du hende hele vejen tilbage til lejren, hva'?"},
  [201] = {c="Hmmm, så mine oplysninger var korrekte, som sædvanligt. Interessant. Nå, jeg regner ikke med, at de udgør nogen form for trussel mod vores operation, men måske har de brug for nogle af vores fremragende fabrikerede varer. Hmmm...", p="Nå? Havde du held med at finde lejren?"},
  [208] = {c="Forbandet godt klaret! Ganske rigtigt! Tillykke, <Name>, fordi du lykkedes, hvor andre har fejlet.\n\nJeg er beæret over at regne dig som kammerat i vores store jagtgruppe her. Ingen vil nogensinde tvivle på din ekspertise i jagt og sporing!\n\nSkål for dig, siger jeg! Skål!", p="Jeg ser, du er tilbage, gamle kammerat. Konge Bangalasj har fået mig til at krybe tilbage til lejren mange gange. Hold ud."},
  [214] = {c="Brønd forvoldt, <Name>! På vegne af Folkemilitsen salutere jeg dig for din indsats. Snart vender vi dette land tilbage til folket med hjælp fra modige sjæle som dig.", p="Har du været i gang med at generobre vores land fra Defias-banden? Hvis ja, så vis mig 10 Røde Silke-halstørklæder som bevis."},
  [216] = {c="Brønd forvoldt <Class>, brønd forvoldt! Jeg vil fortsætte med at sende styrker for at tynde pelsbolgene ud, men jeg kan i det mindste regne med en anden vej, der er fri for Alliancens forviklinger. Horden-erobringen af Askedalen er nu i fuld gang!\n\nDu har fortjent din løn i dag, helt. Jeg salutere dig!", p="Har du taget kampen op mod Tistelpels? Med en klar sti mellem vores baser øger vores chancer for at gøre krav på hele Askedalen sig vildt dramatisk."},
  [217] = {c="Aldeles fortrinligt, <Name>! Du har bragt håb til Modansøen. Nu hvor Grumsmug er død, har vi en bedre sjans for at se Trolde udryddet fra landet.", p="Grumsmug og hans to vagter, Gnaser og Slagsbror, er stadig i live. Din mission er ikke fuldendt, før alle 3 er bragt til døden. Det dværgiske imperium regner med dig, <Name>."},
  [218] = {c="Vidunderligt, <Name>! Mange tak, fordi du hentede min notesbog. Brønd, det ser ud til, at trold-situationen her i Kuldekam-dalen er under kontrol, og der er ikke meget at bekymre sig om.\n\nNår jeg har lagt de sidste finpudsninger på min rapport, får jeg brug for nogen til at kurere den til min bror Senir.", p="<Name>! Noget held?"},
  [219] = {c="Du har tjent Riget godt, <Class>. Tak for at hjælpe Korporal Kisen med hans flugt fra de frygtede Sortklippe-orker. Du skal belønnes for dine modige gerninger i dag.", p="Ja?"},
  [221] = {c="Du klarede dig godt mod Mørke Løberne, <Name>. Men det ser ud til, at deres antal er uudtømmeligt. Hver gang vi gør fremskridt, dukker der flere op for at fylde deres rækker.\n\nHvilken ond magt er det, der lokker dem hertil? Hvorfor er de kommet for at forstyrre vores ulykkelige rige...\n\nJeg sætter min lid til Mester Carevin. Ingen tvivl om, at han vil komme problemet til bunds.", p="Tilbage så hurtigt, <Name>? Jeg håber ikke, du er kommet for at fortælle mig, at du har givet op."},
  [222] = {c="<Name>, ærligt talt troede jeg ikke, at du ville nå så langt, men du er tydeligvis en <Class>, man må regne med. Faktisk, hvis du formelt ønsker at slutte dig til Mester Carevins kamp, vil jeg med glæde skrive et anbefalingsbrev til dig.", p="Skræmmende bæster, er de ikke? Men frygt ikke, <Name>, dem der står for Let, skal aldrig falde!"},
  [224] = {c="Brønd forvoldt, <Name>! Du viste uhyggelig mod på slagmarken. Vores krig mod Trolde vil blive vundet med indsatser som din. Du har tjent Kong Magni brønd.\n\nHvis du synes, du er godt egnet til denne slags eventyr, foreslår jeg, at du taler med Bjergbestiger Grusgaw. Kaptajnen har tildelt ham en hård patrulje, og jeg er sikker på, at han kan bruge lidt hjælp. Tjek med Grusgaw lige inde i tårnet.", p="Modansøen er under belejring, <Name>! Vi har brug for hvert kampdygtigt medlem af Alliancen til at bistå vores sag. Har du dræbt 10 Stensplinter-trogg og 10 Stensplinter-spejdere endnu?"},
  [225] = {c="Morgan Ladimøre?\n\nÅh, ja, selvfølgelig. Hans var en lang og sorgfuld historie. Jeg kendte ham, ja, før han drog i krig, men det var sidste gang, jeg så ham. En ædel og god mand var han, men han fik en ussel ende.\n\nHerinde burde jeg have noget, der kan fortælle historien bedre end mine egne erindringer..."},
  [226] = {c="Åh, godt. Du fik tyndet den flok ud en hel del, og uden de ulve der nappede os i hælene, kan vi binde vores sind til at tage fat på Morbent Ondt.\n\nHer, tag nogle af disse Blitzbundter. De laver dem inde i byen, og en masse er blevet doneret til Sven for at hjælpe hans sag.", p="Jager du stadig ulve...?"},
  [228] = {c="Du dræbte ham? Det er ingen lille bedrift, <Name>! På vegne af folket i Mørkeshire og Nattevagten takker jeg dig.\n\nÅh... der er dog én lille sag...", p="Jeg bebrejder dig ikke, hvis du har problemer med ham, <Name>. Nogle af vores stærkeste Vagter er gået tabt til Mor'Ladhjem."},
  [230] = {c="<Sven læser bogens sider og smækker den så i.>\n\nDen skyggefulde skikkelse, jeg så, var et vidne til min families død! Der er spørgsmål, jeg gerne vil stille den mand... hvis bare jeg vidste, hvem han var!", p="Du fandt hvad?? Vær så snild, lad mig se den..."},
  [231] = {c="<En spøgelsesagtig stemme lyder i vinden...>\n\nDet er...? Sarah? Kan det virkelig være, at hun stadig er i live? Vægten er løftet fra mine skuldre...\n\n<Name>. Tag mit sværd, Arkeus. Nu hvor min sjæl får ro, har jeg ikke brug for det længere. Det blev smedet for at gøre godt, og selvom jeg har bevist, at jeg er uværdig til at bære det, kan du måske føre Let videre gennem det.\n\nLys, min kærlighed...", p="Lad mig være..."},
  [233] = {c="Tak, jeg har ventet på disse breve i ganske lang tid...\n\nDesværre er brevene ikke alle til mig. Dette her er adresseret til Grelin Hvidskæg. Han er ikke langt væk, hvis du gerne vil levere det til ham.", p="Ja? Har du noget til mig?"},
  [234] = {c="Ahh, udmærket. Det er længe siden, jeg modtog nyt fra Jernsmede.", p="Er der noget, jeg kan hjælpe dig med?"},
  [235] = {c="Velkommen til den nye grænse, <Name>. Askedalen er et land fuld af muligheder, et sted hvor en ung <Class> som dig kan finde grænseløse chancer for at bevise sit mod. Se dig omkring i forposten her, og sørg for at tage ud til Zoram-strandbredden, for Horden har også en forpost der.\n\nDin tilstedeværelse her fortæller mig, at du er kommet for at lære mere om jagten. Lyt godt efter, så deler jeg gerne det, du behøver at vide."},
  [237] = {c="Du udførte din mission brønd, <Race>. Kongen selv ville være stolt.\n\nForstærkningerne, der var lovet os, dukkede dog aldrig op. Alliance-fronten er åbenbart et hav af karmosinrødt, af vores faldne brødres blod. Nyheden om tabene efterlader en bitter smag i munden. Men vi må ikke lade deres død gå forgæves. Vi må samle os i disse dystre tider og bringe herligheden tilbage til Alliancen.\n\nTal med Bjergbestiger Vægbang om omplacering. Du er mere påkrævet nu end nogensinde.", p="Vi har brug for mere tid, <Race>. Din ordre er at dræbe 10 Stensplinter-kraniebankere og 10 Stensplinter-synskere. Hold fjenden under pres, indtil vi får forstærkninger. Dette er ingen tid til dagdriveri."},
  [239] = {c="Marskal Dughan sendte dig, hva'? Nå, du er ikke fra hæren, men hvis Dughan sendte dig, så er det godt nok for mig!\n\nVores situation er, mildt sagt, en stresset én. Jeg håber, du kan give os en hånd."},
  [240] = {c="Aha! Tak, <Name>. De ramte lige plet!\n\nOg her, lad mig betale dig for dem!", p="<Name>, du er her! Har du min mad?!?"},
  [244] = {c="Der er Rødryg-gnolde så tæt på Elvendal?? De kan være klar til at rykke frem mod vores hjemland. Snart er folkene i Søshire måske ikke de eneste mennesker, der er belejret!\n\nHer er din løn, selvom du bringer os dystre nyheder. Og det kommer på et dårligt tidspunkt, for vi er dårligt rustet til at håndtere det."},
  [245] = {c="Ah! Du er tilbage. Og ikke synderligt slidt, ser det ud til. Selvfølgelig, <Name>, Nattevagten er taknemmelig for dit arbejde, og jeg lovede dig en belønning, så her er den.", p="Du skal passe godt på, når du har med edderkopperne at gøre; jeg har mistet nogle af mine mænd til dem, og tro mig, det er ikke et behageligt syn at se en mand hænge med hovedet nedad i deres spindelvæv, efter giften er begyndt at blødgøre dem op.\n\nJeg ville ikke ønske at se en af de kravlende skadedyr få dig til frokost."},
  [246] = {c="<Stedfortræder Feldon lytter til din rapport...>\n\nDer er en betydelig styrke af gnoller slået lejr dér, og ud fra det, du fortæller mig, er de hårde nødder. Det må ikke have været let for dig at indhente disse efterretninger.\n\nVærsgo, <Name>. Vi er taknemmelige for din hjælp.\n\nOg hvis du ikke allerede har gjort det, så tal med Marskal Marris og Dommer Salomon inde i Søshire. Vores situation bliver stadig mere desperat - de to får sikkert brug for dig.", p="Undskyld mig, <Name>, men vi har meget at se til her, og hænderne er fuldt optaget. Hvis du intet har at rapportere, må jeg hellere rette tankerne mod andre sager."},
  [247] = {c="<Name>, du har slået alle tre bæster, der udgør Askedalen-jagten. Du har bragt mig tilstrækkeligt bevis på deres undergang; der er ingen tvivl om din styrke og seighed. Et jægers blod flyder i dine årer, og du bør roses!\n\nVær så venlig at modtage denne lille klimpe som et tegn på lykønskninger for dine mægtige bedrifter i Askedalen for Horden i dag. Må dine forfædre vogte over dig!"},
  [248] = {c="Det er et passende kar til Azoras Glyf, der gør det muligt for Teokritos at dykke ned i sindene inde i Stenvagtsfæstningen.", p="Denne krukke indeholdt engang en stinkende spiritus, men nu ligger den tom og glemt på et par tønder."},
  [249] = {c="Du har gjort det godt, <Name>. Ved at besejre hekseren Morgant er Stormvind reddet fra en grum fare.\n\nJeg tilbyder dig denne belønning i al ydmyghed. Og jeg ville ønske dig fred, hvis det var fredelige tider.\n\nMen i stedet ønsker jeg dig held med dine prøvelser og sejr i de kommende konflikter.", p="Skynd dig, <Name>, før mine frygt for at Morgant brede sin magt bliver til virkelighed!"},
  [250] = {c="Den mistænkelig udseende tønde indeholder et pulver med en underlig lugt."},
  [251] = {c="<Sirra begynder at oversætte notatet...>", p="Et notat fra Abercrumbie eremitten, hva'? Jeg kender ham ikke, men hvis han bor ude ved kirkegården, så ved jeg godt, at hans hjerne er rådnet!"},
  [252] = {c="<Ello læser brevet...og hans ansigt bliver hvidt. Så kigger han på dig...>\n\nSelvom den hjælp, du gav Abercrumbie, måske var motiveret af venlighed, har dine handlinger dømt vores by.\n\n<Ello fortaber sig i sine tanker...>", p="Ah, er seddelen oversat? Lad mig se den, værsgo..."},
  [253] = {c="Du har gjort det! Magien i hans hjerte vil være et værn mod Balsamerens onde, og et kraftigt skjold over byen Mørkeshire.\n\nDu har gjort en stor gerning for vort folk, <Name>. Dit navn vil blive i vore annaler for evigt.", p="Har du endnu fundet Elisas grav? Har du Balsamerens hjerte?"},
  [255] = {c="Ah, dette er fremragende nyheder! Dine bestræbelser værdsættes højt af mig og Tælsamars folk. Endnu bedre: Hvis vi kan løse oger-problemet, kan vi flytte fokus over på de Let-brændende trogger.", p="Har du haft held?"},
  [256] = {c="Puha! Hvad er den ting? Og hvorfor ville du tage den med...\n\nBlodig--! Er det? Nå, Let brænde mig, er det hovedet af den blodige oger? Det er da en fangst! Her er din belønning og tak fra mig og folkene i Tælsamar.", p="Ja? Er der noget, jeg kan gøre for dig?"},
  [257] = {c="Hvad? Succes?\n\nTag det fra mig, <Name>ama, lad det ikke gå dig til hovedet. Jeg mener, enhver uvasket dreng med en bue kunne have dræbt sådanne... små eksemplarer. Og jeg håber ikke, du nyder at dræbe gribbene så meget, ikke? Vi vil jo ikke have, at de uddør.\n\nNå, øh... Lad aldrig nogen sige, at Daryl den Modige ikke holdt sit ord.", p="Ikke noget held? Tag det ikke for hårdt, <Name>...\n\nIkke alle kan være mig."},
  [262] = {c="Hmm... Nogen har håndteret denne bog for nylig, nogen der drives af hævn. Men aftrykkene efterladt på den, i hvert fald aftrykkene fra den oprindelige ejer, er svage.\n\nJeg kan dog se, at den oprindelige ejer af denne bog ikke er født i Mørkeshire.", p="Hvis du har noget, der tilhører den skyggefulde skikkelse, du søger, så lad mig se det. Jeg kan måske udlede noget om dens ejer."},
  [263] = {c="Jeg vidste i samme sekund, jeg så dig, <Name>, at du ville gøre Jernsmede stolt. Du har tjent Kong Magni godt. Nu hvor du har bevist dig selv som en så loyal bistand til Riget, bør du måske tale med Kaptajnen for at se, om han vil betro dig en højere opgave.\n\nJeg salutterer dig, <Name>.", p="Tilbage så hurtigt? For at være helt klar: Vi har brug for, at du dræber 10 Stensplinter-shamaner og 10 Stensplinter-benknækkere, <Name>. Gå nu og hent dem, Trogg-banemand!"},
  [264] = {c="Du placerer det værdiløse vedhæng på graven, og ædelstenen i indfatningen bliver mærkbart sløvere.\n\nIdet du rejser dig for at gå, kigger du ned på vedhænget; det ligger livløst hen over hænderne i relieffet, der er udhugget i toppen af kisten. Dine tanker afbrydes af en stiv, kølig brise, der stryger hen over Gravkammeret. I et øjeblik er alt omkring dig stille.", p="Stenen er kold at røre ved, men den er tydeligvis blevet misbrugt. Affald flyder over området; hakker og ridser pryder relieffet oven på kisten; og løvværket omkring graven er begyndt at gro over stedet.\n\nIngen bekymrer sig om den, der er begravet her, og slet ikke pestens ofre."},
  [265] = {c="Ah, ja. Jeg solgte denne bog for en måned siden til en tvivlsom person. Han fortalte mig ikke sit navn, men han var en nervøs, rastløs fyr, der altid kiggede over skulderen.\n\nJeg håber, det hjælper dig...", p="Nogle gange sælger jeg tomme bøger til lærde og magikere, eller til enhver, der vil føre dagbog.\n\nJeg husker godt alle, jeg har solgt en bog til inden for de sidste par måneder..."},
  [266] = {c="Åh ja, jeg husker denne bog. Dens ejer lejede et værelse i et par dage og tilbragte sine nætter i baren, skrivende.\n\nHan forlod byen i en fart og mumlede om at blive jagtet af...noget. Sidst jeg så ham, var han på vej mod vest ud af byen på jagt efter et nyt skjulested.\n\nDet første sted han ville finde mod vest er Ravnehøj...", p="Skarlagenrød Ravn ser ikke længere den forretning, den plejede, men der kommer stadig rejsende forbi.\n\nHvis du kan beskrive den person, du leder efter, husker jeg ham måske."},
  [267] = {c="Jeg er ganske imponeret, <Name>. Du har gjort dværgeracen en stor tjeneste ved at forsvare vores lande. Kong Magni Bronzeskæg selv ville være stolt!", p="Har du 8 Trogg-stentænder at vise mig? Hvis ikke, er der stadig arbejde at gøre, <Name>."},
  [268] = {c="Denne dagbog forklarer mig meget, og sætter mig på sporet af de mørke ryttere! Jeg har set disse ryttere i Skumringsskoven, og set dem tale med magikeren Morbent Ondt, ved Forladt Række.", p="Har du fundet ud af, hvem den Skyggefulde Figur var?"},
  [269] = {c="<Efter at have læst dagbogen og hørt din hensigt...>\n\nEt ondt fordærv har fået fodfæste i det allerede hårdt prøvede Skumringsskoven. Jeg takker Let for, at vi har en helt som dig til at møde det.\n\nMen du må først gøre dig klar til den kommende prøvelse...for Nekromanceren Morbent Ondt er enormt magtfuld og har lagt mørke fortryllelser over sig selv for at beskytte sig mod fysiske angreb. Hvis du skal besejre ham, får du brug for et våben, der er sikkert mod disse beskyttelser.", p="Hvil dig, bror. Jeg kan se, at du har rejst langt, og at du bærer en tung byrde. Kan du fortælle mig, hvad der kaster den mørke skygge over dig?"},
  [270] = {c="Lysssmede-jern er et dyrebart metal, men det lyder, som om din opgave er en alvorlig én. Du er kommet langt, Broder. Med held finder du måske lige præcis det, du leder efter!\n\nOg hvis du får jernet, kender jeg den, der kan smede det om til et våben mod den Nekromanceren, du taler om i Skumringsskoven."},
  [271] = {c="Øh... hvad er det her? Et bjørnehoved, å døm ud fra det.\n\n<Han løber ubevidst en finger hen over sit ar.>\n\nTja, det er et ret interessant bytte, du har der. Kunne ikke være den bjørn fra dengang...\n\n<Han taler stille videre og begynder synligt at ryste.>\n\nÅh, tag det væk, tag det væk! Få den grumme ting ud herfra!", p="Ah, <Name>! Allerede tilbage? Du har vel været ude på jagt igen? Bliv ikke ked af det, hvis det er gået skævt, på længere sigt gør det dig bare bedre!\n\n...Du kunne jo ikke blive meget værre..."},
  [272] = {c="Du har gennemført Søløve-prøven, <Name> - lykønskninger.\n\nHver opgave i at skaffe vedhænget viser, at både smidighed og udholdenhed er nødvendige for at handle i harmoni med det, du ønsker at gøre under vandet. Ingen af delene kan eksistere uden den anden, og begge kan ikke gøres uden din villighed til at omfavne søløvens skikkelse.\n\nHusk disse lektioner godt, og stol på dem, når du har opnået din vandform.", p="Har du fået formet dit vedhæng, så jeg kan inspicere det, <Name>? Hvis du har brug for hjælp til at finde delene, så prøv at spørge de lokale om information. Ikke alene finder du det, du leder efter, men det giver dig også en grund til at udforske denne vidunderlige og hellige lysning."},
  [273] = {c="Hmph, det skal mere end et Mørkejern-baghold til for at standse leverancerne!\n\nMen Saeen... Jeg ville aldrig have mistænkt ham for at være en af deres sympatisører. Vi har arbejdet sammen med ham i næsten et år nu... måske overså jeg tegnene.\n\nNå, den betragtning må vente."},
  [274] = {c="En afvæbnende kolloid? Til Havium? Åh himmel!", p="Hvad er det, du bringer fra Askelan?"},
  [275] = {c="Dette land er blevet beroliget af din indsats, og for det vil jeg give dig en gunst.", p="Vådlandene græder stadig, og Mosekravlerne raser stadig. Kom tilbage til mig, når din opgave er forvoldt."},
  [276] = {c="Ved at reducere gnollernes antal har du taget dig af Vådlandenes helbred. Selvom min tro på dit folk har været sat på prøve tidligere, <Race>, kan den måske stadig genoprettes.", p="Din opgave er stadig lige ved hånden, unge <Class>."},
  [277] = {c="... tak. Jeg vil knuse disse flintesten og kaste dem i havet, så de aldrig igen kan bruges til at brænde levende træ.", p="Har du gnollernes værktøj til affyr?"},
  [279] = {c="Ah, godt gået, <Name>.\n\nAccepter dette som betaling for opfyldelsen af din kontrakt med Handelsmarinen.", p="Vores købmænd vil ikke være trygge, før vi er af med Sluger og de Mudderfisk."},
  [281] = {c="Denne kasse er dækket af klorridser og mærker efter vandskade. Når du bryder den op, afsløres sumpet og rådnet halm, som om noget af værdi var gemt i kassen. Du roder igennem halmen...\n\n...og finder en armfuld rødfarvede flasker."},
  [282] = {c="Hm, ja, hvis Hvidskæg sender dig til Dun Frostbakke på vigtige ærinder, kan jeg vel ikke rigtig stoppe dig, kan jeg?\n\nLad mig i det mindste give dig nogle gode råd og vejvisning.", p="Hilsen! Pas på, <Name>, tunnelen til Dun Frostbakke er hærget af trogger, og den er ikke sikker at rejse i.\n\nHar du ikke noget presserende ærinde i Dun Frostbakke, må jeg bede dig blive i Ambolmar, indtil tunnelen er sikrere."},
  [284] = {c="Denne tønde er stort set uberørt. Mens du brækker den op...\n\n...bliver du overfaldet af den skarpe lugt af ost. Den er lidt våd, men stadig lækker!"},
  [285] = {c="Denne tønde er halvt begravet midt i mudderet og græsset ..."},
  [286] = {c="Kaptajnen på Den Blinde Prinsesse vil blive lettet over at høre, at denne dyrebare last er blevet hentet. Du har fortjent denne betaling for ydede tjenester.\n\nDet er godt at se pålidelige folk som dig, især i så prøvende tider som disse.", p="Har du statuetten?"},
  [287] = {c="Ah, <Name>! Jeg troede ikke, du ville få svært ved at finde stedet, mine anvisninger er jo fortrinlige...\n\nLad mig lige færdiggøre min rapport da.\n\n<Han finder noget papir frem og kradser lidt på det et øjeblik.>\n\nDer! Nå, haha, nu er det her da virkelig morsomt... Du har vel ikke noget imod, <Name>, at gøre mig en sidste tjeneste?", p="Kan du ikke finde den? Mine anvisninger var jo meget tydelige! Vi har ikke meget tid, du må skynde dig! Kom ikke tilbage, før du har fundet hulen."},
  [288] = {c="Ah! Det rammer plet, og løsner tungen. Tak, makker!", p="Åh, jeg er så utrolig tørstig! Vil du ikke købe en drik til denne stakkels, patetiske tølpe?"},
  [289] = {c="Min tak til dig, <Name>. Og de forbandede brødres taknemmelighed går også til dig.", p="I mine drømme kan jeg nogle gange høre mine brødres dødsdømte stønnen! Vær venlig, gode herre, befri dem fra lænkerne og stil deres skrig."},
  [290] = {c="Nøglen er rusten, men den passer pænt i låsen.", p="Denne kiste er sikkert låst."},
  [291] = {c="<Han gennemgår rapporten hurtigt.>\n\nKongens Autoritet!? Er Magnie fuldstændig forsvundet fra sine sindssans! Og den forbandede Hvidskæg... Har han taget sagerne i egen hånd? Senatet bliver ikke glad for at høre om dette, ikke det mindste.\n\nHvad, er du stadig her? Af sted, før jeg kalder vagterne!", p="Hmm... det ser ud til, at mine vagter bliver mindre kræsne over for bedefolk. Nå, hvad vil du? Gør det kort."},
  [292] = {c="Et Palets Øje? Fantastisk! Hmm...der er noget galt med denne her. Fandt du den på et af de skibsvrag? Nå, det forklarer det! Men...jeg vidste ikke, at de havde sådan et Øje i Tredje Flåde...\n\nDet er ingen undren, at Fitzsimmons var så skræmt. Et Forbandet Palet-øje er ingen grund til munterhed.", p="Sendte den fulde Fitzsimmons dig til mig? Nå, du kan fortælle ham, at jeg ikke har nogen ekstra øl. Han må tigge hos en anden!"},
  [293] = {c="Et Palets Øje. Men dette her har set megen sorg...det må have været vidne til en forfærdelig, forfærdelig tragedie.\n\nLad mig rense det, for Øjnene blev skabt til at skinne klart, og deres kræfter kan være ganske farlige, hvis de er besmittet ligesom denne her.", p="Hvad er den kugle, du har? Den ser... besudlet ud."},
  [294] = {c="Drab er en beskidt forretning, men du gjorde dit job godt, <Name>. Hvis jeg ikke var forpligtet til at blive hos Prospektoren og Merrin, ville jeg være nede dernede og udgyde blod lige ved siden af dig.", p="Dræb 10 Plettede Raptorer og 10 Plettede Skrigere, <Name>. Mine kolleger fortjente ikke den skæbne, der blev dem til del. Nu er det tid til at gøre op for det."},
  [295] = {c="Du gjorde et kanonjob med at rydde de Raptorer ud, <Name>!", p="Jeg vil have de Plettede Leklo og Plettede Barberkæber til at betale for det, de gjorde. Har du dræbt 10 af hver slags endnu?"},
  [296] = {c="Tak, <Name>. Din indsats her vil ikke blive glemt. Mange uskyldige Dværge døde på dette sted, blot fordi de passede deres arbejde. Den hævn, du leverede til de onde væsener, burde få dem til at tænke sig om to gange, før de angriber Kong Magnis undersåtter igen.", p="Er Sarltand død? Har du genoprettet erindringen om de faldne?"},
  [297] = {c="Du fik dem! Pænt gjort, <Name>!\n\nOg du ser ikke for medtaget ud, selv med de rasende Trolde omkring dig. Jeg kommer til at holde øje med dig... du viser et vist løfte.", p="Har du de idoler? Vi må studere dem og aflevere vores fund til Jernsmede!"},
  [298] = {c="Bah! Jernbånd har problemer med trolde. Jeg undrer mig over, om han vil have det sprængpulver til at hjælpe sin gravning, eller til at hjælpe sine bestræbelser mod trolde-bæsterne...\n\nNå, uanset hvad, så er det godt brugt pulver!\n\nMen det mærkelige er, at jeg sendte ham masser af sprængpulver for flere uger siden. Jeg undrer mig over, hvor det blev af..."},
  [299] = {c="Ah, Goaz-stenen er færdig! Fint arbejde, <Name>. Virkelig fint arbejde. Nu kan jeg fortsætte med den delikate oversættelse af dette Titan-skrift. Jeg kan allerede tyde nye ord! Hmm. . .der står her, \"De Gamle Guder. . .Lænket under landet.\" Dette er begyndelsen på noget episk.", p="Har du afdækket de fire fragmenter endnu, <Name>? Adøs, Mødr, Gulm og Næru..."},
  [301] = {c="Forbandelse over Jernbånd! For flere uger siden sendte jeg ham et læs sprængkrudt, men han har ikke nævnt det med et eneste ord i denne rapport.\n\nSå... hvor blev sprængkrudtet af?!?", p="Vi Stormspidsere bryder os ikke om at blive forstyrret med trivielle sager, <Class>. Jeg håber, du har bragt nyheder, der er værd min værdifulde opmærksomhed."},
  [302] = {c="Hvad? Stormspids vil have, at du personligt ser til forsendelsen til Jernbånd?\n\nJeg... antager, at det er fint. Det eneste problem er, at jeg allerede har sendt Huldrik af sted med bærerne, Mirran og Saeen. Du missede dem lige, de gik for et lille stykke tid siden."},
  [303] = {c="Du har holdt dine ordrer godt, <Class>. Du har bevist dig selv som en modig soldat og loyal tjener for Kong Magni, og derfor salutterer jeg dig! Med det pres du satte på Mørkejern-lejren, står vi nu en chance for at jage dem fra vores lande for godt. . .bare reserven dog ville vise sig. . . .", p="Rogo har ikke kunnet få kontakt med reservestyrkerne. Vi har brug for offensivt pres på Mørkejern-lejren, <Class>. Kom nu ud igen og gør din pligt over for Kong Magni!"},
  [304] = {c="Balgaras den Onde er endelig død. Selvom hans død ikke vil bringe de mange uskyldige dværge tilbage, som døde unødigt for hans hånd, vil den genoprette sindsroen hos dem, der overlevede. Med Balgaras død burde det resterende Mørkejern-pak være lette nok at holde styr på. Nu må vi udslette dem, før en ny leder bliver sendt til disse egne.\n\nDu har klaret dig godt, <Class>.", p="Har du fundet Balgaras den Onde endnu, <Class>? Han har undveget os i ganske lang tid."},
  [305] = {c="Åh, tak himlen, at du er her!"},
  [306] = {c="Så rædselsfulde nyheder! Mindst 3 af dem overlevede. Men hvornår stopper slagtningen? Jeg higer efter den dag, hvor Kong Magnis undersåtter kan leve uden frygt.", p="Fandt du Merrin? Sendte hun bud?"},
  [307] = {c="Så du en masse kobolderne derinde? Jeg kan ikke vente på, at ordenen rydder dem ud af minen. Tanken om deres snavsede hænder, der kradser rundt i vores mine, får min mave til at rumle!", p="Har du det Minearbejderudstyr, <Name>?"},
  [308] = {c="Til mig? Du er en sand helt, <Name>!", p="Hmph! Der er al den sprit hernede, men jeg har strenge ordrer om ikke at røre den. Hvis bare jeg kunne få en smag af noget af vores Tordenøl... det ville skærpe mine sanser, ingen løgn!"},
  [309] = {c="Åh, tak Let for, at pulveret er her. Men det er bekymrende nyheder, du også bringer. At tænke sig, at Mørkjernsdværgene har sympatisører, der kan skaffe den slags materiale til deres nedrige planer.\n\nDet må andre tage sig af at overveje, på et andet tidspunkt. Jeg må bruge dette pulver til noget godt.", p="Hvor er mit pulver, <Name>? Mit behov bliver mere desperat for hver dag."},
  [310] = {c="Du placerer hurtigt Marleth Byggøls tønde med Byggøl-Skoldeøl blandt Tordenbryg-tønderne.", p="Datoen på denne tønde viser, at den snart bliver tappet."},
  [311] = {c="Ikke dårligt, <Name>! Havde du svært ved at komme forbi deres vagt?\n\nDet gør ikke noget - mange tak, og hvis du nogensinde har brug for stærk øl med et spark, så glem ikke Bygbryggerne!", p="Fik du lavet byttet?"},
  [312] = {c="For en venlig sjæl du er, <Name>! Takket være dit mod behøver jeg ikke sulte, når vinterens snefnug blæser ind.", p="Kunne du komme ind i mit kødkøleskab, <Name>?"},
  [313] = {c="Ah ja, de her manker duer fint! Du viser en masse mod, <Class> - jeg vedder på, at vi vil se store ting fra dig.", p="Hey, <Name>. Har du været i Den Grizzlede Hule endnu? De Vindgængere kan være voldsomme."},
  [314] = {c="Meget godt gjort! Verøn bliver så glad, når han hører de gode nyheder. At dræbe Vagash er ingen let opgave. Jeg forestiller mig, at du en dag kæmper side om side med Kong Magnis mænd på Alliancefronten.", p="Vagash terroriserer stadig flokken! Hjælp os venligst med at dræbe det elendige udyr."},
  [315] = {c="Stor! Jeg kan ikke vente med at bruge disse i nogle af mine opskrifter. Der er én især, jeg tror, den vil passe fantastisk i...", p="Har du den skimmerukrudt? Jeg har næsten en portion stout klar til brygning, og jeg vil prøve at kaste ukrudtet i denne blanding."},
  [317] = {c="Ved Magnies skæg, du fik da jagtet en hel del!! Tak, <Name>.", p="Forberedelserne går godt. Hvordan går det med jagten?"},
  [318] = {c="Bælgfiz har brug for noget af min Evigskinne? Hm...nåja, fint."},
  [319] = {c="Tak, <Name>. Det bliver dejligt at kunne passe vores håndværk uden at høre alle de knurren og snøvs udenfor landsbyen.", p="Har du taget dig af de vilde dyr?"},
  [320] = {c="Ja, det her duer fint. Jeg tror jeg åbner en flaske lige nu og smager lidt på den...", p="Har du fået den Evigskinne?"},
  [321] = {c="Denne kiste er vandfyldt, og dens sider er knækket. Mange klomærker skæmmer både inde- og ydersiden af kisten... som om Mudderfisk har rodet igennem den og stjålet dens skat.\n\nMen dybt inde i kisten ligger en enkelt Lysssmede-barre. Desværre skal der mange flere til, hvis der skal være nok metal til at smede et våben."},
  [322] = {c="Det er en heftig historie, du har. Og lysesmedejern! I årevis har jeg ikke arbejdet med sådan et metal. Det bliver en ære at fremstille noget med det igen. Og du skal vende tilbage til mig senere med historien om din kamp mod Nekromanceren.\n\nMen vi løber lidt foran os selv. Først dit våben mod Morbent Ondt...", p="Hvordan kan jeg udfolde mit håndværk for dig, <Class>?"},
  [323] = {c="Din færdighed i kamp, <Name>, kan ikke betvivles. Din beslutsomhed kan endnu føre os igennem til enden af Morbent Ondt!", p="Kæmp hårdt, <Name>. Og fortvivl ikke, for fortvivlelse er ondskabens største våben."},
  [324] = {c="Ah, du fandt dem! Nu skal vi have dette lysesmedejern hamret om til noget nyttigt, hva'?", p="Har du fundet det Lysesmedejern, du har brug for?"},
  [325] = {c="Ah, dette vil være et bevis mod udyret Morbent Ondt! Godt gået!\n\nDu er klar. Morbent Ondt vil falde.", p="Hej, <Name>. Du har ikke været væk så længe, men jeg ser en ild i dine øjne, som jeg ikke så før."},
  [332] = {c="Ah, så du har mødt Renato? Nå, her er du, min herre. En flaske af vores specielle sort pinot. Du finder ikke dens lige i hele Azerot!", p="Hilsner og velkommen, herre. Har du endnu prøvet et af vores fine vine?"},
  [333] = {c="Der står her, at Harald's forretning blomstrer. Det er gode nyheder, men jeg undrer mig over, hvorfor folk har brug for al den rustning. Jeg har ikke hørt noget om åben krig... er der noget adelen ikke fortæller os?\n\nNå, tak fordi du bragte anmodningen. Her er din betaling, og jeg sørger for, at Harald får sine forsyninger.", p="Du bringer besked fra Hr. Pose?"},
  [334] = {c="Åh, udbrud! Jeg troede, at hvis jeg glemte mit sy-sæt, ville jeg slippe for at arbejde. Nu må jeg vist hjælpe Larsonerne med deres syning...\n\nÅh, well. Sjov kommer vist senere, tror jeg.", p="Er du her for at købe tøj?"},
  [335] = {c="Aldeles fortrinligt! Det er da virkelig fine prøver!", p="Vishock vil snart samle nok opbakning til at volde os stor sorg. Har du mon fået fat i Tilloas Tåre eller Bisamrod endnu?"},
  [337] = {c="Åh min! Denne bog har ikke hvilet på disse hylder siden før genopbygningen af Stormvind, for år tilbage. Den skal selvfølgelig restaureres, den er i dårlig stand, men jeg ville være beæret over at placere den inden for vores samling af sjældne bøger.\n\nTak, min herre. Modtag venligst dette som betaling for at returnere bogen!", p="Åh! Hvad er det for en gammel bog, du har der? Må jeg se den??"},
  [338] = {c="Du har sandelig sparet mig for en masse besvær, <Name>! Jeg kan ikke takke dig nok. Det burde ikke vare længe, før vi ser Mester Jagtvarys' bog i biblioteker over hele verden!", p="Har du samlet kapitlerne endnu, <Name>?"},
  [339] = {c="Endelig! Kapitel I er færdigt!", p="Jeg regner vist ikke med, at du har fået fat i side 1, 4, 6 og 8? De fire er alt, vi behøver for at sætte Kapitel I sammen igen."},
  [340] = {c="Kapitel II er endelig færdigt! Brønd gjort!", p="Vi mangler stadig side 10, 11, 14 og 16 for at fuldføre Kapitel II, <Name>."},
  [341] = {c="Puha! Godt arbejde, <Name>. Kapitel III er nu samlet igen i ét stykke!", p="Har du held med siderne 18, 20, 21 eller 24? Det er de eneste, vi har brug for, for at sætte Kapitel III sammen igen."},
  [342] = {c="Storartet! Vi har nu Kapitel IV klar til at gå!", p="Vi mangler bare tre sider for at afslutte Kapitel IV, <Name>. Har du side 25, 26 eller 27 endnu?"},
  [343] = {c="Metallurgi? Ah ja, vi har mange bøger om emnet, og vi hjælper gerne Broder Kristoff med hans tale! Nu... hvilken bog var det lige, den gode broder havde brug for?"},
  [344] = {c="Hr. Neg spekulerer på, hvor hans bog er? Nå, det er lidt pinligt. Jeg har bogen, men jeg laver stadig min kopi, og jeg er ikke helt klar til at give originalen fra mig!"},
  [345] = {c="Hvad skal du have?? Måske har du ikke bemærket det, men vi har travlt med at befæste Søshires forsvar og reparere skaderne fra de seneste orkeangreb. Hvis du har brug for Rethban-jernmalm, må du selv hente det!"},
  [346] = {c="Den er det! Tak, <Name>. Må Let skinne klart over både din krop og din ånd!", p="Fandt du bogen?"},
  [347] = {c="Åh, herligt! Jeg kan bruge denne malm til at lave min farve, og så kan jeg færdiggøre kopieringen af Jernets Spændinger.\n\nTak, <Name>!", p="Har du Rethban-malmen?"},
  [350] = {c="Du spøger! Skaw vil have min hjælp igen? Af al den frækhed...\n\nDefias-broderskabet, siger du? Ja, du er da vist bærer af vidunderlige nyheder, ikke? Næste gang fortæller du mig vel, at Dødsvinge stadig er i live og angriber byen.\n\nNå, fortæl mig alt fra begyndelsen. Og lad nu være med at udelade noget, du tror måske ikke er vigtigt. Jeg skal vide det hele."},
  [353] = {c="Aha! Så Grimmund fik endelig færdiggjort min økse! Jeg kan ikke vente med at prøve den mod nogle trogger og kobolder!\n\nTusind tak, <Name>. Det var en fjerne rejse for denne levering. Her er nogle mønter for din indsats.", p="Du kommer helt fra Stormvind? Jeg hører, at det bliver hasarderet dernede i menneskenes lande, med røvere og orker, der løber rundt. Et perfekt sted for en <Class> at bevise sin værd!"},
  [354] = {c="Hævn smager sødt, synes du ikke? Da du knuste Agamanderne, opfangede du så nogen antydning af fri vilje i dem? Det håber jeg. Jeg håber, de kendte frygt, før de blev smadret ud i glemslen.\n\nDet er et tåbeligt håb, jeg ved det. Men det er et håb, jeg alligevel nærer.", p="Har du resterne af Agamanderne? Er de forbandede bæster endelig ødelagt?"},
  [355] = {c="Coleman taler brønd om dig, <Name>, og fortæller om dine vellykkede togter til Agamand-møllerne.\n\nDe Forladte har igen brug for dine talenter..."},
  [356] = {c="Meget godt. Dine bestræbelser gør meget for at holde Svøben på afstand. En anbefaling vil blive sendt til min overordnede, Eksekutor Zygant.", p="Har du en rapport fra din patrulje?"},
  [357] = {c="Meget godt, <Name>. Jeg vil studere denne bog og finde ud af, hvem den lisk er. Du har tjent din Dronning godt.\n\n<Bethor åbner bogen og stirrer intenst på dens glødende sider...>\n\nForbløffende! Bogen, du hentede, tilhører ingen andre end Gunner Arkanus!\n\nGunner var en dygtig Nekromanceren i livet; han og jeg var venner og våbenbrødre, før Pesten. Og ud fra hans bog at dømme er han blevet endnu mægtigere i døden.\n\nHans færdigheder ville være en stor gevinst for os.", p="<Name>, har du skaffet bogen?"},
  [358] = {c="Ekspert udført, <Name>. Svøben tager fejl, hvis de tror, de kan bruge disse lig imod os, og væsken, du samlede fra Rådhud-slaverne, vil blive undersøgt af vores Apotekere. Den kan have hemmeligheder, vi kan bruge imod dem.\n\nSom jeg sagde, godt gjort. Men vores kamp fortsætter, og konflikten vil helt sikkert give dig flere chancer for at bevise din værdi over for De Forladte.", p="Er din opgave fuldført? Har du ødelagt de hundeskabninger og drænet dem for deres ikor?"},
  [359] = {c="Dommer Sevrin vil have en rapport? Meget godt: forsvarerne ved Bolværket holder det meste af Svøben stangen, men nogle sniger sig igennem nu og da.\n\nVi har set sporadisk Svøben-aktivitet øst for denne station, med en koncentration omkring Balnirs Gård."},
  [360] = {c="Det er foruroligende at høre, at Svøben er sluppet forbi Bolværket. Liskekongen og hans håndlangere holder aldrig op med deres angreb.\n\nMen vi giver ikke op. Han skal ikke tage os igen!"},
  [361] = {c="Åh... min stakkels Thurmann! Jeg bad ham om at forlade Agamand-møllerne sammen med mig og min far, men hans familieloyalitet var for stærk! Og jeg vidste det! Jeg vidste bare, at Mærke ville ham ondt!! Åh, forbandelse over denne Pesten og Svøben!\n\n<Ivettes ansigt glatter sig så ud og bliver koldt.>\n\nMen fortrydelse er for de svage. Som De Forladte har jeg nye mål, og kærlighed er ikke et af dem. Jeg ville takke dig for at levere dette brev, for jeg havde spekuleret på, hvad der var sket med min tidligere kærlighed.\n\nMen det liv er forbi. Evigt.", p="Ja?"},
  [362] = {c="Tak. Djævlins knogler vil hvile pænt på min kaminhylde.\n\nHvis mit kolde hjerte kan finde varme, er det i at vide, at Agamanderne er tilintetgjort. De svigtede mig og min familie, da Pesten kom - nu sværger jeg, at jeg vil knuse deres rester under min hæl!", p="Fandt du Djævlin?"},
  [363] = {c="Endnu en af de levende døde, hm? Må have været et ordentligt chok at vågne op i krypten med kun kulden og Morder til at tage imod dig...\n\nJeg kan se forvirringen i dit ansigt. Lad mig prøve at forklare dig vores... situation...\n\nVi er blevet befriet fra Liskekongens kontrol af vores nye leder, Frue Silvanas. Den Mørke Dame leder os i krigen mod den forhadte Svøben og menneskehedens stædige rester, som hænger over hvert eneste af vores skridt."},
  [364] = {c="Det er ærgerligt, at Svøben ikke kan føres ind i flokken, for deres store antal ville være nyttigt i de kommende kampe.\n\nMen de vil ikke slutte sig til os, så vi har intet valg andet end at tilintetgøre dem.", p="Du kommer ikke langt i dette nye liv, hvis du ikke engang kan dræbe de svageste af zombier, <Name>. Kom ikke tilbage, før du har succes at rapportere."},
  [365] = {c="Du har udført dine befalinger godt, unge <Class>. Du beviser, at du er en ganske værdifuld aktiv for Den Mørke Dames hær.", p="Dødevagt Simrer sendte bud om, at du skulle skaffe mig nogle stærkt tiltrængte reagenser. Har du fået samlet 10 græskar endnu, <Name>?"},
  [366] = {c="Min bog?!? Så det var dig, tyven, der stjal den!\n\nMen... hvad er denne nye fortryllelse på den... Bethor? Er han i Herrelande?\n\nHvis han stadig eksisterer, så er han måske også undsluppet Liskekongens greb...", p="Dine herrer er tossede, når de sender dig herhen, for jeg bliver aldrig igen Svøbens slave!"},
  [367] = {c="Du har gjort det godt, <Name>, og jeg takker dig for din indsats.", p="Har du samlet 5 hætteglas mørkehund-blod endnu, <Name>? Tiden flygter!"},
  [368] = {c="Vægtene er perfekte, <Name>. Præcis det, jeg havde brug for til denne brygning.", p="<Name>, var du i stand til at skaffe 5 Ondskabsfinne-skæl fra Mudderfiskene?"},
  [369] = {c="Ah, dette gift vil være perfekt, <Name>. Alt det andet er blevet tilsat min brygning og kogt ned. Endelig er jeg klar til at prøve dette nye dødbringende middel!", p="Har du noget gift fra en Grusom Natnet-edderkop endnu, <Name>? Det er den sidste ingrediens, jeg skal bruge for at teste mit eksperiment."},
  [370] = {c="Kaptajn Perrinnes død vil uden tvivl glæde Den Mørke Dame. Du har udført din pligt brønd, <Class>.", p="Ung <Class>, du bør ikke spilde din tid her i Gryde-by, når dit folk har brug for, at du kæmper for deres sag. Tag nu våben op og drag mod sydvest, til det faldne tårn, og slå Kaptajn Perrinne ihjel sammen med 3 Skarlagenrøde Fanatikere og 3 Skarlagenrøde Missionærer. Vi skal drive de Skarlagenrøde Korstog sammen som kvæg til deres undergang."},
  [371] = {c="Kaptajn Vaskons død vil bremse De Skarlagenrøde Korstogs fremmarch i Tirisfal en hel del. Men andre trusler lurer.", p="Jeg ser, du er vendt tilbage, men din opgave er ikke fuldført. Er du måske tilfreds med, at de blotte mennesker blander sig i Den Mørke Damens plan? Eller kan du høre pligtens kald og slå Kaptajn Vaskon og hans bande af Skarlagenrøde Munke ihjel!"},
  [372] = {c="Du har gjort det særdeles godt, <Class>. Med hensynsløse kæmpere som dig, der erobrer i De Forladtes navn, er vores race et skridt tættere på at besejre Arthæus én gang for alle. Jeg har en god fornemmelse om dig, kammerat.", p="Du har endnu ikke udført din pligt, <Class>. Vi kan ikke forvente at gennemføre Den Mørke Dames plan, mens Skarlagenrøde Korstog generer vores soldater. Bring deres død og udfør din pligt over for Silvanas!"},
  [373] = {c="Edwin VanKløft, siger du? Jeg ville lige så meget vente et brev fra min døde bedstemor... Så du har altså dræbt ham? Undskyld, men jeg er lidt overrasket. Han var en uovertruffen kriger i sine yngre år. Lad os se, hvad han finder på at skrive til mig efter så mange år.\n\n<Baros studerer brevet grundigt.>\n\nEdwin... Jeg kan se, at årene ikke har ændret dig det mindste, stadig en idealist og en romantiker. Han er ligeglad med, hvem han sårer, <Name>. Hævnen har fortæret ham. Men så igen, jeg er ikke sikker på, at jeg kan give ham skylden.", p="Ja? Er der noget, jeg kan hjælpe dig med?"},
  [374] = {c="Varimatras ville være stolt. Du tjener dine ledere godt, <Class>.", p="Har du samlet 10 Skarlagenrøde Insignia-ringe endnu, <Class>?"},
  [375] = {c="Jeg sætter pris på din indsats, <Name>. Må Silvanas en dag anerkende din tapperhed. . . .", p="Har du fem Skumringsflagermus-pelse og noget Grov Tråd endnu, <Name>?"},
  [376] = {c="Tak, <Name>. Denne rustning burde hjælpe dig.\n\nForhåbentlig burde den gøre dig mere gavn end den sidste, der bar den...", p="Prøv nu dit bedste på at holde dig uskadt, indtil jeg får dig noget rustning."},
  [377] = {c="Så Dekstren Vagt endelig har betalt for sine forbrydelser mod menneskeheden? Godt rids for skidtet, siger jeg. Og skål for dig, min ven! Du har ikke blot givet de dødes familier den fred i sindet, de fortjener, du har også sendt et skarpt budskab til de korrupte bureaukrater i Adelshuset. Stormvind må imødekomme Skumringsskovens folks behov, ellers bryder vi fri af deres tyranni.", p="Så længe en skænder af de døde som Dekstren Vagt har lov til at leve, er retfærdigheden forrådt. Kom tilbage til mig, når Lord Ebenlås' dødsdom er fuldbyrdet over den besudler, Vagt. Vi skal give de dødes familier den afslutning, de fortjener, og endnu bedre: vi sender et klart budskab til Adelshuset i Stormvind."},
  [378] = {c="Så Kam Dybfuror fik endelig lov til at mærke, hvordan det er at stå i den modtagende ende af Døden? Godt. Det går den kujonagtige Mørkejern-pøbel ud af. Du har gjort det godt, <Class>. Ofrene for angrebet på Thandol-spændet var blot uskyldige i en verden revet i stykker af krig og uro. Deres familier får fred i at vide, at Dybfuror fik den straf, han fortjente. Langflettens brors død er hævnet.", p="Jeg vil ikke lade dumt menneske-bureaukrati blande sig i dværgiske anliggender, <Name>. Kam Dybfuror er en bevist medsammensvoren i angrebet på Thandol-spændet. Kong Magnis gode folk mistede livet på grund af Dybfurors svig. Mennesker kan være tilfredse med at lade Dybfuror rådne i Fængslet, men jeg vil ikke sove roligt om natten, før Dybfuror er slået ihjel."},
  [380] = {c="Hmm, nå, det er en start. Det tager nogle uger eller måneder at rydde op i hele angrebet. Bagefter må vi derned med nogle fakler for at brænde spindelvævet væk.\n\nDu har gjort din pligt godt, <Name>, jeg er sikker på, at jeg kan finde noget andet, du kan lave.", p="Vær på vagt over for edderkoppernes gift, <Name>. Hvis du mærker en skarpt brændende fornemmelse, bør du få det kigget efter."},
  [381] = {c="Hvis de bare lyttede til fornuften, hva', <Name>? Måske kunne vi sætte dem ned til en fornuftig samtale... ha!\n\nLet-blindede tåber.", p="De tosser... De sender sig selv i deres egne grave, med glæde."},
  [382] = {c="Hmm... Lad os se, hvad du har...\n\n<Han begynder at bladre i de dokumenter, du fandt.>\n\nNogle nyheder om deres bedrifter mod os... Værdiløst. Spejderrapporter... Nye ordrer: \"Fortsæt med at bygge en lejr op nær den ruinerede by...\" Intet, vi ikke vidste i forvejen... Ah, hvad er det her? Et kort over placeringen af nogle af deres feltkommandører og agenter! Det kan vi bruge.", p="Hvordan går din mission, <Name>?"},
  [383] = {c="Ja, dette er meget godt. Du har forvoldt det brønd ved at skaffe denne information, <Name>. Hmm... navnene på officererne i Tirisfals Lysninger...\n\nForestil dig det stød vi kunne give de blodige fanatikeres moral, hvis vi dræbte deres ledere i ét hurtigt slag.", p="Ja, hvad vil du have?"},
  [384] = {c="Malten er brygget, vildsvinene er døde\nOg inden alt er gjort og sagt, står bægeret tomt og øde\nVi må slås om første bid, det er bare sådan, vi har det\nMed disse læskende Øl-Glaserede Vildsvin-Ribbenspjæld!", p="Jeg får brug for seks klippevildsvin-ribben og en krus Rapsodi-malt, <Name>."},
  [385] = {c="Nå nu, det er fremragende eksemplarer, du har samlet, <Name>. Gode penge for materialer af høj kvalitet, det er sikkert.", p="Har jeg fortalt dig om dengang, jeg næsten mistede hånden til en af krokodillerne? Et ækelt kræ var det, med tænder som knive. Men jeg var heldig... Klemt udyrets kæbe fast med min kniv. Har stadig kniven her et sted..."},
  [386] = {c="Targorr den Frygtede har endelig mødt sin skæbne. Jeg for min del er glad for at høre, at udyret nu ved, hvordan det er at være på modtagersiden af Dødens ubarmhjertige greb. Du har gjort det godt, <Name>. Nogle gange kan den sande retfærdighed kun findes uden for retssalen og hinsides politikkens tågede blik.", p="Har du været i Stormvind endnu, til Fængslet? Jeg frygter, at det fupnummer, der har holdt Targorr den Frygtede i live så længe, til sidst vil bringe hans frihed. Han blev dømt til døden, <Name>, ikke til at optræde som politisk bonde for en adelsmands lune."},
  [387] = {c="Dine bestræbelser i Fængslet var tapre, <Name>. Det er åbenlyst, at dette problem er større end os to tilsammen. Men du har klaret dig godt, og for det er jeg taknemmelig.", p="Fængslet er stadig overrendt! Disse Defias-rotter må få at vide, at deres handlinger ikke bliver tolereret. Nu skal du tilbage derned og vise lidt styrke!"},
  [388] = {c="Så disse bandanaer -- beskidte tegn på korruption -- er det, min Mak måtte dø for? Sikke et spild. Sikke et tragisk offer.\n\nMen ak, jeg kan ikke vende tilbage til fortiden. Bare vid, <Name>, at du har bragt min familie retfærdighed gennem dine gerninger.", p="Jeg ser, du er tilbage, <Class>. Har du samlet de 10 Røde Uld-halstørklæder fra de Defias-skiderikker i Fængslet endnu?"},
  [389] = {c="Hvad i Let vil du have? Kan du ikke se, at vi har en krise her?\n\nBazil Tredd?! Hvorfor i alverden vil du tale med den bastard? Hvordan skal jeg vide, at du ikke er en af hans håndlangere, kommet ned for at hjælpe med hans forbandede optøj? Hvis ikke alle de sprængte celler var åbne, kunne jeg godt finde på at smide dig i en af dem en stund!"},
  [391] = {c="Uden Tredd til at lede dem, håber jeg, at optøjerne bliver lettere at styre. Vi får se.\n\nJeg må sige, efter en halv time forventede jeg næppe, at du kom ud, men det ser ud til, at jeg tog fejl af dig.\n\nJeg gætter så på, at du ikke fik meget brugbar information ud af ham? Men jeg kender et par ting, der kan være af interesse for dig om Tredds aktiviteter.", p="Enten bringer du mig Tredds hoved, eller også tager jeg dit, forstår du, <Name>?"},
  [392] = {c="Hmm. Mælik? Nej, navnet lyder ikke bekendt, og det gør beskrivelsen heller ikke. Men det kunne være hvem som helst! En tidligere Stenhugger, en af Defias-broderskabet... Men hvis han er så godt forbundet, som Thelvand antyder, kender måske nogen andre ham. Lad mig tænke.", p="Ja, <Name>? Hvad har du fundet?"},
  [393] = {c="Hvad? Hvad er det her? Ja, jeg tror faktisk, jeg ved, hvem manden er, men hans navn er ikke Mælik. Snigmordere bærer mange navne og mange masker og kaster dem, når de ikke længere er nyttige. Et andet alias, denne mand er kendt for at bruge, er Marzøn; men selv det er sikkert ikke hans rigtige navn.\n\nUanset hvad er han snigmorder, og jeg ved en hel del om ham.\n\nMarzøn er i øjeblikket i tjeneste hos Herre Gregers Lescovær, en herre med et lusket ry, selv med den korruption, der findes i adelen i Stormvind.", p="Hilsner. Hvordan kan jeg være dig til tjeneste, <Class>?"},
  [398] = {c="Maddikøjes nedrige gerninger er endelig blevet hævnet. Måske vil dine tapre gerninger sende et tydeligt budskab til dem, der ønsker at skade vores folk. På vegne af byen Gryde-by takker jeg dig, <Name>.", p="Ja?"},
  [399] = {c="Åh, tak, <Name>! Den har ingen praktisk værdi for mig, men den sentimentale værdi... Unødvendigt at sige, tak fordi du bragte den til mig... på bekostning af dit eget brøndvelvære, for slet ikke at nævne den tid, det tog at komme hele vejen ned til Vestfald. Du har min taknemmelighed, og tag dette mærke som tegn på min tak.", p="<Name>! Havde du noget held?"},
  [400] = {c="Har du mine værktøjer? Godt gået, dreng, godt gået! Jeg knækkede lige min sidste hugtand-skralde for en time siden, og jeg har brug for en af dem for at færdiggøre reparationerne på Pilot Stengears belejringsmaskine. Du gjorde en god gerning ved at slæbe de værktøjer herhen, <Name>.\n\nHer, tag disse mønter for din hjælp.", p="Hm? Du ser lidt for ung ud til at være pilot på en belejringsmaskine. Men det gør ikke noget...har du brug for noget repareret?\n\nTag et nummer og gør dig tilpas. Jeg arbejder på et par motorer lige nu og har ikke tid til et nyt job i mindst et par dage.\n\nEller var du her af en helt anden grund...?"},
  [401] = {c="Så er vi der. Den er oversat...\n\n<Luften bliver tung, som om et tykt, sort forhæng bliver trukket hen over landet...>"},
  [403] = {c="Denne tønde med øl bliver vogtet af Jarven Tordenbryg. Så længe han er i kælderen, må ingen tønder røres."},
  [404] = {c="Godt klaret. Jeg ærgrer mig over ikke at have været der for at se dig knuse de udøde til rådnende mos!", p="Har du fuldført den opgave, jeg har ladet dig få? Har du de stinkende klør?"},
  [405] = {c="Ah, du er agenten sendt af Dommer Sevrin. Så ja, dit ærinde hos mig er afgørende.\n\nJeg går ud fra, at Sevrin har udvalgt en passende person til min opgave... men vi får se.", p="Hilsner. Enten kender du ikke til, hvem jeg er, eller også er dit ærinde hos mig hastende.\n\nFor var ingen af disse ting sande, ville du ikke være tåbelig nok til at forstyrre mig..."},
  [407] = {c="Ved Let! Endelig noget mad! Sød, sød græskar. . . .", p="Hold dig væk, væmmelige og uhellige skabning! Må Lyset beskytte mig! Skarlagenrøde Korstog skal befri Azerot for dig. . .\n\n. . .å vent. Er det mad til mig? Jeg er så sulten. . ."},
  [408] = {c="Dine handlinger har rammet Svøben med et mærkbart slag. Og din sejr vil ikke gå ubemærket hen - hverken for De Forladte eller for vore fjender.\n\nFortsæt kampen, som vi alle gør, <Name>, og en dag vil vi drive Liskekongen selv fra Azerot!", p="Tid er ikke en luksus, vi har, <Name>. For hver time der går, bliver Svøbens greb om Tirisfals Lysninger stærkere."},
  [409] = {c="Du har besejret Lilith Nefara og dermed bevist, at du er en fjende af Svøben. Utroligt.\n\nJeg havde troet, jeg var den eneste Udøde med fri vilje, men du har vist mig, at der er andre, som har brudt Liskekongens herredømme.", p="Jeg venter på bevis for din troskab, <Class>."},
  [410] = {c="Du placerer Kaldelyset på bordet og tænder det...", p="Dette er et gammelt, slidt, blodigt bord."},
  [411] = {c="Du overtalte ham til at slutte sig til os! Du har gjort en stor gerning for De Forladte, <Name>. Den Mørke Dame vil blive underrettet.", p="Har du returneret Gunners bog? Har han svaret?"},
  [412] = {c="Disse Gyromekaniske Tandhjul og Restabiliseringshjul er i perfekt overensstemmelse med Ozis tegninger til Rekombobulerings-enheden. Når jeg har tilsat lidt hydrosmøremiddel til de indre forbrændingsstempler, justeret krum-o-rat-hjulet og øget viskositeten i elektrogummi-gelen, vil den gnomiske race være som ny.", p="Rekombobuleringsmaskinen vil være i gang, så snart vi har nok Restabiliseringshjul og Gyromekaniske Tandhjul."},
  [413] = {c="<Bjergbestiger Byggøl smager på Glimmer-Stouten...>\n\nÅh. Uha! Den her sag får virkelig et glimt i øjnene. Jeg føler, at jeg kan se i mørke!", p="Hej, <Class>! Og hvilket ærinde fører dig hele vejen herud?\n\nNoget spændende, håber jeg. Jeg har ikke været i en god kamp i flere dage, og denne ølfad er næsten tør..."},
  [414] = {c="Nu, lad mig smage...\n\nMagnies Skæg! Det her stads får hovedet til at dreje rundt! Og det letter lemmerne også.\n\nJeg føler, at jeg kan flyve!", p="Hilsner, <Class>, og velkommen til Tælsamar!"},
  [416] = {c="Puha! Da jeg bad om de ører, havde jeg ikke regnet med, at de ville lugte så grimt!\n\nHer er din belønning, <Name>. Godt gået.", p="Hilsen, <Name>. Hvordan går det med rottefangsten?"},
  [418] = {c="Stol på mig, det virker meget sværere, end det ser ud, men...\n\nOh, jeg har aldrig mødt nogen, der har vist den mindste interesse for pølsemageri, men jeg giver dig opskriften for en sikkerheds skyld. Værsgo, husk nu at spise dem friske!", p="Jeg er helt klar til at begynde madlavningen, har du ingredienserne til mig?"},
  [420] = {c="Hvad er det her? Ah, min brors rapport. Hmm...\n\nJeg bad ham være sparsom med brugen af Kongens navn, men han lyttede ikke. Ingen skade sket, må jeg vel sige, selvom det helt sikkert vil rode lidt op i nogle fjer i Senatet. Ikke at der ikke var nogle fjer, der trængte til at blive rodet op! Ha!\n\nIkke desto mindre må det betyde, at jeg bør sende min rapport videre til Jernsmede også, men jeg må indrømme, at jeg er en smule bagud. Blodig kulde.\n\nJeg burde have noget arbejde til dig senere, hvis du er interesseret.", p="Hvordan har du det? Har du lyst til at dele en drink med mig, måske? Der er ikke meget andet at lave i kulden."},
  [421] = {c="Du har tjent mig godt, <Class>. Det er tydeligt for mig, at du bliver en værdig hjælper for mig, når jeg gør mig klar til at befri Sølvfyrreskoven for Arugels forbandelse.", p="Hvis du ønsker at bevise dig over for mig, må du dræbe 5 Månevred Hvidskalpe. Fuldfør den opgave, så sørger jeg for, at dine færdigheder bliver sat til mere værdige opgaver."},
  [422] = {c="Det er præcis den besværgelse, jeg har søgt efter, <Class>. Hvis din hengivenhed til Den Mørke Dames sag forbliver ufejlbarlig, vil du opdage, at du har en ganske lys fremtid blandt De Forladte.", p="Før jeg ved, hvad vi har at gøre med her, <Class>, må jeg studere besværgelsen kendt som Arugels Middel. Bring den til mig nu, ellers må jeg se mig nødsaget til at finde en værdig tjener."},
  [423] = {c="Jeg håber, jeg kan udvinde nok energi fra en så begrænset prøve. Måske skulle jeg have fået dig til at skaffe flere lænker.\n\nIkke desto mindre viste du stor færdighed i at samle disse, <Class>.", p="Jeg skal bruge 6 Glubende Lænker og 3 Mørkesjæl-lænker, før jeg kan vurdere situationen og udtænke en endelig løsning på Arugel. Nu skal du adlyde din befaling og slå Månevred Glubende og Månevred Mørkesjæle ihjel, indtil du har det, jeg har brug for."},
  [424] = {c="Aldeles fortrinligt. Minen vil levere udsøgte ressourcer til vores styrker, når vi breder os ud over Sølvfyr og ind i Azerot.", p="Er Grimson den Blege blevet slået ihjel? Varimatras bliver ikke glad, hvis vi ignorerer hans befaling."},
  [425] = {c="Ah, tak. Du har min taknemmelighed, <Name>.\n\nOg jeg vil nævne dig i den rapport, jeg sender til mine overordnede.", p="Har du dræbt Ivar den Ækle? Hvis du ikke vil gøre det for mig og min bror, så gør det for De Forladte."},
  [426] = {c="Dine bestræbelser i krigen mærkes blandt os, <Name>. Jeg vil ikke takke dig for at gøre, hvad der er nødvendigt, men Tirisfals Dødevagter vil huske dit navn.", p="Vores kampe mod Svøben raser videre, <Name>. Gør din del og kast de forbandede, tankeløse udøde tilbage i Pestlandene!"},
  [427] = {c="Aldeles fortrinligt, <Class>. Din færdighed i kunsten at kæmpe er ubestridelig.", p="Hvis du ønsker at bevise din værdi over for Den Mørke Dame, så slå 10 Skarlagenrøde Krigere ihjel, <Class>."},
  [428] = {c="Du fandt os! Og ikke et øjeblik for tidligt..."},
  [429] = {c="<Renfærrel tager hjerterne.>\n\nDet er bekymrende at høre, at vores Dødsstalkere har fejlet deres mission.\n\nLad os håbe, at disse fiaskoer er sjældne.\n\nJeg giver dig eliksiren om et øjeblik, men her er opskriften - hvis de Dødsstalkere en dag får brug for bistand, kan du måske give den selv.", p="Min tid er knap, <Class>, for Den Mørke Dame har pålagt mig en alvorlig opgave."},
  [430] = {c="<Kvinde tager eliksiren og drikker den.>\n\nJa, jeg kan mærke, at den virker. Snart kan jeg rejse.\n\nDu har gjort mig en stor tjeneste, <Name>.", p="Min søster fortalte mig, at du var her for at yde os bistand. Er det sandt?"},
  [431] = {c="Du griber et af stearinlysene og stikker det i din rygsæk."},
  [432] = {c="Nå, det gør mig lidt bedre tilpas...\n\nMen jeg bliver ikke glad, før de alle sammen er døde! Alle sammen!", p="Det gør mig så gal! Grrr..."},
  [433] = {c="Det er en start. Forhåbentlig kan vi drage fordel af det og flytte nogle Bjergbestigere ind for at sikre området. Så kan vi begynde at genoprette vores infrastruktur og få minearbejderne tilbage på arbejde.\n\nTak for din hjælp, <Name>.", p="Hvis vi kan fjerne troggerne fra Gol'Bolar-stenbruddet, bliver det første skridt af mange, vi må tage for at blive af med denne plage."},
  [434] = {c="Så det er gjort? Godt. Mange tak for din diskretion, <Name>. Du har bevist din værdi mere end én gang. Jeg skal nok holde øje med dig og dine fremskridt inden for Alliancen.\n\nSørg for at holde næsen ren.", p="Ja, <Name>? Går det godt med Tyrjon? Han orienterede mig om situationen, og jeg har hjulpet ham med at narre Marzøn op i slottet.\n\nMarzøn har været en torn i øjet på mange i Stormvind; mange af dem er gode venner af mig. Ingen roder med mine venner... ikke hvis de ved, hvad der er sundt for dem.\n\nDet er bare en skam, at jeg imens indirekte gør en tjeneste for Skaw og SI:Syv. Nå, sådan er det, ikke enhver plan er perfekt."},
  [436] = {c="Jern vil gerne vide, hvad forsinkelsen er, hva'?\n\nJernbånd samler sin seneste fremskridtsrapport med detaljer, men jeg kan fortælle dig dette:\n\nDet er Trolde!!"},
  [437] = {c="Jeg hørte om dit vellykkede razzia mod de rådne huder, <Name>, og denne essens er bevis på Natpisks død.\n\nSvøben har tabt terræn i dag. Din værdi for De Forladte vokser.", p="Har du besejret Natpisk, <Name>? Vores sejr over de rådne huder afhænger af hendes undergang!"},
  [438] = {c="Stablet op inde i denne båd ligger en bunke svøbte lig. Og kigger man mod øst over Lordamere-søen, kan man se en modstående kaj på Fenris-øen.\n\nDe svøbte ligs skæbne må ligge på Fenris-øen."},
  [439] = {c="Siger du, at denne ring blev båret af en kvinde, der for nylig er blevet dræbt?\n\nDen eneste nærliggende kilde til et sådant lig ville være massegravene i Tirisfal. Rådhud-gnoldene må være ved at transportere de lig til Fenris-øen!", p="<Name>. Du vender tilbage, så jeg går ud fra, at dine undersøgelser har båret frugt?"},
  [440] = {c="En Deliah boede faktisk i Gryde-by for ikke så længe siden. Hun blev begravet i massegraven, men hvis det, du siger, er sandt, må Rådhud-gnoldene have stjålet hendes lig og taget det til Sølvfyr.\n\nRådhuderne må, ligesom hele Svøben, udryddes. Jeg stoler på, at du tager skridt til at få det til at ske.", p="Hej, <Name>. Hvad fører dig tilbage til Gryde-by?"},
  [441] = {c="Ja, denne ring var min kones. Hendes skæbne var den skæbne alle må lide, der ikke formår at udholde disse hårde tider. Jeg føler intet for hendes død, og heller ikke for historien om, at hendes lig blev bortført.\n\nSådanne følelser er for længst blevet kolde i mig. Men længsel brænder stadig i mit døde hjerte, <Name>.\n\nLængsel efter hævn.", p="Kender jeg dig?"},
  [442] = {c="Thule Ravnekloes død var ingen lille begivenhed, <Name>. Renfærrel fortæller mig, at energierne, der blev frigivet, da du ødelagde Thule, kunne mærkes helt til Gravkammeret.\n\nDine handlinger runger gennem De Forladtes rækker. Din værdi for os vokser.", p="Svøben kan ikke få lov til at blive i Sølvfyr, <Name>. Kom tilbage til mig, når du har bevis for Tules død."},
  [443] = {c="Meget godt. Denne ikor vil hjælpe os med at forstå de rådne huders natur, og den kan måske vise os deres svaghed...\n\n...hvis de har en.", p="Har du rådnehud-ikoren, <Name>?"},
  [444] = {c="Dette stof er gennemsyret af kraftfulde besværgelser, hvoraf nogle jeg ikke har set i lang, lang tid...\n\nVent et øjeblik -- jeg må påkalde en besværgelse af spådom...", p="Mine studier kræver stor koncentration. Så jeg håber, dit besøg ikke er et letsindigt et."},
  [445] = {c="Ah, hvor pænt af Apoteker Johan at sende sin forskning. Med så mange nye tiltag her i Sølvfyr var jeg næsten ved at glemme fundene fra Herrelande og Tirisfals Lysninger. Det minder mig om, at jeg snart må få de prøver sendt af sted til Nekropolis.\n\nMen du må undskylde mit vrøvl. Forlæng dit ophold i Sølvfyr, <Name>. Vi kunne godt bruge en duelig <Class> som dig her omkring.", p="Hvad har du at gøre med mig, <Class>?"},
  [446] = {c="Denne rulle er gennemsyret af kraftig magi. Jeg har aldrig brugt sådanne kræfter i et eliksir ... det bliver en kraftfuld blanding, og den bør gøre dig gode tjenester, hvis du angriber Tule i hans fæstning på Fenris-øen.", p="Hilsner, <Name>. Hvad havde Bethor at sige?"},
  [447] = {c="Hvor heldigt, at Apoteker Renfærrel sendte dig til mig, <Name>. Disse prøver vil sandelig vise sig nyttige for sagen. Jeg begynder straks at studere deres giftige og smittefarlige egenskaber.", p="Hilsen, <Class>. Hvad har du at gøre hos Det Kongelige Apotekerselskab?"},
  [448] = {c="Hvis det, Bethor siger, er sandt, så er Thule Ravnekloe en kraft, der skal tages hånd om, og det hurtigt.\n\nFor at hjælpe med denne opgave må du tage noget fra vores våbenlager her..."},
  [449] = {c="Jeg havde ikke regnet med det niveau af Svøben-tilstedeværelse, vi har set i Sølvfyrreskoven, og heller ikke med de problemer, vores Dødsstalkere har haft med deres spejderarbejde.\n\nDin bistand til vores Dødsstalkere var uvurderlig, <Name>. Og du vil blive rost for det.", p="Opdagede du skæbnen for Dødsstalkerne?"},
  [450] = {c="Apoteker Berards dagbog! Du er da ganske modig, <Name>. Lad os se, hvad Berard fandt på, før han blev gal. . .", p="Jeg ser, du er tilbage, <Name>."},
  [451] = {c="Sådan et slag for Det Kongelige Apotekerselskab at miste Berard. Men gennem dit hårde arbejde og Apoteker Renferrels flittige forskning vil Berards studier stadig være nyttige for Den Mørke Damens nød.\n\nVi står på randen af noget stort her, <Name>. Hvis du ikke var så dygtig i kampens kunst, ville jeg forsøge at hverve dig til medlemskab af Selskabet.", p="Hvad fører dig tilbage til Undergrunden, <Name>?"},
  [452] = {c="Du kæmpede som en sand discipel af Den Mørke Dame, <Name>. Med rådet dødt kan vi måske endelig få kontrol over denne by og drive Arugel væk fra Skyggehugger-fæstningen. Jeg salutérer dig!"},
  [453] = {c="<Ryster sukker...>\n\nJa, jeg er forfatteren af den bog. Du fandt mig endelig, hva'?\n\nNå, hvis du læste den dagbog...så kender du kun halvdelen af det!", p="Hvem er du?? Forlad mig!"},
  [454] = {c="Hej, <Class>.\n\nSkal du eskortere mig til udgravningsstedet? Det er godt at høre... Efter Saeen og hans håndlangere, hvem ved så, hvad Mørkjernsdværgene ellers har gemt i ærmet?\n\nMen lad mig lige lave nogle sidste tjek. Tal til mig igen, når du er klar til at gå."},
  [455] = {c="Din rapport er fuld af dårlige nyheder!\n\nJeg kan se, at Drageskæberne gør et kraftigt træk ind i Algaz. Normalt gemmer Drageskæberne sig bare oppe i bakkerne. Hvad der fik dem til at styrte ind i Algaz, er stadig et mysterium...\n\nTak, <Name>. Og vi får nok brug for din hjælp til at tage hånd om de orker.", p="Kommer du fra Modansøen? Hvordan står det til med ork-situationen ved Algaz-porten?"},
  [456] = {c="Du udførte dine pligter godt, <Name>.", p="Der er stadig arbejde at gøre, <Name>. Kom tilbage til mig, når du har tyndet ud i bestandene af natsabler og tidselvildsvin."},
  [457] = {c="Du har godt bevist din hengivenhed over for naturen, <Name>. En ung <Class> som dig har en lovende fremtid.", p="Din opgave er endnu ikke fuldført, <Name>. Vend tilbage til mig, når 8 skaldede nattesabeltigre og 8 tidselvildsvin er blevet dræbt."},
  [458] = {c="Jeg ser, du fandt mig, unge <Race>. Melitar er en klog druide at have sendt dig."},
  [459] = {c="Din tjeneste mod væsenerne i Skyggedalen er belønningen værd, <Name>.\n\nDu bekræftede dog mine frygt. Hvis gruller er blevet besmittet af Ondmos, kan man kun forestille sig, hvad der er blevet af Knudefyr-stammen af pelsbjørne, der engang boede her.\n\nHvis du skulle befinde dig i Dolanår, dygtig <Class>, så søg den vidende druide Athridas Bjørnekappe. Han deler vores bekymring for skovens velfærd.", p="Stil mine mistanker, <Name>. Bring mig 8 Ondmos."},
  [460] = {c="Tak, <Name>. Jeg frygtede, at gnollerne havde ødelagt min krop. Det er godt at vide, at de ikke gjorde.", p="Denne grav blev gravet i en fart."},
  [461] = {c="Der var vi, den er åben. Forlad mig her. Jeg tilbragte de bedste dage i mit liv i dette fort, og tanken om at hvile inden for dets mure giver mig trøst.\n\nSørg for at lukke nichen godt til - jeg vil ikke have, at Rådhuderne finder mig.\n\nÅh, og tag den her. Den har du fortjent.", p="Det er stedet! Før mig tættere på..."},
  [463] = {c="Rødderne og bregnerne taler godt om dig, lille én. Selvom jeg har mange navne, svarer jeg kun til ganske få af dem. Men du må gerne kalde mig Rethiel.\n\nOg du må lytte... for disse lande græder af betændte sår, og jeg vil pålægge dig at hele dem."},
  [464] = {c="Godt kæmpet, <Name>. Drageskæberne er ikke den samme trussel, som de var dengang, de havde drager, men de er stadig voldsomme modstandere.\n\nDrageskæberne ledes af Nekrosh, søn af Nekrøs, som for år tilbage var den tidligere leder af Drageskæberne. Nekrøs brugte kraftfuld magi til at tæmme de Røde Drager, men da magien svigtede ham... var dragerne ikke glade.\n\nNekrøs blev dræbt, og hans søn har svoret hævn over de drager, der slog hans far ihjel.", p="Har I angrebet Dragemave-lejren?"},
  [465] = {c="Du lægger noget tændsel på katapulten og slår så en gnist ned i det.\n\nFlammen bryder ud og breder sig hurtigt!", p="Den første katapult står foran dig. Vil du sætte den i brand?"},
  [466] = {c="Du fik malmen! Godt gået, <Name>! Jeg får straks nogen til at arbejde med den. Lad os håbe, han ikke sprænger sig selv i luften!", p="Hvor er den malm, <Name>?!"},
  [467] = {c="Hej <Name>. Du er her vedrørende opgaven, jeg har, hva'? Det er godt at se en ung <Race> som dig, hvis blod brænder ved udsigten til eventyr!"},
  [468] = {c="Hej, <Class>! Du er her for spejdermissionen, er du? Meget godt!\n\nJeg håber dit udstyr er i god stand, for denne \"spejder\"-mission er forvandlet til noget mere rodet..."},
  [469] = {c="Hmm, det er fra Ejnar, ikke? Har ikke leveret sine skind til mig personligt i næsten en uge nu. Der er uden tvivl nogle uenigheder med konen!\n\nMåske sender jeg min kone over for at tale med Sida en dag...", p="Hej der, <Class>. Kunne jeg interessere dig for et par støvler? Måske nogle nyligt garvede skind?"},
  [470] = {c="Åh, tak, <Name>! Jeg var bange for, at den var tabt for altid!\n\n<Hun tømmer hurtigt indholdet af den slimvæsen-overtrukne taske ud på jorden, før hun samler det op igen.>\n\nHmm, jeg har ikke meget brug for det længere, men vask det af, så er jeg sikker på, at du kan finde på noget at bruge det til.", p="Fandt du min taske?"},
  [471] = {c="Hmm... Du har vel ikke lyst til at blive min lærling, vel?\n\nHah! Nej, jeg driller bare. Du er alt for gammel, for det første. Desuden - ud fra hvordan du ser ud, må du have andre ambitioner i livet. Ikke desto mindre er det nogle fine skind, du har skaffet, og jeg kan godt bruge dem.", p="Min lærling er som en søn for mig. Det bliver svært for ham at leve sit liv med kun ét ben.\n\nAh, <Name>, hvordan går det? Har du mine skind?"},
  [472] = {c="Hvilken modig <Class> bringer bud fra Menetil? Ah, <Name>, sådan kalder de dig.\n\nDu bringer håb til en håbløs situation. Det er virkelig gode nyheder, at unge Harlø overlevede. Under flugten fik han et grusomt sår. Vi havde kun lidt tid til at sende ham afsted på ryggen af den eneste overlevende hest i regimentet.\n\nMen nu står vi over for en farefuld situation. Dun Mødr er faldet, og vi er kun en skygge af det store regiment, vi engang var."},
  [473] = {c="<Name>. Valstag orienterede mig om dine tidligere succeser med Dragemave-orkerne ved Algaz-bakken. Du er en <Race> af værdi.\n\nOg jeg har en opgave til dig."},
  [474] = {c="Flot gjort, <Name>. Du har tilføjet Dragemave-orkklanen et afgørende slag. De kommer måske aldrig til at komme sig. Og ødelæggelsen af de katapulter har gjort Menetil-havnen tryg.\n\nDu er en <Race> med fortjenester, og Jernsmede-kongeriget belønner dem, der tjener det godt.", p="Har du dræbt Nekrosh?"},
  [477] = {c="<Når du brækker lågen af kassen op, finder du en samling omhyggeligt pakkede genstande. Øverst i kassen ligger et bundt kort, gulnede af alderen, som ser ud til at forestille Sølvfyrreskoven og andre dele af det vestlige Herrelande.\n\nUnder kortene ligger et mystisk udseende magisk vedhæng.>"},
  [478] = {c="Kort og dette... anhæng, hm? Interessant.\n\nDet er tydeligt, at Dalarn-troldmændene er interesserede i Ambermølle af en eller anden grund, men deres mål er stadig skjult for mig.\n\nMåske ved Dalar Morgenvæver noget om, hvad det skal bruges til.", p="Har du lært noget nyttigt, <Name>?"},
  [479] = {c="Dalar har opdaget, at vævningen er temmelig langt fremme, på trods af tilbageslaget.\n\nEn magiker med stor kraft styrer magiens energi. Han skal stoppes hurtigt.", p="Vi må skynde os, deres planer må ikke blive til noget, ellers kan vi miste vores greb om Sølvfyrreskoven."},
  [480] = {c="Troldmændenes magi opløses, og ley-energierne falder i dvale. Din indsats har båret frugt, <Name>, og vi har givet vores fjender et alvorligt slag, og de storsnudede troldmænd fra Dalarn.\n\nVi må dog være på vagt, for vi ved, at energikilden ligger så tæt ved hånden... Der må laves Tegninger til fremtiden.", p="Hurtigt, tiden er knap, <Name>!"},
  [481] = {c="Interessant, flere af Kirin Tårns intriger, det lader til. Dette er et kraftfuldt artefakt. Det blev ofte brugt af mægtige troldmænd i Kirin Tårn til at kanalisere magiske energier.\n\nAt de leverer så mange til Ambermølle, tyder på, at de må være i gang med et projekt af en vis størrelse.\n\nJeg vil se, om jeg kan gennembore deres skjolde og fastslå deres hensigt.", p="Ja, <Class>? Hvad er det?"},
  [482] = {c="Dårlige nyheder bringer du, <Name>. Hvis Dalar har ret – og jeg har ingen grund til at tro andet – må vi handle hurtigt.\n\nJeg må rådslå med ham om vores angrebsplan. Men i mellemtiden må vi forsinke deres fremmarch."},
  [483] = {c="Du er lykkedes, unge <Class>! Godt gået. Og lige til tiden, må jeg tilføje.", p="<Name>, de bortførte Klodruiderne vil for evigt være fanget i Den Smaragdgrønne Drøm, hvis vi ikke kan hente Vækkelsens Relikvier fra Ban'ethil-gravhulen mod vest.\n\nHver minut vi forsinker deres skæbne, kommer den et skridt nærmere evig død."},
  [484] = {c="Godt arbejde, du har udført her, <Name>. Kvaliteten af disse skind er fortræffelig. Jeg må få dem i garvningsprocessen så hurtigt som muligt. Åh, men før jeg kommer til det, er der noget andet arbejde, jeg har brug for udført, og jeg tror, du måske kan klare det.", p="<Name>, ikke sandt? Har du mine skind?"},
  [486] = {c="<Name>, du har bevist dig selv som en yderst værdig og dygtig <Class>. En <Race>, der følger ærens vej lige så sikkert som du, er sikker på at finde stor herlighed i denne verden.\n\nMå skovens ånder beskytte dig, hvorhen dine rejser end fører dig.", p="Vores brødre kan ikke vækkes, før Ursal Lemlæster er slået ihjel, <Name>."},
  [491] = {c="...hvad er dette? Thule havde vores Flettede Stav? Jeg troede, den var gået tabt, da vores venskab gik i stykker, og han sluttede sig til Liskekongen!\n\nHan må ikke have påkaldt dens kraft, for havde han gjort det, ville jeg have mærket det. Og det er godt, at han ikke brugte den...\n\nDette er et vidunderligt fund. Du har min taknemmelighed, <Name>, og du vil blive belønnet.", p="<Name>. Har du besejret Thule Ravnekloe?"},
  [492] = {c="Ah, endelig en drik. Jeg er sikker på, at det ikke er nogen Rapsodi-malt, men jeg tager alt for at fugte den gamle fløjt lige nu.", p="Hvis jeg bare havde min pålidelige riffel, var du så god som død, <Class>. Vent bare, til Damp-stridsvogns-brigaden kommer og redder mig!"},
  [493] = {c="Ah, fortræffeligt. Apoteker Renfærrel har al min respekt. Jeg er ivrig efter at studere hans arbejde.", p="Har du noget til mig?"},
  [494] = {c="Ravnens råb fra vest lokker vel?\n\nFremragende nyheder! Bakkebrad er moden til angreb. Vi kan udføre vores ødelæggelsesplan nu. Varimatras vil blive glad."},
  [496] = {c="Disse prøver er perfekte. Nå, <Name>, du har formået at bringe mig det mindste glimt af glæde på endnu en elendig dag. Din indsats er sat pris på.", p="Jeg ser, du er tilbage. Jeg håber, du fik samlet de agenter, jeg har brug for. Endnu en udødelig dag vil sætte mig i så dyster en stemning."},
  [498] = {c="Så menneskene troede, de kunne gøre vores krigere til slaver, gjorde de? Vi skal vise dem!\n\nDet lader til, at de har taget Gulddyr, vores leder, med til et andet sted. Vi må finde ham og redde ham. Men vi har i øjeblikket ingen anelse om, hvor han er...\n\nNår vi har en ledetråd, skal jeg nok sige til dig, <Name>.", p="Du må skynde dig, <Class>. Jeg gyser ved tanken om, hvad menneskene mon gør ved Drull og Tog'thar."},
  [499] = {c="Kvæk!", p="Kvæk!"},
  [500] = {c="Meget godt, <Name>. Du må have hakket dig igennem en hel masse oger for at få alle disse knoglefingre.\n\nDet burde holde dem ude af vores hår. I hvert fald et stykke tid.", p="<Name>, jagter du stadig oger? Har du de knoglekugler, jeg bad dig samle?"},
  [501] = {c="Storartet indsamlet, <Name>.", p="Jeg husker dig, <Name>. Du skulle have hjulpet mig med at brygge mit nyeste elixir. Jeg skal bruge det blod, før jeg kan bringe mit eget særlige brandmærke af elendighed til indbyggerne i Bakkebrad."},
  [502] = {c="Du hælder noget af elixiren ud i hånden og holder den foran Stanleys mund.", p="Vuf?"},
  [503] = {c="Tak, <Name>. Jeg ledede ekspeditionen fra Durdotar under Krigshøvdingens ordrer, men som du kan se, gik vores planer lidt skævt. De har holdt mig fange her i denne by, tvunget mig til at arbejde, slæbe byrder, grave...\n\nHvad jeg har lidt er dog uvigtigt. Der er vigtige oplysninger, som du skal levere til den, der nu leder vores gruppe.", p="Giv mig nøglen, <Class>, jeg skal selv låse lågen op."},
  [504] = {c="Meget godt. Her er din belønning.\n\nOg da du jagtede de krigsmagerne, hvordan så Alteraz-byen ud? Den er vel i dårlig forfatning, tror jeg. Oger er ikke kendt for deres renlighed.\n\nHeldigvis vil din indsats være med til at holde dem væk fra Sydstranden.", p="Du har flere krigsmagere at slå ned, <Name>. Du burde være oppe i bjergene og passe din opgave, ikke nede her med dit våben stukket væk."},
  [505] = {c="Tak, <Name>. Selvom de måske stadig lurer rundt, håber vi, at nogle af tyvene og gaderøverne, du slog ihjel, var ansvarlige for den sidste dommers død. Men selvom de ikke var det, er Syndikatet en plet på dette land og en skamplet for menneskeracen.\n\nDeres død er velkommen i Sydstranden.", p="Du har slået de Syndikat-bøller ihjel, tør jeg tro?"},
  [507] = {c="Nej, nej, vær venlig, gør mig ikke fortræd! Jeg har aldrig ønsket dit folk nogen skade, han har holdt mig fanget mod min vilje! Vær venlig... skån mig!", p="H-hvad vil du?"},
  [509] = {c="Ah, den forfærdelige stank af Mudderblomster. Men de beskidte gnolde er da til noget.", p="Har du haft held på Nethander-gården?"},
  [513] = {c="Apoteker Lydon sendte dig? Ah, hvorfor sagde du det ikke!\n\nTrods sit mørke sind er Apoteker Lydon et af vores mest hengivne og dygtige medlemmer.\n\nKarlen sender Mudderblomst-komposit! Jeg ved, hvad vores ven i Hillsbrad har gang i nu. Og jeg kan godt lide, hvordan han tænker. Den Mørke Dame ville være imponeret over de fremskridt, han gør mod den nye pest.", p="Kan du ikke se, at jeg er optaget, <Class>? Den Mørke Dame insisterer på en ny pest, før Svøben rykker frem fra Nordrend og overvælder os. Og med den menneskelige trussel, der presser på fra syd, er tid blevet min mest dyrebare vare. Det her må hellere være vigtigt!"},
  [515] = {c="Spændingen ved dette eksperiment får mig til at svimle! Du har været så stor en hjælp, <Name>. Sammen vil vi sprede død og smitte over dette land!", p="Så glad for at se dig igen, <Name>. Jeg var ved at kede mig så forfærdeligt her. Ikke en eneste underholdende ting at tage sig til, bortset fra at forgifte og smitte Umpi og genoplive hende. . .igen og igen og igen.\n\nHvordan gik turen til Undergrunden? Havde du heldet med dig og fik slagtet nogle mennesker undervejs?"},
  [516] = {c="Hvis vores spejdere og agenter bliver ved med at skaffe værdifulde oplysninger som denne, vil vi have Liskekongens Svøben fjernet fra vores lande på ingen tid.", p="Har du fundet deres base endnu, <Name>? Tiden er af essens!"},
  [517] = {c="Endelig! Nu er vi klar til handling!", p="Nogle gange bliver jeg så kedet herude i Tarrenmølle, at jeg åbner krukken med formaldehyd og lader den dejlige aroma sive ud i luften. Det gør Umpi lidt nervøs, må jeg sige.\n\nSå, fik du så fat i en fad fra Dværgene? Jeg sværger, at hvis jeg skal stirre på dette dødbringende elixir en dag mere uden at bruge det på nogen, så skriger jeg."},
  [527] = {c="Hvil dig, <Class>. Jeg ser, du er vendt tilbage fra slaget. Mine kilder fortæller mig, at du klarede dig godt på Bakkebrad-fronten.", p="Som Overeksekutoren i Tarrenmølle, under direkte kommando af Varimatras og Den Mørke Dame, er du mit emne og skal adlyde min kommando.\n\nMener du måske, at krigen mod Alliancen er let? Hvis det er tilfældet, bør jeg halshugge dig lige her og nu. Ellers skal du rejse vestpå til byen Bakkebrad og føre slag mod menneskene, som befalet.\n\nAfskediget."},
  [528] = {c="Dødens greb strammes om byen Bakkebrad. Slaget går godt.", p="Du har dine ordrer, <Class>. Hold op med at dovne her i Tarrenmølle, når der er arbejde at gøre andre steder."},
  [529] = {c="Missionen er fuldført, <Class>. Og udført ganske dygtigt, må jeg tilføje.", p="Kunne du udføre dine ordrer, <Class>? Fik du gjort det af med Værktan og hans assistenter? Og hvor er den jernforsendelse?"},
  [530] = {c="Ah, godt. Disse hænder dræbte min kone, Deliah. Hævn for hendes mord var min eneste bekymring, og du var redskabet for den hævn.\n\nVær så venlig, tag ringen, du returnerede tidligere. Deliah har været død for mig så længe, at hendes ring er et pyntenips, jeg ikke længere gider at beholde. I stedet vil jeg beholde disse hænder som en erindring om min vens forræderi.", p="Har du de hænder, <Name>?"},
  [532] = {c="Nyheder om dine herligheder i Hillsbrad rejste hurtigt. Du har gjort det godt, <Class>.", p="Hvilke nyheder har du?"},
  [533] = {c="Endelig ved vi hvor Gulddyr holdes fanget. Lejren i spørgsmålet er ikke langt herfra, og forhåbentlig er de ikke lige så velforberedte som da de fangede os første gang.", p="Har du fundet noget? Jeg frygter, at Gulddyrs udsigter bliver værre for hver dag..."},
  [535] = {c="Eftersom min død står for døren, tror jeg trygt kan sige at dette er den sødeste smag der nogensinde har været... Her, tag den, den gavner mig ikke når jeg er død.\n\nNå, skynd dig så!", p="Bragte du mig noget drik, eller kom du bare tilbage for at gøre jobbet færdigt?"},
  [536] = {c="Jeg håber, at det bliver nok til at overbevise Rødsti om, at jeg--ha!--har fulgt hans ordrer og renset Sydstranden for den forfærdelige og grusomme plage fra de frygtede mudderfisk! For der kunne ikke være større ondskab end overvoksne fisks hærgen!", p="Endnu en øl, tak, den sidste ser bare ud til at være forsvundet!\n\nLet, hvor længe skal jeg sidde fast herude?\n\nÅh, det er dig, <Name>. Har du dræbt de mudderfisk endnu?"},
  [538] = {c="Ah ja, jeg husker Mildon. En bogorm, uden tvivl. Velsign ham.\n\nOg han har ret. Ruinerne af Alterac gemmer stadig på viden, der er i fare for at gå tabt!\n\nOgre bor nu i Alterac, og de bryder sig ikke meget om højere læring."},
  [539] = {c="Den Mørke Dame vil blive glad, når hun får at vide, at hun har en ny mine, hvorfra hun kan bevæbne sine soldater.", p="Du fik direkte ordre om at angribe Azureload-minen. Dine grunde til at drive rundt i Tarrenmølle må være gode, ellers lader jeg dig halshugge for landsforræderi."},
  [540] = {c="Åh, du fik dem! Storartet! Jeg må straks begynde at studere Grimleks Arm!", p="Jeg ville ønske, jeg også kunne søge i ruinerne, men jeg frygter, at disse knogler ikke ville holde mig under klatringen op ad bjergene. Men hvordan skrider din jagt efter viden frem, <Name>?"},
  [541] = {c="Dine bedrifter på slagmarken er værdige til den højeste lovprisning.", p="Garok-bakken viser sig at være for stor en forhindring for dig, <Class>? Og jeg troede, du havde gjort dig tapper i Bakkebrad.\n\nHvis du ikke er i stand til at håndtere den mission, du har fået tildelt, finder jeg en anden, der kan levere bedre resultater. Hvad dig angår, så er jeg sikker på, at Den Mørke Dame altid kunne bruge flere gravere tilbage i Tirisfals Lysninger."},
  [543] = {c="Ah, dette er storartet. Det skal selvfølgelig renses, men du har virkelig overgået dig selv, <Name>. Jeg får nogen til at gøre tiaraen klar og placere den i vores samling omgående.\n\nSom jeg er sikker på, du vil være enig i, er vores taknemmelighed lige så storslået som vores samling.", p="Vær hilset, <Name>. Prøv venligst at undgå at træde på mine bukseben. Denne dragt er nysyet."},
  [544] = {c="Du har gjort De Forladte en stor tjeneste, <Name>. Disse artefakter har været bittert savnede.\n\nOg det er godt at høre, at Kegøn og de andre forrædere har fundet retfærdighed.", p="Har du fundet tyvene? Og endnu vigtigere: Har du fundet det, de har stjålet?"},
  [545] = {c="Meget godt. Disse ruiner burde nu være sikre nok at søge i, hvis man er forsigtig.\n\nTak, <Name>.", p="Har du endnu tyndet Dalarn-patruljerne ud omkring deres ruiner?"},
  [546] = {c="Dyrebare kranier! Så smukke! Jeg skylder dig som lovet, <Name>!", p="Så vender den heldige <Name> tilbage? Hvor mange mennesker har du slagtet i dag? Hundredvis, håber jeg da!\n\nHar du nogen kranier til mig?"},
  [547] = {c="Du fandt det!\n\nAh, jeg føler mig så komplet med mit dyrebare sværd tilbage i hånden. Mange tak til dig!", p="Kunne du hente mit sværd, <Name>? Højeksekutor Darthalia vil hænge mig op i loftsbjælkerne, hvis hun opdager min dumhed."},
  [549] = {c="Fremragende, <Class>. I dette tempo er Syndikatets plage væk fra landet på et øjeblik.", p="Har du ikke noget bedre at tage dig til end at stå her foran mig, <Class>? Som Overeksekutoren har jeg vigtigere sager end at stirre på dit rådne fjæs."},
  [550] = {c="Så du er den berygtede <Class>, der slog så afgørende til mod Alliance-styrkerne i Hillsbrad-forbjergene? Nyheden om dine strålende bedrifter nåede hurtigt til Undergrunden.\n\nDu har en glimrende fremtid i Den Mørke Dames rækker, hvis du fortsætter med at vise sådan lederskab og ekspertise i kamp.\n\nMens vores primære trussel er Liskekongens Svøben-hær, der nedstiger fra nord, forhindrer det menneskelige \"problem\" stadig vores slagplaner. Du har dog vist, at menneskene kan og vil falde.", p="Hvad får en <Class> til at tage hele vejen til Undergrunden fra slagmarken?"},
  [552] = {c="Du fandt den! Ganske fremragende, <Name>!", p="Har du fundet Helkulars Stav endnu? Der er så mange Yeti i denne region, at den bliver meget svær at finde. Men vi må have den, hvis vi skal komme videre."},
  [553] = {c="En kraftig rumlen stiger op fra jorden.", p="Helkulars grav vrimler med en mystisk energi."},
  [555] = {c="Alle bliver så glade: Kok Jessens Beroligende Skildpaddebisque serveres igen!", p="Har du haft held med at finde ingredienserne? Jeg siger dig, dette område er ikke længere det fredelige sted, det engang var. Ak, hvis blot denne uro aldrig var opstået. . ."},
  [556] = {c="Disse duer udmærket. Selvom det ser ud til, at deres magi er bleget, ville det være bedst, om Magusens første eksperimenter blev lavet på inerte prøver som disse.\n\nTak, <Name>.", p="Har du de Slidte Stenmærker, <Name>? Magusen er ivrig efter at låse deres hemmeligheder op."},
  [557] = {c="Du fandt dem. Jeg går ud fra, at de elementarer, du fjernede disse armbeskyttere fra, var venlige?\n\nHm... død har ikke blot standset mit hjerte, men også røvet mig min komiske timing, ser det ud til.\n\nNå, tak, <Name>. Du tjener Magusen, og dermed Den Mørke Dame, godt.", p="Hej, <Name>. Elementarer er et sejt bytte, men jeg ved, at du er klar til opgaven. Har du de bindende armbeskyttere?"},
  [559] = {c="Åh, for Kærligheden til Let... de drypper på jorden.\n\nKan ikke udstå at røre ved de ting selv. Fisk er alt godt og vel, men når de vokser ben og begynder at gå rundt... Jeg har ikke spist en fisk i uger, kan jeg fortælle dig, og i Sydstranden betyder det, at man ikke spiser meget.", p="Fik du de hoveder til mig, <Name>?"},
  [564] = {c="Er det ikke fantastiske nyheder! Skulle'a gået og fundet mig en almindelig gammel krigshelt fra dag ét til at tage sig af de bæster. Du ville have gjort din far stolt, <Name>.", p="Bjergløver dræber vores heste til højre og venstre, og her står du og vil tale tosset om vejret og sådan noget.\n\nBurde gå ud og finde mig en rigtig helt. Mere dræben og mindre snakken."},
  [565] = {c="Nu er tiden kommet for den store Bartolo til at gøre sin magi! Jeg har ingen brug for en magikers stav, ingen magikerstok. For jeg, den store Bartolo, udfører magi med blot en nål og tråd!", p="Så du er vendt tilbage til den store Bartolo. Måske er du færdig med at samle de materialer, du skal bruge til din Yetipels-kappe? Eller måske nyder du bare at boble i min storhed, Bartolo!"},
  [567] = {c="Du er ret så en dusørjæger, <Class>. Godt gjort.", p="Ja?"},
  [575] = {c="Disse skind bør gøre det. Deres kvalitet er ikke så vigtig, al den stund de skal danne det indvendige lag i støvlerne, men det er stadig vigtigt, at de er behagelige.\n\nHvis de er lidt for stive, bruger jeg noget tigerblod til at blødgøre dem. Håndværkskneb, ved du nok.", p="Mit udstyr er klar til at gå, <Name>, jeg mangler blot de skind. Vi vil ikke lade Direktør Riddlevox vente, det er sikkert.\n\nDet er ingen god idé for nogen at lade chefopfinderen i Tinkerforeningen være utilfreds."},
  [579] = {c="Interesserer nogen af disse titler dig, <Name>?", p="Kong Anduin har lagt stor vægt på læring, og har derfor sørget for midler, så offentligheden kan få kopier af diverse tomer og skrifter. Det er meget enkelt. Du bringer mig en biblioteksseddel, og så kan jeg give dig en kopi af en af de tilgængelige bøger."},
  [581] = {c="Det er gode hugtænder, <Name>. Du beviser, at du har styrken til at jage Blodskalperne.\n\nOg det er godt, for du er ikke færdig med at jage dem.", p="<Class>. Vis mig, at du har gjort jagt på Blodskalp-stammen.\n\nVis mig dine trofæer."},
  [583] = {c="Rigtig hyggeligt at gøre din bekendtskab, <Name>. Har ikke set en <Class> i disse egne i noget tid.\n\nJeg har slået mig ned med denne ekspedition med ét formål: at jage et stort og unddragende udyr. Eftersom du er en slags helt, er jeg villig til at lade dig deltage i jagten, men du skal først bevise dig selv.\n\nJeg skal lære dig raptor-dræbningens kunst. Ajek vil træne dig i tigerjagt. Og Ridder Erlgadin er en mester i panterspor.\n\nBevis dit kunnen, så lader jeg dig være med på den store jagt."},
  [596] = {c="Ah, meget godt. Jeg vil koge dem og suge dem, og deres ejeres ånder vil svækkes, mens jeg gør deres halskæder til pasta!\n\nVær så god, <Name>. Dette vil tilbagebetale min gæld til dig.", p="Blodskalperne vil en dag blive knust af Mørkespyd! Har du halskæderne fra vores dødsdømte fjende?"},
  [600] = {c="Stor! Vidunderligt! Jeg kan få et bundt for disse!!\n\nDet Ventureselskab valgte da sandelig den forkerte jungle at grave i, gjorde de ikke? Vi ville alle have det bedre, hvis de flyttede væk herfra.\n\nTak, <Name>. Du har gjort en god gerning i dag.", p="Har du de krystaller?? Jeg har brug for dem!!\n\nJeg mener... Jeg må vide, at det onde Ventureselskab taber terræn i Kvælerdorn. For, du ved, vi ærlige folk skal jo tjene til dagen og vejen!"},
  [605] = {c="Aha! Disse duer udmærket, <Name>. Ja, ganske udmærket!\n\nHer er din andel, og... det var en fornøjelse at handle med dig.", p="Har du de fragmenter endnu? Jeg giver dig en pæn bid af overskuddet!"},
  [606] = {c="Av! Hvor har du fået de her fra? Nej, sig det ikke. Jeg vil ikke vide det!\n\nHvem sendte dig? Havulven?", p="Hey! Jeg kan ikke lide det blik, du giver mig, mester."},
  [607] = {c="He he, godt klaret! Og da du viste Shaky de indmad, hvor hårdt rystede han så?\n\nHa! Han er så let at aflæse, når jeg spiller kort med ham, kan jeg ikke lade være med at vinde!\n\nTak for din hjælp, <Name>. Nu er det din tur til at blive betalt...", p="Hørhør, <Name>. Fik du Rystefix' betaling?"},
  [609] = {c="Stor! Jeg kan få en god pris for disse, især for det, der er inde i Morys fod! Tak meget, <Name>!\n\nJeg håber, de tre har lært deres lære: Sats ikke noget, du ikke har råd til at tabe.\n\nOg måske er det for sent for dem, men... de bør passe på, hvem de spiller hasard med.", p="<Name>, fandt du de tre hunde? Samlede du deres værdigenstande ind?"},
  [613] = {c="Du fandt den! Tak, tusind gange, <Name>. Du har været en stor hjælp for mig!\n\nVær så god - du har fortjent denne her!", p="Ahoi, <Name>! Har du fundet Morys Nøgle endnu?"},
  [629] = {c="Det er godt. Når jeg vender tilbage til Orgrimgrad, vil jeg placere denne skerv på et helligt sted. Den vil minde os om Grimleks styrke og ære.\n\nTak, <Name>. Dine gerninger markerer et voksende venskab med Mørkspyd-stammen.", p="Jeg venter på Tavleskåret, <Name>."},
  [631] = {c="Du søger i det lille, dværgiske lig. Gravereret ind i hjelmen kan du tydeligt læse: Ebenezer Rustlås."},
  [632] = {c="Åh min, nyheden er alvorlig....", p="Spor af Gamle Rustlås, <Name>?"},
  [633] = {c="Den resterende bro er reddet! Du har gjort en stor tjeneste for Kong Magni og folket i Khaz Mødan.\n\nNu, hvis vi bare kan holde ud længe nok, til forstærkningerne dukker op...", p="Depotet med sprængstoffer skal ødelægges!"},
  [634] = {c="Mine kondolencer går til Langfletten og hans modige soldater. Nyheden om Thandol-spændets tragedie og Dun Mødrs fald hviler tungt på mit hjerte.\n\nMen Strømgård er faldet! Derfor er vi til stede her i Flygtningeodden. Vi står over for at generobre vores egen store by.\n\nÆre og pligt kræver, at vi ikke forlader Højlandet, før Strømgård igen hejser Kongens mægtige banner. Jeg vil give Langfletten besked om, at han må klare sig selv..."},
  [635] = {c="Dette krystal pulserer, som om en levende kraft er fanget indeni det."},
  [642] = {c="Ah! Du aktiverede disse fragmenter. Allerede føler jeg mig mere som mig selv!\n\nMen ak, jeg er stadig langt fra fri...", p="Denne klynge af skår ligner meget Myzraels Skår. Men den samme følelse af tryghed pulserer ikke gennem dem."},
  [659] = {c="Prøv at være så stille som muligt, rejsende.\n\nOrker bryder sig ikke synderligt om at blive spioneret på, og der er mere til denne gård, end øjet ser."},
  [671] = {c="Det vil tage mig noget tid at udrede Syndikatets sande hensigter, men deres åbenlyse forbindelse til mørk, dæmonisk magi bekymrer mig. Jeg siger til, når jeg ved mere.", p="Det engang forbandede blod løber stadig gennem mine årer, <Name>. Hvis nogen... noget kalder dæmoner, må det standses."},
  [672] = {c="Fremragende. Åndene fra de raptorer, der gav disse øjne, vil give styrke til amuletens bærer.", p="Jeg vil lave en amulet, der skal give Gor'mølle noget af raptorernes styrke. Måske vækker det lidt flamme inde i ham..."},
  [676] = {c="Så, du tror, du er stærk nok til at hjælpe Hammerfald? Så være det.\n\nTalg har enten sendt dig til den oger-vold i håb om, at du ville slå dig selv ihjel, eller også tror han, du er stærk nok til at hjælpe os. Uanset hvad, så er du her nu, og jeg har brug for flere soldater i vores kamp mod de konstante angreb.\n\nHvis du har tænkt dig at blive i Hammerfald, så hvil dig lidt, og kom og tal med mig igen, når du er klar. Der er ingen mangel på kamp at komme efter.", p="Jeg har ikke tid til at slibe min økse, endsige forlade forposten for at slå de udyr ihjel, der ville prøve at slå mine egne ihjel.\n\nDu lader ikke til at have en fodsoldats erfaring, endsige en fuldvoksen <Class>. Hvad vil du, <Name>?"},
  [677] = {c="Krigens tegn sidder på dine klæder, og sved drypper fra dit bryn. Godt, meget godt faktisk.", p="Hvis du endnu ikke har fuldført min opgave, så er du måske en kujon i hjertet og en nybegynder i krig."},
  [678] = {c="Du er stærk som kodo-oksen, og din lyst til slag gør dit folk stolt.", p="Du tøver. Hvorfor? Du har vist stor styrke indtil nu, <Name>. Svigt mig ikke nu."},
  [679] = {c="Du gør dit folk stolt, <Name>. Truslen er blevet markant formindsket, og jeg er sikker på, at vi begynder at trives her i Højlandet.", p="Jeg ser, dit mod endelig svinder. Det lader til, at mine instinkter havde ret om dig: din styrke er intet sammenlignet med din bravade.\n\nVend tilbage til mig, når udyrets hoved er blevet afhugget, ellers vend aldrig tilbage."},
  [680] = {c="Du har gjort mig en stor tjeneste, <Name>. Vid, at min mands liv og Hammerfalds sikkerhed er blevet beskyttet endnu en dag takket være dine gerninger. Tag venligst dette som en belønning for dit mod.", p="Nær Arators Tårn--der er det, du finder Eller'Kalar. Hans død vil stoppe angrebene på Hammerfald og beskytte min mands liv.\n\nJeg kan se i dine øjne, at du tror, jeg er svag--endda uærlig--for min tavshed. En dag vil du lære, hvad det vil sige at elske, som jeg gør. Måske vil du så forstå en anden slags styrke og ære.\n\nI mellemtiden skal du gøre, som jeg beder, og slå Eller'Kalar ihjel."},
  [682] = {c="Tak, <Name>. Vi vil informere de faldne soldaters familier om, at de blev dræbt i slag.\n\nDet bliver en dyster nyhed at bære, men det er bedre end usikkerheden ved en savnet elsket.", p="Har du hentet nogle Strømgård-mærker, <Name>? Syndikatet må lære, at de ikke kan tjene penge på vores døde."},
  [684] = {c="Du fældede Marez Hætte? Godt gjort, <Name>. Virkelig godt gjort!\n\nMarez truede vores Strømgård-forsvarere, og der går rygter om, at hun var udsending mellem Syndikatet og en anden, mørkere magt. Vi er glade for at se, at hun ikke længere vil udøve sine kræfter imod os.", p="Hilsner, <Class>. Har du en rapport at aflevere?"},
  [685] = {c="Falkekrone og Otto? Vidunderligt!\n\nHer er din belønning, <Name>. Jeg er glad for at betale den.", p="Hej. Har du en rapport at indsende?"},
  [690] = {c="Så, Malin har sendt dig? Jeg er ligeglad, om Muradin er rejst fra de døde og har kørt dig hertil på en drage. Jeg har travlt! Snak med Kryten, hvis du behøver noget."},
  [691] = {c="Utroligt! Jeg kan se, hvorfor Malin bad dig om at slutte dig til os – virkelig godt gjort!\n\nI dette tempo vender Skruerto og jeg tilbage til Stormvind på ingen tid.\n\nJeg tror, at min dværgiske ledsager er tilbage fra spejdningen af Klippenæve-hallen; gå og tal med ham, når du er klar.\n\nDet så ud, som om han kan have haft en lille håndgemæng med ogerne. Undlad dog at nævne det for ham; han er meget følsom over for kritik af sine spejderfærdigheder.", p="Har du haft held indtil nu, <Name>?\n\n<Kryten skriver nogle noter i sin dagbog, mens han læser.>\n\nHvis min forskning er korrekt, bør hugtænderne komme fra en hvilken som helst Visnebark-trold. Medicinposerne kommer fra Visnebarks hekselæger, og den stærkeste af Visnebarks skyggejægere bør bære den særlige kniv, de får, når de har gennemført deres overgangsriter. Der er ingen måde at vide, hvilke skyggejægere der har kniven, før du har kæmpet med dem."},
  [705] = {c="Disse vil virke fantastisk! Jeg skal bare knuse dem til pulver... og så blande det med lidt af dette og lidt af hint.\n\nPas på, aasgribere! Gør jer klar til et Blitz af Let!", p="Har du fået mine perler? Jeg er næsten løbet tør for Blitzbomber!"},
  [707] = {c="Så Stormspids sendte dig, gjorde han? Godt.\n\nJeg har en stor opgave til dig..."},
  [709] = {c="Åh, held og lykke er med os! Tak skal du have! Vi kan stadig blive frelst!", p="Har du fundet tavlen? Den må indeholde Hemmeligheder! Hemmeligheder, der kan redde os!"},
  [729] = {c="Hulle, er det dig? Jeg har brug for hjælp til at hugge i denne sten. Giv mig min stenbørste, jeg tror, jeg ser noget.\n\nHov, du er ikke Hulle! Har du mon set min stenbørste?\n\nLad det være nu! Jeg lovede Ligaen, at jeg ville sende det mystiske fossil, jeg fandt. Hvor blev Hulle af?\n\nSå meget arbejde, der skal gøres! Nu, hvor er det mystiske fossil... og min børste... og Hulle...\n\nOg hvem er du... det er ligegyldigt, så længe du er her for at hjælpe.\n\nSig til, når du er klar til at begynde at lede."},
  [736] = {c="Jeg er imponeret! Du besidder stor dygtighed, eller stor held, til at have opnået disse relikvier. Uanset hvad, er du en aktiv for os.", p="Hvordan går din mission, <Class>."},
  [738] = {c="Dette skelet må være de ulykkelige rester af Agmund. Hans krop er knækket og medtaget, og hans knogler er gnavet rene."},
  [741] = {c="Åh min! Overlad det til Prospektor Remrejse at finde sådan en skat!", p="Hvad kan jeg gøre for dig, <Race>?"},
  [742] = {c="Velkommen til den nye grænse, <Name>. Askedalen er et land fuld af muligheder, et sted hvor en ung <Class> som dig kan finde grænseløse chancer for at bevise sit mod. Se dig omkring i forposten her, og sørg for at tage ud til Zoram-strandbredden, for Horden har også en forpost der.\n\nDin tilstedeværelse her fortæller mig, at du er kommet for at lære mere om jagten. Lyt godt efter, så deler jeg gerne det, du behøver at vide."},
  [744] = {c="Tak for din hjælp, <Name>.\n\nMin del i min brors ceremoni er næsten fuldendt. At give ham hans hovedpynt og overvære ceremonien er alt, hvad min pligt kræver af mig.", p="Denne hovedbeklædning bliver helt sikkert en vidunderlig gave til min bror."},
  [745] = {c="<Name>, det er godt, at du har taget min opgave alvorligt. Respekt for landet og dets væsener er vigtigt. Død og liv er en cirkel... en nødvendighed. Den ene kan ikke eksistere uden den anden. Tag dig tid til at grubler over dette, og gør godt i aldrig at glemme det.", p="Hvis Blegmanerne havde respekteret landet og dets indbyggere mere, var denne konflikt aldrig opstået."},
  [747] = {c="Tyrefolket i Narache takker dig, <Name>. Du viser stort potentiale.", p="At skaffe kød og fjer til stammen er det første skridt til at bevise dig selv som jæger over for Høvdingen."},
  [752] = {c="Har du rejst hele den vej bare for at hjælpe en gammel kvinde? Ih, ih, er du ikke en rar en?"},
  [759] = {c="Meget godt, <Name>. Jeg kan mærke landets offer i denne gave, og min ånd svulmer af sorg og stolthed.", p="<Name>. Har du de tænder, jeg bad om?"},
  [763] = {c="Ord fra min gode ven, Høvding Falkevind! Ah, jeg kan se på hans udskæringer, at du er af en særegen race.", p="Hvad fører dig til min landsby, <Class>?"},
  [764] = {c="Jeg tror ikke, der kunne være for meget fejlfortolkning eller ignorering af det signal, hm? Ventureselskabet vil vide ikke at tage tyrefolket let på, eller at være så arrogante at tro, at vi ville lade dem stjæle de naturlige ressourcer omkring os uden protest.", p="Ventureselskabet fik nægtet minedriftsrettigheder her i Mulgorr, men det lader til, at de ikke tager nej for et svar. Vi tyrefolk er dog ikke sådan nogle, der sløver ordene, og vi har andre måder at få vores budskab igennem på."},
  [765] = {c="Min vrede er lidt mildnet ved nyheden om, at skurken Gnistfix er død. Jeg vil gennemgå hans personlige effekter og se, om der er yderligere oplysninger om, hvad Ventureselskabet har planlagt for fremtiden. Tak for din indsats, <Name>.", p="Jeg koger af vrede ved tanken om de grusomheder, Ventureselskabet er villig til at begå mod os i profittens navn."},
  [770] = {c="Jeg kan knap tro mine gamle øjne! Du besejrede den store ulv Spøgelsesylen? Jeg ser op til dig med ny respekt, unge <Class>. Du er en jæger af ekstrem dygtighed!\n\nLad mig tilbyde dig noget. Mine jagtdage er forbi, men jeg ville være æret, hvis du brugte et af mine våben på dine jagter.\n\nMåtte det ramme præcist og bringe dig berømmelse.\n\nOg lad os håbe, at Spøgelsesylens ånd endelig har fundet fred."},
  [772] = {c="Frygt ikke, <Name>. Du har bestået Synens Ritual."},
  [776] = {c="Brønd forvoldt! Et fint drab var det.\n\nJeg sender en indsamling-gruppe for at hente kadaveret, så vi kan hente huden og kødet.\n\nDu har gjort en stor gerning for dit folk, <Name>.", p="Har du sporet Arra'kaja op endnu?"},
  [783] = {c="Ah, godt. Endnu en frivillig. Vi får rigtig mange af jer for tiden.\n\nJeg håber, det er nok.\n\nDe menneskelige lande er truet udefra, og så mange af vores styrker er blevet samlet i udlandet. Det giver igen plads til korrupte og lovløse grupper til at trives inden for vores grænser.\n\nDet er en kamp på mange fronter, vi fører, <Name>. Spænd dig op til en lang kampagne."},
  [784] = {c="Ord om dit mod rejser hurtigt, <Class>. Fortællinger om din sejr ved Tiragarde-fæstningen vil blive forkyndt i Orgrimgrad.", p="Du har dine ordrer, <Name>. Durdotars sikkerhed står på spil. Fuldfør opgaven foran dig, ellers hæng hovedet i skam.\n\nVis din ære og besejr menneskene i Tiragarde-fæstningen."},
  [786] = {c="Horden ville helt sikkert sejre, hvis Kolkar-kentaurerne angreb. Men ved at forhindre et sådant angreb har vi sparet vores mægtige krigere for unødvendigt blodspild.\n\nOg lige så sikkert som der er sand i Tanaris-ørknen, ved vi, at der vil blive spildt blod, før disse prøvende tider er forbi.\n\nDu har tjent dit folk godt, <Class>.", p="Kentaurerne har vist sig at være en vedvarende plage for Horden. Deres planer om at belejre vores hjemland kan ikke tolereres."},
  [788] = {c="Hmmm, ikke dårligt, <Name>. Men lad det ikke stige dig til hovedet... du vil kæmpe hårdere end vildsvin i din karriere.\n\nIkke desto mindre har du bevist dig selv godt, og din næste prøve bliver mod en betydeligt farligere modstander, så du får brug for lidt ekstra beskyttelse.", p="Jeg håber ikke, du er vendt tilbage for at prøve at overbevise mig om, at du har fuldført din opgave, <Name>? Nej, selvfølgelig ikke. Jeg ville tænke bedre om dig."},
  [789] = {c="Der er en vigtig lektie, som du må tage med dig fra kampen mod skorpider. Den mindste eller største modstander kan stadig sende dig i døden. I hård kamp kan et hvilket som helst antal ting vise sig at blive din undergang.\n\nJeg har ikke mere at lære dig, <Name>. Du har klaret dig godt, og jeg vil følge din udvikling med interesse.", p="Skorpidens skjold er ikke så tykt, at en besluttet krigers styrke ikke vil blive afskrækket. Slå kraftigt og uden tvivl, så bør skorpiderne vise sig at være let bytte."},
  [790] = {c="Mit slag var ikke nok til at dræbe ham, men når jeg ser på den skade, jeg tilføjede, giver det mig en lille smule stolthed. Den lille smule bliver alt, hvad jeg har at leve af, hvis jeg dør, og i det lys fylder den korte liste over mine livs bedrifter mig med vrede.", p="Ahhh... min far sagde altid, at jeg aldrig ville blive til noget, og her, liggende under et træ mens livet sive væk, er jeg bange for, at det ser ud til, at han havde ret.\n\nMen jeg ønsker i det mindste at dø vidende om, at min sidste fjende i livet ligger død."},
  [792] = {c="Du har gjort det godt, <Name>.\n\nSelvom de Ondskabsfulde Fæller kun var kæledyr for de mørkere kræfter inden for Brændende Klinge, varsler din succes mod dem større gerninger forude.", p="For at bevise dig selv over for Brændende Klinge skal du først besejre dens ondskabsfulde familiarer. Vend tilbage til mig, når du har gjort det."},
  [794] = {c="Du har hentet den! Godt gjort!\n\nDine bestræbelser i Brændende Klinge-hekseriet er afgørende for at udrydde denne sekt i Prøvernes Dal. Men jeg frygter, at de har yderligere planer for vores land.\n\nVi har ikke set det sidste til dem.", p="Er din opgave fuldført, <Name>? Har du Brændende Klinge-medaljonen?"},
  [804] = {c="Ud fra din beskrivelse af udyret, tror jeg du må tale om Sarkot! Det er ingen undren at Hana'zoa blev overmandet af det. Hjælp vil blive sendt af sted til ham med det samme, bekymr dig ikke mere om Hana'zoas kval.\n\nDog må jeg sige, jeg er meget imponeret over at høre at du bragte Sarkot til døde. Det er en bedrift at være stolt af, <Name>. Og at du ville kæmpe for en fremmedes ære, mens andre opgaver optog din tid, øger din egen ære."},
  [805] = {c="Hm... din rapport kommer på et dårligt tidspunkt. Brændende Klinge ses ikke her i Sen'jin-landsbyen, men deres ondskab har slået rod ud for kysten, på Ekkoøerne.\n\nOrkerne er venner med Mørkspyd-trolde. Ærefulde venner. Vi vil gerne hjælpe orkerne, men... vi har også brug for hjælp."},
  [806] = {c="Aha! Du fik ham!\n\nDu gør din klan stolt, <Name>. Og takket være dig er Durdotar fri for endnu en ondskabens agent.", p="Fandt du Fizzle, <Name>? Han og resten af Brændende Klinge skal udryddes fra vores lande!"},
  [808] = {c="Tak, <Name>. Du har reddet Minshina. Du har reddet min brors ånd fra slaveri!", p="Har du min brors kranie, <Name>? Er han endelig fri?"},
  [809] = {c="Neeru vil have Dæmonfrøet ødelagt, gør han? Mærkeligt...\n\nVel. Hvis han ønsker frøet fjernet, så vil jeg fortælle dig, hvordan det fjernes."},
  [815] = {c="Du er måske svag, men i det mindste er du ikke klodset, <Name>.\n\nHer, tag det her, og kom mig af vejen. Jeg har madlavning at tage mig af.", p="Morgenmad, frokost, aftensmad! Hvem bryder sig om, hvilket måltid det er? Det skal stadig tilberedes af nogen – nemlig mig!"},
  [816] = {c="Åh, min søn... min smukke søn.\n\nUsikker på min søns skæbne har jeg pint mig selv, siden han rejste. Nu hvor jeg ved, hvad der er sket, kan jeg måske endelig begynde at sørge.\n\nTak, <Name>. Tag den venligst. Jeg skulle have givet den til Krone som gave, da han vendte hjem vellykket. Nu hvor jeg ved, at han er død, kan jeg ikke bære at se på den.", p="Jeg beder til, at Krone vender tilbage til mig, men jeg er næsten sikker på, at jeg allerede kender hans skæbne."},
  [817] = {c="Jeg er tilfreds, <Name>. Takket være din hjælp bliver vores folk beskyttet, og de skal ikke gå kolde hen, når årstiderne skifter.\n\nTak.", p="Jeg husker min første tigerjagt, <Name>. Jeg valgte at jage på den største af Ekkoøerne, og jeg sad helt stille i skyggerne af dens løvværk i næsten en hel dag... iagttog... ventede.\n\nMine muskler var spændte, og jeg var klar til at slå til. Det var en af mine største sejre, da tigeren endelig bed på agnen."},
  [818] = {c="Godt klaret, unge... virkelig godt klaret.", p="Tiden er den sande prøve på din styrke og vilje. Mister du tålmodigheden eller giver efter for svaghed, vil dit sande jeg blive vist frem."},
  [819] = {c="Nå, dog...\n\nDet her var en af Chen Stormøls tønder. Han rejste sammen med Rexar for længe siden. Jeg har ikke set eller hørt om ham i en kodo-oksens levetid. Jeg sætter pris på, at du bringer det her til mig, <Name>.", p="Ja?"},
  [821] = {c="Haha... Jeg troede aldrig, jeg ville lave mere af den slags igen.\n\nDu har vakt en stor nostalgi i mig, <Name>. Det minder mig lidt om sidste gang, jeg lavede et parti trogg-bryg. Tak. Minderne varmer min mave.", p="Hvordan går eftersøgningen?"},
  [822] = {c="Haha! Jeg vidste, at du ikke kunne modstå noget af dette bryg. Kom gerne tilbage, når du vil have mere, <Name>. Bare bring mig flere af de ingredienser, jeg bad dig samle.", p="Arbejder du hårdt på at finde de ingredienser, <Name>?"},
  [823] = {c="Ja? Har du en rapport at aflevere? Nå, så lad os høre den!"},
  [824] = {c="Denne kugle... den er yderst urovækkende. Mange af de mere mægtige elementarer får deres kraft og energi gennem sådanne apparater. At finde en som denne nær intakt er én ting - at finde den så besmittet er en anden.\n\nJeg vil sørge for, at denne kugle bliver studeret ordentligt af Jordringen. Måske kan vi gøre en ende på denne korruption af elementerne. Værsgo - accepter dette som et rimeligt bytte for at have bragt denne kugle til Jordringens opmærksomhed.", p="Ah, hej der. Jeg bruger rigtig meget tid på at studere vandet - alle elementerne, faktisk - så meget, at jeg nogle gange ikke engang lægger mærke til folk omkring mig.\n\nEr der noget, jeg kan hjælpe dig med?"},
  [825] = {c="Din bjærgningsmission var en succes, <Class>. Jeg vil sørge for, at disse værktøjer kommer til Orgrimgrad med næste karavane.\n\nFint gjort.", p="Når vi lærer, hvordan menneskerne betjener deres mærkelige maskineri, står vi med en større chance for at besejre dem i fremtidige slag.\n\nMed vores nyopnåede viden kan Horden kun vokse i styrke."},
  [826] = {c="Med Zalazan væk kan vores stamme igen sove i fred.\n\nTak, <Name>. Mørkspyd-stammen står i stor gæld til dig. Hvis du lider af en lidelse, så besøg min assistent Bom'bugt, bag mig. Hans voodoo er stærk...", p="Er Zalazan besejret, <Name>?"},
  [827] = {c="God. Skjuler inden for disse halsbånd gemmer sig hemmeligheden bag Brændende Klinge. Og den hemmelighed vil jeg afdække...", p="Har du endnu betrådt Kranieklippen, <Name>? Har du Brændehalsbåndene?"},
  [828] = {c="Velkommen, <Name>. Ord nåede mig om din ankomst og om dine bedrifter i Durdotar.\n\nDu er en <Class> med voksende færdighed og renommé.\n\nBliv på den rene sti, så bliver din fremtid virkelig stor."},
  [829] = {c="Ah, og hvor har du fået det her fra? Sendte gode Margås i Barberbakken dig til mig, gjorde han?\n\nNå, lad mig lige kigge nærmere på det...", p="Mine ydmyge hilsner, <Class>. Hvordan kan jeg hjælpe min <Race>-bror i dag?"},
  [830] = {c="Dette bebuder slet ikke godt. Du var klog nok til at gøre mig opmærksom på denne information.", p="Der er et bekymret udtryk i dit ansigt, <Class>. Hvad har du dér?"},
  [831] = {c="Utallige gange opfordrede jeg Krigshøvdingen til ikke at stole på menneskene, men personlig stolthed er ikke det, der står på spil her.\n\nDu har tjent Horden ærefuldt, unge <Class>.\n\nUndskyld mig nu, jeg må straks rådgive Trael i disse sager....", p="Kan du ikke se, at jeg er optaget? Det her må hellere være presserende...."},
  [832] = {c="<Undersøger Brændende Skyggeøje.>\n\nInteressant. Stemmen du hørte, nævnte den mit navn? Jeg er kendt for at jage fjenderne af vores Krigshøvding, men...det er mærkeligt, at jeg blev udpeget. Endnu mærkeligere, at Brændende Klinge-kultisterne, du fik dette vedhæng fra, har et navn så tæt på mit eget.\n\nJeg må studere dette vedhæng. Jeg må studere og, og må grubler over meningen i dets budskab.\n\nTak, fordi du henledte min opmærksomhed på dette, <Name>. Du har gjort dit folk en stor tjeneste.", p="Du har noget vigtigt at berette. Jeg kan mærke det bag dine øjne."},
  [834] = {c="Hey, er det ikke lige det! Du har fået vores forsyninger tilbage til os. Det er fantastisk. Jeg kan komme tilbage til arbejdet, så snart jeg kan finde nogen til at slæbe de her sække for mig.", p="Jeg er go' til det, jeg laver, misforstå mig ikke, men det her er latterligt! Hvad skal jeg egentlig gøre, bygge sandslotte?"},
  [835] = {c="Jeg tror, jeg kan trække vejret lettet nu, når jeg ved, at harpyerne ikke længere vil genere vores forsyningskaravaner. Og ikke et øjeblik for tidligt, heller ikke. Jeg hører, at der bliver sendt nogle sjove små legetøjer med næste forsendelse!\n\nDu er ret god til det, du laver, <Name>, du burde opspore min chef i Skralde. Jeg vil vædde på, at han kunne finde noget arbejde til dig.\n\nÅh, og bare rolig, jeg ville ikke glemme at betale dig for den tjeneste, du har ydet mig.", p="Det skulle man ikke tro om en fyr som min chef Gazlowe, men han syntes altid at vide, hvordan tingene stod. \"Vær ikke bange for at tage det store skridt,\" sagde han.\n\nHarpyerne holder ikke op med at plage os, og karavanerne holder ikke op med at blive angrebet, medmindre vi gør noget ved det, hva'?"},
  [837] = {c="Jeg vil give besked om, at kvilsvinene er blevet fjernet fra deres lejer, og at deres bygninger må sættes i brand. Fjernelsen af Barbermanken fra Durdotar bringer os tættere på at sikre grænserne til vores nye hjemland fuldt ud.", p="Selvom de nok har lidt intelligens og lidt organisation, forundrer det mig konstant, at kvilleberne var i stand til at erobre og holde så meget land i Kalimdør. Måske er de en mere snedig fjende, end jeg giver dem æren for..."},
  [840] = {c="Åh, så Takrin Vejsøger sendte dig? Han er en fremragende spejder, jeg ved ikke, hvad jeg skulle gøre uden ham.\n\nJeg underskriver dit hvervebrev, men det, vi virkelig har brug for, er nogen ved Korsvejen.", p="Hvad vil du, hvalp? Hvis du ikke er her for at melde dig, har jeg ikke tid til dig."},
  [843] = {c="Kasgorm mødte den skæbne, han fortjente. Jeg føler ingen anger over tossen. Han var en vantro i disse lande.\n\nMåtte hans død tjene som advarsel til alle, der truer med at forstyrre vores livsstil.\n\nNu, lad mig tage et øjeblik til at studere dværgens dagbog....", p="Mange uskyldige tyrefolk mistede livet eller blev tvunget væk fra deres forfædres fødested, da dværgene fra Bål Modan ankom. Mit land må genvindes!"},
  [844] = {c="Meget godt, <Name>. Nu hvor Slettevandrerne er væk, får vi lettere ved at holde vores forsyningskæder intakte. Og jeg håber, du lærte et par tricks derude i Ødemarken, for dit næste bytte har lidt mere ild i blodet end Slettevandrerne...", p="Har du samlet slettegænger-næbbene?"},
  [845] = {c="Ikke dårligt, <Name>. De zebrahester har en masse styrke i benene. Et skarpt spark fra dem kan slå selv en tauren på bagdelen!\n\nDet ser ud til, at du også har lidt styrke i dig. Er du klar til en rigtig udfordring?", p="Hvor mange zebrahest har du slagtet?"},
  [846] = {c="Jeg ser, du er ganske flittig, <Class>.\n\nIngen tvivl om, at vi snart får en passende overraskelse til de dværge.", p="Jeg ser, du er tilbage, <Name>.\n\nSelvom Kasgorms død måske forsinker gravearbejdet i mine forfædres lande en smule, vil det på ingen måde få ødelæggelsen til at ende helt.\n\nFæstningen ved Bål Modan er en stadig voksende militær trussel. Den blev bygget for at forsvare udgravningsstedet, men er nu også klar til et offensivt angreb.\n\nHvis du har de ingredienser, jeg bad om, kan jeg lave en ladning, der får de hastige dværge til at genoverveje deres handlinger her i Ødemarken."},
  [848] = {c="Ah, ja. Dette er gode prøver. Potent.\n\nJeg er De Forladte, og vi holder vores kontrakter. Her er din belønning, <Name>.", p="Har du sporerne, <Name>? Der er en blanding, jeg må sende til min forretningspartner i Tordenklippe, og den kræver sporerne..."},
  [849] = {c="Du har gjort det godt, <Name>! Må du blive æret i Tordenklippe som forsvarer af de hellige tyrefolkslande og en mester for den tabte stamme.", p="Når den dværgiske flyvemaskine er blevet ødelagt, vil jeg mærke den søde tilfredsstillelse af hævn."},
  [850] = {c="Godt klaret, <Name>. Kentaurerne er lave, brutale væsener, men nogle få har snilde og overblik til at lede. Og netop dem er de farligste.\n\nBarak Kodobøf var sådan en kentaur. Det er godt, at han er død.", p="Hej, <Name>. Har du Baraks Hoved til mig?"},
  [851] = {c="Meget godt. Du må virkelig have rørt op i de Kentaurer -- vores vagter så aktivitet nede ved Stillestående Oase, og det var nok dig.\n\nDu bør være stolt af din bedrift, <Name>. Der er meget mod i dig.", p="Har du fundet Verøg, <Name>?"},
  [852] = {c="Jeg roser dig, <Name>. Disse kentaurer er udisciplinerede og kan ikke fokusere deres raseri, som orkerne kan, men de er ikke desto mindre vilde. Ved at besejre dem er dit mod bevist.", p="Er Hezrul besejret, <Name>?"},
  [853] = {c="Ah, sporerne fra Ødemarken, som Helbrim samlede. Fik han din bistand til at levere dem? Godt.\n\nOg emulsionen er stadig potent, så du må have spildt ingen tid på leveringen. Godt gået, <Class>.", p="Har du noget fra Apoteker Helbrim?"},
  [855] = {c="Godt gået. Jeg er sikker på, at du har indjaget frygt i de overlevende kentaurer, <Name>. Hvis de har forstand, vil de nu berolige sig og stoppe deres fremrykning.\n\nMen jeg tror ikke, de vil, og det er uheldigt.\n\nUheldigt...for dem.", p="Hvordan går jagten, <Name>?"},
  [857] = {c="Endelig er kraften min igen! Min, siger jeg!", p="Hvor er Månernes Tåre? Jeg har brug for den nu! Behøver jeg sige det!"},
  [862] = {c="Normalt kan jeg ikke lide at spise disse gnavere, når de er så.... så... modne. Lader dem gerne rådne et par uger for at få smagen virkelig frem. Men du ser så sulten ud.\n\nLad mig lave dig noget Gravrotte-gryderet. Ah, der var den.\n\nVær så god!", p="Har du slået nok gravrotter ihjel endnu, <Name>?"},
  [863] = {c="Forhåbentlig kan vi få noget af værdi ud af det ødelagte Hakkeren-prototype... min tid løber ud! Jeg sender et bjærgningshold til Snurrekrankens placering med det samme.\n\nÅh, lad mig give dig noget for besværet også.", p="Kan jeg hjælpe dig?"},
  [865] = {c="Stor, du fik dem! Nu skal jeg bare male dem ned og blande dem med noget vin, og...", p="Har du fået hornene, <Name>? De her ting skal gøre mig til en formue!"},
  [866] = {c="Ja ja, de her er meget flotte! Jeg vil dyrke eksemplarer af disse rødder og studere dem. Jeg håber at finde nye egenskaber i dem. Skjulte, værdifulde egenskaber...!\n\nOg bare rolig – hvis jeg gør, så er du den første, der får at vide det. For jeg får brug for nogen til at indsamle flere!", p="Hej, <Name>. Fik du de rodfæste-prøver?"},
  [867] = {c="Åh, de er flotte. Rigtig flotte... Godt arbejde, <Name>. Jeg ser frem til at se mere af dit arbejde i fremtiden.", p="Har du skåret nok af dem op endnu? Bliv ved med at skære og tage trofæer. Jeg vil have 8 Hekvinge-klør."},
  [868] = {c="Du behager mig, <Name>. Æggene og værktøjet. Godt gjort.\n\nOg for din belønning...", p="Pas på æggene, du finder, <Name>. Hvis de går i stykker, er de ikke til nogen nytte for mig."},
  [869] = {c="Du fik af med raptorerne!\n\nTak, <Name>. Du er en <Class> af værdi.", p="Har du de hoveder, <Name>?"},
  [870] = {c="Du fandt en revne i jorden, med gasser, der bobler op af den? Mærkeligt. Dette kan være et svar på vores spørgsmål, men vi kan endnu ikke være sikre.\n\nMen det er et spor. Og jeg er taknemmelig for, at du fandt det.", p="Har du været ved De Glemte Pøle, <Name>? Fandt du noget?"},
  [871] = {c="Du har gjort det godt, <Name>. De frække pigvildsvin vil endelig lære, at Hordens magt ikke må ignoreres.", p="Jo længere det tager at stoppe disse angreb, jo sværere bliver det at forsyne folket i Korsvejen."},
  [872] = {c="Godt klaret, <Name>. Med Krønigs død vil angrebene på vores karavaner helt sikkert aftage.\n\nDit folk bør være stolte over at have dig blandt sig.", p="Skær hovedet af deres leder, og kaos bryder ud, <Name>. Lær denne lektie godt. Den vil være til bistand for dig i fremtiden.\n\nVildsvinene vil famle uden retning, og vi kan tage Ødemarken tilbage."},
  [873] = {c="Du er nu én med Isha Vågen, <Name>. Hans ånd er hos dig. Han lurer i dine øjne...\n\nØjne, der en dag vil lære at se.", p="Frygt ikke vandet, <Race>."},
  [874] = {c="Min bror sendte dig, gjorde han? Så må du have bevist dig over for ham. Hvis du har fortjent Jørns respekt, så har du også min respekt.\n\nEr du klar til at træde længere ned ad jægerens sti?"},
  [875] = {c="Fremragende arbejde, min ven. Jeg tror, du kommer langt i Horden.", p="Har du 6 Harpy-løjtnantringe endnu? Retfærd skal tilføjes dem for deres grusomme angreb på Horden."},
  [876] = {c="HA! Godt gået, <Name>! Meget godt gået... Jeg var ikke sikker på, at du var til opgaven, men du har bevist, at du er en ganske hensynsløs halsafskærer. Tak igen, fordi du hjalp os med at dæmpe Harpyje-epidemien. Her er din belønning, brug den godt.", p="Du får ingenting, før jeg ser Serenas hoved."},
  [877] = {c="Dine fund er fantastiske! Frøene, jeg gav dig, var tørre og døde. Hvad end der hviler under disse oaser, kan skabe liv af intet!\n\nVi må studere dette nærmere...", p="Har du været ved Stillestående Oase? Var der en revne under dens vand?"},
  [878] = {c="Ja, ja... fyldt med glæde, fordi Børsterygge endelig <snøfte> kender min stammes smerte, <Race>. Sådan burde jeg føle, men at <snøfte> er ikke tilfældet.\n\nDu hjælper dit folk, og de ærer dig. Kløvtand hjælper sit folk, og hvad gør de? De vender ryggen til ham. De glemmer ham og lader ham rådne i en bur!\n\nJeg hjælper dem selv fra bag låste tremmer, og de sender ingen til at redde mig!", p="Mere information <snøfte> til Horden, når du har dræbt Børsterygges vise, <Race>. <snøfte> Ikke et øjeblik før! Kløvtand er ingen tosse."},
  [879] = {c="Så er det overstået. Bedre at det ender sådan, siger Kløvtand. <snøfter> De burde have <snøfter> sørget for, at jeg var død, da de vendte ryggen til mig, i stedet for at lade <snøfter> mig blive her i denne forladte bur.\n\nDer er kun én opgave tilbage, som du skal fuldføre, <Race>.", p="Hvordan går din jagt, <Race>? <snøfter>\n\nTork tror, han kender sandheden om, hvem der står bag angrebene mod hans folk, <snøfter> men han skal lære, hvor galt han tager fejl, hvis du lykkes.\n\nMin død er uundgåelig, men du har forvoldt store smerter for mine fjender, så Kløvtand fortryder intet. <snøfter>"},
  [880] = {c="Tak, <Name>. At studere bæsterne i et område kan fortælle meget om selve området. Vi skal se, hvilken historie disse granater fortæller.\n\nModtag venligst min taknemmelighed for din bistand ... og måske kan du bruge disse mønter. Jeg finder, at jeg ikke har brug for dem.", p="Hvordan går din samling? Fik du granaterne?"},
  [881] = {c="Du har besejret Ekeyakee, og selvom hans jagtdage er forbi... er hans ånd med dig. Han vil vise dig styrken, der findes i subtilitet, og æren i nåde.\n\nDin vej er stadig lang, <Class>. Lad os håbe, du træder den godt.", p="Den store kat kalder på dig, <Name>."},
  [882] = {c="Denne hugtand er blot et Mærke, men det, den repræsenterer, er dybtgående.\n\nIsjamuhales styrke er i dig, <Name>. Må du bruge den med måde. Det er din byrde.\n\nDet er din ære.", p="<Name>, har du overvundet Isjamuhale?"},
  [883] = {c="Lakotamani kaldes \"Jordryster\" på vores sprog, og hans skridt er som samlet torden. Han er med dig nu, og hans mod blander sig med dit. Sammen er der ingen konflikt, du ikke kan stå ansigt til ansigt med.\n\nGå rank, <Name>. Gå rank, Jordryster.", p="<Name>, da du nærmede dig, så jeg en ny kraft i dit skridt. Fortæl mig -- har din ånd mødt den store Lakotamani?"},
  [884] = {c="Tordenøglen Owatanka kaldes \"Blåbolt\" af tyrefolket, for i ham bor en fart, der står i misforhold til hans størrelse. Man siger, at lynet slog ned i Blåbolt for længe siden, og at den store bestias energi, næret af himlens raseri, ikke kender nogen grænse.\n\nMåtte hans energi strømme gennem dig, <Name>. For du holder nu tempoet med Owatanka.", p="<Name>, der er en ny kraft bag dine øjne! Du har mødt den mægtige Owatanka, ikke sandt?"},
  [885] = {c="Tordenhøgen er et sjældent dyr fra Ødemarken, og dens død kan varsle stor lykke eller stor undergang.\n\nMen Washte Pawne, kaldet \"Åndsbider\" i Tyrahe, kan hverken bringe det ene eller det andet... eller begge dele.\n\nDen nagende smerte, du følte under jagten på Åndsbider, er den, alle føler, der opnår store gevinster til store omkostninger. Svien, du følte, er angerens smerte.\n\nMen jeg kan se, at du har overvundet det. Du har lært, at anger bliver til visdom, og at man gennem smerte vinder styrke.\n\nDu har lært meget, <Name>.", p="Der er en ny beslutsomhed i dig, <Name>. En beslutsomhed født af smerte...\n\nTynger døden af Washte Pawne dig?"},
  [886] = {c="Mine brødre i Tordenklippe var kloge at sende dig, unge <Class>. For mysteriet i Ødemarken er et, som jeg alene ikke kan opklare.\n\nMed din bistand må vi håbe, at vi kan finde svar på vores spørgsmål."},
  [887] = {c="Du klarede dig godt, unge. Lidt mere arbejde af den slags, så er det én ting mindre, jeg skal bekymre mig om. Forhåbentlig bliver de overbevist om, at de bør flytte deres virksomhed et andet sted hen.\n\nI mellemtiden er der den lille sag med at få de varer tilbage, de stjal fra mig!", p="Jeg gider ikke engang tænke på de fortjenester, jeg har mistet på grund af pirat-plyndringerne, og nu slår de lejr på min dørtrin? Det kommer ud af kontrol, Underminen må gøre noget ved det."},
  [888] = {c="Det er en lettelse at få alt dette tilbage, så tak for din hjælp, <Name>. Du ved, jeg kunne bruge en <Race> som dig til at hjælpe med min virksomhed her. Hvis du nogensinde leder efter arbejde, så glem ikke, hvor godt Gazlowe betaler for tjenester!", p="Har du fundet mine ting, <Name>?"},
  [889] = {c="God. Gå med Agamagg'ans ånd som din vejleder, <Race>. Vend tilbage til mig, hvis du ønsker mere af Agamagg'ans magi.", p="Bring Kløvtand 10 blodfragmenter, så velsigner jeg dig med stor hastighed. Du vil løbe sammen med zebraheste, og vinden vil være jaloux på dig.\n\nDet varer ikke længe, men det burde være nok til at hjælpe dig med at rejse rundt i hele Ødemarken."},
  [891] = {c="Desværre, Alliancens retfærdige kanoner er tavsgjort. Du skal belønnes for din bistand, <Name>.\n\nNu til at tage fat på den dystre opgave at bjærge de dødes lig....", p="Min flåde er i fare med Kaptajn Fjernbjerg og hendes forbandede kanonerer, der skyder løs fra Nordvagt-borgen. Jeg vil have hendes soldater til at betale også. Fyld min hånd med medaljer fra deres døde, så ved jeg, at hævnen er givet til mine faldne kaprere."},
  [893] = {c="Fremragende, fremragende eksemplarer, ja.\n\nTornesvinene er længere fremme, end jeg havde forventet.\n\nVær så venlig, <Class>, tag den her og gå mig ud af vejen. Jeg må hellere se nærmere på disse våben. Vi har måske undervurderet vores fjende, og den slags fejl har vi ikke råd til at begå.", p="Jeg tvivler også på, at de patetiske kvilsvin kunne opnå nogen form for færdighed inden for smedning, men jeg gør, som Krigshøvdingen befaler, og jeg vil lære, hvad jeg kan om Barbermanke-stammen.\n\nJeg har haft flere ringere opgaver, og jeg udfører dem gerne, hvis det hjælper ork-folket."},
  [894] = {c="En mængde knapper, håndtag og blinkende lys er noget tilfældigt placeret på kontrolpanelets flade. En lille måler viser, at apparatet for øjeblikket kører inden for optimale niveauer, og angiver at reguleringsventilerne et til tre er åbne. Der er et lille nøglehul placeret i den nederste højre side af kontrolpanelet."},
  [895] = {c="Ahhhh! Den slags forretninger. Du ved, jeg så Det Hensynsløse engang på det åbne hav. Frygtindgydende skib, eller var det båd... de sømænd er så kræsne!\n\nNå, i hvert fald, det var et syn at se hende glide hen over vandet. Jeg er glad for, at hendes berygtede kaptajn ikke længere vil besvære mine skibe.", p="Hvad sker der? Er der noget, jeg kan hjælpe med? Varer der skal sendes, måske et ingeniørjob?"},
  [896] = {c="Se hvor stor den er, <Name>! Vi bliver rige! Lad os se, ud fra de priser jeg har set på ædelsten, der bliver sendt til Underminen, burde jeg kunne regne ud din andel -- halvtreds procent, bare rolig!\n\nNu lad os se... jeg tror, det her burde passe nogenlunde. Det har været en fornøjelse at handle med dig, <Name>.", p="Hvis bare vi vidste, hvilken af minearbejderne der havde fundet smaragden, ville det være en spadseretur i parken..."},
  [898] = {c="Og tænk, vi troede, Ildbøjle var død for længe siden!\n\nDine heltedåd har givet dig en æret plads hos Thalo'dan-kaperne, <Name>.", p="Ja?"},
  [899] = {c="<Class>, du tager min opgave alvorligt, og for det takker jeg dig.\n\nSelvom min hævnlyst består, kan jeg i det mindste smile ved tanken om, at kvilboarene selv har mærket smerte.", p="Tornesvinene skal betale for dette, <Name>. Det sværger jeg."},
  [900] = {c="Lysene, der viser de tre kontrolventiler, dæmpes, når de lukkes. Grønne lys tones langsomt over i gult, og kontakten, der styrer apparatet, kan nu flyttes; med ventilerne lukkede kan det slukkes.", p="Blinkende lys på kontrolpanelet viser, at hovedkontrolventilerne ikke er blevet lukket af."},
  [902] = {c="Dette er... øh... interessant... ja. Jeg får den sendt videre til Tinkerforeningens hovedkvarter i Underminen. Jeg er sikker på, at de efter nogle omhyggelige dissektioner og undersøgelser kan få noget fornuft ud af den.\n\nMen måske kigger jeg lige selv en lille tur på den først...", p="Åh, du er tilbage, <Name>! Har du samofleksen?"},
  [903] = {c="Ah, jeg ser, du har været travl med at ligge på lur i græsset og jage snigende rovdyr. Synes du så, det er tid til at træde an mod en mester iblandt dem?", p="Hvordan går din jagt, <Name>? Har du fundet Luskerne?"},
  [905] = {c="Så du har været ved rederne og lagt fjerene fra dit bytte deri. Det kræver en pæn portion mod, det er der ingen tvivl om.\n\nFører du dig lidt hårdere nu, <Name>? For du ser hårdere ud, end da du først kom hertil. Ødemarken må vist gøre sit arbejde.", p="Har du været til rederne, <Name>?"},
  [906] = {c="Du fandt Barbermanke-lederen og dræbte ham selv, <Name>? Fantastisk.\n\nJeg er uden ord, men det betyder ikke, at jeg er uden tak. Folkene i Korsvejen ville gøre klogt i at respektere din styrke.\n\nJeg må indrømme, at jeg troede, lederen af disse overfald på vores forsyningslinjer var en anden Tornesvin. Tak igen, <Name>.", p="Ja, hvad er det?"},
  [907] = {c="Det er godt at se dig vende tilbage med bevis for sejr. Og det er godt at vide, at du har gjort det med dine knogler hele.", p="Er tordenøglerne besejret, <Name>?"},
  [913] = {c="Du bør, ligesom tordenhøgen, være stolt. Du har overvundet hver eneste fjende, vi har sendt dig imod, og har gjort det med styrke, mod og ære.\n\nMen din vej, <Name>, fortsætter. Faktisk vil du opdage, at sande jægere altid stræber, altid vandrer deres vej med den samme stolthed, som du har vist mig.\n\nNu er det tid til at komme videre.", p="Er det gjort? Har du slået Tordenhøgen ihjel?"},
  [914] = {c="Du har gjort det, <Name>. Du dræbte lederne af Fangets Druider. Mine drømme er nu fri for deres onde ansigter, og du har hjulpet med at redde Ødemarken fra en forbandet fremtid.\n\nJeg takker dig, <Name>. Jeg takker dig på mine egne vegne, på druiderne i Tordenklippes vegne og på landets vegne.", p="Minderne om mine mareridt hjemsøger mig, <Name>. Har du besejret lederne af Hugtænderne og skaffet deres ædelstene?"},
  [923] = {c="Brønd forvoldt! Disse tumorer er symptomet på tømmerfolkenes smitte. De er fyldt med et gift, som vi må rense fra vores nye land.\n\nJeg vil bortskaffe disse tumorer. Tak, <Name>.", p="Har du været ved Brøndsøen, <Name>? Har du jaget trælingerne dernede?"},
  [924] = {c="Din opgave er fuldført. Du har ødelagt Dæmonfrøet, som Neeru bad om. Men dette er ikke enden...\n\nDestruktionen af Dæmonfrøet sendte bølger af kraft gennem æteren, bølger af forbløffende styrke. Jeg mærkede dem, og jeg er sikker på, at andre væsener også gjorde det. Andre, der vil undre sig over, hvorfor deres legetøj blev knust...\n\nMen uanset fremtidige problemer har jeg noget til dig. Neeru sendte det som betaling. Og han bad mig takke dig.\n\nSå, tak.", p="Dæmonfrøet eksisterer stadig. Jeg kan mærke dets kraft..."},
  [931] = {c="Hvor har du fået den fra? Jeg har ikke set en plante som denne siden et ophold, jeg havde i Sorgens Sump... for årtier siden! Det er utroligt, at et eksemplar har fundet vej til Teldrasil. Og den er vokset til sådan en størrelse!\n\nTak, <Name>. Tilgiv min korthed, men der er en test, jeg gerne vil udføre på dette blad...", p="Har du noget til mig?"},
  [935] = {c="Ah ja, det vand jeg havde bedt om. Tenarøn og Korithras har bestemt taget deres tid med at få det leveret... måske ikke valgt de mest pålidelige budbringere... hmm.\n\nIkke desto mindre kan jeg endelig vende tilbage til mit arbejde. Teldrasils problemer hviler tungt på mine skuldre. Et åg, som jeg gerne snart vil være fri for.\n\nTag den her, du kan måske finde nytte i den.", p="Jeg ved godt, at jeg ikke tilkaldte dig, så jeg kan ikke lade være med at undre mig over, hvorfor du er kommet for at tale med mig.\n\nUanset hvad det er, så vær sød at gøre det kort."},
  [940] = {c="Jeg har undret mig over, hvorfor Orakeltræet har været så tavst over for mig i så lang tid... Det ser ud til, at nogle problemer bliver mindre, mens andre vokser til større bekymringer.\n\nJeg frygter, at mit arbejde på Teldrasil aldrig bliver fuldført, og vores udødelighed aldrig genoprettet.\n\nIkke desto mindre har du udført Orakeltræets opgave godt, og du bør belønnes for din flid.", p="Hmm... Du kommer med skovens ånd stærkt inden i dig, <Class>. Hvad har du at gøre hos den kaldoriske Ærkedruide?"},
  [942] = {c="Åh min! Siger du, at den her kommer fra de fjerne lande i Kalimdør?\n\nFantastisk! Simpelthen fantastisk!", p="Hvad har du dér, ven?"},
  [943] = {c="Aldeles fortrinligt, <Name>!\n\nNu må vi se, om jeg kan bruge stenen til at tyde fossilernes kræfter.", p="Med Relu-stenen vil jeg kunne frigive de skjulte hemmeligheder i min fossil, såvel som Remrejses fossil fra Mørkekysten, <Name>."},
  [945] = {c="Min søster var hvor?! Therymåne har ingen problemer med at gøre sig beskidt, men alligevel! Det er en lang vandring, og Mesterens Glaive er et usundt sted...\n\nNå, tak, <Name>. Det var meget venligt af dig at lade mig vide, at hun har det godt."},
  [947] = {c="Mange tak, <Name>. Disse svampe er fine eksemplarer!\n\nOg da du var ved Klippefjeder-faldene, fandt du så noget, der bekræftede Oldtidens Folks advarsler?\n\nOldtidens Folk er kloge, men jeg havde håbet, at de denne gang tog fejl.", p="Har du mine svampe, <Name>? Har du været i hulen?"},
  [948] = {c="<Name>. Du er her.\n\nGodt.\n\nVi har sager... at drøfte. Dig og mig."},
  [951] = {c="Tak. Disse relikvier stammer fra en tid, hvor Matystra strålede. Den engang store bastion for alferne er forblevet, men fragmenter af dens magi består. Lad os håbe, at vi kan låse stedets hemmeligheder op, før vores fjender gør det...\n\nVær årvågen, <Name>.", p="<Name>. Har dit roderi i Ruinerne af Matystra været frugtbart?"},
  [952] = {c="Ah. Tak, <Name>. Det er dog mærkeligt. Ærkedruiden synes altid at have så travlt. Skoven ved, at alt vil ske til den fastsatte tid. Shan'do Stormrasen forstod det.", p="Ah. <Class>. Hvordan kan Unu assistere dig?"},
  [954] = {c="Ahh... Hvad kunne jeg dog skylde den yderst særlige ære, at en <Race> som dig er mit selskab. Det siger sandelig meget om mit nuværende selskab--uden at krænke mine værter, de ædle grellerne og satyrerne--at din tilstedeværelse kan betragtes som en forbedring.\n\nMen vær så venlig, lad ikke min uhøflige tunge drive dig væk fra stedet. Det er faktisk mange år, ja årtier, siden jeg havde civiliseret selskab."},
  [955] = {c="Faktisk... Grullerne fra Bashalhand besidder ikke det, jeg søger... men de har dog været i kontakt med det for nylig. For nylig... jeg vil regne med, at det er efter din tid, ikke min. For mig strækker 'for nylig' sig ind i fortidens slør, næsten en anden tidsalder...", p="Når jeg har ørehængerne, vil jeg udsende besværgelsen for at finde ud af, hvor seglet, der binder mig, befinder sig. I århundreder har jeg tænkt på den frihed, det vil bringe mig at ødelægge seglet... Måske har de århundreder taget sådan en vejafgift af mit sind, at jeg aldrig vil komme mig igen..."},
  [956] = {c="Det... det er svært for mig selv at tro, at det, jeg nu holder, er det, der har holdt mig fanget så længe. Lad os ikke spilde tiden, <Name>. Når seglet er ødelagt, kan jeg måske vandre frit i jordens skove igen.", p="Dette helligdoms søjler er for mig som fængslets tremmer, <Name>. Ingen styrke, jeg stadig besidder, kan bryde dem, og ingen magi, jeg råder over, kan ødelægge dem...\n\nI tusind år og mere har jeg stirret på dem og undret mig over, om jeg til sidst, når selv stenen var overlevet, ville være fri? Eller ville det være usynlige tremmer, der holdt mig fast dengang..."},
  [958] = {c="Selvom det sikkert kun er indbildning, føler jeg næsten, at jeg kan mærke fordærvet af skumle højfødt-magi på dem. Jeg vil have dem ødelagt, så deres længe sovende ondskab aldrig bliver løsladt igen.", p="Hvis bare redskaberne til deres undergang var blevet ødelagt i kataklysmen, der ødelagde vores verden... Ikke desto mindre må vi gøre, hvad vi kan, for at sikre, at fortidens rædsler ikke gentages i fremtiden."},
  [959] = {c="Storartet! Og lige som jeg var ved at miste mit job også! Jeg sørger for, at Gazlowe får denne gave med det samme.\n\nTak, <Name>. Pænt gjort, siger jeg!", p="Havnefogeden har været efter mig, lige siden Gal Magglish stak af med den 99 år gamle portvin. Jeg gætter på, at flasken var tiltænkt som en gave til Gazlowe fra ingen ringere end Baron Tyranbrand selv.\n\nHvis du er modig og tålmodig nok til at opspore Gal Magglish og få portvinen tilbage, skal jeg sørge for, at du får en fin belønning."},
  [962] = {c="Ah, prægtige eksemplarer. Du har gjort det godt, <Name>.", p="Jeg er ivrig efter at se, om du kan samle nok Slangeblomst fra Klagehulerne. Jeg har sendt mange for at udføre mit ærinde, men ingen er vendt tilbage."},
  [963] = {c="Tak, <Name>. Måske havde det været bedre... hvis jeg selv havde gjort det. Men selv efter disse tusinder af år kunne jeg ikke bære at løfte hånden mod min elskede.\n\nVær venlig, jeg vil gerne være alene med min sorg...", p="Med en stor sorg i mit hjerte fulgte jeg Shan'do Stormrasen ind i dvale, og jeg tog min sorg med ind i mine drømme og sov tusindvis af år væk."},
  [965] = {c="Elissa sendte dig? Så er det gode nyheder, du bringer. Jeg har urolige nyheder at rapportere til hende, og jeg havde ingen måde at levere dem på."},
  [967] = {c="Hvis du ikke har noget imod, at jeg siger det, ser du ud til at være lidt for veludrustet til en budbringer, hm? Jeg regner med, at Balthule ville være sikker på, at hans brev nåede mine hænder. Lad os se, hvad han har at sige...\n\nDet er foruroligende nyheder. Når udøde eller dæmoniske styrker findes, hjælper jeg Vagterne med at ødelægge dem.\n\nI starten var jeg ikke vant til nattealfernes manerer, men jeg er vokset til at respektere dem meget som allierede.", p="Har du nogen forretning med mig, <Class>?"},
  [968] = {c="Ah, et eksemplar af De Nedre Kræfter. En interessant tekst, det her. Og nogle vil nok finde den nyttig...\n\nMen denne her er i trist forfatning. Og se lige her! Der er noter i margen på næsten hver eneste side!\n\nHm...Jeg kender dette eksemplar. Jeg solgte det til Bolger sidste år. Er du...en ven af ham? Ja, det troede jeg nok. Du har den samme ild bag øjnene!\n\nNå, pr. definition er en ven af Bolgers en ven af mig. Og vi tager os af vores egne, ikke?", p="Hej, herre.\n\nMå jeg interessere dig for en af mine tykke bøger?"},
  [970] = {c="Hmm, noget mørk magi har fortryllet denne sjælesten. Lad os se, hvad der er fanget indeni, skal vi?", p="Har du skaffet den sjælædelsten?"},
  [971] = {c="Du fandt manuskriptet! For en glædelig dag dette er! Der vil blive lavet kopier og uddelt, og Lorgalis' oldtidsviden vil endelig være kendt af mine brødre og søstre!\n\nDin tjeneste for os er mere, end du aner, <Name>. Men jeg håber, at denne gave viser dig den taknemmelighed, vi viser vores allierede.", p="Rejsen til Askedalen er lang, og din opgave er ikke let. Men hvis du skaffer mig manuskriptet, <Name>... så bliver din belønning stor."},
  [973] = {c="Det var en stor ting, du gjorde i dag, <Name>. Du bør være ganske stolt af dig selv, for du stod over for en hekser af så stor magt.\n\nNu, lad os se, hvad vi kan lære af Ilkruds skrifter.", p="Du ser lidt rystet ud, <Name>. Har du det godt?"},
  [976] = {c="Du har gjort det godt i dag, <Class>. De ting, vi sendte som bistand til Auberdin, vil være til øjeblikkelig nytte i kampen mod de mørke trusler, der hærger skoven.\n\nTag dem med min hjertelige tak.", p="Vagterne har et stort behov for forsyninger for at forstærke sig selv i Mørkekysten."},
  [982] = {c="Du har gjort os her i Auberdin en stor tjeneste, knægt. Vi sørger for, at deres effekter bliver behørigt taget hånd om.\n\nNu til dig, værsgo, tag det her. Det er det mindste, jeg kan gøre for en, der har modet til at rette op på tingene.", p="Kaptajnerne på de skibe var gode nattealfer, og de fortjener en bedre skæbne, end de fik. Måske er det bedste at passe på deres personlige effekter for at lægge deres ånder til hvile."},
  [983] = {c="Idet du placerer Kryberbenene inde i maskinen, hører du tandhjul begynde at gnide. Efter dømmelse af de bankende lyde fra Summekassen tror du, at Kryberbenene bliver sat på deres rette plads. Snart begynder maskinen at summe, og du hører en lille stemme råbe indefra.\n\n\"Hej? Øhm... Hej! Du fik den til at virke! Det er i øvrigt Vidunderbang! Tak skal du have... Hey, du har ikke lyst til at reparere en til, vel?\"", p="Summekasse 827 sidder i en uhyggelig tavshed. Et enkelt blinkende lys viser, at den har brug for, at der placeres 6 Kryberben i dens holdeboks."},
  [984] = {c="Det er virkelig forfærdelige nyheder, <Name>.\n\nNu hvor pelsbjørnene er så tæt på Auberdin, må vi forberede os på det uundgåelige.\n\nTak, <Name>.", p="Hvordan går søgen, <Name>?"},
  [985] = {c="Vask blodet af dine klæder, <Name>, og sørg ikke over det, du måtte gøre. I stedet, giv tak. Du har mindsket truslen mod vores folk her i Auberdin, selvom Mørkekysten stadig er i fare på grund af effekterne fra dæmonisk mos.", p="Hold ikke din hånd fra det, der skal gøres, barn. Jeg ved, hvor frastødende tanken om at dræbe skovens væsener må være, men i dette tilfælde er det nødvendigt. Der er ikke fundet nogen kurere mod korruptionen, der er sluppet løs over skoven, og vi må gøre, hvad vi kan for at standse dens fremskridt, indtil en findes."},
  [986] = {c="Disse duer udmærket, <Name>. Jeg går straks i gang med kappen.\n\nGiv mig et øjeblik, og vend så tilbage til mig.\n\nÅh, en ting mere: Når du har brugt fortryllelsen på kappen, bliver du begrænset i din omgang med andre. Hvis du kan undgå det, må du kun tale med andre. Meget mere end det kan fjerne illusionen.", p="Jeg kan med god samvittighed ikke tillade dig at søge Volkor, før jeg har fremstillet den kappe til dig."},
  [990] = {c="Ah, en <Class> fra Mørkekysten. Sælarin har gjort det godt med at sende dig herhen så hurtigt, <Name>. Jeg ville ønske, din rejse herhen ikke var under så prekært et pres. Måske kan vi med din hjælp forbedre tingene.\n\nJeg ville begynde dit besøg med at tale med de andre borgere i Stjernelund. Nogle af dem kunne helt sikkert bruge din bistand."},
  [991] = {c="Terøns krop ligger knust oven på øen. Af en ukendt grund har mudderfiskene ladet den være i fred.\n\nDe dybe snit hen over hans lig stammer åbenbart fra mudderfiskenes våben og kløer."},
  [993] = {c="Vidunderligt! Terentis fandt nogen til at hjælpe mig.\n\nOg se, en månesnigerkappe...<hoste> Åh... det gør ondt. Tak, <Name>.\n\nPelsbjørnene såret mig, før jeg nåede at undslippe dem. Giv mig et øjeblik, så er jeg sikkert klar til at snakke lidt mere."},
  [1001] = {c="Summekassen summer til live kort efter, at du har lagt Tærsker-øjnene indeni. Der er et øjeblik med statisk støj, før du hører en velkendt lille stemme kalde.\n\n\"Krybervin er det bedste...\" *hik*\n\n\"Hvad? Åh, du har allerede fikset den? Wow, du er en hurtigh en. Sååå, vil ya ha' lyst til at fikse en til?\"\n\nDu tror, du hører væske blive hældt i et krus, efterfulgt af høje slurrende synkelyde.", p="Maskinens luge er åben, og den ser ud til at vente forventningsfuldt på, at der lægges 3 Tærsker-øjne indeni."},
  [1002] = {c="Summekassen springer pludselig i gang, og du kan høre de tydelige lyde af tænder, der bliver malet til støv inde fra.\n\n\"Sååå, ya klarede det! Dethh er fantashtiske nyhedsh... Sååå... Hvorfor går ya ikke bare videre? Åh! Medmindre du vil have et nyt job!\"", p="Selvom du endnu ikke har sat de 6 Månesniger-hugtænder i, tror du at høre statisk støj og usammenhængende gnom-vrøvl komme indefra. Kan nogen andre have repareret maskinen allerede?"},
  [1008] = {c="Meget godt gjort, <Name>. Dine handlinger i Zoram-strandbredden mod slangefolket er prisværdige.\n\nJeg ved, at din bedrift ikke var let at udføre, for slangefolkets styrke og snedighed er velkendt blandt nattealferne. Det ved vi, for vi deler en historik med dem.\n\nDet er en historik, jeg ikke har lyst til at gentage.", p="Vi kan ikke tillade slangefolket at invadere vores kyster, <Name>. Det er vigtigt, at du går til Zoram-strandbredden og fuldfører din mission."},
  [1009] = {c="Du fandt ringen! Tak, <Name>. Tag venligst dette som betaling, og vid, at dine gerninger i dag vil forblive i min erindring for evigt.", p="Det siges, at Zorams Ring er nøglen til enhver lås i byen. Har du den, <Name>?"},
  [1010] = {c="Ah, du har håret! Nu vil jeg blande en kurere til barnet, og bede om at min brygge virker.\n\nOg... De Forladte er ved Bathrans Hjemsøgte? Meget foruroligende at høre, det er. Meget foruroligende, ja...", p="Har du samlet Bathrans Hår, <Name>? Barnets helbred bliver svagere for hver time..."},
  [1011] = {c="Meget godt, <Name>. Nu... ved at teste indholdet af denne flaske, vil De Forladtes mål blive afsløret!", p="Har du fundet lejren, <Name>? Har du en flaske smitte?"},
  [1012] = {c="Jeg mærkede angsten i Dor'dagnil-gravhøjene lette, og vidste, at du havde fuldført din opgave.\n\nDet var et dystert stykke arbejde, du udførte, <Name>, for de ånder, du ødelagde, var blot ofre for De Forladtes ondskab. Men med deres ødelæggelse, lad os håbe, at de andre rasende ånder finder fred.", p="Dor'dagnil-druidernes pine hjemsøger stadig mine drømme, <Name>. Du må tilintetgøre deres ledere!"},
  [1013] = {c="Meget godt. Denne bog vil passe fint ind i min samling af Urs værker. Hans viden var stor, men hans samvittighed holdt ham fra ægte magt. Og da Svøben kom, og hans styrke blev sat på prøve, slog den fejl.\n\nVi fra De Forladte har ikke råd til sådan en svaghed, hvis vi skal overleve...\n\n...hvis vi skal erobre.", p="Har du fundet bogen, <Name>?"},
  [1014] = {c="Sølvfyrreskoven er endelig fri for den ussel Arugels last. Du har gjort Den Mørke Dame en stor tjeneste, <Name>. Din udholdenhed skal belønnes.", p="Med Arugels død står vi til at øge Den Mørke Damens højborg i Herrelande."},
  [1016] = {c="Brønd forvoldt, <Name>, dette bør give os de oplysninger, vi behøver for at få synderen opdaget. Hvad synes du om at tage magikeren, der fylder vores bassiner med korrupte elementarer? Korruptionen af Askedalen og videre gør mig kvalm af sig selv--at have en Magiker, der aktivt forsøger at ødelægge den yderligere, gør mig syg uden ende. Han skal nok betale for det.", p="Eftersom du må ødelægge armbeskytterne for at dræbe elementarerne, bliver det nok svært at finde de præcise, der indeholder de oplysninger, spårullen har brug for. Du kan bytte armbeskyttere med andre for at få dem, du skal bruge, eller har du måske allerede det spåede papir?"},
  [1017] = {c="Nu kan jeg se det modbydelige smil viske af hans ansigt for evigt. Du har gjort det meget godt, <Name>. Tag dette, Elunes Lys, drik af det, når alt synes tabt, og døden er nær. Det kan redde dig, hvis Gudinden vil.", p="Er det gjort? Er Sarilus Ondbryg død?"},
  [1020] = {c="Er det fra Orendil?\n\nHans færdighed med urter og heling er stor. Denne kur giver mig håb, når jeg før havde så lidt...", p="Jeg må undskylde, for jeg har ingen tid til at tale. Mit barn, Relaria, er dødeligt syg!"},
  [1023] = {c="Det er forfærdeligt, <Name>. Terøn er død?!\n\nTiden til sorg kommer, men lige nu må vi samle vores kræfter. Jeg sender nogle af Vagterne for at hente Terøns lig så hurtigt som muligt.\n\nDu har Terøns dagbog og ædelstenen, han var på jagt efter. Tror du, du er i stand til at fuldføre hans opgave? Jeg ville sove meget bedre, vidende at hans død ikke var forgæves.", p="Ah, velkommen tilbage, <Name>."},
  [1024] = {c="Åh, Rane sendte dig? Så må det virkelig være seriøst. Hvad kan jeg hjælpe dig med?", p="Hej. Hvordan har du det?"},
  [1025] = {c="Du har gjort det godt, <Name>. Tak.", p="Pelsbolgene var ikke altid vores fjender, <Name>. Men tiderne ændrer sig, og det er ikke længere en fredstid her i disse mørke skove."},
  [1026] = {c="Jeg er glad for at se dig tilbage, <Name>.", p="Det gør mig så ked af, at trækkene er blevet korrupte. Jeg ville ønske, jeg kunne gøre mere for at hjælpe dem."},
  [1027] = {c="Du fandt den sidste brik? Herligt for dig... og for Rane.\n\nJeg regner med, at vi må se på at reparere den, ikke sandt?", p="Har du fundet det sidste stykke af staven, <Name>?"},
  [1028] = {c="Når gløden dør hen, kan du se den genfortryllede stav inden for helligdommens bassin.", p="Du kan fornemme en subtil, men mægtig kraft i helligdommen og de omkringliggende træer.\n\nDu begynder at placere staven i helligdommen, og en blød summende lyd udsendes fra omgivelserne, mens helligdommen begynder at gløde..."},
  [1029] = {c="Du har genskabt staven, Terøn havde sat sig for at finde? Det var da dejligt at høre.\n\nTerøn ville være stolt over at se, at hans opgave fortsætter, selv efter hans tragiske bortgang."},
  [1030] = {c="Ja, ja... du er af min slags, men stadig hel. Stadig ren.\n\nJeg er i tvivl om, hvordan du er sluppet fra de grusomheder, nattealferne har udsat vores folk for, men jeg er glad for at vide, at jeg ikke længere er alene.\n\nFordærvelse løber nu gennem vores slægtninges årer, unge, en korruption bragt over os af de stolte nattealfer. Det er dem, der gjorde dette mod vores folk... Det er dem, jeg giver skylden for at være blevet smidt ud af min stamme.\n\nOm natten kan jeg stadig se lejrbålene brænde i mørket."},
  [1032] = {c="Tak, venlige <Race>. Min søsters ånd glædes over din indsats.", p="Hjælp mig venligst med at hævne Anelias død."},
  [1033] = {c="Åh, du fandt den! Jeg lægger tåren i en gryde og beder til, at den kan kurere hende.\n\nTak! Tak, <Name>!", p="<Name>, fandt du Iris-søen? Har du Rive?"},
  [1034] = {c="Du samlede støvet! Jeg laver en kompres af disse -- den burde få Relarias feber ned.\n\nTak igen, <Name>. Uden din hjælp ville mit barn helt sikkert gå til grunde.", p="Har du Stjernestøvet endnu, <Name>?"},
  [1035] = {c="Åh, <Name>, du har reddet min datter! Jeg ved, at månestenens kraft vil give min datter hendes styrke tilbage!\n\nJeg kan aldrig betale dig fuldt ud tilbage for den hjælp, du har givet mig, men... værsgo, tag dette. Bortset fra Relaria er det min kæreste ejendel.", p="Mødte du Skyggekrat-orakellet, <Name>? Hvis ja, så giv mig venligst den faldne Månesten. Relaria har styrke nok til kun nogle få åndedrag mere!"},
  [1038] = {c="Det ser ud til, at Vellindes forsvinden er mere foruroligende, end den først virkede. Alligevel kan jeg ikke tro, at hun er endt ilde. Måske ville det være gavnligt for os at tage kontakt til hende.\n\n<Name>, da du har vist en personlig interesse i denne sag, vil jeg gerne have din hjælp.", p="Hvad har du fundet ud af?"},
  [1045] = {c="Du har gjort det godt, min ven.\n\nSkoven er stadig besmittet, men i det mindste ved vi, at vi har gjort en lille del for at vende den tilbage til sin tidligere herlighed. Hvis du ønsker at vende tilbage til mig igen, ville jeg nyde selskabet fra mit eget folk.\n\nPas godt på dig selv. Måske møder vores stammer hinanden igen i mindre voldsomme tider.", p="Har du slået Ræn ihjel endnu, min ven?\n\nSelv Nattealferne fortjener ikke rigtigt hans vrede. Hans had brænder endnu stærkere end mit eget, men hans sind er ikke længere hans eget. Han er en trussel mod alle skovens naturlige væsener."},
  [1049] = {c="De Faldnes Kompendium! Jeg var ved at tvivle på, at selve bogen overhovedet fandtes!\n\nDu har tjent tyrefolket i Tordenklippe godt, <Name>. Din hengivenhed skal ikke glemmes.", p="Kærne er en modig og ædel leder, og jeg ville stole på ham med mit eget liv. Men det er andre, jeg ikke stoler på i dette politiske klima.\n\nNår jeg engang får en chance for at samle al den tilgængelige viden, kan jeg give Høvdingen et velovervejet råd.\n\nHar du haft mulighed for at rejse til Tirisfals Lysninger? Til Det Skarlagenrøde Kloster? De Faldnes Kompendium er blot én brik i dette indviklede puslespil..."},
  [1050] = {c="Du har reddet den hellige tekst!\n\nDin rejse var lang, og at skaffe bogen var uden tvivl ingen let opgave. Men dværgene i Jernsmede står til at få gavn af din succes.\n\nTak, <Name>, på vegne af Opdagelsesrejsende-Ligaen.", p="Klosteret var et seminarium for paladiner under uddannelse. Engang en højborg for Let, faldt det i hænderne på de gale fanatikere fra det Skarlagenrøde Korstog.\n\nKorstoget mente, at deres mål var et ædelt et: at rense landet for den udøde pest. Men galskab har plettet deres færd, og nu står de som fjender over for alle.\n\nBring Titanernes Mytologi til mig, så jeg kan studere den og huse den her i Jernsmede.\n\nKlosterets korrupte haller er ikke noget sted for en sådan historisk skat."},
  [1051] = {c="Vorrel førte en så urolig tilværelse. Og hvilken god kammerat han var...\n\nPokkers de snavsede mennesker!\n\nVorrel er væk og får aldrig nydt udødheden igen. Jeg kan i det mindste trøste mig med den hævn, du tog i hans navn. For den takker jeg dig.\n\nLad mig nu sørge i fred....", p="Hvad vil du, fremmede?"},
  [1054] = {c="Brønd forvoldt, <Name>.\n\nVi er under konstant trussel fra pelsbolgene. Forhåbentlig holder dette dem på afstand et stykke tid endnu.", p="Pelsbjørnenes korruption har fået Askedalen til at blive en brøkdel af sin tidligere herlighed."},
  [1055] = {c="Du har gjort det, <Name>! Godt gået!"},
  [1056] = {c="Endelig, du ankommer. Jeg ser at Faldræs har lyttet til skovånderne...."},
  [1057] = {c="Nu hvor Blodraserne har lidt et så stort tab, kan det sande arbejde med at genoprette landet måske begynde....", p="Der er meget arbejde, der skal gøres, før Den Brændte Dal kan genoprettes til den frodige skov, den engang var.\n\nRyd området for de ulækre pestilenser, <Name>! Først da kan vi begynde at generobre det, der tilhører naturen."},
  [1058] = {c="Åh, hvor bliver disse små skovnymfer glade! Vi får dem til at føle sig helt hjemme med denne særlige mixtur!", p="Se på vores stakkels lille alfevenner. Alle sammen buret inde uden skov at boltre sig i!\n\nNu, har du så kunnet finde noget harpiks til mig? Hvad med skæggene fra Skumringsløberne? Har du ikke tilfældigvis den fe-drageskæl på dig?\n\nOg øjne! Jeg skal bruge så mange øjne! Man kan jo ikke lave en vild skovmagisk brygning uden en god omgang øjne!"},
  [1059] = {c="Vogter Albagorm var klog i at sende dig af sted med sådan en hast.\n\nLad os se, om vi ikke kan tilkalde hjælp fra den store skov til at rejse til Den Brændte Dal, før det er for sent."},
  [1060] = {c="Ahh, et brev fra Darsok. Jeg har ikke hørt fra ham i mange år.\n\nSå de sidste af Blodfjerene er døde, hva'? Det er gode nyheder. Jeg husker, da min ven Rokhen drog af sted med den skøre mok'nathal for at dræbe hendes ældre søster. Ah, at være ung igen, ligesom dig.", p="Du virker som en skummel type. Har du noget, jeg skal se?"},
  [1061] = {c="Ah, en <Class>. Meget godt. Vi får brug for dine færdigheder til at tage hånd om disse plyndrere!"},
  [1062] = {c="Modigt gjort, <Name>.\n\nVi har måske i sidste ende brug for tyrefolkets ældstes visdom for at berolige Stenklippes ånder, men...\n\nAt rydde Ventureselskabet for dets personale er et godt første skridt mod dem.", p="Storskov-dalen ligger mod nordvest, <Name>. Af sted med dig. Indjag frygt i dem, der vil plyndre dette land!"},
  [1063] = {c="Jeg byder dig hilsen. Er du kommet hertil for at søge råd?"},
  [1064] = {c="Magata sendte bud om din ankomst, <Name>. Selvom mit hjerte ikke længere slår, føler jeg stadig sorg over Stenklippes ånder.\n\nDe Forladte er ivrige efter at tilbyde den hjælp, vi kan."},
  [1065] = {c="Et notat fra Zamaa? Hendes behov må være store, siden hun sender bud så langt. Lad os se, hvad hun skriver...\n\nAh, herligt! Jeg ved præcis, hvad jeg skal gøre!", p="Ah, er du her med mine nye forsøgspersoner?"},
  [1066] = {c="Meget godt! Jeg regner med, at Syndikatet ikke voldte dig større besvær?\n\nSom jeg nævnte, er uskyldiges blod ikke let at skaffe. Vi er heldige, at Syndikatets Skyggemagikere udførte det svære arbejde for os.\n\nVent nu et øjeblik, mens jeg brygger min blanding...", p="Har du fundet Syndikatets Skyggemagikere og samlet blodet fra dem?"},
  [1067] = {c="Et gift fra Apoteker Lydhøj? Udmærket. Hvis jeg kender Lydhøj, så bliver det her gift ganske virkningsfuldt mod Ventureselskabet...", p="Du er vendt tilbage, <Name>. Medbringer du hjælp fra Apoteker Lydon?"},
  [1068] = {c="Ødelæggelsen af maskinerne XT:4 og XT:9 har beroliget mange af Stenklippes ånder, <Name>. Med deres tab må vi håbe, at Ventureselskabet fjerner sig fra disse bjerge.\n\nFor hvis de ikke gør, frygter jeg, at de grusomheder, dette sted har lidt, vil blegne i forhold til det, der venter forude.", p="Træåndene klager over tabet af deres brødre, <Name>. Du må tilintetgøre Fliseknuserne XT:4 og XT:9, ellers frygter jeg, at Stenklippe aldrig bliver helbredt."},
  [1069] = {c="Du fik dem! Tak!\n\nJeg sender dem til Svimlevig og får dem fragtet til Bytteviken. Jeg kan allerede smage overskuddet!\n\nHer er din andel, <Name>. Jeg kunne ikke have indgået denne handel uden dig.", p="Har du fået æggene, <Name>? Jeg har allerede indgået en fragtaftale med Havnemester Svimlig!"},
  [1070] = {c="Ah, du er kommet fra Askedalen på Tarras foranledning--hvor savner jeg hende, mit hjemland og mine venner. Hun må have det godt hos Vagterne, når hun sender eventyrere ud på andre opgaver. Jeg er stolt af hende.\n\nDet er en fornøjelse at møde dig, <Name>."},
  [1071] = {c="Mange tak for din hjælp, <Name>. Du er faktisk kommet lige til tiden.\n\nJeg tror, jeg har en perfekt plan... sprængstoffer. Nej, det er ikke planen, men det er en del af planen.\n\nSe, jeg har brugt højeksplosive stoffer--bare rolig, de er ikke så farlige, som alle tror--til at skubbe kobolderne lidt tilbage. Jeg kan drive dem ret godt med et par nøgledetonationer langs bjergenes kanter, men jeg har været lav på forsyninger i nogle dage...", p="Hvordan går kampen på din front, <Name>?"},
  [1073] = {c="Det duer nok.\n\nHvis jeg ikke vidste bedre, fremmede, ville jeg sige, at du kender noget til alkymi. Godt, godt... verden handler jo ikke kun om sværd og trolddom, ved du?", p="Jeg kan ikke lave noget Nitromirglycerium, hvis jeg ikke har eliksirerne... de er afgørende for dets skabelse."},
  [1075] = {c="Nu, den besværgelse du har brug for; en der lader dig eksplodere sprængstoffer på fjerne afstande... hmmm."},
  [1076] = {c="Giv mig lige et par øjeblikke, så har jeg din rulle klar til dig.", p="Hej, <Name>. Har du fundet den komponent, jeg har brug for?"},
  [1078] = {c="Det er perfekt, <Name>. Tusind tak.\n\nMåske kan jeg en dag i fremtiden hjælpe dig, ligesom du har hjulpet mig.", p="Hej igen, <Name>.\n\nEr du allerede vendt tilbage fra dalen i Stenklippe med de skæl?"},
  [1079] = {c="Virkelig fantastisk! Dette er et enormt slag mod Ventureselskabet.\n\nVi kan finde svaghederne i deres maskiner og også indarbejde deres design i vores egne skabelser. Det er virkelig en vidunderlig dag.", p="Har du fået planerne, <Name>?"},
  [1085] = {c="Forræderisk... forræderisk og farligt, det er hvad dette land er.\n\nMen jeg er her for at vise nattealferne, at det er lidt mere sikkert med hjælp fra god gammel ingeniørkunst og et strejf af magi.\n\nSe, at sværge magi helt af vil ikke hjælpe nattealferne--de har brug for den. Verden har brug for den. Og med ingeniørkunst og alkymi oveni kan man ikke tage fejl. Mulighederne er uendelige."},
  [1086] = {c="Du fandt havnen? Godt klaret, <Name>! Jeg er sikker på, at kobolderne blev ret overraskede over din levering! Lad os håbe, at giftstoffet finder vej til deres hovedkvarter.\n\nDu har tjent dit folk godt, og jeg råder dig til at ignorere al den skyld, du måtte nære over at have forgiftet Ventureselskabet. De fortjener langt værre.\n\nOg hvis der er ét eneste partikel visdom, De Forladte kunne lære deres allierede, så er det dette:\n\nVig ikke tilbage fra mørke stier... hvis de fører til sejr.", p="Du må finde Ventureselskabets lufthavn, hvis den findes, <Name>."},
  [1087] = {c="Allerede kan jeg mærke det... ja... kraft så sød... den suste-strømmende flod. Nattebørnene er dumme, når de forsmår denne verdens gaver, når de afviser magiens strøm, der synger gennem jeres årer.\n\nHvilken bleg hån er et liv uden dens brændende omfavnelse!", p="Her er kanalisering af magi som at hente vand fra en brønd med en spand fuld af huller."},
  [1088] = {c="Jeg kendte Højmod engang, for længe siden. Han havde sin slags arrogance og hævede sig selv over selv de Højfødte.\n\nHans hoved hæver sig ikke så højt nu, vel, <Name>?\n\nJeg lovede dig en belønning, og den skal du have. Hør efter, hvad jeg siger.", p="Da min herre bød mig op til Stenklippe-toppen, forventede jeg, at alt, hvad jeg skulle gøre, var at lægge nattealferne øde, dem der krøb rundt i ruinerne af vores hellige, gamle Azsyra-tempel, og deres berøring besmidskede dets helligdom... men Højmod var sluppet ud af mit greb."},
  [1089] = {c="Idet de tre nøgler glider ind i deres matchende åbninger, dukker en række genstande op midt i det glødende lys.", p="Tre nøglehuller er udhugget i stenen."},
  [1090] = {c="Tak, <Name>. Det så lidt farligt ud der et øjeblik, og vi har nok trukket alt for meget opmærksomhed til os selv.\n\nDet vigtige er dog, at vi har malmprøven, og den skal til Zizz så hurtigt som muligt."},
  [1093] = {c="Hey, er det det, jeg tror det er? Fantastisk!\n\nNu, lad os se. Ugh... hvordan skal jeg dog forstå det her hukommelsesbras... kan ikke regne ud, hvordan gnomer tænker. Hør lige her, jeg er overrasket over, at de kunne bygge hjulet, for slet ikke at tale om de flyvemaskiner, de er så vilde med.", p="Har du fundet de planer? Jeg er ivrig efter at imponere den nye chef. Forhåbentlig, når han er overbevist om min loyalitet--nåja, så meget som han nu kan overbevises... kobolds ære, ved du?--vil han føle sig tryg ved at gøre brug af mit temmelig imponerende geni."},
  [1094] = {c="Sprydhjul, hva'? Kan ikke sige jeg stoler på ham, men denne information lyder godt nok. Hvad jeg ikke ville give for at få Ventureselskabet ud af mit hår.\n\nDe kommer dog med nogle gode maskiner... Jeg kan ikke nægte at vi har nydt godt af nogle af de forbedringer de har udtænkt.", p="Hej der! Hvordan kan jeg hjælpe dig?"},
  [1095] = {c="Eliminere Gerenzo? Nu er det en udsigt, jeg ingen indvendinger har imod.\n\nGnomer er slemme nok i forvejen, men det, jeg har lært om Gerenzo, gør det kun værre. Tilsyneladende var han en af de øverste ingeniører i Gnomregan, hvor han arbejdede på deres hemmelige projekt--vi kunne aldrig trænge ind i Dun Frostbakke godt nok til at finde ud af specifikke detaljer. Det var en fiasko. Vores rapporter siger, at hvad det end var, bogstaveligt talt eksploderede dem i ansigtet."},
  [1096] = {c="Se på den ting... der skal en gnom til for at finde på noget sådan. Jeg forstår ikke, hvorfor du ville hugge en arm af og erstatte den med det, når du bare kunne beholde begge arme og tilføje en tredje!\n\nGnomer, siger jeg dig...\n\nI det mindste er Gørenzo ude af spillet. Forhåbentlig er det bevis nok, og Sprutventil vil tildele mig et af Tinkerforeningens værksteder i Gadgetbyen eller måske endda Underminen.", p="Sprutventil vil have en form for bevis på, at Gørenzo er død. Jeg tror nok, hans mekaniske arm duer."},
  [1097] = {c="Er du her for at hjælpe med min levering? Meget godt!"},
  [1098] = {c="Vinsents krop ligger knust og stille.\n\nSelvom Dødsstalker Stålhård vil sende sin rapport til Hadrec... må alle yderligere detaljer, Vinsent måtte have opnået, forblive hos ham.\n\nMen i hans hånd klemmer han en lille tingest..."},
  [1101] = {c="Heksen er blevet lagt til hvile. Det er fantastiske nyheder, <Name>.\n\nI disse farefulde tider er det forfriskende at se én så modig som dig selv.\n\nNu hvor Rasorflankes håndlangere er taget hånd om, kan vores studier i området fortsætte. Måske kan vi nu få mere viden om, præcis hvad der skete for at korrumpere Agamagg'ans hvilested.\n\nJeg frygter dog, at svaret på det spørgsmål også ligger i forræderi...", p="Så længe Charlga Rasorflanke samler en styrke i Rasorhegn-Kraulen, er disse lande i stor fare."},
  [1102] = {c="Jeg ser, at den onde stamme fra Rasorhegn-Kraulen nu kender smerten fra mit folk. De modbydelige bæster har fortjent det.\n\nAt drive én fra et helligt land er en synd, der fortjener den alvorligste hævn.\n\nTak, <Name>, for at hjælpe mig i min nød.", p="Når jeg ved, at de snavsede bæster fra Rasorhegn-Kraulen er drevet ud af deres snavsede hule, vil jeg kunne hvile i fred, vel vidende at hævnen er blevet tilfredsstillet.\n\nHar du drevet tornesvinene ud af Kraulen? Bringer du mig gode nyheder i form af Rasorflankes Hjerte?"},
  [1103] = {c="Ahhh, den yur klar...\n\nJeg lægger mine ting i braseren, så kan du snakke med ånden også.\n\nOg bekymr dig ikke en smule om at kigge ind i åndeverdenen med sapta... ol' Tiv ved et puds eller to om, hvordan sapta-magien virker.\n\nKom nu, gå ned med mig til helligdommen, og lad os tale med ånderne sammen, brormand.", p="Ha' ya sapta, broder?\n\nJeg kender en anden, der fik problemer efter at have besejret den korrupte vandånd--det lader til, han ventede for længe, og kom for hurtigt ud af åndeverdenen til hans smag. Hader at se det hænde en anden, så jeg venter lige her et stykke tid for at sikre, at ingen andre får brug for min hjælp."},
  [1104] = {c="Okay! Giften kommer til at virke fantastisk! Tak, <Name>!\n\nNu skal jeg bare koge den ned, anvende Skipperotomer, tilføje en nega-katalysator, og... Pokkers! Hvor er mine noter!?", p="Hi hi hi! Fik du den gift??"},
  [1105] = {c="Du fik dem! Tak, <Name>!\n\nHold da op, disse granater er hårdere, end jeg troede! Hehe, når jeg arbejder med dem, kommer jeg sikkert til at bøje en hel kasse fuld af værktøj!", p="Min bror gør fremskridt med sit nye brændstofdesign, og det bekymrer mig. Jeg må hurtigst muligt i gang med en brændstofstridsvogn af skildpaddeskal!\n\n<Name>, har du de granater endnu?"},
  [1106] = {c="Fizzle sendte dig? Nå, så ændrer det tingene! Selvfølgelig hjælper jeg dig. Fizzle og hans bror er to af de få mennesker der ikke vil have mig død!\n\nSå Fizzle vil lave stempler, hva'? Stempler stærke nok til at klare alle de belastninger han har planlagt, og hvis jeg kender Fizzle, så er hans nye bil en vulkan på hjul!", p="Nå, du fandt mig. Godt for dig.\n\nEr du her på grund af den økse, jeg lavede til Gath'Ilsnavs? Eller er du her for at genvinde Hertuginde Pamays ære?\n\nJeg er faktisk ligeglad med hvilken. Hvis du er her for at kæmpe, så lad os få det overstået..."},
  [1107] = {c="Tak, <Name>! Når jeg har malet disse ned og smeltet dem sammen med nogle få andre ingredienser, er kompositten klar. Og derefter er bilen Boks for sin egen hastighed.\n\nBoks, så længe den ikke rammer noget...", p="Har du halefinnerne? Hvis jeg ikke kan beskytte vores vogn mod dens egen hastighed, holder den ikke længe i disse væddeløb."},
  [1108] = {c="Ah ja, de her duer fint. Nu lad os komme dem i varmen og se, hvordan de klarer sig...", p="Fandt du nogen indurium-flager, <Name>. Jeg har min smedje opvarmet og klar til at teste dem."},
  [1109] = {c="Storartet! Det er netop den start, vi havde brug for, <Name>.", p="Ah, jeg ser, du er vendt tilbage. Lykkedes det dig at skaffe noget Kraul-guano?"},
  [1110] = {c="Hov, se lige alt det der! Der er noget godt gods i den skrotbunke. Jeg er sikker på, at jeg kan pantsætte det for en pæn sum.\n\nOg... er det et øre, jeg ser klemt mellem de to metalplader?? Av! Hehe, jeg ville bestemt ikke ønske at være den pilot!\n\nTak, <Name>. Her er din løn. Og her er et lille råd, helt gratis...\n\nHvis du kigger hårdt nok, kan du altid finde profit i en andens tragedie.", p="<Name>, har du været ude i Sletterne? Bragte du det læs dele tilbage, jeg ville have?"},
  [1111] = {c="Åh ja. Dele til Kravel. Jeg er glad for, at du er her. Disse ting har stået herude i dagevis, og jeg var bange for, at de ville ruste!", p="Tal højere! Sig mig, afleverer eller henter du noget?"},
  [1112] = {c="Stor, du fik dem! Nu skal vi have dem bragt til gnomerne. Men først...\n\nLad os tage én lille genstand ud...", p="Nåede du til Skralde og fik de dele?"},
  [1113] = {c="Åh, hvilken overflod af blod du har bragt mig, <Name>! Din indsats har været yderst fortrinlig!", p="Er du vendt tilbage fra Det Skarlagenrøde Kloster? Jeg skal bruge mange hjerter til dette dejlige eksperiment!\n\nUden tvivl vil Varimatras og Den Mørke Dame også være glade for at blive af med Skarlagen-skummet..."},
  [1116] = {c="Nå, se lige dér. Du fandt drømmestøvet!\n\nOg hvordan var sumpen, <Name>? Det er ikke let at få et varmt måltid dér, vel?", p="Tilbage så hurtigt? Har du mit drømmestøv?"},
  [1130] = {c="Så, <Name>, du er kommet. Er du nu klar til at rejse gennem fjerne lande?\n\nHvis du er det, unge <Class>, så hør efter..."},
  [1131] = {c="Ved at besejre skabningen Stålbid har du renset Tusindnåle for et forfærdeligt fordærv.\n\nOg det, <Name>, er din lektie for i dag.", p="Har du besejret den modbydelige Stålbid, <Name>?"},
  [1132] = {c="Goddag! Du blev sendt af Hr. Flint i Menetil-havnen? Nå, Hr. Flint er en stærk karakterdømmer. Hvis han sendte dig, så er der ingen tvivl om at du hører til her i Kalimdør!"},
  [1133] = {c="Er du kommet hertil for at tilbyde dine tjenester til Alliancen, <Name>? Vi byder bistanden velkommen, for selvom dens skønhed består... er Askedalen-skoven ikke længere det fredelige sted, den engang var."},
  [1134] = {c="Tak, <Name>. Det gør mig ondt at skulle beordre slagtningen af væsener, der måske ikke frivilligt hjælper vores fjender, men det er min pligt.\n\nDit hjerte må måske græde over de Stolt-vinger, du slog ihjel, min ven, men må dit hjerte så svulme op ved tanken om, at dine allierede er i sikkerhed for Stolt-vingernes gift.", p="Har du giftsækkene fra Stolthedsvingerne, <Name>? Vi kan ikke tillade orkerne at bruge bæsternes gifte mod os!"},
  [1135] = {c="Ah, de fleste af disse er næsten sprængfulde med gift, <Name>. Sådan noget bliver normalt kun høstet fra unge wyverner eller frugtbare hunner. Der må have været et ret blodigt slagteri deroppe i Højrede!", p="Fandt du Højrede, <Name>? Har du haft held med wyvernerne derude?"},
  [1136] = {c="Både styrke og list var nødvendige for at finde og besejre Frostgab, <Name>. Du har begge dele.\n\nDin vej har ført dig til dalene i Tusindnåle og til de høje bjerge i Alteraz. En dag vil den føre dig gennem alle Jordmoderens lande, for sådan er jægerens vej.", p="Har du været i Alterac-bjergene, <Name>? Stod du over for den svært fangbare Frostgab?"},
  [1138] = {c="Vow, de her fine krabbestykker er præcis hvad jeg har brug for. Tak <Name>! Jeg fandt dem, mens jeg fiskede for et stykke tid siden, og jeg har ingen brug for dem. Måske kan du gøre noget ud af dem. De duer da ikke til gode krabberetter.\n\nJeg fortalte dig vel alt om krabber, ikke?", p="...citronkrabbe, piskerodskrabbe og Jernsmede-overraskelseskrabbe. Det var vist det.\n\nÅh, hej dér <Name>. Har du de fine krabbestykker, jeg fortalte dig om?"},
  [1140] = {c="Måske har bukkefolkene fået lov til at blive i skoven for længe. Jeg vil tale med Elissa om det, næste gang jeg rejser til Auberdin.\n\nIkke desto mindre vil Atrikus' kraft, med sjælstenene ødelagt, være stærkt svækket. Vi må gribe denne chance for at udslette ham og hans kult.", p="Jeg har engang hørt en hvisken om, at bukkefolkets historik på en eller anden måde er beslægtet med nattealfernes, men jeg har fundet mine ærede værter tilbageholdende med at tale om sagen."},
  [1141] = {c="Det er nogle rigtig flotte havaborrer, <Name>! Tak fordi du hjalp mig!\n\nDu er i hvert fald mindst lige så god en fisker som min fætter, Graun Blump. Hun har også skæg, og hun lugter lidt underligt, men det gør ikke noget ved hendes fiskeri. Jeg regner med, at du har, hvad der skal til for at bruge en Blump-familiens Fiskestang.", p="Der findes masser af gode retter, man kan lave af Mørkekyst-havaborrer. De er gode at spise, men jeg synes, det er sjovere at fange dem.\n\nHar du fanget nogen Mørkekyst-havaborrer endnu?"},
  [1142] = {c="Nej!\n\nDet er ikke retfærdigt. Åh, grusomme og uudholdelige verden!\n\nJeg må nu bære denne sorgens byrde og ikke lade Heralåths værk dø med ham.\n\nDu var modig at rejse fra et så farligt sted, <Name>. Men gå venligst nu.\n\nI ensomhed vil jeg sørge.", p="Hvad fører dig til mit hjem, <Race>?"},
  [1143] = {c="Med Atrikus' død håber jeg, at de dæmoniske styrker i dette område bliver drevet tilbage. Jeg tvivler ikke på, at de vil samle sig igen og vende tilbage, men så er vi endnu bedre rustet til at møde deres trussel.", p="Atrikus Narasin er en gammel og mægtig hekser. Måske bør vi vente på Delgrens bistand, men han havde tydeligvis stor tro på dig, siden han sendte dig alene."},
  [1144] = {c="Tak igen, ven! Jeg sagde jo, at jeg ville gøre besværet værd for dig!"},
  [1145] = {c="Ah, et brev fra Korrand. Han har været en loyal tjener i nogen tid nu. Jeg har undret mig over, hvordan hans pligter går i Korsvejen.", p="Jeg misunder dig, <Class>. Du har udseendet af en, der har været uden for Orgrimgrads mure i et stykke tid.\n\nJeg selv ville rejse i Krigshøvdingens navn, hvis Trael ikke havde brug for mine færdigheder her i byen. Men han leder os godt, og jeg stoler på hans dømmekraft--jeg bliver her, så længe han har brug for mig."},
  [1146] = {c="Lad dig ikke forstyrre af de tordnende ekkoer fra bjergvæggene. Kobolderne og gnomerne er ude på Sletterne og kapløber hinanden i gerninger, skabt af det, de kalder videnskab. Der er større trusler her i Tusindnåle, og en af dem slagtede mere end halvdelen af min krigsgruppe.\n\nMen vi bliver her, indtil vi hører fra Belgrom i Orgrimgrad. Indtil da holder vi vores position her og er på vagt.", p="Krig fører min gruppe og mig til Glimmerflatene, <Class>. Hvad fører dig hertil?"},
  [1147] = {c="Ha! Det ikor, du er dækket af, gør dig faktisk pænere, <Name>! Det får dig dog også til at stinke på samme tid. Stå ikke for tæt på kodo-oksen; du starter enten en stampede, eller også får du dem i brunst.\n\nJeg tror, mine ledsagere ville være enige i, at din lugt alene beviser, at du har gjort din del for at hjælpe os mod de insektvæsener. Tak, <Name>.", p="Med så mange rejsende på vej ud til Sletterne for de løb, er jeg sikker på, at vi kan overtale nok eventyrlystne til at hjælpe med at skubbe de insekter tilbage. Min gruppe og jeg kan ikke tage af sted, før vi gør det."},
  [1149] = {c="Det er først, når vi står over for uforudsete modgange, at vi begynder at se, hvor stærke vores ånder er. Du tog et tro-spring, selvom du ingen garanti havde for, at du ville overleve. Dit sind er åbent, og din ånd er forberedt på det, der skal komme.\n\nHvis du er villig, så er din næste prøve klar.", p="Tro. Den er langt vigtigere, end nogle indser.\n\nDet betyder nogle gange ikke noget, hvad du tror. Det er bare vigtigt, at du tror på noget."},
  [1150] = {c="Grenka var mægtig, selv efter <Race>-standarder. Du bør være stolt af din bedrift i dag.\n\nUnder din troksprøve viste du åndens styrke, og nu har du vist udholdenhed i kamp ved at tage fat på Forræderfjer-harpyjerne, men tiden er kommet til en ny prøve.", p="Du skal være forberedt åndeligt, fysisk og mentalt på de udfordringer, der venter dig.\n\nAlt for ofte skynder vi os forpost, før vi er klar. Jeg anser det for min pligt over for ungdommen, uanset hvilken stamme de tilhører, at forberede dem på de farer, de kan møde, når de forlader hjemmets helligdom."},
  [1151] = {c="Styrkens Prøve er gennemført. Du har vist styrke og mod, og du er nu klar til den sidste prøve, før disse ritualer er fuldført.", p="Rok'Alim kaldes også Stamperen af kentaurstammerne i Tusindnåle, på grund af den tordnen hans næver laver, når han pisker de væsener, der er modige eller dumme nok til at stå i hans vej."},
  [1152] = {c="Dagene og nætterne bliver koldere over hele verden, mens kobolderne hærger landet, og nattealferne peger fingre ad de yngre racer. De Forladte og orkerne er ikke de eneste, der har skylden for lidelserne i Kalimdør og Herrelande. Mange af de intelligente racer har bidraget til verdens smerte. Dorne ved det, og han har sendt dig til mig, fordi du har vist de egenskaber, der er nødvendige for at indse det også.\n\nNu står du foran Brauk."},
  [1153] = {c="En god prøve, <Name>. Virkelig en god prøve.\n\nDe rejsende kan ikke længere hovmode sig over mig med den malm, de fandt, nu hvor du har været vellykket.\n\nJeg går straks i gang med den. Hvis den viser sig stærk nok, sender jeg et våben fremstillet af materialet tilbage til krigshøvdingen, så han kan se vores succes.\n\nJeg glemmer ikke din hjælp, <Class>.", p="Jeg så de rejsende igen--dem, der ikke ville sælge mig en prøve af malmen. Jeg spyttede efter dem, fordi de ikke hjalp krigshøvdingen.\n\nMåtte de dø i slaget som kujoner og ikke som krigere, sådan som det burde være retten for alle, der allierer sig med Horden."},
  [1154] = {c="Dette er bogen, jeg nævnte. Der er håb om, at du så vil besvare mit spørgsmål korrekt... medmindre du har glemt at studere dens indhold.\n\nNår du er klar, så tal med mig igen, så stiller jeg dig et spørgsmål.", p="Bring mig bogen, når du har studeret den. Jeg stiller ikke mit spørgsmål, før du har givet mig bogen."},
  [1160] = {c="Dette er bogen, jeg sendte dig ud for at lede efter.\n\n<Parqual stryger langsomt sin hånd hen over bogens top, mens han stirrer ned på den.>\n\nSå nu ønsker du et spørgsmål, der beviser, at dit sind er lige så stærkt som din krop og ånd. Hvis du har studeret bogen længe nok, så stiller jeg dig dit spørgsmål, og så kan du blive færdig med disse prøver!", p="Jeg håber, du fik Skarlagenrøde Korstog til at lide lidt, før du stjal bogen fra dem.\n\nMine synspunkter om deres slags er ikke ubegrundede. Korstoget har måske engang været tilhængere af Let, men nu søger de at udslette enhver skabning, der ikke har taget parti med deres religion. De mener, at alle udøde, De Forladte eller ej, skal renses, og de, der rejser i deres lande, må enten være gale eller underlagt de udødes mægtige magi. Idioter. Idioter og tåber; hver eneste en af dem."},
  [1164] = {c="Du står foran mig som en hævnens figur, og jeg bøjer mig for dig i taknemmelighed.\n\nMed den kos død, og da jeg ved, at deres frø ikke længere vil sprede sig over hele Azerot, kan jeg lægge min energi i noget mere indbringende. Jeg håber, du plyndrede deres gård, efter du var færdig med dem.", p="Dræb dem alle sammen og bring mig deres hoveder!"},
  [1167] = {c="Ah, det er godt at se dig igen, <Name>! De mærkeligste ting er sket her omkring, og jeg er glad for, du dukkede op!\n\nDet var meget underligt, <Name>. Alt virkede normalt – nå ja, så normalt, som tingene bliver her omkring – og så kom der pludselig et blændende lysglimt fra det øverste rum i tårnet. Så kom skrigene. Skrigene skar gennem luften, og lyn slog ned i jorden fra tid til anden. Hvad foregår der?"},
  [1175] = {c="Jeg håber, du ikke har dræbt nogen af kongeøglerne oppe på selve skinnerne! Det tager lang tid for kadaverne at rådne op i solen, og jeg har ikke lyst til at skulle tage en skovl frem for at gøre rent.", p="Det er slemt nok at skulle rydde op i væddeløberens vrag, uden at skulle plukke dem ud af brændte dyredele."},
  [1179] = {c="Ah! Langskæg sendte dig med et læs hjelme! Hurra!\n\nNu kan vi måske overtale en pilot til at køre vores bil...", p="Pas på, hvor du træder! Vagt vagt vagt!! Det her er skrøbelige sager, du ser her, og hvis vi skal vinde, så skal det hele fungere perfekt!"},
  [1180] = {c="Forsendelser til Skralde? Lad mig lige tjekke logbøgerne...\n\nNej, den seneste forsendelse jeg har registreret til Skralde var støvler fra Dryppelik. Der har ikke været meget andet, bortset fra byggematerialer og værktøj. Bestemt ingen racedele."},
  [1182] = {c="Nu, lad mig lige få en kopi af disse tegninger til mine egne noter, så kan du tage dem direkte til Pozzig. Vi vil jo ikke have, at han tror, at en af hans sponsorer har svigtet ham.", p="Så meget som jeg hader at indrømme det, er det gnom-holdet derude ganske godt. Vores drenge behøver hver en fordel, de kan få."},
  [1195] = {c="Meget godt. Dette burde opfylde Raus anmodning fint nok. Kunne du levere det til ham? Du kunne måske nyde at bruge lidt tid ude i Nåle.", p="Når vi har det fyldte hætteglas, kan vi sende det videre til min medarbejder, Rau, i Tusindnåle. Det var ham, der bad om hætteglasset med vand, så han ved bedre, hvordan vi kan gøre brug af det."},
  [1196] = {c="Hm, ja, dette lille hætteglas med vand vil tjene vores formål perfekt. På grund af dryadernes og kentaurernes fælles aner vil vandet fra Månebrøndene gøre det muligt for os at bryde igennem beskyttelsen af den evige flamme, der omgiver kentaur-relikken.", p="Jeg regner vist ikke med, at Zangen har sendt dig, hm?"},
  [1197] = {c="Jeg fornemmer en mærkelig energi, der udstråler fra Hoven... Jeg tvivler ikke på, at vi vil opdage overraskende ny information om kentauren fra dens undersøgelse.\n\nTak, <Name>. Nu må jeg begynde at tyde de mysterier, du har bragt mig.", p="Jeg er ivrig efter at få mine hænder på det Kløvede Hov. Har du taget det endnu?"},
  [1198] = {c="Daggryvogter Skyggelass var god at sende dig. Der er faktisk en ondskabsfuld intrige i gang på dette fordærvede sted."},
  [1199] = {c="Du er uden tvivl af modig og adelig blod, <Name>. Sølvdæmringen roser dig for dine bestræbelser mod det onde.", p="Sortdybet var engang et gammelt nattenisse-tempel. Det husede engang en yderst magtfuld månebrønd. Hvem ved, hvilken ondskab der nu bryggers dernede i Tusmørkets Hammers hænder.\n\nHar du gjort nogen fremskridt med at fjerne deres tilstedeværelse?"},
  [1200] = {c="Kelrik har undgået os i ganske lang tid.\n\nDet ser ud til, at hver gang ondskaben viste sig i disse egne, havde Kelrik en finger med i spillet. I nogen tid anså vi ham for død eller forsvundet.\n\nMen det giver perfekt mening. Ved at afslutte hans herredømme har du skånet mange uskyldige liv.\n\nPå lyset! At ofre nogen til en tjener for en Gammel Gud for egen vindings skyld er ud over al kritik!\n\nDu har gjort en stor gerning, <Name>. Jeg hilser dig på Sølvdæmringens vegne.", p="Tid er en dyrebar vare, <Class>.\n\nMin rolle her i Darnassos er at sikre, at Sølvdæmringen trives, og at de onde kræfter, der trænger ind i Kalimdør, bliver standset.\n\nFremsæt dit ærinde hurtigt, ellers må du se at komme videre."},
  [1201] = {c="God gerning. Deres infiltratører er dygtige, men de er ikke gode nok til at undslippe Hordens vågne øje!", p="Har du fundet infiltratørerne, <Name>?"},
  [1221] = {c="Stor, du fik dem! Jeg kan sælge disse til mine kontakter for et bundt!\n\nTak for leveringen, <Name>! Du er en stor partner.", p="Har du knoldene, <Name>?"},
  [1241] = {c="Hmm... <Jørgen kigger op på dig med sammenknebne øjne.>\n\nDet er i orden. Jeg hjælper ya, men ikke fordi jeg vil, men fordi jeg er forpligtet.\n\nOg lad os få én ting på det rene: du ved langt mere, end du burde fra starten. Lad os holde det her som vores lille hemmelighed, og brøl ikke om noget, du finder ud af, i nogen kro. Forstået?", p="Hmph, du har bedre en god grund til at forstyrre en mand og hans fiskeri. Jeg bryder mig ikke om pjankere, og slet ikke om tiggere."},
  [1242] = {c="Undskyld, et brev til mig? Nå, mig den lade... Det er ikke tit, man får en leverance, der ikke er en kasse eller tønde, når man kun arbejder. Lad os se, hvad det handler om.\n\n<Elling kigger op på dig, mens han åbner brevet.>\n\nDu ser lidt anspændt ud, er du okay, <Name>?", p="Hej, <Name>. Er der noget, jeg kan gøre for dig? Måske vil du gerne prøve noget af vores specielle Trøsen-cheddar? Eller en klods darnassisk blåskimmelost?"},
  [1243] = {c="Åh, Trøsen sendte dig, hva'? Det er lidt anderledes.\n\nKæmp bare løs mod de uhyrligheder, der kommer imod dig fra mørket. Jeg er sikker på, at du klarer det ret nemt, hvis du er den type, der hænger ud med sådan en som ham.\n\nSå hvad har min ven brug for af mig på sådan en dyster dag som denne?", p="Ikke særlig sikkert at færde sig rundt i skoven, <Name>. Vær forsigtig, og hvis du ser noget mistænkeligt eller farligt, så kontakt Vagterne med det samme. Prøv ikke at tage noget på dig selv. Vi er ikke ansvarlige for noget forfærdeligt, der måtte ske med dig.\n\nMen vi ved begge to, at du vil ignorere mig og alligevel kæmpe mod det, der kommer ud af mørket, ikke sandt? Haha, ja, I eventyrertyper... alle sammen den samme slags."},
  [1244] = {c="Du er tilbage i god behold. Det kan man vel ikke bede om meget mere end, vel?\n\nNu, lad os se, hvad vi har her. Det ser ganske officielt ud, så vidt jeg har set af Defias-dokumenter. Men det kunne være en dublet, bare for at lede dig på vildspor fra det, du nu end leder efter.", p="Pas på dig selv derude, <Name>. Jeg ved, at det var Trøsen, der sendte dig hertil, men det betyder ikke, at der ikke lurer noget i skovene, som kunne volde dig besvær... især når du undersøger Defias."},
  [1245] = {c="Jo... det her er en interessant læsning. Jørgen og DeLøvi var kloge nok til at lade mig være med her.\n\nDet lader til, at Defias har kæmpet ret hårdt for at fuldende deres plan. Hmm... hvad er det her? \"Næve\"? Det er et velkendt navn.", p="Jeg ser, du er tilbage, og i ét stykke. Vi ved begge to, at du ikke er her for at få ost, så lad os springe høfligheds-fraserne over. Var Bakkus til nogen hjælp, eller har du overhovedet forladt for Skumringsskoven endnu?"},
  [1246] = {c="Hvad?!\n\nDu kommer ind i min gyde og stiller spørgsmål om min personlige forretning? Forretning, som du tydeligvis slet ikke har noget med at gøre."},
  [1247] = {c="God at se, at du stadig er i live, <Name>. Så, det gik brønd med Dashel dengang, hva'?\n\nJeg har læst mere om denne deres plan, og selvom den ikke nævner navnet på diplomaten, de var ude efter, omtaler den denne plan B, de satte i værk efter deres fejlslagne første forsøg på at fange ham.\n\nDenne Slank, som Dashel nævnte, har ikke noget andet navn skrevet her, men hvis du siger, at han er i Menetil, så er det en start."},
  [1248] = {c="Velkommen, velkommen, velkommen, <Name>. God af dig at slutte dig til os. Måske en øl i dag? Eller noget fåre?\n\nNævn din fornøjelse, så sørger jeg for, at du bliver taget godt hånd om. Jeg hedder Mikail, og jeg glæder mig til at betjene dig.\n\nHm? Hvad er det? Trøsen? Giv lyd lavere, min ven. Det her er ikke noget for hele krostuen at høre om."},
  [1249] = {c="Fangede ham, hva'? Godt for dig. Jeg er overrasket over, at det var Slank.\n\nJeg vil være ærlig, jeg troede aldrig, jeg ville savne spændingen ved nogle af de mere snedige underjordiske aktiviteter. Jeg gætter på, at gamle vaner dør hårdt. Undlad at nævne det over for Elling—han ville nok prøve at få mig til at vende tilbage til Stormvind, hvis han hørte, at jeg savnede action.\n\nJeg er glad for, at jeg i det mindste kunne være en lille smule til nytte, mens du var i Menetil. Hvis du har brug for noget andet, så bare spørg.", p="Smuttede han væk? Han så lidt tvivlsom ud, måden han holdt øje med os på."},
  [1251] = {c="Jeg tildeler gerne, at mennesker har underlige smag, når de indretter sig, men ville de bruge et simpelt jernskjold til at pynte deres pejs? Måske blev dette skjold placeret der af dem, der brændte kroen ned.\n\nEn advarsel? En trussel?", p="Hvad er det, du har dér, <Name>? Beviser fra resterne af Skyggefuld Hvile-kroen?"},
  [1264] = {c="Det er en fornøjelse at møde dig, <Name>. Jeg er Kommandør Samaul. Jeg har ansvaret for Frøken Stoltmoors styrker her i Theramøre.\n\nSelvom jeg er ret travl, så må du gerne sige til, hvis du har spørgsmål. Jeg må måske holde det kort, men der er ingen grund til at være uhøflig, hvis du har brug for min hjælp.\n\nHvis du planlægger at rejse ud af byen, vil jeg foreslå, at du er forsigtig. Ud over oger, orker og mudderfisk er den sydlige del af sumpen fyldt med sorte drager."},
  [1265] = {c="Manden, du søger, han der kaldes Hændel, er ikke her. Andre kilder har bragt Dame Stoltmoor oplysninger, som jeg tror, du allerede kender. Hun har bedt mig finde dig og give dig bistand til dit foretagende. Hvis du tillader det, vil jeg fortælle dig, hvor du finder Menig Hændel, så vi kan bringe ham til retfærdighed.", p="Ja, <Name>?"},
  [1268] = {c="Hovaftryk... Det kunne have været tornesvinene, tror jeg. Eller måske endda kentaurerne. Deres tilstedeværelse i Ødemarken er ikke ubetydelig, og jeg synes ikke, det ville være et stort spring at begå sådan en handling.\n\nFortalte jeg dig det? Det var ikke bare, at kroen blev brændt ned... Ejerens kvinde og hvalp blev dræbt. Ringe forretning, det.\n\nIkke desto mindre vil jeg sende Kagorø ud for at finde ud af, hvor sporene fører hen."},
  [1269] = {c="Jeg kender det menneske, Pavle Rytte. Patetisk, selv for hans slags. Han forlod sine kammerater og gemmer sig nu i skovene.\n\nJeg sendte Ogrøn ud for at spore ham op. Nogle af de andre mistænker, at han har stjålet fra vores forsyninger. Jeg tror, jeg så Ogrøn gå mod sydøst.", p="Har du fundet nogen spor om, hvad der skete i Skyggefuld Hvile-kroen?"},
  [1273] = {c="Hmph. Det er godt, at Rytte ikke længere vil lure rundt i sumpen, men det er en skam, at mennesker er bygget så skrøbelige, at han ikke kunne komme sig over et lille pilesår.\n\nDet ser ud til, at denne tråd i mysteriet har ført til ingenting, og vi må lede andetsteds.", p="Har du fundet Rytte?"},
  [1274] = {c="Hej, <Name>. Jeg er Biskop DeLøvi.\n\nUden tvivl, hvis du spørger mig om min virksomhed her i fæstningen, så er det lykkedes unge Thomas at rekvirere dig til at hjælpe vores kongerige. Han har altid været dygtig til at følge mine anmodninger.\n\nJeg er bange for, at jeg ikke har tid til at uddybe meget, så lad mig være stumpt... og prøv venligst at holde det her fra at blive almen viden."},
  [1275] = {c="Du har rejst langt og utvivlsomt stået over for stor fare.\n\nDine handlinger har været uselviske. Det er til gavn for hele Azerot, at du hjælper mig med min forskning. Jeg takker dig, <Name>, for alt, du har gjort.\n\nNu, hvis du undskylder, har jeg masser af arbejde at tage mig af...", p="Når jeg har nok prøver at studere, kan mit sande arbejde begynde. Med de fordærvede hjernestammer fra både satyren og slangefolket i Sortdybet kan jeg forsøge at finde en sammenhæng mellem mutationerne.\n\nMåske kan vi med den opnåede viden forhindre blodalferne i at grave dybere ned i misdannelse og ondskab."},
  [1284] = {c="Hovaftryk, hva'? Det er sandt, at der er en usædvanlig stor mængde kentaur-aktivitet i landene nær Støvsumpen. På korte udflugter ind i Ødemarken fandt vi deres lejre og besiddelser spredt ud over området.\n\nJeg sender Falgran Hastig ud, en af vores sporere, for at se, om han kan finde ud af, hvor sporene fører hen."},
  [1302] = {c="James Hyl, James Hyl... Hvorfor lyder det navn så bekendt?\n\nSelvfølgelig! Hændelsen på Skyggefuld Hvile-kroen. Hvis du har nogen oplysninger om, hvad der skete der, vil jeg opfordre dig til at tale med Kaptajn Vimmes om det. Han står for efterforskningen."},
  [1322] = {c="Jeg bryder mig ikke om edderkopper, der er så store, at jeg ikke kan sidde på dem og mase dem.\n\nTak for at hente dem, <Name>. Nu river jeg dem op og hælder dem ud over skjoldet...", p="Fik du de sække fra edderkopperne?"},
  [1338] = {c="Ah, en anmodning fra en af Stormspidserne. Det er en stolt klan, fuld af fine dværge. Rige nogle af dem også.\n\nTak, <Name>. Jeg går i gang med Bjergbestiger Stormspids' skjold, så det er klar inden dagens udgang.", p="Et brev fra de dværgiske lande? Jeg undrer mig over, hvem der kan ringe fra så langt mod nord...\n\nVær venlig, lad mig se ordren."},
  [1339] = {c="Sådan er det. Jeg har en opgave, som jeg ikke kan udføre, mens jeg vogter. Faktisk vil den tage dig langt væk fra Modansøen.\n\nDin perfekte chance for eventyr!"},
  [1358] = {c="Ah, meget godt. Hvis de første rapporter er sande, kan giftigheden i disse hjerter føre til yderligere fremskridt i vores viden om gifte.\n\nDette er en velkommen levering, <Name>. Din belønning er velfortjent.", p="Har du en pakke til mig?"},
  [1361] = {c="Ja, jeg hverver. Denne mission fører ind i Forødelse, mod kentauren derinde. Jeg vil være kortfattet, så du hurtigt kan komme i gang."},
  [1362] = {c="Er du her på ordre fra Regtar? Så er du her for at tage dig af kentauren. God.\n\nJeg håber, du er udhvilet. Jeg ved ikke, hvordan vores kampagne mod kentauren ender, men jeg ved, at kampen bliver lang.\n\nSæt dig, og lyt."},
  [1365] = {c="Godt klaret. Dette hurtige angreb mod Kolkarerne er en effektiv demonstration af styrke, og styrke er det, kentaurerne forstår bedst.\n\nKolkarernes lederes død vil ikke blot forstyrre den klan, men også få de andre til at standse op og tænke sig om.", p="<Name>, har du besejret Khan Dæs'hepa?"},
  [1366] = {c="Nu må kentauren kende dit navn. Jeg er sikker på, at de kender det, respekterer det og frygter det. Og ligesom de kender dig, kender de også det banner, du rider under.\n\nHordens banner.", p="Hvordan står det til med din samling af ører, <Name>? Store?"},
  [1368] = {c="Jorden taler til mig. Og den siger, at du har dræbt mange Magrom. Det er godt.\n\nHvis du er en ven af Gellekis, så lyt. Jeg har flere opgaver til dig.", p="Dine to fødder træder på Gellekis-jord. Du er ikke velkommen her!\n\nBevis, at du søger venskab med Gellekis-folket. Dræb Magrom-kentaur. Vend tilbage, når jorden er våd af Magrom-blod."},
  [1371] = {c="Ja, det var præcis det jeg havde! Jeg får det til at bevæge sig igen. Det får mig til at grine!", p="Hvis du ikke er vores fjende, så gør du, hvad jeg beder om!"},
  [1386] = {c="Kolkarerne frygter dig nu! Jeg håber, du lo, da du dræbte dem. Det er bedst at grine, når man dræber, så fjenden kan se, at han er svag.", p="Er du bange for Kolkarerne? Hvorfor dræber du dem ikke? Måske har du glemt, hvordan man dræber. Skynd dig og dræb Kolkarerne, før de er døde!"},
  [1418] = {c="Helgrum vil have en rapport, hva'? Jeg sendte en udløber til Stenard for ikke tre dage siden. Fejlede han sin mission? Hvis Stenard ikke har min rapport, så ser det ud til, at han fejlede.\n\nLad os håbe, at den næste løber jeg sender har mere færdighed, eller mere held."},
  [1419] = {c="Det er en fin samling kæbeben, <Name>. Nu kan de kojoter ikke rive i vores forråd efter madrester.\n\nGodt gået. Kojoterne i Ødelandene er ikke let bytte. Din bedrift viser mig, at du måske lige netop kan overleve her.", p="Har du kæbeknoglerne?"},
  [1420] = {c="Tak, <Name>. Fra Nikas rapport ser jeg, at Alliancen heller ikke er uden egne problemer. Og vi kan opdage, at nogle fjender deles mellem os.", p="Du er vendt tilbage. Har du en rapport?"},
  [1431] = {c="Vær hilset, ædle <Class>. Jeg er Keldrun, elev i magi... og andre mystiske kunster.\n\nDen sag Kujon sendte dig her for at tale med mig om, kræver en lille smule mere finfølelse, end du har haft brug for før, men det betyder ikke, at du ikke stadig kan hjælpe vores sag.\n\nGør dig venligst hjemme, så skal jeg fortælle dig, hvorfor Krigshøvdingen har brug for min hjælp... og din.\n\nDet begynder med udseende, <Name>. Hvordan Horden ser sig selv. Hvordan vores allierede ser os. Og vigtigst af alt, hvordan vores fjender ser os."},
  [1432] = {c="Hilsner, <Class>. Du bringer nyheder fra Orgrimgrad; det er godt.\n\nDæmon-invasionen overvælder dette område endnu mere end lugten af kentaurernes møg. Hest-mændene hævder, at landet er deres eget, men der er tydeligvis påvirkninger uden for deres kontrol, som vil knuse dem, hvis de ikke holdes i ave.\n\nDet behager mig ikke, at vi hjælper kentaurerne indirekte, men det er til gavn for Horden, så jeg gør min pligt for Krigshøvdingen, selv om det betyder at hjælpe hekserne inden for Horden."},
  [1433] = {c="Ah, ja. Bistand fra dem, der er loyale over for Krigshøvdingen, bliver altid værdsat.\n\nMit navn er Maurin. Jeg er her på Keldruns foranledning og krigshøvdingens unge Trael. Det er mit ønske at hjælpe den unge leder mod de onder, der truer hans herredømme.\n\nKom, kom tættere på, <Class>. Jeg skal forklare dig min plan for at fjerne den pussende byld, som Brændende Klinge er."},
  [1434] = {c="Du har gjort det godt, <Class>. Du har vist ære og hengivenhed.\n\nNår vores kampagne i Forødelse er forbi, vil Krigshøvdingen vide, at du bistod os i vores handlinger her, og at du hjalp med at gøre hans vilje til virkelighed.\n\nJeg takker dig.", p="Jeg blev advaret af en ledsager fra tyrefolket om, at satyrerne ikke er, hvad de ser ud til at være. Han mener, at der er mere over dem, at deres ondskab er en forvridning af deres sande natur. Men jeg har ikke set sådanne ting.\n\nJeg ser kun det nådesløse slagteri af de svage og korruptionen hos dem, der søger mørk magt.\n\nJeg vil fortsætte min pligt med at udslette dem, indtil Krigshøvdingen beordrer mig andet. Indtil da har jeg ingen medlidenhed med dem."},
  [1435] = {c="Ah, du er vendt tilbage vellykket. Det er godt. Giv mig ædelstenene, så skal jeg gemme dem et sikkert sted....\n\nMine opgaver til dig er fuldført, <Class>. Tal med Takata Stålklinge, når du har hvilet dig. Han har måske andre opgaver til dig, eller også skal du vende tilbage til Orgrimgrad for at fortælle Keldrun om vores fremskridt her i Forødelse.", p="Jeg har prøvet at gøre magierne så simple som muligt. At trække din offers ånd ud af dens såret skikkelse burde være en børneleg. Stol ikke på ædelstenens kraft til at fælde din fjende helt. Du må kun aktivere ædelstenen, når de er tæt på døden, ellers er den ubrugelig."},
  [1442] = {c="Dette er faktisk den ædelsten Stilvæg higer efter, men før jeg kan lade dig bringe den til ham, skal den renses for korruption – slangefolk-tøserne indgyder ædelstenene med kraft, det er rigtigt nok, men med deres egen onde slags.\n\nLad Stilvæg vide, at dens kraft er intakt, og den burde virke godt til det ritual, han ønsker, den skal indgå i.\n\nJeg håber, du ved, hvad du har gang i, <Class>; dette er ingen simpel genstand, du har i din besiddelse.", p="Jeg ville være mindre tillidsfuld over for en, der ikke går en hellig vej, hvis de kom og spurgte om en Kor-ædelsten. Men jeg stoler mere på dit slags end på nogle af mine egne slægtninge. Jeg dømmer ikke hele din orden ud fra handlingerne hos bare ét af jeres faldne."},
  [1447] = {c="Så, du kom til mig af en grund. Hvad er det, du har brug for?", p="Jeg mente ikke noget med kommentaren om, at du var en dum <Class>. Vi er venner, ikke? Ingen ondt blod?"},
  [1453] = {c="Godt at se at Genvinderne ikke er gået tør for arbejde, eller for eventyrere der vil hjælpe til.\n\nJeg er Kreldig, <Name>. Du har gjort et klogt træk ved at hjælpe Genvinderne. Alle har brug for noget i dag: de har mistet et familiearvestykke, en magisk genstand, en elsket. Man ved aldrig. Men med Genvinderne i nærheden er der ingen grund til at man, for den rette pris, ikke kan finde det man har tabt."},
  [1470] = {c="Selvom du stadig er uprøvet og ung i din læring, har du bevist, at du har nok evne til at mestre kaldelsen og bindingen af en drilling. Lad dig ikke narre af drillingens størrelse. Selvom den mangler fysisk styrke, besidder den kræfter og en snildhed, der vil gøre dig gode tjenester.\n\nLyt nøje efter, <Name>, for jeg gentager ikke denne lektion, og jeg overlader dig at mestre den.", p="Din kraft er lille nu, men jeg mistænker, at du allerede fornemmer mulighederne.\n\nSelv de døde kan måske føle sig levende, med den kraft der strømmer gennem os."},
  [1471] = {c="Du har gjort det godt, <Name>. Nu vil jeg lære dig besværgelsen, der bruges til at tilkalde tomgængeren.\n\nDen kraft, den slap løs på dig, er nu din at styre. Brug den klogt.", p="Jeg forventer at høre om din succes, <Name>. At ikke leve op til mine forventninger bliver dog det mindste af dine bekymringer, hvis du fejler."},
  [1473] = {c="Ah, udmærket. Sandsynligvis var Perrinne uvidende om den sande kraft i den muggne bog, han havde stjålet fra os.\n\nDen falder ikke ud af vores hænder igen. Se, <Name>, besværgelsens struktur, og måden hvorpå din kraft skal kanaliseres.", p="Egalin var den lærer, der lærte mig det. Næsten uden at se på den var han i stand til at befale den tomgænger, han havde fremkaldt.\n\nDa det blev min tur til at prøve, var jeg for selvsikker. Leg ikke med de kræfter, du råder over, <Name>; de kan fortære selv de årvågne."},
  [1476] = {c="Hjertet hos en gudfrygtig mand ligner vist nok alle andres, når man ser det sådan her, synes du ikke?\n\nMåske har vi en lidt... anderledes... opfattelse af emnet. De duer nok dog. Jeg tvivler ikke på, at en Sukkubus ville blive tiltrukket af deres renhed.", p="Jeg er blevet behageligt overrasket over din fremskridtshastighed indtil videre, <Name>. Bring mig hjerterne, så imponerer du mig igen."},
  [1478] = {c="God, jeg ser, at Agerøn fik fat i dig, <Name>. Lad os ikke spilde tid på småsnak og høflighedsfraser, men fokusere på din træning. Der er stadig meget, du skal lære."},
  [1480] = {c="Hmm, disse runer er faktisk et sprog, <Name>, et gammelt sprog. De ligner fjernt Eredunsk-sproget, men forskellene er drastiske. Hvis jeg ikke tager fejl, er det en slags kontrakt.... Her, ja, dette symbol er dæmonens signatur: Herre Azrethok.", p="Den Brændende Klinge begynder at indse, hvor svage de virkelig er. Deres magi er patetisk, deres styrke kraftløs.\n\nDeres eneste kraft kommer fra dem, de tjener, og ikke fra nogen forståelse af ægte kraft og viden."},
  [1481] = {c="Skyggestalkerne kunne ikke dræbe dig, <Class>. Imponerende... virkelig imponerende.\n\nDenne hovedbund duer fint til min besværgelse. Mens du var væk, lykkedes det mig at skaffe nogle af de andre reagenser, der er nødvendige for besværgelsen.\n\nJeg er næsten klar. Jeg mangler kun et fokus til besværgelsen--noget, der kan fremkalde et billede af dæmonherren og hans opholdssted.", p="Bring mig ikke en forkert skalp, <Class>. Hvis du bruger de forkerte reagenser, kan det koste os livet. Dæmonherren kan have beredskabsbesværgelser på sig, der skal dræbe dem, som vil spejde efter ham.\n\nSkæbne har allerede tilføjet mig nok smerte."},
  [1483] = {c="Jeg troede, at de der topfolk i Ventureselskabet var slavedrivere, men så mødte jeg Sprutventil, den grusomste af dem alle!\n\nHa! Selvom det er bedre end at være uden job, må jeg indrømme... Eller værre, at arbejde sammen med den Gerenzo Skruefløjte. Hvis du er her for at hjælpe, har jeg noget, du kan lave."},
  [1485] = {c="Gennem din træning som <Class> vil du lære at fremkalde væsener af mange slags. Nogle ser måske ikke sådan ud, men alle er nyttige redskaber.\n\nLad dig ikke narre af drillingens lille størrelse. Som du sikkert har bemærket, er den stadig en skrækindjagende modstander.", p="Det er vigtigt, at du kan kontrollere de væsener, du tilkalder med din magi. Der er så få, der er interesserede i at lære vejene for <Class>, at jeg ville risikere at smide dit liv væk ved at lære dig noget, før du er klar."},
  [1486] = {c="Dine bestræbelser på at indsamle disse huder skal ikke gå ubemærket hen, <Name>.\n\nTak for din hengivenhed.", p="Jeg er meget interesseret i at undersøge huderne fra de afvigende væsener, der har inficeret disse huler. Har du haft held med at samle nogle, <Class>?"},
  [1487] = {c="Som Discipel af Naralex roser jeg din tapperhed, <Name>.\n\nDin bistand med at rydde hulerne er første skridt i vores lange kamp for at se Ødemarken genoprettet.\n\nTak, og må du trives.", p="<Name>, vi, Naralex' Disciple, har brug for din hjælp. Vores tal svinder ind, mens vores mester sidder fanget i sit forvridne mareridt. Vi har ikke de nødvendige styrker til at tage fat på de korrupte væsener, der nu hjemsøger disse huler.\n\nJeg beder dig indtrængende: gå ind i grotterne og før krig mod de afvigende væsener!"},
  [1489] = {c="Jeg byder dig hilsen, <Name>. Du er velkommen her, og jeg foreslår, at du samler al din styrke. For den opgave, vi nu stiller dig ... er en rædsom én."},
  [1490] = {c="Ja, det er sandt. Jeg kender druiderne i Klagehulerne. Jeg har set deres snoede, skællede ansigter. Jeg kender deres forbrydelser, og jeg kender deres planer.\n\nDu må stoppe dem, <Name>."},
  [1491] = {c="Stor, du fik den! Jeg kan ikke vente med at prøve den af. Det her kommer til at gøre mig rig, det ved jeg bare!\n\nTak, <Name>. Tag det her, og når jeg er rig, sender jeg dig flere, det lover jeg!", p="Hvor er min klagende essens?"},
  [1492] = {c="En lille nok kasse. Ja, jeg burde kunne finde plads til den om bord på skibet. Det sejler med næste tidevand, så det her burde være hurtigt nok? Fremragende. Lad mig lige indtaste den i min protokol.\n\nAlt er klaret! God dag til dig, <Class>.", p="Søger du passage med det næste skib, eller har du en genstand, du vil sende med det?"},
  [1499] = {c="Du har gjort det godt, <Name>.\n\nSelvom de ondskabsfulde fæller kun var kæledyr for de mørkere kræfter inden for Brændende Klinge, varsler din succes mod dem større gerninger forude."},
  [1501] = {c="God. Jeg håber, at du påførte Brændende Klinge nogle andre tab, da du gik efter denne.\n\nDe har været en stor irritation for Krigshøvdingen og en stor plage for hekseriet som helhed.", p="Har du Vergas Tavle, <Name>? Hvis ikke, har jeg ingen lyst til at tale med dig, før du har den."},
  [1510] = {c="Endnu en ork, hva'? Jeg håber, du ikke er kommet for den anden. Han klarede den ikke. De kobolder gjorde godt arbejde på ham.\n\nHan sagde, at han havde brug for en heling-drik, men ikke meget andet."},
  [1511] = {c="Nå, på tide var det! Dogran har været derude og døende og ventet på det her.\n\nVi skal have det ud til ham med det samme, men de fleste af fodfolket, der er stationeret her, er ude på en fourageringsmission.", p="Ja, hvad er det?"},
  [1525] = {c="Disse vil gøre det fint, <Name>.\n\nIld er mere end kaos og ødelæggelse--husk det godt. Den handler også om liv og skabelse. Alt hænger sammen på den måde. Kræfter står over for hinanden, men samtidig kan den ene ikke eksistere uden den anden. Begge slukker hinanden, men giver også hinanden mening. Husk altid dette.\n\nAt bruge forskellige typer magi i forbindelse med hinanden vil vise ikke blot ægte færdighed, men også stor visdom.", p="Jeg har nok ingredienser til en affyr-sapta, hvis du kan finde reagenstasken og noget affyr-tjære. Brændende Klinge-fanatikerne bærer de rette komponenter til de fleste af deres besværgelser i de tasker, og de har normalt nok af de ting, jeg har brug for, så vi ikke behøver at lede meget længere efter noget andet.\n\nSaptaerne er altid lavet af ingredienser, der er tæt knyttet til deres respektive elementer. Det gør vores arbejde lettere på grund af heksemestrenes bånd til ild."},
  [1530] = {c="Ja?\n\nMm. Jeg har en fornemmelse af, at jeg ved, hvad du vil spørge mig om: hvad der kan få nogen til at bo her ude i det dybeste af Ødemarken, med truslen fra Tornesvinene overalt og ingen beskyttelse? Brønd, vi har alle vores grunde til at retfærdiggøre, hvordan vi handler. Det egentlige spørgsmål er, hvad der bringer en ringe <Race> til Ødemarkens dybeste kroge for at tale med en kvinde, der åbenbart slet ikke bekymrer sig om sit eget velbefindende?\n\nJeg er villig til at vædde på, at vi begge kender svaret på det."},
  [1534] = {c="Vidunderligt, <Name>. Når alle tre prøver er samlet, kan jeg lave et hætteglas med det reneste vand, enhver skabning nogensinde vil finde. Det skal bruges i de næste trin af din overgangsrite.\n\nJeg er glad for at regne dig blandt vores slags, <Name>. Du gør hele <Class> stolt, og jeg glæder mig til at høre om dine bedrifter i fremtiden.", p="Har du vandet endnu, <Name>? Fortællingerne siger, at ruinerne var beskyttet af store naturvæsener, der ikke bryder sig om besøgende, men det kan lige så godt være myter, der er skabt for at skræmme nattealfernes fjender væk.\n\nUanset hvad, så pas på dig selv."},
  [1536] = {c="Det er godt, <Name>. Du er hengiven til opgaven og har evnen til at opspore det, der er nødvendigt.\n\nEn prøve mere er alt, jeg behøver for at lave reagenset til din Sapta. Isleif bliver også glad.", p="Brønden, der stadig er ren inden for byen, minder mig om de historier, man fortalte mig, da jeg var yngre, <Name>. Selv i tider med stor smerte og sorg kan man finde et lille glimt af håb, et lille symbol at samles om. Ork-folket ser Trael på den måde. Han overlevede mod alle odds og rejste sig for at lede vores folk med sin styrke og sit eksempel.\n\nJeg er ikke sikker på, at nogen ork har lidt så meget som ham, men samtidig er jeg heller ikke sikker på, at nogen ork er lige så stærk som ham."},
  [1578] = {c="Ah, undskyld! Jeg var ikke klar over, at du var her for at hjælpe med at forsyne vores tropper igen. De ting, du har lavet, bliver en stor hjælp!\n\nHer er tegninger til noget rustning. Jeg håber, du finder dem nyttige.", p="Jeg har ingen tid til at snakke. Har du forretninger med mig?"},
  [1579] = {c="Jeg kan ikke tro, du fandt dem! Du må være den heldigste <Race> i Kalimdør!", p="Har du fundet mine Gaffer-krikker, <Name>? Uden mine Gaffer-krikker kan jeg ikke stille mine Stintle-tapper!"},
  [1580] = {c="Jeg kan ikke tro det! Du fandt dem! Du er den bedste fisker, jeg nogensinde har set!\n\nTak, <Name>. Og her, tag disse. Selvom du er så god, at du nok ikke har brug for dem, vil de hjælpe dig med dit fiskeri.", p="Fandt du nogen elektrokugler? Jeg får brug for dem, hvis jeg skal fortsætte min forskning i andelokkere..."},
  [1581] = {c="Disse er fint blandet. Du passer godt på dit håndværk, <Name>, og det er vigtigt for en alkymist.\n\nHer er dine urter, friskt plukket. Må du bruge dem godt.", p="Hej, <Name>. Har du eliksirerne til at bytte med?"},
  [1582] = {c="Ja, disse stykker er gode. Du har en dygtig hånd og et øje for detaljer. Din fremtid som læderarbejder er lovende.\n\nSe her, <Name>. Lad mig vise dig mønsteret til at lave Månelysvesten.", p="Hilsner, <Name>."},
  [1598] = {c="Fremragende... Jeg har aldrig kunnet få adgang til denne tekst, den var gemt i en beskyttet fløj af biblioteket, hvor det ville have set mistænkeligt ud, at jeg hang rundt.\n\nTja, du har gjort et godt stykke arbejde med at skaffe den her, og jeg er overbevist om, at du sikkert kan klare din egen drilling, så der er ingen grund til, at jeg ikke skulle vise dig, hvordan man tilkalder en.", p="Det var for iøjnefaldende for mig at stjæle bogen selv. Hvilket held, at en af deres egne håndlangere gjorde det beskidte arbejde for mig."},
  [1618] = {c="Tak, <Name>. Det her hjælper mig enormt. Med Sortklippe-orkerne, der angriber fra Stenvagtsfæstningen, og Rødryg-gnoldene, der lurer i foden af bjergene mod nord, er jeg altid i gang med at reparere rustninger og lave nye våben til vores tropper.\n\nDe forsyninger, du bragte, giver mig et øjebliks fred. Jeg vil få tid nok til at lære dig noget...", p="Jeg håber, du er her med gode nyheder fra Jernsmede. For jeg er ved at ryge ud over kanten!"},
  [1638] = {c="Åh ho! Tag en drik med mig, <Name>. Du ser hård ud udenpå, men lad os se, om din mave kan klare et par krus af Gris og Fløjtes stærkeste!!\n\nEller... var du her for en lektion?"},
  [1639] = {c="Hej, pyntedukke! Hvad laver sådan en fjollet tøs som dig i Gris og Fløjte? Pas på, ellers knækker du en negl..."},
  [1640] = {c="Du er meget sejere, end du ser ud!", p="Du får kun denne krus, hvis du prøver at pille den ud af mine kolde, døde fingre..."},
  [1645] = {c="Det er en fornøjelse at møde dig, <Name>. Jeg har ansvaret for at sætte paladiner på vejen mod større dyd, mens de vier sig til Lyset og forsvarer Azerot mod Svøben og andre trusler.\n\nNu er tiden kommet til, at du tager dit første skridt mod at blive ægte dydig. Hvis du accepterer, giver jeg dig en Bog om Guddommelighed. Ved at studere den vil du lære lidt om Lyset og om, hvad der forventes af dig. Hvis du forstår den og er i stand til det, vil du lykkes med at opnå større evner."},
  [1646] = {c="Velkommen tilbage, <Name>. Du har vel brugt tid på at læse bogen, håber jeg?\n\nSå bør du være forberedt på at blive testet. Der er altid opgaver at løse i hele byen og i vores lande; handlinger af medfølelse og forståelse; folk, der har brug for hjælp; væsener, der skal slås ned.\n\nVed at bevise, at du har tålmodigheden til at hjælpe andre, især dem der er mindre heldige stillet, beviser du, at du er en tjener for Let og af sund sind."},
  [1647] = {c="BØRNEHJEMMET I STOR... åh, undskyld, jeg ville ikke råbe ad dig, sir,\n\nMit navn er John Tørner. Hvordan har du det?\n\nGodt, godt, dejligt at høre, at det går godt for dig. Jeg har allerede haft en lang arbejdsdag, og jeg savner min kone forfærdeligt, men sådan er prisen, når der er munde at mætte og kroppe at klæde."},
  [1648] = {c="Det er så vidunderligt af dig, <Name>. Tusind tak igen.\n\nDu er en ædel mand, fordi du gør dette for mig. Det er ingen undren, at du har valgt at følge Lyset. Jeg ønsker, der fandtes en måde, jeg kunne betale dig tilbage for alt, hvad du har gjort... hvad siger du? Det er det mindste, du kunne gøre? Ser du? Det er netop det, jeg taler om, <Name>, ædel til sidste ende.\n\nVær forsigtig, og må Lyset beskytte dig på dine rejser.", p="Med al den tilstrømning af håndværkere her og over hele Azerot er der mindre at få af de ting, vi bruger til at sy tøj til børnene på vores børnehjem. Det er meget ædelt af dig, <Name>, at hjælpe mig med at samle lærred, så min kone kan sy nyt tøj til dem. Tak.\n\nForhåbentlig kan jeg snart vende hjem til min kone."},
  [1650] = {c="Hej, <Name>. Jeg går ud fra, med al den rustning og det våben, du har, at du enten er her for at tage mit land, eller at Kirken endelig har sendt nogen til at beskytte mig, mens min Jordæn er væk.\n\nLad mig præsentere mig: Jeg er Daphne Stilvæg. Det er en fornøjelse.\n\nNu er du ikke for sent på den... Jeg har kun dræbt et halvt dusin af skumlingerne siden solopgang. De har været lidt langsomme til at komme rundt om svinget deroppe, men de har nok set dig komme, hvilket betyder, at de sikkert er her om et øjeblik."},
  [1654] = {c="Det er vidunderligt! Du har fået alle genstandene.\n\nJeg burde ikke have det mindste problem med at smede dig et storslået våben af disse. Jeg har faktisk haft tegningerne til det i et stykke tid. Jeg har bare aldrig fået chancen for at samle varerne. Tak, <Name>.\n\nDet føles godt at have min fars hammer tilbage... og en Kor-ædelsten. Jeg troede aldrig, at jeg selv skulle få at se en af dem.", p="De genstande, du leder efter, vil være svære at skaffe, men jeg kan forsikre dig om, at våbnet, jeg vil fremstille til dig, er umagen værd.\n\nDet bliver mit fineste værk til dato, og kun en lille betaling for den tjeneste, du har gjort mig."},
  [1655] = {c="Jep jep, det er det. Ha! Hvis jeg havde vidst, at du faktisk ville tage derud og kæmpe mod nogle af de oger, havde jeg givet dig en liste over ting at skaffe i stedet for bare denne ene ting. Men du er ikke her for at handle med mig, er du?\n\nEn aftale er en aftale; Jordæn ville have en forsendelse af min legering, og det er præcis, hvad han får.\n\nSig hej til dem fra mig, og pas nu på dig selv, <Class>.", p="Så, noget held endnu? Haha, de oger har vel ikke fået det bedste af dig endnu, vel?"},
  [1656] = {c="Ah, de pelse jeg ventede. Tak.\n\nDe kom hurtigere, end jeg havde regnet med. De bliver gode tæpper til alle, der ønsker at blive her.\n\nBliv præcis så længe, du har lyst. Min kro er altid åben, og alle vores folk er velkomne her. Og undervurder ikke en god nats søvn, for den kan gøre en stor forskel, mens du er ude at rejse.", p="Ja, unge? Hvad kan Kauth gøre for dig?\n\nRejsen hertil fra Plateauet kan være en enorm byrde for nogle, men et velkomment syn for andre. Hvilket er det for dig, mon?"},
  [1658] = {c="Godt klaret, <Name>. Kurvemand-festivalen vil blive ved med at give problemer, så længe de afskyelige De Forladte får lov at hjemsøge resterne af Herrelande. Det er IKKE en passende hyldest til det engang så stolte kongerige, lad mig sige dig det...\n\nHer er nogle mønter til eventuelle reparationer, du måtte have brug for, og i årstidens ånd har jeg også medtaget nogle lækkerier, som du måske kan lide. Glad Helligaftens Ende - lad os holde det så sikkert som muligt her i Sydstranden.", p="Har du været op til Tirisfal-lysningen og set efter? De holder normalt festivalen tæt på Undergrunden..."},
  [1665] = {c="Der har vi den! Han ville bestemt ikke skilles fra den, men du var overbevisende. Godt gjort.\n\nNu til din lektion...", p="Jeg så din kamp mod Bartleby Bajer. Godt gået! Fik du hans krus?"},
  [1666] = {c="Hvem er der?\n\nBulvagt, er det dig?\n\nDu bliver nødt til at træde lidt nærmere. Mine øjne er ikke, hvad de plejede at være.\n\nGang derhen sådan, troede jeg, du var en hyænemand!"},
  [1667] = {c="Stor, du fandt den! Jeg frygtede, at den var væk for evigt, brugt af Defias til at udgive sig for en Stormvind-embedsmand. Brønd, det sker ikke nu, takket være dig.\n\nHer er nogle våben, jeg brugte, dengang jeg var Marskal. Jeg holdt dem i stor stand--vælg bare!", p="Har du mit mærke? Jeg vil ikke tænke på, hvilken ballade Døde-tand-Jack kan lave med det."},
  [1681] = {c="Du fandt den! Godt gået!\n\nJeg håber, du slagtede en hel hær af Mørkejern-dværge under din søgen. Jeg frygter, at Jernbånds kompleks ikke bliver det sidste sted, vi ser dem.\n\nMen tak for malmen, <Name>. Jeg glæder mig til at bearbejde den og finde ud af dens egenskaber.", p="Har du trådt ind i Jernbånds Kompleks? Fandt du skyggemalmen?"},
  [1685] = {c="På tide, at du dukkede op. Selvom jeg nok burde have sendt nogen mere kompetent end Remmen for at finde dig.\n\nUanset.\n\nDu har været for længe uden træning, og en hekser uden træning vil ikke beholde hovedet på skuldrene særlig længe."},
  [1688] = {c="Sørina var talentfuld, men ikke nok til at opnå mestring af hekserimagi på egen hånd. Det er en skam at se talent gå til spilde, men nogle gange er det nødvendigt.\n\nJeg håber, min investering i dig vil bære andre frugter.", p="Selv de ældre og klogere kan blive gjort rådvilde af ungdommens og skønhedens listigheder, <Name>. Et råd, du gør klogt i at huske hele dit liv."},
  [1689] = {c="Du klarede det bedre, end jeg forventede, <Name>, men lige så godt, som jeg havde håbet. Nu kan du lære at kommandere din underkuede tomgænger, en allieret, du vil finde værdifuld i de prøvelser, der helt sikkert venter dig.\n\nJeg har ikke mere at lære dig lige nu, men jeg er langt fra færdig med dig, <Name>.", p="Jeg kan ikke vise dig, hvordan man kontrollerer en tomgænger, før du har overvundet en."},
  [1698] = {c="Ha! Så du har hørt om min udfordring, vel?\n\nNå, sæt dig ned og lyt. Tag en drik, og nyd den... for det kan være din sidste."},
  [1701] = {c="Du fik det hele? Fantastisk! Jeg var bange for, at de kimærer ville æde dig helt op!\n\nNå, lad os gå i gang med den rustning...", p="Hvordan går skraldejagten, <Name>? Har du materialerne?"},
  [1712] = {c="Du har samlet tingene til min besværgelse og har vist mig din styrke og snedighed. Men det næste trin i vores opgave er endnu farligere.\n\nLad os håbe, at din styrke ikke svigter.", p="Har du tingene, <Name>? At samle dem er beviset på, at du har styrken til at møde Cyklonianeren."},
  [1716] = {c="Var din overfart svær, <Name>? Du har rejst langt for at tale med mig. Men frygt ikke, jeg ved, hvorfor Gakin har sendt dig, og han var klog nok til det, for jeg kan hjælpe dig i din søgen."},
  [1740] = {c="Ja... Kuglen var ikke særlig splintret, og næsten alle stykkerne er her. Det er en simpel sag at genskabe dem, så Soran'ruk bliver hel igen.\n\nJeg har viet mit liv til studiet af den Brændende Legions kugler og deres genskabelse. Du har forvoldt mig en tjeneste ved at samle disse stykker til studie, og jeg vil give dem tilbage til dig – fuldt genopbygget – i en form, du selv vælger.", p="Det tog mig mange år at samle stykkerne af Zargains kugle, men den har tjent mig godt, og jeg er sikker på, at Soran'ruks kugle vil tjene dig lige så godt."},
  [1778] = {c="Så, du er vendt tilbage så hurtigt, hva'? Og hvad har du så udrettet, mens du har været væk herfra?\n\nKunne du hjælpe en ædel sag? Måske har du lært værdien af næstekærlighed eller lidt mere om dine forpligtelser over for Azerots borgere. Fortæl mig, hvem har du hjulpet, og hvordan.... Imponerende, <Name>, det er givet de handlinger, en der følger Lyset.\n\nSådant offer vil altid blive belønnet med tiden."},
  [1779] = {c="*hoste*\n\nGod dag til ya, <Class>. Tag ikke notits af mine sår, den gode præst her tager sig nok af gamle Muiredon i tide. Har ikke brug for den Livets Symbols kraft, du har dér, endnu.\n\nSå, min kone sendte ya over for at snakke med mig, hva'? Smuk nok. Jeg tager mig tid til at snakke med ya--jeg fortæller ya præcis, hvad der skete med Muiredon og hans bedste ven Narm, en paladin lige som dig selv."},
  [1783] = {c="Jeg kan ikke takke dig nok, broder.\n\nJeg kan kun antage, at Tisa og Muiredon sendte dig hertil for at hjælpe mig, hvis du bærer Livets Symbol.\n\nDet er sandt, jeg faldt for Mørkejernet, mens jeg forsøgte at opnå et af skrifterne: Jeg var i stand til at holde ud længe nok til at lade Muiredon flygte, men Let havde næsten omfavnet mig fuldt, da du kom. Det faktum, at du var mægtig nok til at bruge Symbolet, betyder store ting for dig, men der er tid til at tale om det senere."},
  [1784] = {c="Haha! Du har gjort det! Du reddede Narmund, og du fandt beviset, min kone skal tage med til rådet. Du er en velsignelse fra Let, hvis jeg nogensinde har set en... dog ikke medregnet min kone, naturligvis.\n\nTak igen, <Name>.", p="Er du tilbage! Jeg er glad for at se det, <Name>. Mine sår er helet, og jeg er næsten klar til at vende tilbage til Helms Seng-søen, så snart jeg kan overbevise min kone om, at jeg nok skal klare mig."},
  [1785] = {c="Du har gjort hele Jernsmede en stor tjeneste i dag, <Name>. Jeg er stolt over at regne dig blandt os, og hvis du føler, du er klar, vil jeg gerne velsigne dig med denne rulle. Livets Symbol ville kun have virket, når det blev brugt af en paladin, der var klar til en af Lysets største velsignelser - kraften til at genoprette de døde til livet.\n\nJeg vil lære dig evnen til at genoplive dine følgesvende. Brug den klogt, <Name>, og tak, på vegne af mig selv, min mand og Jernsmede."},
  [1787] = {c="Vidunderligt! Du klarede det og reddede Henze. Let er helt sikkert med dig, <Name>!", p="Er Henze i sikkerhed, <Name>? Var du succesfuld?\n\nMellem din færdighed med et våben og kraften fra Let, må jeg forestille mig, at Heltevagten er tryg for enhver Defias-trussel, men det er op til Konge og hans rådgivere at sige."},
  [1791] = {c="Du har rejst langt, unge kriger. Jeg ser ild i dine øjne. Du søger et våben af stor kraft, ikke?\n\nJeg kan hjælpe dig med din opgave. Og du kan hjælpe mig med min."},
  [1798] = {c="<Name>? Ah, selvfølgelig. Vores nyeste vidunderbarn. Den rigtige vare kan desværre ikke leve op til legenden.\n\nSkidt pyt, du er kommet her for at lære, ikke for at høre mig fjolle rundt med vitser for mig selv."},
  [1801] = {c="Kortlægning! Billeder, skøn over virkeligheden. Jeg har ingen brug for sådanne ting.\n\nI bøger, fortællinger, beskrivelser! Der ligger sandheden. Jeg ville bytte alle kortene i denne butik for én bog om nekromantiens opstigning, eller en fortælling om Den Mørke Damens triumf."},
  [1806] = {c="Værsgo, <Name>. Et våben, der er værdigt en Let-kæmper som dig selv. Jeg har navngivet det efter en stor dværgisk paladin, som var en ven af mig. Han hed Verigen... Bosk Verigen.\n\nTag det venligst på vegne af mig selv og min kone. Vi står i stor gæld til dig, og verden bliver et tryggere sted med en med din færdighed, der rejser rundt i landet."},
  [1823] = {c="Er du her til min prøve, <Name>?"},
  [1838] = {c="Du bragte alt, hvad jeg bad om. Nu vil jeg gøre min del...", p="Har du tingene på min rulle, <Name>?"},
  [1839] = {c="Hilsner, <Name>. Gamle Thun'grim sendte mig bud om din ankomst, men havde han holdt tæt, ville din tilstedeværelse her ikke have overrasket mig.\n\nÅndene følger dit fremskridt, unge <Class>, og de fortæller mig, at mange fjender er faldet for dig."},
  [1861] = {c="Tak, <Name>. Jeg vil teste dette vand for magiske egenskaber. Lad os håbe, at det ikke indeholder nogen, ellers kan vi opdage, at dem, der drikker fra Spejlsøen i for lang tid, bliver negativt påvirket.\n\nSå her, <Name>. Tag denne kugle eller stav som et mærke på din tjeneste. Må den tjene dig godt.", p="Har du prøven, <Name>? Magiens strøm i Stormvind og Elvendal er blevet ændret, og jeg må vide, om den siver ned i vandet."},
  [1880] = {c="Åh, herlig dag! Da jeg lavede Prylmonitoren, forestillede jeg mig aldrig, hvor afhængig af den jeg ville blive. Nu kan jeg begynde mine studier forfra!\n\nTak, <Name>! Og værsgo – det her var mine første værktøjer som magiker. De er lidt ridsede, men de er velafprøvede. Vælg den, du vil – jeg er sikker på, at du finder glæde i begge.", p="Har du fundet Prylmonitoren? Jeg skal have den, før dens energiforsyning løber tør!"},
  [1881] = {c="Hilsner, <Name>. Du var klog nok til at svare på mit kald, og endnu klogere, hvis du lytter til det, jeg siger nu..."},
  [1882] = {c="Ah, et fint eksemplar er dette. Jeg sender det til vores apotekere, så de kan fastslå, hvor vidt Pestlandets fordærv har bredt sig.\n\nVel gjort, <Name>. Som tak for dine tjenester tilbyder jeg dig dette valg: en kugle eller en stav. Uanset hvad du vælger, vil du finde den ganske nyttig.", p="Har du løvemundene? Den slags blomst er yderst modtagelig over for magisk energi, og hvis vi studerer løvemundene så tæt på Pestlandene, kan vi finde ud af, om pesten har sneget sig ind i Tirisfals Lysninger."},
  [1883] = {c="Hilsen, <Name>. Lov være dig, for mit opråb om hjælp er nu blevet besvaret. Lad os håbe, at du er vokset til opgaven..."},
  [1885] = {c="Hm. Uden tvivl har du fundet vej hertil i samme øjeblik, jeg nævnte min tilkaldelse, ikke? Naturligvis. Jeg ville ikke forvente mindre af en kommende Dødsstalker."},
  [1886] = {c="Godt klaret, <Name>. Du har bestået første del af prøven. Forhåbentlig har Andron ikke fået færten af dine aktiviteter, og så kan vi overbevise ham om, at du faktisk er den budbringer, han venter på.", p="Succes at rapportere?"},
  [1918] = {c="Du finder en ussel vandkugle og beslutter dig for at bringe den til mig? Hvem er jeg, Jordringen eller hvad?\n\nFaktisk giver det mig en idé... måske har du brug for Jordringen til dette. Altså, hvis det hjælper med at rydde op i situationen ved søen for altid, så er jeg helt for det.\n\nVed du, hvem Jordringen er, <Name>?", p="Jo, hvad har du brug for?"},
  [1919] = {c="<Name>, jeg har en opgave til dig, her i magikerkvarteret. Lyt nøje, for der er ingen tid at spilde."},
  [1920] = {c="Meget godt gjort! Jeg vil studere disse væsener og med flid og held finde ud af, hvordan de smuttede ind i vores verden.\n\nDin værdi for magikernes samfund vokser, <Name>.", p="Har du fanget væsnerne, <Name>? De skal studeres, for at man kan finde ud af årsagen til deres ankomst."},
  [1921] = {c="Ja, disse er glimrende stykker hør. Jeg kan lave en fin kåbe af dem. Og når jeg har vævet revneædelstenene ind i den, har vi et klædningsstykke som en magiker kan bruge!", p="Hej, <Name>. Jeneia fortalte mig, at du ville komme. Har du noget til mig?"},
  [1938] = {c="Jeg frygtede, at Morgant havde skjult bogen et andet sted, eller at han havde fundet en måde at åbne den på og læse dens indhold.\n\nDet er godt at se, at han ikke gjorde det, og at seglene, vi satte på Urs Afhandling om Skyggemagi, stadig holder.", p="Har du bogen, <Name>? Dens hemmeligheder er ikke beregnet til de uøvede, og at dykke ned i dens dyb kan føre til død og undergang."},
  [1939] = {c="Hilsner, <Name>. Jeg er glad for at se dig, og jeg håber, du har tid til at lytte til en gammel mands ord..."},
  [1940] = {c="Pæne eksemplarer, disse. Jeg går straks i gang!", p="Ah, ja. Magikerne i Troldmandens Helligdom sagde, at du ville tale med mig. Har du den krævede silke?"},
  [1944] = {c="Ah, meget godt. Jeg går ud fra, at satyrerne fra Xavian ikke voldte dig større besvær?\n\nTak, <Name>. Jeg vil straks studere denne Xavian-vandprøve.", p="Jeg er glad for, at du er vendt tilbage med huden intakt, <Name>. Har du vandprøven? Jeg er ivrig efter at studere dens egenskaber."},
  [1945] = {c="Ah, dette hår bliver til en fin kåbe, <Name>. Det er en medlidenhed, at de lattermilde søstre måtte dø for at skille sig af med det, selvom jeg tvivler på, at de nogensinde ville have givet det frivilligt.\n\nEn medlidenhed, men kun en lille en.", p="Hilsner, <Name>. Deinos sagde, at du ville komme og bringe de grinende søstres hår. Har du det?"},
  [1947] = {c="Stille! Jeg er midt i et kritisk punkt og må ikke forstyrres!\n\nEt øjeblik..."},
  [1948] = {c="Aha! Du fik jadestenen og lavede brombærranken! Godt gået!\n\nEr det røg, jeg ser stige op fra dine ører? Du er måske kommet for tæt på, da lynet ramte totemstængerne, men bekymr dig ikke. At blive ramt af lyn er held!", p="Hej, <Name>. Har du de ting, jeg har brug for?"},
  [1949] = {c="Hvad? Tal højere! Disse gamle ører er ikke så skarpe, som de har været.\n\nNå, jeg håber, du er her med en frisk krus øl eller nogle varme tips til næste race! Hvis ikke, så gå hellere videre... for jeg har en forvandlingstryllestav med dit navn på!"},
  [1951] = {c="Så er den der! Det er lige det, jeg skal bruge for at forberede ritualet til at fremstille din tryllestav! Jeg håber, det ikke var for meget besvær at finde...", p="Hilsner, <Name>. Fandt du bogen, Kræfternes Riter?"},
  [1960] = {c="Meget godt, <Name>. Skabningerne i disse indespærringskister vil blive studeret af vores fineste hjerner, og årsagen til deres tilstedeværelse i Undergrunden vil blive fastslået.\n\nHvis deres optræden skyldes en revne i magiens naturlige strøm, må vi afgøre, om revnen var tilfældig. Hvis den ikke var tilfældig, men i stedet et angreb fra en eller anden magisk kraft, må vi forberede os på fremtidige, mere alvorlige forstyrrelser.", p="Har du undersøgt forstyrrelsen, <Name>? Har du fanget væsnerne?"},
  [1961] = {c="Dette er meget godt materiale, og selvom jeg mangler talentet til at vurdere kvaliteten af disse mana-ædelstene, får vi snart at vide, om de besidder den kraft, der skal til for at skabe besværgelsesildskåber...", p="Anastasia sagde, at du ville komme til mig, og jeg er klar til at sy dine klæder. Har du ædelstenene og linnedet?"},
  [1998] = {c="Du har klaret dig godt, <Name>. Det falder mig ind, at du har udført mange tjenester for Dødsstalkerne og dermed bevist din værdi, og at det måske er på tide, at vi udvider din oplæring i skyggekunsterne.", p="Jeg har sat al min lid til dig i at udføre denne tjeneste for Herre Varimatras."},
  [2038] = {c="Du har gjort bevægelsen en stor tjeneste, <Name>. Trogerne og spedalske gnomer, der hærger Gnomregan, vil snart mærke et gnomisk luftangreb med fuld tyngde!", p="<Name>! Hvor er mine ting?!"},
  [2039] = {c="Så Gnåhrn stoler ikke på mine spejderevner? Jeg undrer mig over hvorfor...\n\nLad det ligge, jeg har brug for din hjælp! Nej! Bevægelsen har brug for din hjælp!"},
  [2040] = {c="Godt klaret, <Name>. Takket være dig er Gnomregan et skridt tættere på sin befrielsesdag!", p="Har du fundet Gnoam Sprækkekædehjul, <Name>?"},
  [2041] = {c="Bringer du besked fra centralkommandoen?"},
  [2078] = {c="Yarrr... Du beviser, at du er mere end en gul søhund, landkrabbe.\n\nKap'n kan befordre dig til bagdæks-dækskrubber, hvis du bliver ved sådan her...", p="Hvor er min førstestyrmand, <Name>? Lænker og hajer venter snart på dig, hvis du ikke skynder dig!"},
  [2098] = {c="Stå fast, din skørbugede havhund! Du gjorde det! Snart er min første styrmand tilbage i arbejdsdygtig stand, og bæstene aner ikke, hvad der ramte dem!\n\nHm, har du set min første styrmand?", p="Har I fundet min knækkede nøgle, landkrabbe?"},
  [2118] = {c="Vores arbejde er kun lige begyndt, <Name>. Er du klar til din næste opgave?", p="Har du bragt mig det syge dyr, <Name>?\n\nSkulle du undlade at udløse fælden, så fortvivl ikke - Tharnariuns Håb er evigt. Hvis du har brug for en ny fælde, så opgiv din opgave og rapportér tilbage til mig."},
  [2138] = {c="Du har gjort Auberdin en stor tjeneste, <Name>, men din opgave er endnu ikke fuldført.\n\nVend tilbage til mig, når du har hvilet dig.\n\n...og <Name>, gør dit sind og din sjæl klar til mere blodsudgydelse.", p="Er din opgave fuldført?"},
  [2158] = {c="Hvile og afslapning for de trætte og kolde -- det er vores motto! Sæt dig venligst ved bålet og hvil dine trætte knogler.\n\nVil du gerne prøve en smagsprøve af vores fine mad og drik?"},
  [2160] = {c="Ah, endelig, forsyningerne fra Hænder! Jeg var ved at blive bekymret, for vi har haft sparsomme nyheder fra Ambolmar, lige siden trogerne overrendte passet.\n\nTak, fordi du bringer det her til mig, <Name>. Og værsgo, gør dig hjemme. Du må være træt efter din rejse.", p="Hej der! Kom indenfor, tag plads ved ilden og varm dig med et krus øl."},
  [2161] = {c="Ah, det er maden, Ukor bragte til Prøvernes Dal. Havde de ikke brug for den? Nå, jeg gætter på, at de kan lide at sulte jer helte i træning. Det opbygger ånden, siger de!\n\nTak for at returnere maden. Jeg stiller den tilbage på hylderne... men lad mig først tilbyde dig lidt forfriskning!\n\nOg glem ikke at hvile dig her i kroen. Du er måske en modig <Class>, klar til at tage verden, men hvis din energi er udtømt, gør du hverken dig selv eller Horden megen gavn.", p="Velkommen til Barberbakken!"},
  [2206] = {c="Jeg er forbløffet... Forbløffet over, at Keryn endelig fandt en rekrut, der muligvis har det rigtige stof til at blive en ordentlig snigmorder. Tag dette sværd, <Name>. En dag vil du igen blive kaldt til at tjene SI:Syv. Slib dine færdigheder, hold øjnene åbne og klingen skarp.\n\nDu vil ikke se os komme, men du vil mærke det, når vi er der...", p="Din dødelighed svinder med hvert øjeblik, du spilder på at hænge rundt i kasernen, <Class>."},
  [2281] = {c="Ah, så dine fingre er lidt tykke, hva'? Bare rolig, <Name>, jeg har forvandlet flere ubrugelige tyvekoster end dig til dygtige skurke."},
  [2282] = {c="Revnet den op, gjorde du? Flot arbejde, <Name>.\n\nHvis du dør nu, kan vi hvile trygt i vished om, at det skyldtes din egen dumhed og ikke uerfarenhed.", p="Glemte jeg at nævne orkerne?\n\nJeg har hørt, at de har snuset rundt oppe ved møllen."},
  [2359] = {c="Det ville forklare de Defias-droner, du og Kjarnen så uden for tårnet, <Name>. Det ville også forklare Ventureselskabets involvering med Defias og de mærkelige forsendelser ud af Skumringsskoven.\n\nIfølge denne bog har Zanzel-trolde i Kvælerdorn fundet en måde at rejse de døde på med eliksirer... eller for at være mere præcis: gift.\n\nDu bliver ingen nytte for SI:Syv uden en fast forståelse af gift, <Name> -- især når opskriften på at skabe udødhed ligger lige for dine fingerspidser.", p="Nyt fra Agent Kjarnen?"},
  [2360] = {c="Mathias sendte endelig en anden agent for at bakke mig op, hva'? Nåja, jeg håber da, han er klar til at høre nogle dårlige nyheder."},
  [2381] = {c="Utrolig! Usandsynligt! Simpelthen forbløffende! Du har talent, <Name>. Enten det, eller også er du den heldigste mand i live!\n\nHer er din andel af udbyttet. Jeg er sikker på, at du ville gøre bedre brug af sagerne, end jeg kunne.", p="Nå, i det mindste har du stadig alle dine kropsdele. Fandt du skatten?"},
  [2382] = {c="Endnu en? De sidste fem, den skøre trold sendte mig, endte som hajmad. Lad os håbe, du klarer dig lidt bedre, hva'?"},
  [2418] = {c="Det er fantastisk, du fandt nogle! Mange tak, <Name>. Du er den mest pålidelige <Race>, jeg har mødt!\n\nJeg glæder mig til at prøve dem på nogle apparater, jeg har tinkeret med. Jeg vil vædde på, at apparater drevet af disse sten under de rette omstændigheder bliver ved og ved og ved...", p="Har du kraftstenene, <Name>? Jeg har en robotgnaver, der har brug for en strømforsyning..."},
  [2438] = {c="Min smaragdgrønne drømmefanger betyder meget for mig. Det er en gave, som kun få får. Tak, fordi du gav den tilbage, <Name>.", p="Skynd dig venligst. Jeg kan kun håbe, at min smaragd-drømmefanger ikke er blevet skadet af pelsbolgen.\n\nHar du fået den tilbage endnu, <Name>?"},
  [2458] = {c="Det er godt at se endnu en agent fra Den Splittede Hånd her i egnen, men signalraketten var måske lige i overkanten!\n\nNæste gang du skal tale med mig, så blæs to gange i denne fløjte, så ved jeg, at du er allieret."},
  [2478] = {c="Stakkels Fizzule, han var en god agent -- en af vores bedste. Ak, det er prisen vi betaler, <Name>. At være feltagent for Den Splittede Hånd er farligt arbejde.\n\nDu har udført din pligt godt, <Class>. Det ville være ærgerligt, hvis du ikke levede længe nok til at tjene os igen.", p="Hvad har du at rapportere, <Name>?"},
  [2498] = {c="Ah, så Rellian sendte dig for at bistå mig. Jeg er glad for, du er kommet hertil så hurtigt.\n\nJeg har opdaget noget ganske foruroligende!"},
  [2499] = {c="Jeg vidste, du var mere end i stand til at befri søen for det forfærdelige udyr.\n\nDet er en foruroligende situation; Egetrutz var engang en stor leder blandt sit folk... men korruption skelner ikke mellem de lave og de ædle.\n\nStørrelsen af denne tumor er ganske foruroligende, men jeg må studere den for at lære mere om smitten, der forstyrrer tømmerfolkets bestand.\n\nTak, <Name>.", p="Har du fundet Egetrutz endnu, <Race>?"},
  [2518] = {c="Skoven sørger over Lady Sathrah, men det var noget, der måtte gøres.\n\nTak, <Name>.", p="Jeg fortryder den opgave, jeg har bedt dig udføre; men Lady Sathrah er uden håb.\n\nVores håb er at ofre spindekirtlerne til Elunie. Med dette offer vil Elunie velsigne Sathrah, så hun kan blive genfødt og få fred."},
  [2520] = {c="Tabet af Lady Sathrah er foruroligende, men kun på denne måde kan hun genfødes med en fornyet ånd.\n\nMå Elunie villigt acceptere det offer, du har bragt hende.", p="Har du placeret offeret ved fontænen, <Name>?"},
  [2541] = {c="Tak, <Name>.\n\nHvilket underligt lille krimskrams dette er... Jeg kan fornemme den modbydelige glorie, der udstråler fra det; dette er en meget kraftfuld fortryllelse.", p="Hvis jeg kan undersøge fortryllelsen, kan jeg måske finde ud af, hvordan man bryder forbandelsen. Har du fundet en?"},
  [2561] = {c="Jeg er endelig fri for Knudefyrens kontrol. Tak, <Name>.\n\nMin ånd kan nu hvile fredfyldt for evigt i Den Smaragdgrønne Drøm.\n\nMåske mødes vi igen en dag, unge <Class>. Men foreløbig, modtag venligst denne belønning som et symbol på min taknemmelighed.", p="<Name>, vær forsigtig, når du nærmer dig min fysiske skikkelse; fortryllelsen den er under er ganske kraftfuld."},
  [2607] = {c="På tide! Bare læg osten på bordet og skrid. Osbjørn betaler dig på vej ud."},
  [2608] = {c="Giv mig et øjeblik til at rådføre mig med mine kolleger, <Name>. Dr. Montgomeri, Hr. Noarm, lad os holde konference!", p="Når du er klar til undersøgelsen, /læg dig ned på jorden, så begynder jeg på aderladningen."},
  [2609] = {c="Hvad laver jeg? Hvad ser det ud til, jeg laver? Jeg udtænker en kur mod din 'itis'! Bliv ikke fornærmet over mig nu, <Name>!\n\nBare et par sekunder mere. Der! Bare sprøjt denne, øh, fantastisk duftende medicin på dig, så er du som ny.", p="Hvis du vil have 'betændelsen' kureret, må du prøve hårdere end det, <Name>. Hvor er reagenserne til kuren?"},
  [2745] = {c="Hvad i alverden...?! Snig dig ikke sådan ind på mig! Og hold lidt lavere stemme! Hvad i Skyggens navn bruger du på at snige dig op på mig for? Kan du ikke se, at jeg er optaget, din åndssvage tølpe?\n\nHvad mener du med, hvad laver jeg? Jeg venter på, at den næste Mørke Portal åbner sig, hvad fanden tror du, jeg laver? Sig dit, og forsvind... inden vagterne opdager, at vi to gemmer os sammen i buskadset. Jeg har et ry at vedligeholde."},
  [2746] = {c="Disse duer udmærket, <Name>. Godt arbejde.\n\nJeg har resten af det udstyr, jeg skal bruge, i min taske... tak Let, at jeg lige fik en skrædderven til at sy mig en silketaske. Jeg var ved at løbe tør for plads, mens jeg bar rundt på alt mit udstyr.\n\nFør Spionbot tager ind, lad os få detaljerne på plads, så du ved, hvad du skal gøre.", p="Jeg har holdt øje med Lescovær i et par uger nu. Trøsen har aldrig stolet på ham, men vi mistænkte ikke, at han var involveret i noget med Defias-broderskabet. Vi fulgte spor, der knyttede ham til Tusmørkets Hammer. Uanset hvad er han blevet farligere, end denne by kan klare, og det er her, vi kommer ind i billedet.\n\nHent mig de ting, så kan vi sætte min plan i værk."},
  [2841] = {c="Jeg vidste, du kunne gøre det, <Name>! Søvik derimod, han tvivlede.\n\n<Nogg rydder halsen.>\n\nNu hvor vi har tegningerne i vores besiddelse, er det kun et spørgsmål om tid, før vi har regnet ud alle de gnomiske opfindelser, der gik ind i skabelsen af maskinen, og gjort dem til kobold-opfindelser til vores nye Hakkeren-modeller.", p="Jeg kan ikke se nogen blåtryk. Har du gemt dem et sted på din krop, eller står du bare her for at irritere mig?"},
  [2842] = {c="Hun er en skønhed, ikke? Tinden inden for kobold-transportteknologi -- er kun eksploderet et halvt snes gange.\n\nBekymr dig ikke, <Name>, jeg har fået hende helt i orden. Hun sprænger ikke i hovedet på dig - og hvis hun gør, går det hurtigt og smertefrit."},
  [2904] = {c="Jeg må vel sige, at du burde belønnes for at bringe Kernobi tilbage til os i ét stykke, <Name>. Hvis du tager tilbage til Gnomregan, kan disse måske give dig det forspring, du får brug for til at besejre den nytteløse bagstikker, Mekgineer Thermaplugg.", p="Hæ? Lever Kernobi??"},
  [2922] = {c="Åh, det her er vidunderligt! Tak, <Name>! Jeg går straks i gang!!\n\nStakkels, stakkels Teknobot... Vær ikke ked af det. Vi får dig fikset.\n\nNu, hvor lagde jeg lige proppen til min hydro-jack drejenøgle...", p="Har du fundet Teknobot? Fik du hentet dens Erindringskerne??"},
  [2923] = {c="Jo, det er sandt. Teknobot er gået hen og er blevet en snigmorder! Please, kan du hjælpe mig?"},
  [2924] = {c="Du fik dem! Nu kan jeg begynde mine nye eksperimenter!\n\nJeg kan ikke takke dig nok, <Name>! Din tapperhed har fremmet gnomisk forskning med et kæmpespring!", p="Har du de væsentlige kunstigheder?"},
  [2925] = {c="Jeg gør! Jeg har virkelig brug for hjælp til en mission ind i Gnomregan. Og du er netop den <Class>, der kan klare det!"},
  [2926] = {c="Fremragende arbejde! Nu er tiden kommet til at teste den nye formel. Hvis det virker, skal den fangne spedalske gnom ikke bare kureres, men jeg burde også have et fuldt hår på hovedet! Træd tilbage!", p="Kan du ikke se, at vi prøver at kurere en hel art gnomer her??! Vi har brug for mere af den grønne glød!"},
  [2927] = {c="Jeg troede helt sikkert, at tabet af det fremragende hovedhår ville blive enden for ham, men han overlevede!\n\nJeg stod lige ved siden af ham, da han blev ramt af strålelynet. De dejlige brune hårlokker røg ned på gulvet i klumper! Klynger! Rædslen ved det hele blev kun værre, da Gnåhrn fuldstændig gik i panik! Åh ja, gik i panik siger jeg! Gnåhrn rørte ved sit skaldede hoved i vantro, og blikket i hans øjne skreg hævn, <Name>! Så vendte han sin vrede mod troggerne!\n\n<Ozi krymper sig.>"},
  [2928] = {c="Det duer nok, <Name>. Én gyrodrillmatisk udgravningsmaskine repareret; 398 tilbage.", p="Hvis dette var et væddeløb, havde du tabt nu."},
  [2929] = {c="Jeg kan godt lide at tro, at det sidste, der gik gennem hans hoved, da han faldt til jorden, var din fod, <Race>. Med Thermaplugg død er vores planer om at generobre Gnomregan et skridt tættere på at blive til virkelighed.", p="Er opgaven fuldført? Bad han om eftergivenhed? Om nåde??"},
  [2930] = {c="Du klarede det! Du fandt det prismatiske slagkort og genvandt de forsvundne data! Vitalt, kritisk, umådeligt vigtige data, som vi ikke kunne leve et øjeblik længere uden!\n\nDin tjeneste for gnomerne vil blive husket længe, <Name>.", p="Har du det prismatiske slagkort??"},
  [2931] = {c="Jeg organiserer dataudvindingsmissioner ind i Gnomregan. Hvis du er her for det, så lyt godt efter!"},
  [2945] = {c="Du placerer ringen inde i Glimmatic 5200 og indsætter en sølvmønt i pladsen.\n\nSmertefulde knasende lyde stiger op fra maskinen, mens den begynder at rykke voldsomt rundt. Man kan kun gætte på, hvad der sker med ringen inde i maskinen...\n\nMaskinen stopper pludselig og udråber sin standsning med et simpelt \"Klang!\" Genstandsbeholderen åbner sig og afslører en lille æske, pænt indpakket med en rød bue. Det ser ud til, at Glimmatic 5200 også indpakker gaver!", p="Den gnomiske indretning foran dig har en plade, der kalder den \"Glimmatic 5200\". Ifølge instruktionerne under pladen er maskinens formål at skrubbe jord væk fra en genstand. Maskinen har en møntindkaster, der accepterer tre sølvmønter for at starte processen, når genstanden er lagt indeni.\n\nDet lader til, at den snavsede ring, du fandt tidligere, er lige det rigtige at prøve i denne maskine!"},
  [2948] = {c="Ah, præcis det, jeg havde brug for! En dag, når jeg kommer ud af dette hul, jeg uretmæssigt sidder i, vil jeg lave de fineste nipsting i hele Azerot til DIG, til ALLE! Indtil da, tak fordi du var sportslig omkring reagenserne. Normalt ville jeg tage ti gange så meget, som jeg har taget af dig, for en ring af denne kvalitet...\n\nApropos ringe, her er din nye!", p="Har du de materialer, jeg har brug for? Jeg ville ikke bede dig om dem, hvis jeg ikke var kørt så elendigt i held lige nu..."},
  [2950] = {c="Her er din ring, bedre end før. Tak igen for oplysningerne om de mørkejern-dværge. Det virker som en rimelig ledetråd til, hvordan de gnomer pludselig blev rammet af kobold-agtig inspiration.", p="Har du de materialer, jeg har brug for? Jeg kan ikke forbedre dette design uden alt det, jeg bad om."},
  [2962] = {c="<Ozi undersøger dig.> Imponerende, du har stadig alle dine lemmer. Nu er det tid til at se, hvad det her skidt kan!", p="Hm, du lyser ikke. Det er et godt tegn."},
  [2984] = {c="Hmmm, Narmund sendte dig til mig, gjorde han?\n\nNå, Narmund har altid været til at stole på, så det må betyde, at du er klar til at tage del i den næste sapta--Ildens sapta.\n\nJeg kan allerede se det i dine øjne, brændingen, begæret. Du har smagt kraft, og nu er du klar til mere af den. Tålmodighed, <Name>. Husk hvad jorden lærte dig. Kraft og ødelæggelse vil komme let, men du skal stadig vide, hvornår du skal holde hånden tilbage."},
  [2998] = {c="Det er smukt her i Stormvind, er det ikke?\n\nDit timing kunne faktisk ikke have været bedre, <Name>."},
  [2999] = {c="Godt mødt, <Name>. Jeg håber, Let viser dig den sande vej og beskytter dig mod det onde."},
  [3085] = {c="Som ya' tester dig selv, ska' ya' finde ud af, at ya' har bedre og bedre kontrol over de ånder--ya' vil kalde på dem fer størra og størra ting... dér kommer gamle Ken'jaj ind i billedet. Du kommer og snakker med gamle Ken'jaj, når du føler dig klar. Hvis ånderne er enige, så ser vi om at lære dig mere kraftfulde evner... men kun hvis ånderne er enige.\n\nGå nu, snak med resten af Dalens folk. Tal med mig igen senere.", p="Så ja kom'et... godt godt! Åndern' sagde til mig, at du snart nok kommer og ser Ken'jaj. Lad mig være en af de første til at byde dig velkommen til Prøvernes Dal. Her bliver du ikke boende længe, men så længe du er her, hvorfor ikke gøre det bedste ud af det, hva'?"},
  [3098] = {c="Du må vende tilbage til mig ofte, hvis du skal blive kraftfuld nok til at tilintetgøre dem, der ville modarbejde os. Magiens regler gælder stadig for dig, <Name>. Du vil stadig opdage, at korruption følger dig som sultne ulve om natten. Du vil opdage, at dens kærtegn ikke er ulig en afhængighed, en gammel elsker, der stadig vil være ved din side. Men disse ting kan holdes på afstand. De vil kun kontrollere dig, hvis du lader dem.\n\nGå nu, og vend tilbage til mig, når du er blevet mere mægtig.", p="Jeg vidste, du ville komme til mig, <Name>. Ikke fordi du mangler viljen til at følge din egen vej, men fordi vi er sjælsbeslægtede. Vi har begge følt smerte. Vi har begge lidt. Og nu vil vi have magten til at tage tilbage, hvad vi ved er vores: dette land, vores liv, vores skæbner. Men der er stadig meget, du må lære."},
  [3099] = {c="Jeg nævnte, at en slave stadig er en slave, uanset herren. Husker du? Vi ved begge, at det er den slags kontrol--den slags magt--der driver os nu. Vi stræber efter at få væsener til at tjene os. Vi ved, at vi er mere magtfulde og fortjener mere respekt, end andre giver os ... og derfor vil vi nu tage den.\n\nJeg vil være din allierede i denne kamp--kampen for vores egen frihed. Frihed til selv at vælge vores loyalitet. Når du føler dig klar, så kom tilbage til mig, så lærer jeg dig alt, hvad jeg ved.", p="Jeg byder dig velkommen, broder. Jeg vidste, du ville komme. Det var kun et spørgsmål om tid.\n\nDet, jeg sagde, interesserede dig, ikke? Jeg slog en akkord... noget inde i dig vidste, at det, jeg hævdede, var sandt. Godt.\n\nVed dog dette: Jeg er ingen forræder mod Silvanas. Hvis noget, ville hun sætte pris på mine påstande, al den stund det var hendes egne overbevisninger, der har sat De Forladte i den stilling, de befinder sig i nu."},
  [3101] = {c="I mellemtiden bør du vide et par andre ting. Du er et symbol for mange her i landet – handl derefter. Det Hellige Let skinner inden for dig, og det vil være tydeligt for både dine allierede og dine fjender.\n\nOg når du opnår visdom og kraft, må du træne for at lære nye evner. Der kommer jeg ind i billedet. Når du føler, at du har opnået lidt erfaring her i Nordshire, så kom tilbage til mig, og jeg vil lære dig det, jeg mener, du er klar til at lære. Held og lykke... <Class>!", p="Endelig! Vi møder hinanden ansigt til ansigt, bror til bror. Velkommen til Nordshire. Dette bliver dit hjem i en kort tid, mens du lærer finurlighederne og kneb ved hvordan tingene gøres, men vid at Stormvind ikke er langt væk, og før eller siden fører din vej dig dertil. Men indtil da, vær tålmodig... Ridder af Sølvhånden."},
  [3104] = {c="Haha, jeg vidste, at mit brev ikke ville afskrække dig fra din vej. Så du er altså forberedt, siger du? Forberedt på at acceptere din skæbne? Forberedt på at udfordre guderne og alle andre magter, der står i din vej i jagten på viden og magt?\n\nJeg vil ikke lyve, <Name>, du vil blive frygtet lige så meget, som du bliver respekteret. Men vid også dette: Jeg vil være her for dig, når du har brug for træning. Søg mig blot op, efterhånden som du bliver mægtigere.", p="Hej, <Name>. Jeg er Kheldén. Er der noget, jeg kan gøre for dig?"},
  [3105] = {c="Når du vokser i kraft, vil du blive fristet--du må altid huske at kontrollere dig selv. Jeg vil ikke lyve--korruption kan ramme enhver udøver af arkan; især en der handler med væsener fra Tvistende Nether. Vær tålmodig og klog... men lad det ikke kvæle din ambition.\n\nNår du bliver mere mægtig, så vend tilbage til mig, så lærer jeg dig mere om vores måder.", p="Ah, så du er kommet, og ikke et øjeblik for tidligt, <Name>. Nogle af vagterne var herovre for et øjeblik siden og kiggede nysgerrigt på mig... ynkelige almuer."},
  [3107] = {c="Menneskene har lært os meget om Hellig Let, og hvor vigtig deres orden er for dem... og for at beskytte hele Azerot. Vi har stor respekt for, hvordan den er gennemsyret af tradition, og hvordan blot én skikkelse, ét offer, kan gøre forskellen mellem smerte og frelse.\n\nVi to kommer til at arbejde sammen et stykke tid. Når du tror, du er klar, så kom tilbage til mig, så skal vi se at få dig noget træning. Vi kan jo ikke have, at du går ud i verden uforberedt, vel?", p="Så, du er kommet! Og ikke et sekund for tidligt. Der er meget at gøre i Kuldekam-dalen og videre ud. Jeg får brug for din hjælp lige så meget, som du får brug for min!\n\nDu er nu Ridder af Sølvhånden, så vær klar til at spille rollen."},
  [3113] = {c="Jeg holder mig for mig selv herude, så vi ikke får et dårligt ry for ting, der forsvinder, men hvis du har brug for noget, træning eller sådan noget, så kom bare tilbage når som helst.\n\nDu og jeg har en forståelse. Vi ved, at det hele kommer an på, at man kun kan stole på familie... og det er netop det, vi har her, ikke sandt? Uanset om Gnomregan er... overrendt, og uanset hvad andet der bliver kastet efter os, har vi hinanden til at bakke hinanden op. Ikke?", p="Godt at se at du fik mit notat og kom over. Undskyld at jeg lod som om det var et notat fra dine overordnede... ingen krænkelse ment. Jeg vidste bare at vi to, sammen med andre af vores slags, må holde sammen.\n\nIkke mange synes det er verdens bedste idé at have jeres og mit slags gemt sammen i samme by, men jeg tror vi nok skal få det til at fungere. Hvad siger du?"},
  [3116] = {c="Snart vil du se andre fra forskellige væddeløb i vores hjems grene--lad det ikke skabe fordomme i dig. De er velkomne. De vil hjælpe os, når de kan. Ikke alle af dem vil være uegennyttige, men de bør tildeles en vis mængde tillid.\n\nMen intet af dette betyder noget nu. Nu må vi fokusere på dig, og hvordan du kan hjælpe vores folk. Det er netop derfor, jeg er her. Jeg vil oplære dig i <Class>ens veje, efterhånden som du bliver stærkere. Vend tilbage til mig, når du vil, så gør jeg, hvad jeg kan for at hjælpe dig.", p="Du klarede det. Jeg er så glad.\n\nDer er sket meget i de seneste år, <Name>: skabelsen af Teldrasil, korruptionen af mange af skovens væsener her og ude i verden, opdagelsen af lande, vi troede var tabt for os, som Vildalas... så meget på så kort tid. Men det er blot nogle af grundene til, at vi er her, og den vigtigste er at beskytte vores folk mod yderligere ondskab."},
  [3261] = {c="Hilsner, unge. Er du her for at gå jægerens vej?\n\nGodt. Lad os begynde."},
  [3281] = {c="Aha! Så raptorerne gemte sølvet i deres hule. Det er svært at tro, at disse bæster skulle have begær efter sølv. Måske er historierne om deres intelligens ikke så langt fra målet, som jeg troede!\n\nTak, <Name>. Tag dette som belønning for din tjeneste mod os, og vid, at vagterne ved vejkrydset skylder dig næste måneds løn.", p="Har du sølvet?"},
  [3301] = {c="Ah, hvad er det her? Denne skal har en indre glød, som om den stadig pulserer af liv. Fantastisk! Jeg må studere den nærmere.\n\nTak, <Name>. Med held vil denne skal rumme en hemmelighed, jeg kan bruge til at hjælpe det fattige land Sølvfyr.", p="Jeg kan lugte Ødemarkens støv på dig, <Class>. Du har rejst langt."},
  [3361] = {c="Hurra, du har fundet dem! Du er en komplet redningsmand, min ven. Her, det er ikke meget, men det er noget for besværet, jeg har udsat dig for! Tak!", p="Åh, godhed <Name>, den her by er ikke særlig velegnet for folk som mig. Der er lige så mange ækle væsener her, som der var i Gnomregan før ulykken!\n\nHar du mine ejendele? Hvis ikke, så ved man jo ikke, hvad trolderne har gjort med dem nu..."},
  [3364] = {c="Ah godt, nu rammer det plet. Lad mig tage en lille pause, mens jeg nyder denne brandvarme morgenbryg!", p="Jo, jeg er Durnan Pelsskærer. Har du noget til mig?"},
  [3365] = {c="Fremragende, <Name>! Du ville blive overrasket over, hvor mange budbringere jeg møder, der glemmer at gøre noget så simpelt som at bringe krusen tilbage. Krus gror ikke på træerne, så vidt jeg har hørt!\n\nHer er en lille ting for indsatsen. Tak igen for din hjælp.", p="Jeg regner med, at den brændende morgenbryg nåede Durnan Pelsskærer til tiden! Huskede du at tage mit krus med tilbage til mig?"},
  [3369] = {c="Falla sendte dig til mig? Nå, lad os se på den skærv du siger hun var så tøvende med at tale om...\n\n<Hamuul kigger nærmere på skærven>\n\nÅh... Det havde jeg ikke... Nå.\n\n<Name>, tak fordi du leverede dette til mig. Det er dog ikke klogt at tale om sådan noget, råder jeg dig. Dette er sager du ikke skal bekymre dig om.\n\nLad os bare sige at tingene i Den Smaragdgrønne Drøm ikke er som vi troede...\n\nMåske krydser vores veje hinanden igen engang.", p="Må jeg hjælpe dig med noget?"},
  [3370] = {c="Falla sendte dig til mig? Nå, lad os se på den skærv du siger hun var så tøvende med at tale om...\n\n<Mathrengyl kigger nærmere på skærven>\n\nÅh... Det havde jeg ikke... Nå.\n\n<Name>, tak fordi du leverede dette til mig. Det er dog ikke klogt at tale om sådan noget, råder jeg dig. Dette er sager som kun Cenarion-druiderne skal tage sig af.\n\nLad os bare sige at tingene i Den Smaragdgrønne Drøm ikke er som vi troede...\n\nMåske krydser vores veje hinanden igen engang.", p="Må jeg hjælpe dig med noget?"},
  [3513] = {c="Nå nu... Hvor fandt du det her?", p="Hvad har du?"},
  [3514] = {c="Du er en hård nød! At rydde Rynthariels Hule er et stort skridt, <Name>. De vil være langsomme til at samle sig igen, så vi kan regne med færre Alliance-løbere i Ødemarken. De vil tænke sig om, før de sender endnu en herover.\n\nTak.", p="Vi kan ikke tillade Alliancen på vores land, <Name>. Gør det kendt."},
  [3524] = {c="Jeg håber, mudderfisken ikke gav dig for meget besvær med at samle dette ind til os! Jeg sørger for at få det afsted med den næste hippogryf til Darnassos. Månens Tempel har givet mig nogle midler at uddele som bistand; tag venligst lidt med, med vores tak.\n\nDin succes her opmuntrer mig til at tilbyde dig en chance for at hjælpe Månens Tempel yderligere, hvis du er interesseret...", p="Det er først for nylig, at disse skabninger begyndte at lande på kysten af Mørkekysten i så alarmerende antal. Jeg kan ikke lade være med at tro, at dette er et ondt varsel af en slags. At hente en prøve af den skabnings knogler mod syd ville hjælpe os i Darnassos med at vurdere situationen!"},
  [3643] = {c="Her er dit første Gnome-ingeniør-Medlemskort!\n\nDette kort har fået betalt sit kontingent på forskud for fjorten dage; alle kort udløber efter to ugers aktivitet. Når det sker, skal du betale dit næste kontingent til en hvilken som helst gnome-ingeniør-træner for at få et nyt kort; uden kortet bortfalder dit medlemskab midlertidigt, og du kan ikke få adgang til nye skemaer.\n\nDette påvirker aldrig det, du allerede kan; når først man er gnome-ingeniør, er man altid gnome-ingeniør.", p="Når jeg har modtaget dine fremstillede ingeniørgenstande til min vurdering, rækker jeg dig et ægte Gnome-ingeniør-medlemskort! Så længe kortet er gyldigt, har du ubegrænset adgang til enhver gnome-ingeniør-træner hvor som helst i verden."},
  [3741] = {c="Tak, fordi du fandt min halskæde, mister <Class>... du er meget venlig! Min killing takker dig også - ikke sandt Puffi?", p="Hej. Jeg savner min halskæde. Min far gav mig den. Far siger, at der er monstre i søen. Har du tævet nogen monstre?"},
  [3765] = {c="Ah, så min bror, Argos, sendte dig? Jeg forstår, du må være træt efter dine rejser. Men vi har meget at snakke om."},
  [3861] = {c="\"KLUK-KLUK!!!\"\n\nKyllingen begynder at sluge det foder, du har lagt ud.\n\nEfter et øjeblik kigger kyllingen sig forskrækket omkring. Den flytter sig ubekvemt frem og tilbage. Er denne kylling gravid? Du tænker, at du nok bedre må tjekke under den.", p="Kyllingen stirrer på dig med mørke, kolde øjne. Den venter sultent på dig.\n\n\"BOKAAAW!\n\nKluk...kluk...kluk.\""},
  [3901] = {c="Jeg er færdig med dig, <Name> - du har vist dig værdig til den frihed, du har fået. Mange vil stå imod dig for det, du er blevet, men vid, at uanset hvad de måtte forsøge imod os, er vi frie og vil ikke blive lænket igen.\n\nTag disse og gå din vej. Du har meget at udrette, <Class>.", p="De, der dovner med denne opgave, kan lige så godt ende med at vandre rundt uden mål som vores faldne brødre og søstre i landsbyen. Lad os håbe, du klarer dig bedre end dem, ikke?"},
  [3902] = {c="Stor gerning <Name>, jeg vidste, at du ikke var ubrugelig. Her - tag en af de bedre genstande, jeg har fundet blandt de partier, der er blevet samlet indtil nu.", p="Har du formået at skrabe nogle nyttige genstande sammen til os? Der er ingen skam i at genbruge det, der er blevet smidt til side. Ingen kommer til at give os nogen almisser - vi De Forladte må klare os selv!"},
  [3903] = {c="Åh, Stedfortræder Willem bad dig tale med mig? Han er en modig mand og altid villig til at hjælpe, men hans pligter holder ham fast ved Nordshire-klosteret, og jeg er bange for, at det problem, jeg har i dag, ligger langt over hans evner.\n\nKan du måske hjælpe mig?"},
  [3904] = {c="Åh, tak, <Name>! Du reddede min høst! Og jeg håber, du viste nogle af de Defias, at de ikke kan skabe ballade her omkring.\n\nVi har måske ikke mange vagter i disse dage, men vi er heldige at have helte som dig til at beskytte os!", p="Har du min høst, <Name>?"},
  [3905] = {c="Lad os se her...\n\nÅh du milde! Millys druer er blevet reddet! Da hun fortalte mig, at røvere havde overrendt hendes vingårde, var jeg nær ved at give op, men min tro på Let vaklede ikke!\n\nOg takket være din tapperhed har vi nu druer til mere vin! Må Let velsigne dig, <Name>, og holde dig i sikkerhed!", p="Du ser ud til at være i godt humør! Kom! Sæt dig, og tag en drik!"},
  [3921] = {c="Åh, hvad er det her? En samofleks, siger du? Hvad er en samofleks??\n\nAh... men se, hvordan den bevæger sig, når man håndterer den. Og der er lyden af indviklede tandhjul indeni. Åh, min! Jeg vil gerne reparere den og se, hvad den gør, gør du ikke??", p="Jeg har meget travlt med mit arbejde, <Class>. Medmindre du har noget til mig, er det bedst, at du bevæger dig videre..."},
  [3922] = {c="Stor, du fik dem! Nu kan jeg gå i gang...", p="Har du nuggetsneglene, <Name>? Jeg har kigget på denne Samoflange, og jeg kan ikke vente med at tinkre med den."},
  [3923] = {c="Hvad er det her? Nå, det er en samofleks! Hvor har du fået den fra? Har du rodet rundt i Ventureselskabets besiddelser i Ødemarken?\n\nDu må være meget modig, eller meget dum.", p="Pas på dit hoved! Jeg vil ikke have, at det kommer i vejen for mit arbejde!"},
  [3924] = {c="Du fik manualen! Jeg kan ikke vente med at læse den og finde ud af, hvordan jeg reparerer Samoflangen! Jeg talte med Sprutventil i Skralde--han ville takke dig for din hjælp og ville belønne din indsats.\n\nJeg vil også gerne takke dig, og hvis jeg nogensinde får denne tingest repareret, skal jeg nok give dig besked...", p="Har du manualen?"},
  [4021] = {c="Du har gjort det! Du har besejret Kolkarerne!\n\nJeg sørger for, at Trael får besked om dine gerninger her, <Name>.\n\nStå højt. Du gør dig selv og Horden stolte.", p="Har du banneret?"},
  [4181] = {c="Brønd <Name>, du var klog til at søge min undervisning! Enhver tølper kan blive ekspert i det grundlæggende ingeniørarbejde - gnomerne og deres bestrålede hjem Gnomregan er bevis nok på det. Det kræver dog et stærkt sind og en stødig hånd (understreget STØDIG) at mestre disciplinen Nisse-ingeniørarbejde.\n\nHold ørerne spidse, <Name>, så lærer du måske noget.", p="Jeg kan lugte friske rekrutter lige så godt, som jeg kan lugte et fremragende sprængpulver - på en mils afstand. Er du kommet for at lære om mestringen af eksplosionen?"},
  [4402] = {c="Vidunderligt, <Name>! Som lovet, her er din kaktusæble-overraskelse plus en lille ekstra ting.", p="Er du færdig med at samle kaktusæbler?"},
  [4495] = {c="Jeg er så glad for, at du fandt mig, <Name>. Hvordan vidste du, at jeg var her?"},
  [4542] = {c="Flere dårlige nyheder! Disse centaurer er gået for vidt! De plyndrede en af mine forsyningskaravaner og slagtede hele gruppen. Det er en skandale, og det vil ikke forblive ustraffet!", p="Hvad vil du, <Class>? Et hastebrev – til mig?"},
  [4581] = {c="Ah, Shindrells rapport! Mange tak, <Name>. Shindrell er en fin vagtpost, modig og skarp. Jeg må læse den for spor til en ondskab, som jeg frygter bevæger sig gennem Askedalen.", p="Har du noget til mig?"},
  [4641] = {c="Endnu en af Kaldtonks rekrutter, hm?\n\nEn ynkelig tilstand vi befinder os i, hvis dette er det bedste Horden kan frembringe. Det gør ikke noget. Når vi synes, du er klar til at forlade Dalen, vil du være en stolt kriger i Horden."},
  [4681] = {c="Du har været en enorm hjælp her i dag; vi har nu en solid chance for at løse mysteriet om, hvorfor disse væsener vælger at strande sig selv på Mørkekystens kyst. Tanken om, at de måske flygter fra området omkring Teldrasil, er foruroligende. Hvis du støder på andre under dine rejser, så lad mig venligst vide det. Vores forskning her står kun i sin spæde begyndelse.\n\nPå vegne af Månens Tempel, vær venlig at modtage dette som tak for den indsats, du har ydet. Tak, <Name>!", p="Når du har undersøgt skabningens rester i vandet vest for her, burde jeg kunne indgive en ordentlig rapport til Månens Tempel i Darnassos. Måske er vi så tættere på at finde ud af, hvorfor disse uheldige væsener vælger at ende deres liv strandet ved Mørkekysten."},
  [4740] = {c="Nå, det ser ud til, at du er kommet for at gøre mere end blot at forhøre dig! Borgerne vil blive glade for at vide, at de i nat vil sove lidt bedre og tryggere.\n\nDu har i dag fungeret som retfærdighedens bøddel for Auberdin-folket, <Name>. Derfor vil jeg gerne tilbyde dig dette som en passende belønning... for en sand helt fra Auberdin-folket.", p="Hilsner <Class> - hvad kan Vagterne assistere dig med i dag? Måske er du kommet for at høre om dusøren på Mudderdyb?"},
  [4761] = {c="Godt mødt, <Class>. Din spejdning af pelsbolg-situationen kommer på et heldigt tidspunkt for os i Auberdin. I nogen tid har vi haft at gøre med ikke blot skovboere, som nu åbent er fjendtlige over for vores tilstedeværelse, men også med den rene ud sagt korruption af selve skoven. Forhåbentlig kan du yde Auberdin bistand i disse urolige tider."},
  [4762] = {c="Det er ingen overraskelse, hvor forurenet dette vand er, men se bare, hvor modbydeligt det bliver! Det lader til, at handling er nødvendig før end senere, hva' <Name>?\n\nMod øst ligger Ondskoven; den er den egentlige kilde til denne korruption, en som jeg har set før i tidligere tider. Jeg forudser, at denne prøve vil bekræfte det. Vi kan måske fremstille en kur mod den her, men for overhovedet at forsøge må vi have hjælp. Når den tid kommer, <Name>, håber jeg, du kan give den bistand, vi har brug for.", p="Forureningen af Klippefjeder-floden er blot begyndelsen på en alarmerende tendens her i Mørkekysten. Prøven, du leverer, vil hjælpe os med at formalisere en plan... en angrebsplan, begynder jeg at mistænke."},
  [4763] = {c="Vi har lige begyndt denne krig for at genvinde vores skov fra korruptionens styrker, men et slag er vundet i dag! <Name>, Auberdin-folket står i taknemmelighedsgæld til dig, en gæld der aldrig nemt bliver tilbagebetalt. Modtag venligst dette sammen med vores tak. Det vi har lært her i dag kan en dag befri vores pelsbolg-venner fra pinens lænker permanent.", p="Fordærvelsens Talisman er et ondskabsfuldt apparat, der kun tjener til at forvrænge naturens balance. Når du får fat i denne genstand fra den satyr, der plager pelsbjørnene, og bringer den til mig for at blive bortskaffet, har vi vundet en stor sejr i dag!"},
  [4767] = {c="Perfekt! Med disse æg håber jeg at tage næste skridt mod at blive vindrytter. Her er et mærke på min påskønnelse; må god jagt altid skinne på dig, <Class>.", p="<Name>, har du hentet de vyvern-æg, jeg leder efter? Jeg er virkelig ivrig efter at begynde min vindrytter-træning!"},
  [4811] = {c="Så krystallen findes, <Name>? Fascinerende... i hvert fald er din opgave udført godt; godt arbejde!\n\nHvad er denne krystal egentlig? Det er blot ét spørgsmål i et hav af spørgsmål. Et andet spørgsmål, der melder sig, er hvorfor månekinen mon blev tiltrukket af dette objekt? Er krystallen godmodig af natur, eller gemmer den på et mere ondskabsfuldt formål?\n\nJeg har mange flere spørgsmål, men vi bliver nødt til at undersøge den krystal nøje for at få nogle svar.", p="Hvad har du at rapportere om den røde krystal? Findes den overhovedet?"},
  [4812] = {c="Du er kommet tilbage til den mystiske krystal. Du fjerner proppen fra røret med månebrøndvand og hælder forsigtigt indholdet ud over toppen af krystallen. Mens vandet vælter ned ad dens gitterværk, ser du den uigennemsigtige overflade blive gennemsigtig...", p="Krystallen ser meget fremmedartet ud mod det skovklædte landskab i Mørkekysten. Du tror, du kan høre en meget svag summen komme fra dybt inde i den."},
  [4821] = {c="Ja, endelig... det mystiske æg er endelig blevet leveret til mig. Nu, lad mig se nærmere på det her... Hvad..! Hvad er det her..?", p="Jeg må vide mere om dette mystiske æg, for hvem ved, hvad der vil klække ud af det."},
  [4841] = {c="Som tak er dette til dig, <Name>.", p="Kom nu, <Name>, jeg ved, at du endnu ikke har dræbt din andel. Jag dem, og jeg skal give dig en belønning for min taknemmelighed."},
  [4865] = {c="Hævn! Så er legenden om Arikarra sand. Det er faktisk et problem, der må løses med det samme."},
  [4881] = {c="De kommer for at dræbe mig? Jeg skal vise dem, hvordan en Taurer kæmper!"},
  [4921] = {c="Jeg forstår. Tak, <Class>.", p="Har du fundet det mindste tegn på hende? Smerten i mit bryst fortæller mig, at det værste er sket, men jeg har håb om, at du finder hende rask og rørig."},
  [4966] = {c="Tak for din hjælp, <Name>. Jeg kunne ikke have holdt stand mod dem uden dig."},
  [5041] = {c="Haha! Tak, <Name>! Dette vil hjælpe os meget. Du er en velsignelse for Korsvejen og for Horden. Hvis der er noget, jeg kan gøre for dig, så lad mig vide det.", p="Hvordan går din søgen efter forsyningerne, <Name>? Jeg regner med, at Tornesvinene falder for din styrke uden videre."},
  [5042] = {c="Hvis bare Kløvtand var fri til at se dig decimere dem, der forrådte ham! <snøfter>\n\nJeg takker dig for at have ødelagt flere af Børsterygge ved at samle disse fragmenter. Værsgo, fortsæt med det, så fortsætter jeg med at hjælpe dig. <snøfter>", p="Jeg skal bruge 4 blodfragmenter, hvis du ønsker Agamaggans styrke, <Race>.\n\nDine fjender vil krympe sig for din styrke, hvis du får denne velsignelse. <snøfter>\n\nBarbermankens største krigere er gennemsyret af sådan en kraft!"},
  [5043] = {c="Må dit sigte være ufejlbarligt, og dit våbens mærke være sandt, <Race>.\n\nAgamagg'ans ånd er med dig. Kom <snøfte> tilbage til mig, hvis du har lyst. Kløvtand vil velsigne dig igen, hvis den store vildsvinegud finder mig værdig. <snøfte>", p="Min stammes største spejdere siges at være uovertrufne i deres præcision, og ingen snigmorder <snøfter> kunne måle sig med deres hurtighed i slag.\n\nBring mig 4 blodfragmenter, så gør jeg dig endnu smidigere end nogen Tornesvin nogensinde har været."},
  [5044] = {c="Dine fjender burde frygte dig endnu mere, <Race>. <snøfter>\n\nFortæl Kløvtand om dine snedige kneb i slaget, næste gang vi mødes - hvad enten i dette liv eller det næste. <snøfter>", p="Sjamanerne og geomantikerne i tornesvin-stammerne <snøfter> kalder på Agamagg'ans styrke for at hjælpe dem i kamp og i deres ritualer, <Race>.\n\nHvis du også ønsker den ekstra kraft fra Agamaggans velsignelse til dine besværgelser, så bring mig 4 blodfragmenter, så vil Kløvtand hjælpe dig. <snøfter>"},
  [5045] = {c="Vores største krigere og vores største <snøfter>-shamaner ville misunde din vilje, <Race>.\n\nBesejr flere af Børsterygerne, vidende at de ikke kan stoppe dig! <snøfter>", p="Krigere af alle slags <snøfte> har brug for en stærk ånd. Den driver dig til større bedrifter, når alt håb er ude. Det er ikke ukendt for <snøfte> Barbermanke. Vi er et åndeligt stamme-folk--vi er stoltere af vores forbindelse til Agamagg'an end af vores kampdygtighed <snøfte> i slag.\n\nBring mig 4 blodfragmenter, så velsigner jeg din ånd til slaget. <snøfte>"},
  [5046] = {c="Gå i krig, <Race>.", p="Alle dem der <snøfter> går i kamp har brug for beskyttelse. Deres knogler skal være stærke. Deres hud sej. <snøfter> Min stamme ved det også, og for at supplere den naturlige beskyttelse vores pigge og hud giver os, <snøfter> kalder vi ofte på Agamagg'an for at beskytte os mod skade, før vi drager i krig.\n\nBring mig 4 blodfragmenter <snøfter> så giver jeg dig den samme beskyttelse."},
  [5052] = {c="Ah, du forstår. <snøfter> Mine ord gik ikke tabt på dine ører, <Race>. Kløvtand kan være i bur, men intet bur kan stoppe Agamaggans kraft! <snøfter>\n\nBerøringen af skårven, følelsen af den... det er længe siden, <Race>.\n\nVed du, hvordan det er? At få din kraft skåret fra dig?\n\nMen det er en historie til en anden gang. Jeg lovede dig oplysninger. Jeg lovede dig Agamaggans kraft. Mit folk vendte ryggen til Kløvtand. Nu slipper jeg dig løs på dem. <snøfter>", p="Vores stammer tilstrømmer til de tornede områder over hele Ødemarken <snøfter>, fordi de er hellige steder, men ingen er så hellige som Barbermose. Agamagg'ans krop udgør hele Barbermosen, <snøfter>, men Slettene er særligt beskyttede, fordi indgangen er dannet af hans store gab! <snøfter> Den vil sluge dem hele, som ikke er loyale over for ham, og spytte deres kroppe ud, når han har tygget dem igennem! <snøfter>\n\nAgamagg'an har efterladt sin krop for at beskytte os, og han giver af sin ånd, så vi kan beskytte ham. <snøfter>"},
  [5062] = {c="God, du har samlet den nødvendige mængde Incendia-agave. Denne sjældne urt, som kun findes i Tusindnåle, vil hjælpe med at antænde det hvilende, hellige livsaffyr.\n\n<Magata begynder at fortrylle Incendia-agaven.>", p="Så, Motega Ildmanke sender bud om Arikarra... nå, det er jo alvorlige nyheder.\n\n<Magata kigger sig omkring.>\n\nArikarra er et dødbringende væsen, født udelukkende for at søge hævn over dem, der har begået afskyelige gerninger.\n\n<Magata smiler.>"},
  [5064] = {c="Den Store Ånd-totem! Dette er virkelig dystre nyheder. Jeg må begynde at planlægge for, hvad der end måtte komme.\n\n<Name>, som lovet, her er din belønning for din modige tjeneste.", p="Har du opdaget, hvad Grumtotemerne har gang i?"},
  [5088] = {c="Det giver ingen mening. Hvorfor skulle Arikarra være ude efter Kærne Blodhov? Magata kan ikke tage fejl, hun er vores mægtigste shaman.\n\n<Motega rister på hovedet.>\n\nUanset hvad, skal din store bedrift for Horden ikke gå ubemærket hen - vær venlig at vælge en af disse som belønning for din hjælp.", p="Har du slået den onde slange Arikarra ihjel, <Name>?"},
  [5147] = {c="Hah! Nå, det er glimrende nyheder! Jeg begyndte at tro, at han aldrig ville blive stillet for retfærdighed!\n\nVær så god, <Name>... og tak. Nyheden om Arnaks ondskabsfulde gerninger kogte mit blod!", p="Har du nogen nyt om den morderiske Arnak Gribetotem?"},
  [5151] = {c="Min hyperkapacitor! Den vil holde mig beskæftiget et stykke tid, indtil jeg finder ud af, hvad den gør...", p="Har du min hyperkondensator?"},
  [5261] = {c="Det er rigtigt. Jeg leder efter nogen, der kan jage nogle ulve til mig! Er du den person?"},
  [5441] = {c="God, god. Måske tænker de sig om to gange, før de slapper af næste gang! Tak for hjælpen!", p="Ingen god dorsk...\n\nHva'? Har du min kølle? Fangede du nogen arbejdere, der sov på jobbet?!"},
  [5481] = {c="Hvad er det her? Mørkeukrudt?! Jeg har ikke brug for mørkeukrudt! Den hjernedøde kødmasse derude plukker tusindfryd og overtaler Dame-ved-hvor-mange fjolser som dig til at gøre det samme. Ingen fornærmelse.\n\nNå, du er her nu, og det er det eneste, der tæller. Da jeg ikke gider forsøge at forklare tingene til det afskyelige væsen, hvad med at du samler det, jeg virkelig har brug for... dødsurt!", p="Hvor er det ubrugelige væsen? Enten har du det, jeg har brug for, eller også må du hellere af sted og finde det."},
  [5482] = {c="Ah, min dødsurt. Fortræffeligt!\n\n<Juniorapoteker Holland gnider grådigt sine hænder sammen.>\n\nDisse kommer til at være ganske nyttige. Du har gjort mig, øh, Damen, en fin tjeneste i dag, <Name>. Som lovet her er den belønning, du har fortjent.", p="Det må være godt. Jeg regner med, at du har al den dødsurt, jeg har brug for?"},
  [5541] = {c="Stor, mere ammunition! Gamle Loslors forsendelse kom endelig igennem! Ammunitionen er måske sent fremme, men ligesom min farfar plejede at sige til mig: sent er bedre end aldrig!\n\nTak meget, <Name>. Jeg har allerede købere, der er ivrige efter det her!", p="Jeg håber, du ikke er her efter ammunition, for jeg er næsten løbet tør!"},
  [5545] = {c="Fremragende! Takket være dig burde jeg kunne nå at fuldføre ordren i tide. For at vise min taknemmelighed vil jeg gerne tilbyde lidt mønter som kompensation for dine besvær.\n\nTak, og farvel.", p="Den frist bliver ikke længere væk, <Class>. Skynd dig venligst at samle de bundter træ."},
  [5623] = {c="Jeg er glad for, at du er ankommet, <Name>. Vi har meget at drøfte om din fremtid og din vej inden for Let."},
  [5625] = {c="Fremragende, <Name> Med endnu en sund vagt derude til at hjælpe byen, bliver vi så meget mere trygge. Jeg er glad for at se, at du allerede lærer at bruge dine evner klogt. Hvis du på et hvilket som helst tidspunkt føler dig klar til mere træning, så kom venligst tilbage til mig. Men for nu, tag denne kåbe. Den lader andre vide, at du er en af vores orden. Hvis du ikke ønsker at bære den, er det fint. Senere vil der være flere prøver, og til dem er denne kåbe ikke nødvendig.", p="Har du fundet Dulf endnu, <Name>?\n\nDet har du nok allerede lært, men vores evne til at hele er meget nyttig. Vi kan ikke blot tage os af de sårede, vi er også afgørende for overlevelsen af alle de vordende helte derude, der prøver at gøre sig et navn. Med Sejhed til at øge antallet af slag vi kan tåle, og vores helende magi til at holde dem i live, er der intet, vi ikke kan overvinde!"},
  [5626] = {c="Åh, så Brandstok sendte dig, gjorde han? Godt, godt! Han har ret, det er på tide, du tager et meget større skridt ind i Let. Det vil opbygge karakter og gøre dig stærkere... og det er det, du får mest brug for: styrke i kroppen... styrke i viljen."},
  [5646] = {c="God, du er vendt tilbage, og ikke et øjeblik for sent. Vi har store ting at drøfte, <Name>. Dine evner bliver stærkere, og vi må sikre, at du er klar."},
  [5648] = {c="God, så lever Kor'ja og drager af sted for at forsvare vores by mod de ondsindede mennesker. Jeg ønsker ofte at huske kampens dage, hvor kraft blev vist i kamp, og det var de kloge, der ofte ødelagde dem, som kun stolede på ren styrke.\n\nDu har forvoldt godt over for mig, <Name>. Tag nu denne kåbe. Måske hjælper den, måske er du ligeglad, men du har fortjent den, og jeg er stolt over at kalde dig bror.", p="De fleste synes det er logisk, at helbredende magi er kraftfuld, men ikke mange forstår, hvor kraftfuld. Du kan holde mange i live, når de i stedet burde være ude at møde deres egne forfædre. Denne helbredende magi, blandet med evnen Sejhed, er en meget kraftfuld besværgelseskombination. Husk det. Det gavner alle slags folk: krigere, magikere og alt derimellem."},
  [5649] = {c="Ahh... så du kommer endelig til Tajjin. Det her er godt.\n\nDu ved allerede, at vi ikke er de samme stamme, der engang sluttede sig til Horden. Vi er meget stærkere nu. Vi er stærkere, 'for vi tilpasser os--Horden lærte os det. Vi besejrer ikke længere vores fjender og får styrke af dem; nu får vi styrke, og så besejrer vi vores fjender.\n\nForskellen er subtil, men du lærer den. Du vil se. Stammen regner med, at du lærer sådan noget."},
  [5654] = {c="Du gør klogt i at lytte til denne lektion, unge. Forbandelse af Svaghed vil blive en stor velsignelse for dig i kamp. Senere har jeg prøver til dig, så du kan forbedre dig selv og bevise din værdi for stammen."},
  [5673] = {c="Må Elunie velsigne dig, fordi du vendte så hurtigt tilbage til os. Dette er en vigtig tid i din træning, og en tid, som hele vores orden tager meget alvorligt. Når du har hvilet dig efter rejsen hertil, så lad mig venligst vide det. Så kan vi drøfte fortsættelsen af din træning og hvor din vej fører dig hen næste gang."},
  [5722] = {c="Liget ser alvorligt tævet ud af køller eller næver, men det meste af ligets tøj og udstyr ser stadig til stede ud. Det lader til, at trogerne ikke synderligt hælder til materiel rigdom.\n\nDu begynder at lede liget igennem for noget af interesse, der måske kan hjælpe Magata."},
  [5723] = {c="Jeg er glad for at se, at du tog Magatas opgave alvorligt. Tak, <Name>. Jeg er sikker på, at troggerne får sværere ved at komme op til overfladen nu, hvor deres tal er så kraftigt reduceret.\n\nMåske kan vi i fremtiden tage os tid til at finde ud af, hvor sådanne væsener kom fra, og hvad de egentlig vil.", p="Hvordan går din eftersøgning efter Kløften? Og troggerne?\n\nTrusslen kan ikke tillades at vedblive - den skader kun vore ork-brødre, hvis den fortsætter."},
  [5724] = {c="Fremragende, <Name>. Tak.\n\nMagata fortalte mig, at hvis du lykkedes med at finde hendes klanmand, skulle du have denne. Tag den venligst som tak.", p="Fandt du noget, <Name>? Ledetråde om, hvorfor en af hendes klanfæller måtte dø unødigt, ville være til hjælp."},
  [5725] = {c="God, <Class>. Du har forvoldt brønd i tjenesten for Den Mørke Dame. Din fortsatte udholdenhed og ambition vil være til stor nytte for Damens undersåtter. Kom tilbage til mig igen i fremtiden. Måske har jeg andre opgaver til dig, som kan hjælpe Den Mørke Dame i hendes forsøg på at overtage Liskekongen og fuldstændig befri Svøben.", p="Der venter hundrede andre opgaver på min opmærksomhed, <Class>. Har du bøgerne?"},
  [5726] = {c="God, <Name>! Ånderne være lovpriset, måske er du den, der endelig vil lægge mine største frygt til hvile! Hvem skulle tro, at nogen så ung og så modig ville rejse sig og forsvare vores sag? Du minder mig om mig selv, dengang jeg var yngre. Jeg vil sørge for, at du bliver retfærdigt belønnet for din indsats, hvis vi begge overlever den kommende storm.\n\nMen der er tid til mere ros senere. Du har ikke udrettet noget i sammenligning med det, du kommer til at stå over for... men dette er en god start.", p="Har du insignien endnu, <Name>?\n\nDen vil være et vitalt værktøj til at infiltrere det, jeg tror er den største trussel mod Horden, og endelig finde fred i vores nye hjem.\n\nDu vil lære, hvor indviklet et spind mænd og orker lige fra hinanden kan væve, når de er drevet af griskhed og magt. De skjulte dagsordener, korruptionen, alt sammen vil træde frem i klart lys. Du vil finde dig selv midt i en krig, du aldrig vidste eksisterede."},
  [5727] = {c="Fremragende! Yderst fremragende, <Class>!\n\nDet, du har gjort i dag, er kun første skridt i et meget bredere fundament--et fundament, som vi skal bygge tilintetgørelsen af Skyggerådet på, én gang for alle.\n\nFortæl mig alt, hvad han sagde... og udelad ikke ét eneste ord--det kan være vigtigere, end du tror.", p="Nå, <Class>? Tror han på vores list, eller står det værre til, end jeg først regnede med?\n\nAt vise sig værdifuld for Neeru vil gøre vores infiltration af Skyggerådet meget lettere. Han vil have masser af information, som vi kan bruge til at rydde ud i dem, der ville ødelægge alt, hvad vi har bygget i Durdotar."},
  [5728] = {c="Jeg er glad for, at du er vendt tilbage, <Name>. Nogle af dem, der var loyale over for mig, bragte straks besked om, at hulerne under Orgrimgrad var i uorden, nu hvor deres ledere er slået ihjel. Jeg hørte endda rygter om, at Neeru var mere end ophidset. Det lader til, at vi har sat en bule i hans rustning. Jeg kan ikke sige, at jeg er utilfreds... selv med en så mindre sejr.", p="Har du fundet dem endnu, <Name>? Lederne af den Svidende Klinge.\n\nJeg vidste, at Skyggerådet ville tage Orgrimgrad og hele Horden fra mig, men jeg havde ikke indset, hvor hurtigt de kunne snige sig ind i byen. Så mange arme har dette udyr... vi kan skære dem af, indtil udmattelsen sætter ind, men vi kommer ikke længere, end da vi startede. Jeg må få mine spioner til at fordoble deres indsats."},
  [5729] = {c="Hvad er det?! Åh, dig, <Class>... min undskyldning. Min vrede kan måle sig med en rablende kodo-okse... men måske er det min egen skyld. Når jeg sendte rejsende ind i Vredesild-kløften, burde jeg have set muligheden for, at det kunne gå ud over dem. Det ser ud til, at både Bazzelan og Jergosh blev overrumplet og slået ihjel af nogle af Traels godhedsfjolser. Et yderst uheldigt tidspunkt, men der er ikke noget at gøre ved det nu."},
  [5730] = {c="Askedalen? Hmm, jeg har ikke hørt om nogen tilstedeværelse af Rådet eller Brændende Klinge i Askedalen. Mine spioner vil undersøge sagen, <Name>. Du har klaret dig godt.\n\nHvil dig nu, og hold dig beskæftiget med andre opgaver. Jeg kalder snart på dig igen.\n\nLokk-Tar Ogar!"},
  [5741] = {c="Det undvigende Scepter af Let! Din erhvervelse af det har fjernet en alvorlig trussel mod verden. Godt gået, <Class>, godt gået.", p="Har du Scepteret af Let?"},
  [5761] = {c="Ha! Du har gjort det! Trael bliver så glad.\n\nJeg vil sørge for, at dette hjerte bliver behandlet ordentligt.\n\nNu skal du dog fejre din sejr. Jeg vil underrette Trael om din succes.\n\nTak for din hjælp, <Class>.", p="Har du dræbt udyret? Han må da være lederen af den Svidende Klinge i Vredesild-kløften."},
  [5762] = {c="Stor, min pakke fra Koalskæg! Tak, <Name>. Denne kasse indeholder ammunition i speciel kaliber, og den vil gøre os gode tjenester ude i junglen!\n\nHer er din betaling, og fortæl mig, hvordan går det den skorpede gamle Kravel i disse dage? Stadig ude på ondskab, vil jeg vædde på...", p="Er det ørkenstøv på din krave?\n\nHm... hvis min næse fortæller sandt, så er det ikke ørkenstøv, det er ørkensalt! Har du været på Glimmerflatene, siger du?"},
  [5763] = {c="Ah, dette horn tilhører en Taurer, Roon Vildmanke. Han og jeg havde det godt sammen, da vi jagede bæsterne i Forødelse. Så Roon inviterer mig tilbage, gør han?\n\nVi står lige nu til halsen i junglen, men tak, <Name>. Måske fører min næste ekspedition mig tilbage til Forødelse, kentaurernes land.", p="Sid, <Class>. Snart nok slår du tilbage ind i junglen."},
  [5881] = {c="Det er gode nyheder; jeg har siddet her og vogtet dette træstykke alt for længe. Nu kan jeg bruge lidt tid sammen med min familie... Jubiii!", p="Har du nyt fra Mavgran Jordbinder?"},
  [6027] = {c="Den længe savnede De Ældgamles Bog! Jeg vil sikre, at bogen bliver overgivet til højrådet. Du har gjort det godt i dag, og for det skal du takkes... som en helt bør takkes!", p="Ah, <Name>! Det er godt at se dig igen. Har du De Ældgamles Bog med?"},
  [6121] = {c="Hilsner unge druide, jeg er glad for at se dig klar og ivrig efter at lære om kurering af gift.\n\nMens de fleste druider i fortiden blev sendt igennem forudplanlagte prøver, vil dit arbejde ikke involvere noget sådant. Der har været en bølge af dyreforgiftninger i Auberdin, og landsbyen dernede har ikke kunnet kurere det. Til den ende har en repræsentant dernede bedt Månelunden om bistand, og vi sender dig derned for at assistere dem. Dette er ingen øvelse - det arbejde, du skal udføre, er ganske virkeligt. Husk det."},
  [6122] = {c="Ved Elunie, dette vand er ækelt! Intet under, at hjortene er syge.\n\nNoget forurener vandet og ødelægger i sin tur hele Mørkekystens grundvandsspejl. Syge hjorte er set over hele området, og ikke bare ved floden. Selvom dette vand højst sandsynligt er en primær kilde til sygdommens spredning, er der også noget andet på spil her.\n\nDette vand, tro det eller ej, vil hjælpe os med at formulere en kur. Mens jeg undersøger vandet, har jeg brug for nogle ting til at formulere en kur...", p="Er det dig, Cenarion-kredsen i Månelunden har sendt? Det er vidunderligt! Vi har en ret slem krise på vores hænder her med de stakkels hjorte, og vi er glade for al den hjælp, vi kan få.\n\nHar du vandprøven, som Dendrit Stjerneblus sagde, du ville have? Han meddelte mig, at du ville tage en, så vi kunne arbejde på en kur sammen..."},
  [6123] = {c="Det er godt, <Name>, så godt at det burde være nok til at lave en rigelig portion salve – i hvert fald nok til at begynde at gøre en forskel.\n\nDet kan være ret svært at lave en kur mod gift, for hver enkelt kræver som regel et meget specifikt modgift for at modvirke den. Forestil dig at kunne kurere en gift på kommando uden at skulle bekymre dig om de præcise ingredienser i modgiften!\n\nNu, lad mig gå i gang med dette!", p="Har du de reagenser, jeg skal bruge til at lave salven? Hjortene bliver ikke bedre af sig selv, så vi må skynde os at hjælpe dem!"},
  [6124] = {c="Du har gjort det godt med at passe på de syge hjorte i Mørkekysten; de er uvidende ofre for et større fordærv og en korruption, der breder sig over hele landet. Der er nogle i Darnassos, som vælger at erkende denne trussel... og der er dem, der ignorerer de voksende tegn. Jeg håber, du ikke bliver en af dem, der lukker øjnene for de kendsgerninger, der stirrer dig lige i ansigtet, <Name>.\n\nUanset hvad, har du bevist din værdi som naturens og Kredsens ven - tag dette som et symbol herpå.", p="Har du fuldført det, Alanndarian Nattesang fra Auberdin bad dig om? Dit arbejde er ikke færdigt, medmindre det er."},
  [6126] = {c="Hilsner unge druide, jeg er glad for at se dig klar og ivrig efter at lære om kurering af gift.\n\nMens de fleste druider i fortiden blev sendt igennem forudplanlagte prøver, vil dit arbejde ikke involvere noget sådant. Der har været en bølge af dyreforgiftninger i Korsvejen i Ødemarken, og de kan ikke få styr på det. Nogen dernede har bedt Månelunden om bistand, så vi sender dig derned for at assistere dem. Dette er ingen øvelse - det arbejde, du skal udføre, er ganske virkeligt. Husk det."},
  [6127] = {c="Af mine forfædre, dette vand er ækelt! Intet under, at gazellerne er syge.\n\nNoget forurener vandet og begynder i sin tur at ødelægge økosystemet i den nordlige del af Ødemarken. Syge gazeller er set overalt nord for øst-vest-vejen her. Selvom dette vand højst sandsynligt er en primær kilde til sygdommens spredning, er der også noget andet på spil her.\n\nDette vand, tro det eller ej, vil hjælpe os med at formulere en kur. Mens jeg undersøger vandet, har jeg brug for nogle ting til at formulere en kur...", p="Er du den, Cenarion-kredsen i Månelunden sendte, ikke? Det er uhyre heldigt for os! Vi er kørt fast i vores bestræbelser på at bringe balance til de sygelige gazeller, der vandrer rundt i det nordlige Ødemark; vi er glade for al den hjælp, vi kan få.\n\nHar du prøven af vand, som Dendrit Stjerneblus sagde, du ville have? Han underrettede mig om, at du ville tage en, så vi kunne arbejde på en kur sammen..."},
  [6128] = {c="Det er godt, <Name>, så godt at det burde være nok til at lave en rigelig portion salve – i hvert fald nok til at begynde at gøre en forskel.\n\nDet kan være ret svært at lave en kur mod gift, for hver enkelt kræver som regel et meget specifikt modgift for at modvirke den. Forestil dig at kunne kurere en gift på kommando uden at skulle bekymre dig om de præcise ingredienser i modgiften!\n\nNu, lad mig gå i gang med dette!", p="Har du de reagenser, jeg skal bruge til at lave salven? Gazellerne bliver ikke bedre af sig selv, så vi må hellere ikke dvæle ved det, når vi skal redde dem!"},
  [6129] = {c="Du har gjort det godt med at passe på de syge gazeller i Ødemarken; de er uvidende ofre for et større fordærv og en korruption, der breder sig over hele landet. I tyrefolket er meget ivrige efter at forstå Cenarus' veje; du og jeres ældste i Tordenklippe beviser, at behovet for balance overskrider kunstige racemæssige skel.\n\n<Name>, du har bevist din værdi som en ven af naturen og Kredsen - tag dette som et symbol herpå.", p="Har du fuldført det, Tonja Runetotem ved Korsvejen bad dig om? Dit arbejde er ikke færdigt, medmindre det er."},
  [6130] = {c="Velkommen tilbage - jeg har fulgt din fremgang med denne lektion, siden du gik, og jeg må indrømme, at jeg blev overrasket over at høre om situationen ved Korsvejen. Dette fortjener nærmere undersøgelse, for indførelsen af sådanne gifte i miljøet er yderst urovækkende for balancen.\n\nDu klarede dig med nåde under pres. For det kan jeg ikke finde nogen bedre måde at belønne dig på end med permanent kraft over gift. Brug den brønd, <Name>... brug den brønd."},
  [6161] = {c="Bryst åbner sig og afslører Rackmores skat!", p="Denne kiste er sikkert låst."},
  [6181] = {c="Skal du have denne seddel til Stormvind? Det er ikke noget problem, du kan tage en af mine griffer!", p="Du ser ud, som om du har travlt. Nå, så er du kommet til det rette sted!"},
  [6261] = {c="En kasse til Vestfald, hva'? Har du været i Vestfald før? Hvis ja, så er det intet problem, min ven. Jeg har masser af griffener trænet til at flyve den rute!", p="Er det sved på dit bryn, knægt? Du har løbet for meget. Næste gang, tag en gryfon!"},
  [6281] = {c="Ah, et brev fra Kvartermester Lewys? Jeg er ikke overrasket over, at han har brug for mere udstyr. Vagtbakken ligger langt væk, i et land, Stormvind næsten har glemt.\n\nTak, <Name>. Her er nogle penge til at dække dine rejseudgifter.", p="Du har været på rejse, hva'? Har du været nogen spændende steder?"},
  [6282] = {c="Det er de mest fremragende nyheder! Fortæl mig igen, hvordan du besværgede frygt ind i de nedrige harpyers kulde-hjerter. Blodraserne har fået tilføjet et alvorligt slag!", p="Vær ikke træt af Den Brændte Dal; mange onde væsener holder til i de bakker. Vær stærk, <Name>, så skal du sejre over denne trussel mod vores folk. Gå nu og slå hårdt til - vores børn skal aldrig kende til det onde af det, der var."},
  [6283] = {c="Allerede føler jeg vreden forlade mig. Hvad skal jeg bruge min tid på? At vide, at det onde bevæger sig nær mit land, holdt mine tanker i gang, men nu er de tavse. Måske er det en god ting... måske kan jeg nu fokusere på det gode, som alle Taurer bør.\n\nVær venlig at modtage dette som belønning for dine besværligheder.", p="Blodraser-Rivekløen er et ondskabsfuldt uhyre! Du vil få held med at finde hende langs bakkekæden mod vest i Den Brændte Dal.\n\nBlodraserne vil være hjælpeløse uden... vi kan sikkert udslette dem for altid!"},
  [6284] = {c="God jagt, <Name>! Besselet har længe været et gammelt rovdyr i disse egne... Jeg kommer ikke til at savne hende. Tag denne belønning som et Mærke på, at du er skovens mester.\n\n<Mavgran gnider sig over Såret, som Besselet har forvoldt.>\n\nMåske vil nu langt flere rejse til Solklippe-tilflugtsstedet uden at frygte det, der lurer i mørket.", p="Besselet er et ubarmhjertigt rovdyr... Jeg frygter for dem, der rejser ad Spindelvævs-vej om natten. Det er da, at hun og hendes unger jager uskyldige rejsende. Selv faldt jeg offer for hendes to-fods dødshugtand, men heldigvis formåede jeg at holde hende fra livet og komme i sikkerhed. Jeg ville give alt for at se det uhyre udslettet."},
  [6285] = {c="Stor, du bragte rustningen! Vi deler det ud til dem, der har brug for det med det samme.\n\nTak, <Name>. Din indsats har været en stor hjælp for os. Og nu hvor du ikke længere er fremmed for grifoner, håber jeg, at du vil komme og yde din bistand til Vagtbakken ofte!", p="Er du tilbage fra Stormvind? Sendte Osric rustningen?"},
  [6301] = {c="Ah, <Name>, du har Gaia-frøene. Se og lær, hvordan Jordmoderens velsignelse kan få selv disse små livskerner til at blomstre og trives.\n\n<Tamra begynder at messe.>", p="Den konstante ødelæggelse, som krig og dem, der jagter profit på tømmer, forårsager, smerter mig dybt. For at hjælpe genfødslens kredsløb og genopbygge landene har jeg brug for Gaia-frø. Har du nogen, <Class>?"},
  [6321] = {c="Ah, en ordre på forsyninger. Du vil sikkert gerne tage den her med til Undergrunden. Og hurtigt, for Gravkammeret må ikke stå med et for lille lager.", p="Du ser ud til at være på officielt ærinde..."},
  [6323] = {c="En ordre fra Gravkammeret? Meget vel. Det er en ære at tjene dem, der tjener vores Den Mørke Dame.", p="Jeg holder mine våben i topstand. De er rengjort og klar til brug."},
  [6324] = {c="God gerning, <Name>. Disse våben sørger for, at vores Dødevagter ikke bliver fanget uforberedte.\n\nDu har forvoldt en værdifuld tjeneste for vores Mørke Dame.", p="<Name>, du er vendt tilbage. Har du vores forsyninger fra Undergrunden?"},
  [6365] = {c="Skal du have dette kød til Orgrimgrad? Det er ikke noget problem. For et lille gebyr kan min vindrytter tage dig derhen.", p="Skal du hen et sted hurtigt? Så taler du med den rette ork!"},
  [6381] = {c="Det er en stor sejr for landet. Med tiden vil andre ting ske: Ventureselskabet vil pakke deres rundsave og økser sammen, de vrede affyr-ånder vil falme, og harpyerne vil blive drevet væk af landet.\n\nFørst da, <Name>, vil Stenklippe virkelig være i fred.\n\nDu har klaret dig godt, <Class>; tag en af disse genstande som tak for det nye liv, du har skabt her i dag.", p="Disse frø, du planter, er stærke, de modstår korruption og skaber et fodfæste for andet liv. De vil vokse og vokse, først ved at forhindre korruption og hele det ar-medtagne land, og så en dag genoprette Stenklippe til en frodig skov igen.\n\nHar du plantet alle Gaia-frøene?"},
  [6382] = {c="Velkommen til den nye grænse, <Name>. Askedalen er et land fuld af muligheder, et sted hvor en ung <Class> som dig kan finde grænseløse chancer for at bevise sit mod. Se dig omkring i forposten her, og sørg for at tage ud til Zoram-strandbredden, for Horden har også en forpost der.\n\nDin tilstedeværelse her fortæller mig, at du er kommet for at lære mere om jagten. Lyt godt efter, så deler jeg gerne det, du behøver at vide."},
  [6383] = {c="Der er tre legendariske væsener, som udgør Askedalen-jagten; du kan søge dem og måle dig selv med deres snedighed og styrke. Undervejs vil du forhåbentlig lære noget om dig selv. Væsnerne er: bjørnen Bjørnegus, natsabelkatten Skyggedrøm og hippogryffen Skarpklo.\n\nVæsnerne i Askedalen-jagten er mægtige, og du kan blive nødt til at få hjælp til at fælde dem. Hvis du overgår dem, så bring mig bevis på din bedrift."},
  [6384] = {c="Åh, herligt! Det er fine udskæringer! Er de fra Skarv, siger du? Den ork ved da virkelig, hvordan han finder vej ind i en damers hjerte...\n\nÅh, jeg kan ikke vente med at tilberede det. Men ikke for meget! Kød er bedst, når det er blodigt, synes du ikke?", p="Der lugter godt af noget! Du har vel ikke noget råt kød på dig, vel?"},
  [6385] = {c="Skal du have det her til Korsvejen i Ødemarken? Ja, jeg kan få dig derhen...", p="Har du brug for en af mine vindryttere?"},
  [6387] = {c="Skal du have det her til Jernsmede, hva'? For et lille gebyr kan jeg sætte dig på ryggen af en af mine griffer, så tager den dig derhen. Hvordan lyder det?", p="Har du allerede fået nok af Tælsamar? Er du klar til at tage af sted til en anden by?"},
  [6388] = {c="Skal du have disse til Tælsamar, hva'? Det er ikke noget problem. Så længe du allerede har været i Tælsamar og talt med Thorgrum Borrelsen, kan du tage en af mine griffer tilbage til ham.", p="Du ser ud, som om du har et sted at være. Har du brug for en af mine gryfoner?"},
  [6391] = {c="Ah, den seneste liste over Grævlings bedste elever. Jeg har en bunke æresudnævnelser klar til at gå af sted. Jeg mangler bare at hugge elevernes navne ind...", p="Hvad kan jeg gøre for dig, herre?"},
  [6392] = {c="Du bragte hakkerne. Herligt! Jeg får dem bragt til mine minedrifts-elever. Jeg er sikker på, at de er ivrige efter at bruge dem på malmforekomsterne i Modansøen.\n\nTak for din hjælp, <Name>. Jeg står i din gæld, men jeg håber, at pengene i det mindste dækker dine rejseudgifter.", p="Ah, <Name>. Er du vendt tilbage fra Jernsmede?"},
  [6393] = {c="Vandånderne i mig bobler af begejstring. <Name>, du har givet mig en herlig sejr at rapportere til Tidevandets Tribunal.", p="Tidevandets Tribunal bliver utålmodigt. De søger at afslutte denne krig, der har hærget på tværs af alle dimensioner i evigheder. Mine brødre er ivrige efter at høre nyheder om den herlige sejr over de hadede ildelementarer. Har du de Incendriter, jeg kræver?"},
  [6394] = {c="Stor, du fik den! Tak meget, <Name>. Det her er mit yndlingsvalg! Hvis mine peoner nu bare får fældet de her træer færdigt, kan vi måske finde en fin hule at grave i!", p="Har du trådt ind i Brændende Klinge-hekseriet, <Name>? Fandt du min hakke?"},
  [6395] = {c="Du har gjort en god gerning i dag, <Name>. Selvom vores kamp mod Svøben fortsætter, så lad os håbe, at Marla og Samuel finder fred sammen på deres sidste hvilested.", p="Vi må respektere vores døde, <Name>. Det er en af de måder, hvorpå vi adskiller os fra Svøben..."},
  [6401] = {c="Herregud, min niece Kaja er i live! Det er virkelig gode nyheder. Tak, <Name>."},
  [6421] = {c="Ah... Ja! Det er det; Resonit-krystallerne har et spor af jordmagi. Kobolderne må have gravet dybt og afdækket et Jordvæsen.\n\nLegenden fortæller, at Jordvæsnerne er væsener skabt af Titanerne. De blev brugt til at skabe landet, vores fødder træder på. Dette er helt bestemt en trussel, der ikke kan ignoreres.\n\n<Mor'rogal Hønsefar ryster på hovedet.>\n\nMåske kan jeg fortrylle disse malmprøver til at bruge mod kobold-rænken.", p="Hvilke nyheder har du fundet i Klippeskred-kløften? Jeg husker en legende om Resonit... Jeg kan bare ikke få hoven på den. Måske vil det at vide, hvad der ligger på bunden af hulen, kaste lys over deres snedige hensigter."},
  [6441] = {c="Disse er perfekte, <Name>! Tak fordi du hjalp mig!\n\nÅh, og det her er for din tid...", p="Jeg håber, du kan være hurtig til at skaffe de horn, <Name>. Jeg skal snart tilbage til Skralde!"},
  [6442] = {c="Vi kunne godt bruge flere af din slags her omkring, <Name>. Tak for din hjælp.", p="Slangefolkene øger sig i antal, <Name>. Vær venlig at fuldføre denne opgave for mig."},
  [6461] = {c="Sød, mand! Gode nyheder, måske får vi færre uinviterede middagsgæster i aften.\n\nMange tak, <Name>. Vi står for evigt i din gæld.", p="Hey mand, har du slået de hårede blodsugere ihjel? Jeg frygter ingen her i Stenklippe, men jeg går ikke rundt herude om natten... hvis du forstår mig, mand!\n\nSå længe jeg holder mig fra deres middagstallerken, så er alt vel.\n\nHeld til dig, <Class>!"},
  [6462] = {c="Du fandt dem! Tak! Tak, <Name>! Du aner ikke, hvor stor en ting du har gjort for mig.\n\nEn trold uden sin fortryllelse er som en ork uden sine slagmærker...\n\nUdenværdig.", p="Har du fundet amuletterne, <Name>? Hver gang pelsbjørnene besidder de hellige genstande, koger mit blod af raseri!"},
  [6481] = {c="Du bringer gode nyheder, <Class>! Jeg frygter, hvad en Jordvæsen ville betyde for Kalimdør.\n\nAt dræbe Klaprok var en opgave for ikke mindre end en helt. Du har gjort det godt; hele Stenklippe og Kalimdør står i gæld til dig, ædle <Class>.\n\nAcceptér dette som din belønning, du mest hædrede.", p="Jeg frygter, at hvis vi ikke får fjernet denne trussel med det samme, vil hele Stenklippe gå tabt. Et Jordvæsens styrke kan ikke matches på nogen måde. Når Klaprok vækkes, vil han være svag efter sin lange dvale, og det bliver den mulighed, du skal udnytte... gå nu <Name>!"},
  [6482] = {c="Du fandt min bror! Han blev taget til fange af Tidselpelsene? Det er forfærdelige nyheder at høre, for selvom mange af Furbolgerne er ædle væsener, så er Tidselpelsene korrupte.\n\nTak fordi du reddede min bror, <Name>. Jeg vil ikke tænke på, hvordan de behandlede stakkels Rulle. Han kommer nok til at sove længe efter denne prøvelse...", p="Har du set min bror Rulle? Han gik ind i skoven for flere dage siden og er ikke vendt tilbage..."},
  [6503] = {c="Meget godt, <Name>. Dine jagtfærdigheder er imponerende...\n\nTabet af de fortropsløbere hjælper med at blinde Alliancen, og når de mangler efterretninger, er de mindre tilbøjelige til at indlede angreb.", p="Jeg venter på rapporter om dine drab på Askedalen-løbere, <Name>."},
  [6504] = {c="Læsning er ikke mit stærke punkt... men nu kan jeg komme tilbage til arbejdet! Tak, <Name>!", p="Jeg håber, du finder siderne snart, <Name>! Jeg må virkelig tilbage til arbejdet!"},
  [6521] = {c="God. Forvoldt brønd, <Class>.\n\nNu hvor Malsin er død, kan vi i det mindste vide, at Svøbens fremrykning vil blive standset. Den Mørke Dame takker dig for din indsats og ønsker at belønne dig med en gave.\n\nSkønt vi ikke kender omfanget af Svøbens indflydelse i Slettene, er jeg sikker på, at vi snart vil opdage deres rænker.", p="Har du fundet Ambassadøren, <Name>? Er han død?\n\nVi har ikke råd til at lade Svøben få fodfæste på Kalimdør. De er trussel nok mod vores egne grænser til, at vi skal tage os af dem på to fronter.\n\nDet eneste optimistiske tegn fra de begivenheder, du har fortalt mig om, er, at heksen virkede uforfalsket. Hun må dybt i sin ånd vide, at Svøben kan bringe stor magt, men at Ødemarken aldrig rigtigt ville være hendes, hvis hun gik med til deres aftale."},
  [6522] = {c="Jeg genkender insignierne på denne rulle, <Name>. Fandt du den hos den hekse, der hersker over Rasorhegn-Kraulen? Interessant.\n\nSvøben nøjes tydeligvis ikke med ét kontinent. Denne Ambassadør Malsin--han, der skrev brevet--er en af Svøbens pestramte tjenere, en menneskelig diplomat for Herrelandes kongerige, før tingene... ændrede sig.\n\nHvis Svøben forsøger at få fodfæste i Kalimdør, så er det op til os at handle.", p="Hvad er det for en sag, du vil tale om, <Name>? Du må mene, at den er vigtig, når du bliver ved med at plage mig."},
  [6541] = {c="Askedalen er et delt land, men vores seneste indsatser har været meget vellykkede. Vi har ikke bare en forpost ved Zoram-strandbredden, men også en anden lige nord herfra, kaldet Flistræ."},
  [6542] = {c="Askedalen er et delt land, men vores seneste indsatser har været meget vellykkede. Vi har ikke bare en forpost ved Zoram-strandbredden, men også en anden lige nord herfra, kaldet Flistræ."},
  [6543] = {c="Jeg kan se, at du er en, man kan regne med. Disse opdateringer er afgørende for vores planer om at styrke vores tilstedeværelse i Askedalen. Nu kan vi planlægge vores næste træk.", p="Skynd dig, <Name>. De skal modtage deres rapporter; det haster."},
  [6544] = {c="Så Toreks angreb lykkedes! Velgjort, <Name>. Nattealferne er anstændige fjender. Lidt tynde, men stærke og vilde! Jeg er sikker på, at slaget var et syn...\n\nOg jeg håber, du fik et ar eller to!", p="Tørek blev sendt på en mission mod Sølvvinge-forposten. Var angrebet vellykket?"},
  [6545] = {c="Nå, min opdatering vil forklare alt dette til Kadrak. Du skal bringe dette tilbage til ham så hurtigt som muligt.", p="Så du er her med mine ordrer? Altid godt at se en ny rekrut med en overstadig natur og en stærk vilje.\n\nDu må hellere lære hurtigt, hvis du regner med at følge med her. Trusselen fra slangefolkene vokser, <Name>. Jeg har holdt øje med det og har siden min ankomst sat forsvar op mod flere angreb på denne forpost.\n\nMen hvis du har lyst til at give en hånd med til den indsats, så tal med en af de andre her på forposten."},
  [6546] = {c="Tag min opdatering med til Kadrak. Hurtigt, <Name>.", p="Der lurer megen fare langs denne sti, <Name>. Du gør klogt i at huske det, mens du rejser i disse lande. Forbundets trussel er ganske nær.\n\nVi står over for fjender på alle fronter. Satyrerne er en vældig og udbredt styrke i det østlige Askedalen. Jeg har også opdaget, at slangefolkene har overtaget et stort område i Azsyra-landet.\n\nDet er godt at se, at vi stadig styrker vores rækker -- vær klar til det, der venter forude, <Name>."},
  [6547] = {c="Lad Kadrak vide, at vi har haft succes her med at holde nattealferne stangen. Vores planer går godt.", p="Hold øje, <Race>. Alferne gemmer sig ofte i skyggerne...\n\nVi må altid holde vagt. Vi har arbejdet hårdt for at gøre dette land til vores, og alferne leder efter en chance for at tage det fra os.\n\nJeg går ud fra, at du har mine næste ordrer fra Kadrak?"},
  [6548] = {c="<Name>, jeg takker dig... men jeg vil aldrig glemme, hvad Grumtotem-klanen har gjort mod min landsby.", p="Har du dræbt dem endnu?"},
  [6561] = {c="Kelrik har undgået Sølvdæmringen i nogen tid.\n\nI nogen tid anså de ham for død eller forsvundet.\n\nVed at afslutte hans herredømme har du skånet mange uskyldige liv, <Name>.\n\nJordmoderen være lovet! At ofre en anden til en tjener for en Gammel Gud for egen vindings skyld er ud over al beskrivelse modbydeligt!\n\nDu har gjort en stor gerning i dag. Kelrik var et ondskabens væsen og søgte at bringe verden tilbage til en tid med kaos ved at tilbede sådanne væsener som De Gamle Guder. Tak, <Name>.", p="Må Jordmoderen være med dig, <Name>.\n\nFred mellem jorden og alle hendes folk bør være vores mål. Hun har en storslået plan for naturen, og vi har alle en rolle at spille i den plan."},
  [6562] = {c="Bølgeman sendte dig? Fremragende. Så har vi noget at drøfte."},
  [6563] = {c="Godt klaret, <Name>. Det er krystallerne, jeg talte om. Intrigerende...\n\nJeg kan mærke kraften i dem. Vandåndene klamrer sig til dem. Hvad slangefolkene end ville bruge dem til... ja, lad os være glade for, at de ikke længere er i deres hænder.", p="Hvordan går din søgen efter krystallerne, <Name>? Har du set slangefolkene høste dem? Jeg beder til mine forfædre, at vi finder grunden til, at de samler sådan noget."},
  [6564] = {c="Det er virkelig interessant. Jeg er glad for, at du har gjort mig opmærksom på det.\n\nNu har vi et navn på vores problemer... Lorgøs Jet.", p="Ja, <Name>? Hvad er det, du har brug for? Der er stadig meget, jeg må lære om de krystaller, slangefolkene indsamler."},
  [6565] = {c="Meget godt!! Tak, <Name>. Vi fik måske ikke stoppet Tusmørkets Hammer helt, men du har i det mindste afværget endnu en af deres planer om at bringe De Gamle Guder tilbage til magten.\n\nHvem ved, hvilke andre planer de har under opsejling, men vi kan hvile trygt for nu.", p="Har du fundet ham endnu, <Name>? Lorgøs må stoppes!"},
  [6571] = {c="Fremragende, <Name>. Du har sparet mig for en masse arbejde!\n\nMen tro ikke, at jeg ikke er taknemmelig!", p="Jeg håber, du kan levere forsyningerne! Jeg er i store vanskeligheder, hvis jeg ikke får dem leveret snart!"},
  [6581] = {c="Det er perfekt – lige det rette! Nå, her er forsendelsen.", p="Direkte fra Skralde, Krigssang-savklingerne! Jep, jeg har dem lige her.\n\n..Men hvad slags betaling har du til mig? Du kan ikke bare tage dem, ved du nok! Min tid er ikke billig!\n\nDet, jeg virkelig har brug for, er et godt gevær at tage med mig på mine rejser. En pige må jo beskytte sig selv, ved du nok? Der er et gevær, jeg rigtig godt kan lide, og jeg er sikker på, at en ingeniør ikke ville have problemer med at lave det.\n\nSå, hvis du bringer mig en dødbringende blunderbøsse, giver jeg dig forsendelsen af savklinger. Har vi en aftale?"},
  [6621] = {c="God gerning, <Name>. At udfordre Rådskovene og besejre deres leder sender dem et kraftigt budskab:\n\nHorden er ikke til at lege med.\n\nJeg tror ikke, at den stamme vil give os meget besvær i lang tid.", p="Besejrede du Høvding Murgut, <Name>? Hentede du hans Rådskov-totem?"},
  [6626] = {c="Tak, <Name>! Det arbejde, du har udført, vil være en stor hjælp, er jeg sikker på.\n\nJeg vil fortsætte mit studie af denne diplomat og resten af Tornesvinene her. Hvis du søger større eventyr, så find nogle venner og tag ind i hulen, der ligner et stort vildsvine-gab lidt derovre. Jeg er sikker på, at når du er inde, vil du finde større udfordringer at tage op.", p="Hvordan går jagten, <Name>? Blot at se denne lille prøve på denne diplomats kraft fjerner al tvivl, jeg havde om, at Svøben er en af de største trusler, denne verden nogensinde har set."},
  [6629] = {c="Grundig Mørkeskye er død! <Name>, jeg vil altid være taknemmelig for det, du har gjort her i dag.", p="Har du dræbt Grundig Mørkeskye og hans personlige bande af Brutaler?"},
  [6641] = {c="Jeg har set mange angreb fra slangefolket, siden jeg kom hertil. Det beroliger mit sind, at Vorsha Piskeren ikke længere kan strejfe frit omkring.\n\nVi står i din gæld, <Name>."},
  [6661] = {c="Disse'll værk fint, makker. Min bror har brug for dem stadig tikkende og sprællende, ellers går de sure... Du vil ikke smage no sur rottekebab.", p="Yarrr... Dækskrubber, hvad tager dig dog så lang tid?"},
  [6662] = {c="Stakkels Monty. Lige siden Gnomregan-hændelsen har han ikke været den samme. Drengen har aldrig set et hav i sit liv, endsige været en slags pirat.\n\n<Nipsi sukker.>\n\nI det mindste sørger han for, at strømmen af krampende kryb holdes i gang.", p="<Nipsi stikker sin pegefinger igennem et af luftehullerne i kartonen.>\n\nLevende og sparkende... og lige til tiden!"},
  [6681] = {c="Aldeles fortrinligt, unge tyv.\n\nDu ser lidt medtaget ud, men ikke værre end det.\n\nEn lang rejse venter dig - lang og givende. Er du klar til endelig at omfavne din skæbne blandt Ravnehold-mestrene?\n\nTal med vagterne udenfor. De får dig i gang.", p="Mødte du Mildon?\n\n<Fårhad griner.>"},
  [6921] = {c="Det er præcis hvad jeg har brug for! Dybdekernen er en utrolig brønd af viden, som vi kan hente masser af godt ud af. Hvad Tusmørkets Hammer end har gang i derinde – og tro mig, det er intet godt – vil mine kammerater og jeg nu afdække.\n\nDu har klaret dig godt i dag; Jordringen ser venligt til dig, fordi du hjalp os. Du har også hjulpet Horden som helhed, og det burde du være stolt af.", p="Er du lykkedes med at finde dybdekernen? Uden den har vi ingen anelse om, hvad Tusmørkets Hammer egentlig har gang i dernede."},
  [6922] = {c="Det här... det her er et ret stort fund, <Name>.\n\nDu fik det fra Baron Akvanis i Sortdybet, siger du? Baron Akvanis har længe været anset for en fordærvet elementarkraft; denne kugle vil afsløre præcis, hvad der fordærvede ham. Det ville ikke komme bag på mig, om det viste sig at være Tusmørkets Hammer, men vores studier vil også vise, hvordan de gjorde det.\n\nDu gjorde det godt i at bringe mig dette. Værsgo - tag den her, sammen med Jordringens varmeste hilsner.", p="Ah, hej igen <Name>. Jeg læste lige bølgerne i havet, ligesom jeg altid gør. Hvad fører dig til forposten?"},
  [6981] = {c="Åh... Jeg har aldrig set noget lignende...", p="Hej, <Race>. Hvad kan jeg gøre for dig?"},
  [7321] = {c="Min beroligende skildpaddebisque vil holde dig varm på en kold nat... hvis du interesserer dig for den slags ting.", p="Har du haft held med at finde ingredienserne? Jeg siger dig, forbundets maddiker er alt for talrige i dette område nu... Efter min mening er de allerede kommet alt for tæt på..."},
  [7383] = {c="At stå i nærværet af Orakeltræet... det er næsten, som om visdommen tager form. Lad mig fortsætte fortællingen...\n\nDa Teldrasil var vokset frem, henvendte Ærkedruiden sig til dragerne for deres velsignelser, sådan som dragerne i gamle dage havde givet Nordrassil dem. Men Nosdormu, Tidens Herre, nægtede at give sin velsignelse og irettesatte druiden for hans arrogance. I enighed med Nosdormu afslog også Aleksstrasa Hjorthelm, og uden hendes velsignelse er Teldrasils vækst blevet fejlbehæftet og uforudsigelig...", p="Sammen med druiderne har Orakeltræet og Ærkedruiden omhyggeligt overvåget Teldrasils vækst. Men selvom vi har et nyt hjem, er vores udødelige liv ikke blevet genoprettet."},
  [7802] = {c="Vidunderligt! Vi takker dig for din generøse donation, <Name>!", p="Vi modtager i øjeblikket donationer af uldklæde. En donation på tres stykker uldklæde vil give dig fuld anerkendelse fra Jernsmede for dine generøse handlinger. Vores lager af uld er sådan, at vi kun ville have brug for tres stykker fra dig i alt; vi burde kunne skaffe nok fra andre i riget til at støtte vores indsamling.\n\nHvis du har de tres stykker uldklæde på dig og er klar til at donere dem, kan jeg tage dem fra dig nu."},
  [7807] = {c="Vidunderligt! Vi takker dig for din generøse donation, <Name>!", p="Vi modtager i øjeblikket donationer af uldklæde. En donation på tres stykker uldklæde vil give dig fuld anerkendelse fra Gnomregan-eksilerne for dine generøse handlinger. Vores lager af uld er sådan, at vi kun ville have brug for tres stykker fra dig i alt; vi burde kunne skaffe nok fra andre i riget til at støtte vores indsamling.\n\nHvis du har de tres stykker uldklæde på dig og er klar til at donere dem, kan jeg tage dem fra dig nu."},
  [7808] = {c="Vidunderligt! Vi takker dig for din generøse donation, <Name>!", p="Ligesom med de fleste andre stoffer er vores silkelager på et lavpunkt nogensinde. Vores forråd er sådan, at vi kun skal bruge seksti stykker silke fra dig samlet; vi burde kunne nå vores mål med støtte fra andre.\n\nEn velvillig gave som silke, må jeg tilføje, vil helt sikkert øge din lokale anseelse i fællesskabet! Hvis du har de seksti stykker silkeklæde på dig og er klar til at donere dem, kan jeg tage dem fra dig med det samme."},
  [7813] = {c="Vidunderligt! Vi takker dig for din generøse donation, <Name>!", p="Vi modtager i øjeblikket donationer af uldklæde. En donation på tres stykker uldklæde vil give dig fuld anerkendelse fra Undergrunden for dine generøse handlinger. Vores lager af uld er sådan, at vi kun ville have brug for tres stykker fra dig i alt; vi burde kunne skaffe nok fra andre i riget til at støtte vores indsamling.\n\nHvis du har de tres stykker uldklæde på dig og er klar til at donere dem, kan jeg tage dem fra dig nu."},
  [7820] = {c="Vidunderligt! Vi takker dig for din generøse donation, <Name>!", p="Vi modtager i øjeblikket donationer af uldklæde. En donation på tres stykker uldklæde vil give dig fuld anerkendelse fra Tordenklippe for dine generøse handlinger. Vores lager af uld er sådan, at vi kun ville have brug for tres stykker fra dig i alt; vi burde kunne skaffe nok fra andre i riget til at støtte vores indsamling.\n\nHvis du har de tres stykker uldklæde på dig og er klar til at donere dem, kan jeg tage dem fra dig nu."},
  [8311] = {c="Vow, du fik dem alle! Du er fantastisk!\n\nTak fordi du gik pjus-eller-slik for mig. Her, tag disse græskarbolcher – jeg tror, du kommer til at elske dem!\n\nGlad Helligaftens Ende, <Name>!", p="Er du færdig med at gå rundt efter puds og godter endnu? Jeg er ked af, at jeg ikke kan gå selv, fordi jeg er syg, men at du hjælper mig, gør mig lidt bedre tilpas..."},
  [8373] = {c="Ah, det lugter næsten bedre her omkring allerede. Næsten.\n\nTak til dig, <Name>, så klarer Sydstranden måske endnu en Helligaftens Ende. Her er dine godter, med min tak! Løber du tør for slik, tror jeg, der er en gnom ved navn Katrina Glimmerstjerne i Jernsmede, som kan sælge dig mere; hun er vist kun til stede under Helligaftens Ende.", p="De forbandede Forladte... det er allerede slemt nok, at de er udøde, men så bliver de ophidsede og begynder at skabe ballade i MIN landsby!"},
}
for id, t in pairs(extra) do
    local q = ns.Quests[id]
    if q then
        if t.p and not q.p then q.p = t.p end
        if t.c and not q.c then q.c = t.c end
    end
end
